/**
 * Câu ví dụ từ vựng N1 (Mimikara N1) — tra theo số thứ tự (no) của thẻ trong vocab.js.
 * Từ đang học được đánh dấu bằng **...** trong câu tiếng Nhật.
 */
tangoRegister('n1', 'examples', {
  "1": [{"jp":"学生時代、私は部活に**青春**を捧げた。","vi":"Thời học sinh, tôi đã dành trọn thanh xuân cho câu lạc bộ."},{"jp":"あの映画を見ると、自分の**青春**時代を思い出す。","vi":"Mỗi khi xem bộ phim đó, tôi lại nhớ về thời thanh xuân của mình."}],
  "2": [{"jp":"祖父は**晩年**、故郷の村で静かに暮らした。","vi":"Những năm cuối đời, ông tôi sống yên bình ở ngôi làng quê nhà."},{"jp":"その画家の**晩年**の作品には、深い孤独が感じられる。","vi":"Trong các tác phẩm cuối đời của họa sĩ đó, người ta cảm nhận được một nỗi cô đơn sâu sắc."}],
  "3": [{"jp":"恩師の**葬式**には大勢の教え子が参列した。","vi":"Rất nhiều học trò cũ đã đến dự tang lễ của người thầy."},{"jp":"**葬式**には黒い服を着て行くのがマナーだ。","vi":"Mặc đồ đen khi đi đám tang là phép lịch sự."}],
  "4": [{"jp":"日本では一人暮らしの**世帯**が年々増えている。","vi":"Ở Nhật, số hộ gia đình sống một mình tăng lên qua từng năm."},{"jp":"この給付金は1**世帯**あたり10万円支給される。","vi":"Khoản trợ cấp này được chi 100.000 yên cho mỗi hộ gia đình."}],
  "5": [{"jp":"彼は若いころから苦労してきたので、**世間**のことをよく知っている。","vi":"Anh ấy đã vất vả từ khi còn trẻ nên rất hiểu sự đời."},{"jp":"その政治家の発言は**世間**の批判を浴びた。","vi":"Phát ngôn của chính trị gia đó đã hứng chịu sự chỉ trích của dư luận."}],
  "6": [{"jp":"この店は**庶民**的な値段で本格的な料理が食べられる。","vi":"Ở quán này có thể ăn món ăn chính hiệu với giá bình dân."},{"jp":"物価の上昇は**庶民**の暮らしを直撃している。","vi":"Giá cả leo thang đang giáng đòn trực tiếp vào cuộc sống của người dân thường."}],
  "7": [{"jp":"父は眠ってしまった娘を**おんぶして**家まで帰った。","vi":"Bố cõng đứa con gái đã ngủ thiếp đi về đến nhà."},{"jp":"兄は30歳を過ぎても実家に**おんぶして**暮らしている。","vi":"Anh trai tôi đã ngoài 30 mà vẫn sống nhờ nhà bố mẹ."}],
  "8": [{"jp":"彼女は**片言**の日本語で一生懸命道を尋ねてきた。","vi":"Cô ấy cố gắng hỏi đường bằng thứ tiếng Nhật bập bẹ."},{"jp":"1歳の息子が**片言**で「ママ」と言えるようになった。","vi":"Cậu con trai 1 tuổi đã bập bẹ gọi được \"mẹ\"."}],
  "9": [{"jp":"昨夜は**夜更かし**をしてしまい、今朝は起きられなかった。","vi":"Tối qua thức khuya nên sáng nay tôi không dậy nổi."},{"jp":"**夜更かし**は肌にも健康にもよくない。","vi":"Thức khuya không tốt cho cả da lẫn sức khỏe."}],
  "10": [{"jp":"親と大げんかをして、高校生の息子が**家出**した。","vi":"Sau trận cãi nhau lớn với bố mẹ, cậu con trai học cấp 3 đã bỏ nhà ra đi."},{"jp":"**家出**した少女は、3日後に警察に保護された。","vi":"Cô bé bỏ nhà đi đã được cảnh sát bảo hộ sau 3 ngày."}],
  "11": [{"jp":"出かける前に、しっかり**戸締り**をしてください。","vi":"Trước khi ra ngoài, hãy khóa cửa cẩn thận."},{"jp":"最近この辺で空き巣が多いので、**戸締り**に気をつけている。","vi":"Gần đây khu này hay có trộm đột nhập nên tôi rất chú ý khóa cửa."}],
  "12": [{"jp":"急な雨に降られて、**ずぶ濡れ**になった。","vi":"Gặp mưa bất chợt nên tôi bị ướt sũng."},{"jp":"川に落ちた子供は**ずぶ濡れ**で震えていた。","vi":"Đứa trẻ ngã xuống sông ướt sũng và run lẩy bẩy."}],
  "13": [{"jp":"話を聞いた父は、急に険しい**顔つき**になった。","vi":"Nghe xong câu chuyện, bố bỗng có vẻ mặt nghiêm nghị."},{"jp":"彼は優しい**顔つき**をしているが、仕事には厳しい。","vi":"Anh ấy có nét mặt hiền lành nhưng rất nghiêm khắc trong công việc."}],
  "14": [{"jp":"面接では**身なり**をきちんと整えることが大切だ。","vi":"Khi phỏng vấn, điều quan trọng là ăn mặc chỉnh tề."},{"jp":"その男性は立派な**身なり**をしていたが、実は詐欺師だった。","vi":"Người đàn ông đó ăn mặc chỉnh chu sang trọng nhưng thực ra là kẻ lừa đảo."}],
  "15": [{"jp":"入院中は、母が**身の回り**の世話をしてくれた。","vi":"Trong thời gian nằm viện, mẹ đã chăm lo mọi việc sinh hoạt cá nhân cho tôi."},{"jp":"**身の回り**の物を整理したら、気分がすっきりした。","vi":"Sắp xếp lại đồ đạc quanh mình xong, tôi thấy tinh thần sảng khoái."}],
  "16": [{"jp":"言葉が通じなかったので、**身振り**で気持ちを伝えた。","vi":"Vì không hiểu ngôn ngữ của nhau nên tôi đã truyền đạt cảm xúc bằng cử chỉ."},{"jp":"彼は**身振り**手振りを交えて、旅の話を楽しそうに語った。","vi":"Anh ấy vừa khoa tay múa chân vừa hào hứng kể chuyện chuyến đi."}],
  "17": [{"jp":"嘘をついたことで、ずっと**良心**が痛んでいる。","vi":"Vì đã nói dối nên lương tâm tôi cứ day dứt mãi."},{"jp":"彼は**良心**に従って、会社の不正を告発した。","vi":"Anh ấy làm theo lương tâm, tố giác sai phạm của công ty."}],
  "18": [{"jp":"彼には音楽家としての**素質**がある。","vi":"Cậu ấy có tố chất của một nhạc sĩ."},{"jp":"いくら**素質**があっても、努力しなければ才能は開花しない。","vi":"Dù có năng khiếu đến đâu, không nỗ lực thì tài năng cũng không nở rộ."}],
  "19": [{"jp":"彼女は同僚の男性に**好意**を抱いている。","vi":"Cô ấy có cảm tình với một đồng nghiệp nam."},{"jp":"先輩の**好意**に甘えて、車で駅まで送ってもらった。","vi":"Nhận lòng tốt của đàn anh, tôi được anh chở ra ga bằng ô tô."}],
  "20": [{"jp":"成績表を見た母は、深い**ため息**をついた。","vi":"Xem bảng điểm xong, mẹ thở dài thườn thượt."},{"jp":"山積みの仕事を前に、思わず**ため息**が出た。","vi":"Trước núi công việc chất đống, tôi bất giác thở dài."}],
  "21": [{"jp":"よく知っている俳優なのに、名前を**ど忘れ**してしまった。","vi":"Là diễn viên tôi biết rõ vậy mà tôi lại chợt quên mất tên."},{"jp":"緊張のあまり、自分の電話番号を**ど忘れ**した。","vi":"Vì quá căng thẳng, tôi quên bẵng cả số điện thoại của mình."}],
  "22": [{"jp":"夜道を一人で歩くときは**用心**したほうがいい。","vi":"Khi đi một mình trên đường đêm thì nên cẩn thận."},{"jp":"空気が乾燥する季節は、火の**用心**を忘れずに。","vi":"Vào mùa hanh khô, đừng quên đề phòng hỏa hoạn."}],
  "23": [{"jp":"朝から何か悪いことが起こりそうな**予感**がしていた。","vi":"Từ sáng tôi đã có linh cảm sắp có chuyện chẳng lành."},{"jp":"彼は会社の倒産を**予感して**いたかのように、早めに転職した。","vi":"Như thể đã linh cảm trước việc công ty phá sản, anh ấy chuyển việc từ sớm."}],
  "24": [{"jp":"教室に入ると、全員の**視線**が私に集まった。","vi":"Vừa bước vào lớp, mọi ánh mắt đều đổ dồn về phía tôi."},{"jp":"彼は気まずそうに**視線**をそらした。","vi":"Anh ta ngượng ngùng lảng tránh ánh mắt."}],
  "25": [{"jp":"「夜に爪を切ると縁起が悪い」というのは**迷信**だ。","vi":"\"Cắt móng tay ban đêm là xui xẻo\" chỉ là mê tín."},{"jp":"祖母は今でも古い**迷信**を信じている。","vi":"Bà tôi đến giờ vẫn tin vào những điều mê tín xưa cũ."}],
  "26": [{"jp":"これも何かの**縁**ですから、今後ともよろしくお願いします。","vi":"Đây cũng là cái duyên, mong từ nay về sau được anh giúp đỡ."},{"jp":"彼とは留学先で知り合った**縁**で、一緒に会社を始めた。","vi":"Nhờ cái duyên quen nhau khi du học, tôi và anh ấy đã cùng mở công ty."}],
  "27": [{"jp":"**使い捨て**のプラスチック製品を減らす取り組みが広がっている。","vi":"Các nỗ lực giảm đồ nhựa dùng một lần đang lan rộng."},{"jp":"会社は社員を**使い捨て**にするべきではない。","vi":"Công ty không nên dùng nhân viên xong rồi vứt bỏ."}],
  "28": [{"jp":"新車を買うときに、古い車を**下取り**に出した。","vi":"Khi mua xe mới, tôi đã đổi chiếc xe cũ để được trừ tiền."},{"jp":"この店では、古いスマホを**下取り**してもらうと割引がある。","vi":"Ở cửa hàng này, nếu đổi điện thoại cũ thì sẽ được giảm giá."}],
  "29": [{"jp":"家を買うために、夫婦で**倹約**して貯金している。","vi":"Để mua nhà, hai vợ chồng tiết kiệm chi tiêu và dành dụm tiền."},{"jp":"祖父は**倹約**家で、無駄な物は一切買わなかった。","vi":"Ông tôi là người tằn tiện, không bao giờ mua thứ gì lãng phí."}],
  "30": [{"jp":"今月は結婚式が続いて、**出費**がかさんだ。","vi":"Tháng này đám cưới liên tiếp nên chi tiêu tăng vọt."},{"jp":"家計が苦しいので、無駄な**出費**を切り詰めている。","vi":"Kinh tế gia đình eo hẹp nên tôi cắt giảm các khoản chi lãng phí."}],
  "31": [{"jp":"食事が終わったので、**会計**をお願いします。","vi":"Chúng tôi ăn xong rồi, cho tôi tính tiền."},{"jp":"大学で**会計**を学び、今は経理部で働いている。","vi":"Tôi học kế toán ở đại học và giờ đang làm ở phòng tài chính kế toán."}],
  "32": [{"jp":"**所得**が一定額を超えると、税率が上がる。","vi":"Khi thu nhập vượt quá một mức nhất định, thuế suất sẽ tăng."},{"jp":"地方と都市部では、平均**所得**に大きな差がある。","vi":"Giữa nông thôn và thành thị có chênh lệch lớn về thu nhập bình quân."}],
  "33": [{"jp":"今年、我が社は新卒を20人**採用した**。","vi":"Năm nay công ty chúng tôi đã tuyển 20 sinh viên mới tốt nghiệp."},{"jp":"会議で私の企画案が**採用された**。","vi":"Bản kế hoạch của tôi đã được chấp nhận trong cuộc họp."}],
  "34": [{"jp":"その工場は地元の住民を100人**雇用して**いる。","vi":"Nhà máy đó đang thuê 100 lao động là người dân địa phương."},{"jp":"不況の影響で、**雇用**が不安定になっている。","vi":"Do ảnh hưởng của suy thoái, việc làm đang trở nên bấp bênh."}],
  "35": [{"jp":"私は営業部に**所属して**います。","vi":"Tôi thuộc phòng kinh doanh."},{"jp":"彼女は区のボランティア会に**所属し**、清掃活動をしている。","vi":"Cô ấy là thành viên hội tình nguyện của quận và tham gia hoạt động dọn vệ sinh."}],
  "36": [{"jp":"今の会社は**待遇**がいいので、辞めるつもりはない。","vi":"Công ty hiện tại có đãi ngộ tốt nên tôi không định nghỉ việc."},{"jp":"そのホテルでは、常連客は特別な**待遇**を受けられる。","vi":"Ở khách sạn đó, khách quen được hưởng sự tiếp đón đặc biệt."}],
  "37": [{"jp":"政府は被災地に医療チームを**派遣した**。","vi":"Chính phủ đã cử đội y tế đến vùng bị thiên tai."},{"jp":"彼は会社から海外の工場に**派遣された**。","vi":"Anh ấy được công ty cử sang nhà máy ở nước ngoài."}],
  "38": [{"jp":"父は来月から大阪の支店に**赴任する**ことになった。","vi":"Từ tháng sau bố tôi sẽ chuyển công tác đến chi nhánh Osaka."},{"jp":"彼は家族を日本に残して、単身で海外に**赴任した**。","vi":"Anh ấy để gia đình lại Nhật và một mình sang nước ngoài nhận nhiệm vụ."}],
  "39": [{"jp":"大学を卒業した後、**地元**の企業に就職した。","vi":"Sau khi tốt nghiệp đại học, tôi vào làm ở một doanh nghiệp quê nhà."},{"jp":"このお祭りは**地元**の人々に長く愛されている。","vi":"Lễ hội này từ lâu đã được người dân địa phương yêu mến."}],
  "40": [{"jp":"祖父は80歳になった今も**現役**の医師として働いている。","vi":"Ông tôi nay đã 80 tuổi mà vẫn đang hành nghề bác sĩ."},{"jp":"兄は**現役**で東京大学に合格した。","vi":"Anh trai tôi đỗ Đại học Tokyo ngay khi còn là học sinh cấp 3 (không phải thi lại)."}],
  "41": [{"jp":"私は誰からも**指図**を受けるつもりはない。","vi":"Tôi không định nghe theo sự sai khiến của bất kỳ ai."},{"jp":"部長は自分では何もせず、部下に**指図して**ばかりいる。","vi":"Trưởng phòng tự mình chẳng làm gì, chỉ toàn sai bảo cấp dưới."}],
  "42": [{"jp":"彼の夢は旅客機を**操縦する**パイロットになることだ。","vi":"Ước mơ của anh ấy là trở thành phi công lái máy bay chở khách."},{"jp":"彼女は夫を上手に**操縦して**いる。","vi":"Cô ấy khéo léo \"điều khiển\" chồng mình."}],
  "43": [{"jp":"日本人の**主食**は米だ。","vi":"Lương thực chính của người Nhật là gạo."},{"jp":"ヨーロッパではパンを**主食**とする国が多い。","vi":"Ở châu Âu có nhiều nước lấy bánh mì làm lương thực chính."}],
  "44": [{"jp":"**食物**アレルギーがある人は、原材料をよく確認する必要がある。","vi":"Người bị dị ứng thực phẩm cần kiểm tra kỹ nguyên liệu."},{"jp":"野生の動物は**食物**を求めて移動する。","vi":"Động vật hoang dã di chuyển để tìm thức ăn."}],
  "45": [{"jp":"米や小麦、大豆などの**穀物**の価格が高騰している。","vi":"Giá các loại ngũ cốc như gạo, lúa mì, đậu nành đang tăng vọt."},{"jp":"この地域では、昔から**穀物**の栽培が盛んだ。","vi":"Vùng này từ xưa đã phát triển trồng ngũ cốc."}],
  "46": [{"jp":"今年は天候に恵まれ、米は**豊作**だった。","vi":"Năm nay thời tiết thuận lợi nên lúa được mùa."},{"jp":"村の人々は**豊作**を祈って祭りを行う。","vi":"Dân làng tổ chức lễ hội để cầu mùa màng bội thu."}],
  "47": [{"jp":"今年の桜は**例年**より1週間早く咲いた。","vi":"Hoa anh đào năm nay nở sớm hơn mọi năm một tuần."},{"jp":"この祭りには**例年**約10万人の観光客が訪れる。","vi":"Hằng năm lễ hội này đón khoảng 100.000 khách du lịch."}],
  "48": [{"jp":"春になったら、庭にひまわりの**種**をまこう。","vi":"Sang xuân, mình hãy gieo hạt hướng dương ngoài vườn."},{"jp":"息子の進路が最近の悩みの**種**だ。","vi":"Chuyện hướng đi tương lai của con trai là nguồn cơn lo lắng của tôi dạo gần đây."}],
  "49": [{"jp":"バラの**とげ**が指に刺さって血が出た。","vi":"Gai hoa hồng đâm vào ngón tay làm chảy máu."},{"jp":"彼女の言葉には**とげ**があって、聞いていて不愉快だった。","vi":"Lời cô ấy nói có gai, nghe thật khó chịu."}],
  "50": [{"jp":"このきのこには**毒**があるので、絶対に食べないでください。","vi":"Loại nấm này có độc, tuyệt đối đừng ăn."},{"jp":"タバコは吸う人だけでなく、周りの人にも**毒**だ。","vi":"Thuốc lá có hại không chỉ cho người hút mà cả người xung quanh."}],
  "51": [{"jp":"誰が司会をするか、**くじ**で決めよう。","vi":"Ai làm người dẫn chương trình thì mình bốc thăm quyết định nhé."},{"jp":"福引きで**くじ**を引いたら、一等が当たった。","vi":"Rút thăm trúng thưởng, tôi trúng giải nhất."}],
  "52": [{"jp":"値段の**桁**を一つ見間違えて、驚いた。","vi":"Tôi nhìn nhầm giá mất một chữ số nên giật cả mình."},{"jp":"彼の年収は私とは**桁**が違う。","vi":"Thu nhập năm của anh ấy khác tôi cả một hàng số (hơn hẳn)."}],
  "53": [{"jp":"メートルは長さの**単位**だ。","vi":"Mét là đơn vị đo chiều dài."},{"jp":"家族は社会を構成する最小の**単位**だ。","vi":"Gia đình là đơn vị nhỏ nhất cấu thành xã hội."}],
  "54": [{"jp":"車の代金を**一括**で支払った。","vi":"Tôi đã trả tiền xe một lần."},{"jp":"各支店の注文は、本社で**一括して**管理している。","vi":"Đơn hàng của các chi nhánh được trụ sở chính quản lý tập trung."}],
  "55": [{"jp":"牛肉の**塊**をオーブンで焼いた。","vi":"Tôi nướng tảng thịt bò trong lò."},{"jp":"彼は好奇心の**固まり**のような人だ。","vi":"Anh ấy là người tò mò từ đầu đến chân (như một khối tò mò)."}],
  "56": [{"jp":"このスカートは**丈**が少し長いので、短くしてもらった。","vi":"Chiếc váy này hơi dài nên tôi nhờ cắt ngắn lại."},{"jp":"空き地の草が人の**丈**ほどにも伸びていた。","vi":"Cỏ ở bãi đất trống đã mọc cao ngang tầm người."}],
  "57": [{"jp":"申込書の太枠の**欄**に記入してください。","vi":"Hãy điền vào các ô viền đậm trong đơn đăng ký."},{"jp":"父は毎朝、新聞のスポーツ**欄**から読む。","vi":"Mỗi sáng bố tôi đọc mục thể thao trên báo trước tiên."}],
  "58": [{"jp":"部屋の**隅**にほこりがたまっている。","vi":"Bụi bám đầy ở góc phòng."},{"jp":"彼女はパーティーの間、ずっと会場の**隅**に一人で立っていた。","vi":"Suốt buổi tiệc, cô ấy đứng một mình ở góc hội trường."}],
  "59": [{"jp":"眼鏡の**縁**が壊れてしまった。","vi":"Gọng (viền) kính của tôi bị hỏng mất rồi."},{"jp":"コップの**縁**が欠けているので、気をつけて。","vi":"Miệng cốc bị mẻ nên cẩn thận nhé."}],
  "60": [{"jp":"地震で壁に**ひび**が入った。","vi":"Trận động đất làm tường bị nứt."},{"jp":"些細な誤解から、二人の友情に**ひび**が入った。","vi":"Chỉ vì một hiểu lầm nhỏ, tình bạn của hai người đã rạn nứt."}],
  "61": [{"jp":"意見の対立から、党が二つに**分裂した**。","vi":"Do bất đồng ý kiến, đảng đã chia tách làm hai."},{"jp":"細胞は**分裂**を繰り返して増えていく。","vi":"Tế bào tăng lên bằng cách phân chia liên tục."}],
  "62": [{"jp":"大型トラックが通るたびに、窓ガラスが**振動する**。","vi":"Mỗi lần xe tải lớn chạy qua, kính cửa sổ lại rung lên."},{"jp":"マナーモードにすると、着信を**振動**で知らせてくれる。","vi":"Khi để chế độ im lặng, điện thoại sẽ báo cuộc gọi đến bằng rung."}],
  "63": [{"jp":"お湯が**沸騰したら**、パスタを入れてください。","vi":"Khi nước sôi thì cho mì Ý vào."},{"jp":"その事件をきっかけに、世論が**沸騰した**。","vi":"Sự việc đó đã làm dư luận sôi sục."}],
  "64": [{"jp":"運動をすると、血液が体中を**循環する**。","vi":"Khi vận động, máu tuần hoàn khắp cơ thể."},{"jp":"このバスは市内を**循環して**いる。","vi":"Xe buýt này chạy vòng quanh nội thành."}],
  "65": [{"jp":"使用済みのペットボトルは、毎週水曜日に**回収される**。","vi":"Chai nhựa đã qua sử dụng được thu gom vào thứ Tư hằng tuần."},{"jp":"メーカーは欠陥が見つかった商品を**回収した**。","vi":"Nhà sản xuất đã thu hồi sản phẩm bị phát hiện lỗi."}],
  "66": [{"jp":"彼女はオリンピックで金メダルを**獲得した**。","vi":"Cô ấy đã giành huy chương vàng tại Thế vận hội."},{"jp":"国民は長い闘争の末に自由を**獲得した**。","vi":"Sau cuộc đấu tranh lâu dài, nhân dân đã giành được tự do."}],
  "67": [{"jp":"この電車は東京から横浜までの**区間**で各駅に停車する。","vi":"Đoàn tàu này dừng ở tất cả các ga trên đoạn từ Tokyo đến Yokohama."},{"jp":"大雪のため、一部の**区間**で運転を見合わせている。","vi":"Do tuyết rơi dày, tàu tạm ngừng chạy ở một số đoạn."}],
  "68": [{"jp":"この町には図書館や体育館などの公共**施設**が充実している。","vi":"Thị trấn này có đầy đủ công trình công cộng như thư viện, nhà thi đấu."},{"jp":"祖母は介護**施設**に入居している。","vi":"Bà tôi đang ở trong một cơ sở chăm sóc người cao tuổi."}],
  "69": [{"jp":"学生たちが中心となって学園祭を**運営して**いる。","vi":"Sinh viên đóng vai trò chính trong việc điều hành lễ hội trường."},{"jp":"彼は地方で小さな学校を**運営して**いる。","vi":"Anh ấy đang điều hành một ngôi trường nhỏ ở địa phương."}],
  "70": [{"jp":"首相は来日した大統領と**面会した**。","vi":"Thủ tướng đã hội kiến tổng thống đang thăm Nhật Bản."},{"jp":"入院中の父は、まだ家族としか**面会**できない。","vi":"Bố tôi đang nằm viện, hiện vẫn chỉ được gặp người nhà."}],
  "71": [{"jp":"図書館の本は2週間以内に**返却して**ください。","vi":"Sách thư viện vui lòng trả lại trong vòng 2 tuần."},{"jp":"レンタカーは満タンにしてから**返却する**ことになっている。","vi":"Xe thuê phải đổ đầy bình xăng rồi mới trả lại."}],
  "72": [{"jp":"彼は駅前の騒音について新聞に**投書した**。","vi":"Anh ấy đã gửi thư cho báo về tình trạng ồn ào trước nhà ga."},{"jp":"市民からの**投書**をきっかけに、公園のルールが見直された。","vi":"Nhờ thư góp ý của người dân, nội quy công viên đã được xem xét lại."}],
  "73": [{"jp":"わからない言葉は、インターネットで**検索する**と便利だ。","vi":"Từ nào không hiểu thì tra trên Internet rất tiện."},{"jp":"このシステムでは、過去10年分のデータを**検索**できる。","vi":"Hệ thống này cho phép tra cứu dữ liệu của 10 năm qua."}],
  "74": [{"jp":"彼は試合中に足を**負傷し**、途中で退場した。","vi":"Anh ấy bị thương ở chân trong trận đấu và phải rời sân giữa chừng."},{"jp":"交通事故で3人が**負傷した**。","vi":"Vụ tai nạn giao thông làm 3 người bị thương."}],
  "75": [{"jp":"インフルエンザに**感染しない**よう、手洗いを徹底しよう。","vi":"Hãy rửa tay kỹ để không bị nhiễm cúm."},{"jp":"パソコンがウイルスに**感染して**、データが消えてしまった。","vi":"Máy tính bị nhiễm virus nên dữ liệu đã bị mất."}],
  "76": [{"jp":"この薬は神経に**作用して**痛みを抑える。","vi":"Thuốc này tác động lên thần kinh để giảm đau."},{"jp":"月の引力が海水に**作用して**、潮の満ち引きが起こる。","vi":"Lực hấp dẫn của Mặt Trăng tác động lên nước biển gây ra thủy triều."}],
  "77": [{"jp":"彼は大人になっても経済的に親に**依存して**いる。","vi":"Anh ta đã trưởng thành mà vẫn phụ thuộc kinh tế vào bố mẹ."},{"jp":"日本はエネルギーの多くを輸入に**依存して**いる。","vi":"Nhật Bản phụ thuộc phần lớn năng lượng vào nhập khẩu."}],
  "78": [{"jp":"運動はストレスを**解消する**のに効果的だ。","vi":"Vận động rất hiệu quả để giải tỏa căng thẳng."},{"jp":"二人は性格の不一致から婚約を**解消した**。","vi":"Hai người đã hủy hôn ước vì không hợp tính nhau."}],
  "79": [{"jp":"政府は再生可能エネルギーの普及を**促進して**いる。","vi":"Chính phủ đang thúc đẩy việc phổ cập năng lượng tái tạo."},{"jp":"両国は貿易を**促進する**ための協定を結んだ。","vi":"Hai nước đã ký hiệp định nhằm thúc đẩy thương mại."}],
  "80": [{"jp":"社長は今年度で引退する**意向**を示した。","vi":"Giám đốc đã bày tỏ ý định nghỉ hưu vào cuối năm tài chính này."},{"jp":"住民の**意向**を無視して計画を進めるべきではない。","vi":"Không nên phớt lờ nguyện vọng của người dân mà cứ tiến hành kế hoạch."}],
  "81": [{"jp":"筆者がこの文章で**意図して**いることを読み取りなさい。","vi":"Hãy đọc hiểu điều tác giả muốn nhắm tới trong đoạn văn này."},{"jp":"彼の発言の**意図**がよくわからない。","vi":"Tôi không hiểu rõ ý đồ trong phát ngôn của anh ta."}],
  "82": [{"jp":"経済成長によって、国民の生活水準が**向上した**。","vi":"Nhờ tăng trưởng kinh tế, mức sống của người dân đã được nâng cao."},{"jp":"毎日練習を重ねた結果、技術が大きく**向上した**。","vi":"Nhờ luyện tập mỗi ngày, kỹ thuật đã tiến bộ rõ rệt."}],
  "83": [{"jp":"朝の市場は**活気**にあふれている。","vi":"Khu chợ buổi sáng tràn đầy sức sống."},{"jp":"新入生が入ってきて、クラブに**活気**が出てきた。","vi":"Có tân sinh viên gia nhập, câu lạc bộ trở nên sôi động hẳn."}],
  "84": [{"jp":"大画面で見る映画は**迫力**が違う。","vi":"Phim xem trên màn hình lớn có sức cuốn hút khác hẳn."},{"jp":"彼の演説には聴衆を圧倒する**迫力**があった。","vi":"Bài diễn thuyết của ông ấy có sức mạnh áp đảo người nghe."}],
  "85": [{"jp":"我がチームは決勝戦で3対1で**勝利した**。","vi":"Đội chúng tôi đã thắng 3-1 trong trận chung kết."},{"jp":"彼は大統領選挙で圧倒的な**勝利**を収めた。","vi":"Ông ấy giành thắng lợi áp đảo trong cuộc bầu cử tổng thống."}],
  "86": [{"jp":"人間は新しい環境にも徐々に**適応して**いく。","vi":"Con người dần dần thích ứng cả với môi trường mới."},{"jp":"生物は長い時間をかけて気候の変化に**適応して**きた。","vi":"Sinh vật đã thích nghi với biến đổi khí hậu qua thời gian dài."}],
  "87": [{"jp":"この建物は周りの自然と**調和して**いる。","vi":"Tòa nhà này hài hòa với thiên nhiên xung quanh."},{"jp":"チームで働くには、人との**調和**を大切にすることが必要だ。","vi":"Làm việc theo nhóm cần coi trọng sự hòa hợp với mọi người."}],
  "88": [{"jp":"彼は**権力**を握ると、反対派を次々に追放した。","vi":"Khi nắm được quyền lực, ông ta lần lượt trục xuất phe đối lập."},{"jp":"メディアには国家**権力**を監視する役割がある。","vi":"Truyền thông có vai trò giám sát quyền lực nhà nước."}],
  "89": [{"jp":"彼は心臓外科の**権威**として世界的に知られている。","vi":"Ông ấy nổi tiếng thế giới là bậc thầy về phẫu thuật tim."},{"jp":"度重なる不祥事で、政府の**権威**は失墜した。","vi":"Do bê bối liên tiếp, uy tín của chính phủ đã sụp đổ."}],
  "90": [{"jp":"急激な物価高が家計を**圧迫して**いる。","vi":"Giá cả tăng đột ngột đang đè nặng lên kinh tế gia đình."},{"jp":"大きな腫瘍が神経を**圧迫し**、激しい痛みを引き起こしている。","vi":"Khối u lớn chèn ép dây thần kinh, gây đau dữ dội."}],
  "91": [{"jp":"参加は自由です。**強制**はしません。","vi":"Tham gia là tự do. Chúng tôi không ép buộc."},{"jp":"会社が社員に残業を**強制する**のは問題だ。","vi":"Công ty ép nhân viên làm thêm giờ là có vấn đề."}],
  "92": [{"jp":"政府は排気ガスの排出を厳しく**規制して**いる。","vi":"Chính phủ quy định hạn chế nghiêm ngặt việc thải khí thải."},{"jp":"マラソン大会のため、今日は市内で交通**規制**が行われる。","vi":"Vì giải marathon, hôm nay nội thành có hạn chế giao thông."}],
  "93": [{"jp":"組合は会社側の提案を**拒否した**。","vi":"Công đoàn đã bác bỏ đề xuất của phía công ty."},{"jp":"その子は学校に行くことを**拒否して**いる。","vi":"Đứa trẻ đó đang từ chối đến trường."}],
  "94": [{"jp":"大手スーパーに**対抗する**ため、商店街は値下げを始めた。","vi":"Để cạnh tranh với siêu thị lớn, khu phố buôn bán bắt đầu giảm giá."},{"jp":"明日はクラス**対抗**のリレー大会がある。","vi":"Ngày mai có cuộc thi chạy tiếp sức giữa các lớp."}],
  "95": [{"jp":"市民たちは増税に**抗議して**デモを行った。","vi":"Người dân biểu tình phản đối việc tăng thuế."},{"jp":"選手は審判の判定に激しく**抗議した**。","vi":"Cầu thủ phản đối kịch liệt quyết định của trọng tài."}],
  "96": [{"jp":"その政党は古い政治を**革新する**ことを訴えている。","vi":"Đảng đó kêu gọi đổi mới nền chính trị cũ."},{"jp":"技術**革新**によって、私たちの生活は大きく変わった。","vi":"Nhờ đổi mới công nghệ, cuộc sống của chúng ta đã thay đổi lớn."}],
  "97": [{"jp":"この会社では、**原則**として残業は禁止されている。","vi":"Ở công ty này, về nguyên tắc làm thêm giờ bị cấm."},{"jp":"多数決は民主主義の基本的な**原則**の一つだ。","vi":"Biểu quyết theo đa số là một trong những nguyên tắc cơ bản của dân chủ."}],
  "98": [{"jp":"事故から3か月が**経過した**が、原因はまだわかっていない。","vi":"Đã 3 tháng trôi qua kể từ vụ tai nạn nhưng vẫn chưa rõ nguyên nhân."},{"jp":"手術後の**経過**は順調だ。","vi":"Diễn biến sau phẫu thuật thuận lợi."}],
  "99": [{"jp":"オリンピックの開会式は世界中に生**中継された**。","vi":"Lễ khai mạc Thế vận hội được truyền hình trực tiếp ra toàn thế giới."},{"jp":"国会の審議をテレビで**中継して**いる。","vi":"Phiên thảo luận của Quốc hội đang được truyền hình trực tiếp."}],
  "100": [{"jp":"その会社は従業員1万人を超える大**規模**な企業だ。","vi":"Đó là một doanh nghiệp quy mô lớn với hơn 10.000 nhân viên."},{"jp":"発掘された遺跡は、予想をはるかに超える**規模**だった。","vi":"Di tích được khai quật có quy mô vượt xa dự đoán."}],
  "101": [{"jp":"彼は眠そうに目を**擦って**いた。","vi":"Anh ấy dụi mắt vẻ buồn ngủ."},{"jp":"寒いので、両手を**擦り**合わせて温めた。","vi":"Vì lạnh nên tôi xoa hai tay vào nhau cho ấm."}],
  "102": [{"jp":"気分が悪そうな友人の背中を、そっと**擦って**あげた。","vi":"Tôi nhẹ nhàng xoa lưng cho người bạn trông có vẻ khó chịu."},{"jp":"祖母はひざを**擦り**ながら、「雨が降りそうだ」と言った。","vi":"Bà vừa xoa đầu gối vừa nói: \"Trời sắp mưa rồi\"."}],
  "103": [{"jp":"彼は猫の頭を**撫でた**。","vi":"Anh ấy vuốt ve đầu con mèo."},{"jp":"春の風が頬を**撫でて**いった。","vi":"Làn gió xuân khẽ vuốt qua má."}],
  "104": [{"jp":"彼女は緊張すると、髪を**いじる**癖がある。","vi":"Cô ấy có tật hay mân mê tóc khi căng thẳng."},{"jp":"文章を**いじり**すぎて、かえってわかりにくくなった。","vi":"Sửa câu văn quá nhiều, kết quả lại càng khó hiểu."}],
  "105": [{"jp":"鍋のスープをお玉でゆっくり**かき回した**。","vi":"Tôi dùng muôi khuấy nhẹ nồi súp."},{"jp":"鍵を探して引き出しの中を**かき回した**。","vi":"Tôi lục tung ngăn kéo để tìm chìa khóa."}],
  "106": [{"jp":"野原で花を**摘んで**花束を作った。","vi":"Tôi hái hoa ngoài đồng và kết thành bó."},{"jp":"この地方では、5月になると新茶を**摘む**。","vi":"Ở vùng này, đến tháng 5 người ta hái chè mới."}],
  "107": [{"jp":"彼は皿のクッキーを一つ**摘んで**口に入れた。","vi":"Anh ấy nhón một chiếc bánh quy trên đĩa cho vào miệng."},{"jp":"ごみ置き場のひどい臭いに、思わず鼻を**摘んだ**。","vi":"Mùi kinh khủng ở bãi rác khiến tôi bất giác bịt mũi."}],
  "108": [{"jp":"転びそうになって、思わず手すりを**掴んだ**。","vi":"Suýt ngã, tôi bất giác nắm lấy tay vịn."},{"jp":"彼はついに成功のチャンスを**掴んだ**。","vi":"Cuối cùng anh ấy đã nắm bắt được cơ hội thành công."}],
  "109": [{"jp":"ネクタイが**捻じれて**いるよ。直してあげる。","vi":"Cà vạt bị xoắn rồi kìa. Để mình chỉnh cho."},{"jp":"ホースが**捻じれて**、水が出なくなった。","vi":"Ống nước bị xoắn nên nước không chảy ra."}],
  "110": [{"jp":"固いびんのふたを力いっぱい**捻じって**開けた。","vi":"Tôi dùng hết sức vặn mở chiếc nắp lọ bị chặt."},{"jp":"警官は強盗の腕を**捻じり**上げた。","vi":"Viên cảnh sát vặn ngược tay tên cướp."}],
  "111": [{"jp":"蛇口を**捻る**と、お湯が出てきた。","vi":"Vặn vòi thì nước nóng chảy ra."},{"jp":"難しい問題に、彼は首を**捻った**。","vi":"Trước câu hỏi khó, anh ấy nghiêng đầu suy nghĩ."}],
  "112": [{"jp":"強く引っ張ったら、ひもが**ちぎれて**しまった。","vi":"Kéo mạnh quá nên sợi dây bị đứt."},{"jp":"強風で、旗が**ちぎれ**そうなほどはためいている。","vi":"Gió mạnh làm lá cờ bay phần phật như sắp rách."}],
  "113": [{"jp":"レタスを手で**ちぎって**サラダに入れる。","vi":"Xé rau xà lách bằng tay rồi cho vào salad."},{"jp":"彼女は怒って、手紙を細かく**ちぎった**。","vi":"Cô ấy tức giận xé vụn lá thư."}],
  "114": [{"jp":"古新聞をひもで**束ねて**、資源ごみに出した。","vi":"Tôi buộc báo cũ bằng dây rồi đem bỏ vào rác tái chế."},{"jp":"彼は100人の部下を**束ねる**部長だ。","vi":"Ông ấy là trưởng phòng quản lý 100 cấp dưới."}],
  "115": [{"jp":"暑かったので、うちわで顔を**扇いだ**。","vi":"Trời nóng nên tôi lấy quạt nan quạt mặt."},{"jp":"炭火を**扇いで**火を強くした。","vi":"Tôi quạt bếp than cho lửa cháy to hơn."}],
  "116": [{"jp":"昔は毎朝、井戸から水を**くんで**いた。","vi":"Ngày xưa, sáng nào người ta cũng múc nước từ giếng."},{"jp":"山の湧き水をペットボトルに**くんで**持ち帰った。","vi":"Tôi múc nước suối trên núi vào chai mang về."}],
  "117": [{"jp":"彼はたばこを**銜えた**まま話し始めた。","vi":"Anh ta vẫn ngậm điếu thuốc mà bắt đầu nói."},{"jp":"犬が新聞を**銜えて**戻ってきた。","vi":"Con chó ngậm tờ báo chạy về."}],
  "118": [{"jp":"子供がソフトクリームを**舐めて**いる。","vi":"Đứa trẻ đang liếm kem ốc quế."},{"jp":"相手を**舐めて**かかると、痛い目にあうぞ。","vi":"Coi thường đối thủ thì sẽ chuốc lấy thất bại đấy."}],
  "119": [{"jp":"先生に叱られて、彼は**俯いた**まま黙っていた。","vi":"Bị thầy mắng, cậu ấy cúi gằm mặt im lặng."},{"jp":"水をやり忘れて、花が**俯いて**しまった。","vi":"Quên tưới nước nên hoa đã héo rũ xuống."}],
  "120": [{"jp":"赤ちゃんが**這って**母親のところへ行った。","vi":"Em bé bò đến chỗ mẹ."},{"jp":"古い洋館の壁にはつたが**這って**いる。","vi":"Dây thường xuân bò kín tường tòa nhà kiểu Tây cũ."}],
  "121": [{"jp":"神社の鳥居を**潜る**と、空気が変わった気がした。","vi":"Bước qua cổng torii của đền, tôi cảm thấy không khí như thay đổi."},{"jp":"彼は法の網を**潜って**不正な利益を得ていた。","vi":"Hắn ta lách lưới pháp luật để thu lợi bất chính."}],
  "122": [{"jp":"彼は彼女の耳元で「好きだ」と**囁いた**。","vi":"Anh ấy thì thầm \"anh yêu em\" bên tai cô."},{"jp":"社内では、社長の辞任が**囁かれて**いる。","vi":"Trong công ty đang rỉ tai nhau chuyện giám đốc từ chức."}],
  "123": [{"jp":"酔っ払いが駅のホームで大声で**喚いて**いた。","vi":"Một gã say rượu đang gào thét trên sân ga."},{"jp":"子供は泣き**喚いて**、おもちゃを買ってくれとせがんだ。","vi":"Đứa trẻ khóc lóc ầm ĩ, vòi mua đồ chơi."}],
  "124": [{"jp":"いたずらをしたら、お母さんに**言いつける**からね。","vi":"Nghịch ngợm là chị mách mẹ đấy."},{"jp":"父は私に庭の掃除を**言いつけた**。","vi":"Bố sai tôi dọn vườn."}],
  "125": [{"jp":"彼は長年の悩みを親友に**打ち明けた**。","vi":"Anh ấy đã thổ lộ nỗi trăn trở bao năm với người bạn thân."},{"jp":"彼女は過去の過ちを夫に**打ち明ける**決心をした。","vi":"Cô ấy quyết định thú nhận lỗi lầm trong quá khứ với chồng."}],
  "126": [{"jp":"最近、この辺で外国人観光客をよく**見かける**。","vi":"Dạo này tôi hay thấy khách du lịch nước ngoài quanh đây."},{"jp":"昨日、駅前で偶然先生を**見かけた**。","vi":"Hôm qua tôi tình cờ nhìn thấy thầy giáo trước nhà ga."}],
  "127": [{"jp":"ひよこのオスとメスを**見分ける**のは難しい。","vi":"Phân biệt gà con trống hay mái rất khó."},{"jp":"本物と偽物を**見分ける**目を養いたい。","vi":"Tôi muốn rèn con mắt phân biệt hàng thật và hàng giả."}],
  "128": [{"jp":"山頂からは町全体が**見渡せる**。","vi":"Từ đỉnh núi có thể nhìn bao quát toàn bộ thị trấn."},{"jp":"彼は会場を**見渡して**、知り合いを探した。","vi":"Anh ấy nhìn khắp hội trường để tìm người quen."}],
  "129": [{"jp":"大事なメールを**見落として**いて、返事が遅れてしまった。","vi":"Tôi bỏ sót email quan trọng nên trả lời muộn."},{"jp":"検査で小さな異常を**見落とさない**よう、慎重に確認する。","vi":"Kiểm tra thận trọng để không bỏ sót bất thường nhỏ nào."}],
  "130": [{"jp":"電車で寝てしまい、降りる駅を**乗り過ごした**。","vi":"Ngủ quên trên tàu nên tôi đã đi quá ga cần xuống."},{"jp":"スマホに夢中になっていて、バス停を2つも**乗り過ごして**しまった。","vi":"Mải mê điện thoại nên tôi đi quá những 2 trạm xe buýt."}],
  "131": [{"jp":"多くの困難を**乗り越えて**、彼はついに夢を実現させた。","vi":"Vượt qua bao khó khăn, cuối cùng anh ấy đã biến ước mơ thành hiện thực."},{"jp":"家族の支えがあったからこそ、母を亡くした悲しみを**乗り越える**ことができた。","vi":"Chính nhờ sự nâng đỡ của gia đình mà tôi đã vượt qua được nỗi đau mất mẹ."}],
  "132": [{"jp":"彼は医師として地域医療に尽くす道を**歩んで**きた。","vi":"Anh ấy đã bước đi trên con đường cống hiến cho y tế địa phương với tư cách bác sĩ."},{"jp":"戦後、この国は平和国家としての道を**歩み**続けてきた。","vi":"Sau chiến tranh, đất nước này đã không ngừng bước đi trên con đường của một quốc gia hòa bình."}],
  "133": [{"jp":"この電池は一度充電すれば、丸一日**もつ**。","vi":"Pin này sạc một lần là dùng được trọn một ngày."},{"jp":"こんなに無理な働き方を続けていたら、体が**もたない**よ。","vi":"Cứ làm việc quá sức thế này thì cơ thể không chịu nổi đâu."}],
  "134": [{"jp":"室内の温度を20度に**保つ**よう設定してある。","vi":"Máy đã được cài đặt để giữ nhiệt độ trong phòng ở 20 độ."},{"jp":"祖母は毎日散歩を欠かさず、80歳を過ぎても健康を**保って**いる。","vi":"Bà tôi ngày nào cũng đi dạo, dù đã ngoài 80 vẫn giữ được sức khỏe."}],
  "135": [{"jp":"戦国時代、この山の上に城が**築かれた**。","vi":"Thời Chiến Quốc, một tòa thành đã được xây trên ngọn núi này."},{"jp":"取引先との信頼関係を**築く**には長い時間がかかる。","vi":"Để gây dựng quan hệ tin cậy với đối tác cần rất nhiều thời gian."}],
  "136": [{"jp":"彼女が来てから、職場に笑い声が**絶えない**。","vi":"Từ khi cô ấy đến, nơi làm việc lúc nào cũng rộn tiếng cười."},{"jp":"留学した友人からの連絡が、半年前から**絶えて**いる。","vi":"Liên lạc từ người bạn đi du học đã bặt từ nửa năm trước."}],
  "137": [{"jp":"健康のために、父はきっぱりと酒を**断った**。","vi":"Vì sức khỏe, bố tôi đã dứt khoát bỏ rượu."},{"jp":"その記者は取材中に消息を**絶った**。","vi":"Phóng viên ấy đã bặt vô âm tín trong lúc đi lấy tin."}],
  "138": [{"jp":"深夜になると、この通りは人通りが**途切れる**。","vi":"Về khuya, con phố này vắng hẳn người qua lại."},{"jp":"電波が悪くて、電話の声が時々**途切れた**。","vi":"Sóng yếu nên tiếng trong điện thoại thỉnh thoảng bị đứt quãng."}],
  "139": [{"jp":"大雪のため、山の村との通信が**途絶えた**。","vi":"Do tuyết lớn, liên lạc với ngôi làng trên núi đã bị cắt đứt."},{"jp":"息子が家を出てから、仕送りが**途絶えて**しまった。","vi":"Từ khi con trai rời nhà, khoản tiền gửi về đã ngưng hẳn."}],
  "140": [{"jp":"裁判所から被告に有罪の判決が**下った**。","vi":"Tòa án đã tuyên án có tội đối với bị cáo."},{"jp":"ボートで川を**下り**ながら、両岸の紅葉を楽しんだ。","vi":"Vừa đi thuyền xuôi dòng sông, chúng tôi vừa ngắm lá đỏ hai bên bờ."}],
  "141": [{"jp":"十分な議論を経て、委員会は最終的な結論を**下した**。","vi":"Sau khi thảo luận kỹ, ủy ban đã đưa ra kết luận cuối cùng."},{"jp":"決勝で彼は前回の王者を**下し**、初優勝を果たした。","vi":"Ở trận chung kết, anh ấy đã hạ nhà vô địch kỳ trước và lần đầu đăng quang."}],
  "142": [{"jp":"池のほとりで、柳の枝が水面すれすれまで**垂れて**いる。","vi":"Bên bờ ao, cành liễu rủ xuống sát mặt nước."},{"jp":"雨上がりの軒先から、水滴がぽたぽたと**垂れて**いた。","vi":"Sau cơn mưa, những giọt nước nhỏ tí tách từ mái hiên."}],
  "143": [{"jp":"夏になると、庭の木々が青々と**茂る**。","vi":"Đến mùa hè, cây cối trong vườn xanh tốt um tùm."},{"jp":"長年誰も住んでいない家の周りには、雑草が**茂って**いた。","vi":"Quanh ngôi nhà nhiều năm không ai ở, cỏ dại mọc um tùm."}],
  "144": [{"jp":"春になると、農家の人々は田畑を**耕し**始める。","vi":"Đến mùa xuân, nhà nông bắt đầu cày xới ruộng vườn."},{"jp":"定年後、父は田舎に土地を借りて、自分で畑を**耕して**いる。","vi":"Sau khi nghỉ hưu, bố tôi thuê đất ở quê và tự mình cày cấy."}],
  "145": [{"jp":"留学経験を**生かして**、通訳の仕事に就いた。","vi":"Phát huy kinh nghiệm du học, tôi đã làm nghề phiên dịch."},{"jp":"この料理は調味料を控え、素材の味を**生かして**いる。","vi":"Món ăn này hạn chế gia vị để phát huy vị tự nhiên của nguyên liệu."}],
  "146": [{"jp":"彼は地方への転勤を**拒んで**、会社を辞めた。","vi":"Anh ấy từ chối chuyển công tác về địa phương và đã nghỉ việc."},{"jp":"容疑者は警察の取り調べに対して証言を**拒み**続けている。","vi":"Nghi phạm tiếp tục từ chối khai báo trước sự thẩm vấn của cảnh sát."}],
  "147": [{"jp":"会社の都合で、多くの社員が単身赴任を**強いられて**いる。","vi":"Vì hoàn cảnh công ty, nhiều nhân viên bị buộc phải đi công tác xa một mình."},{"jp":"上司が部下に飲酒を**強いる**のはハラスメントにあたる。","vi":"Cấp trên ép cấp dưới uống rượu là hành vi quấy rối."}],
  "148": [{"jp":"医者に飲酒を**禁じられて**から、父は一滴も飲んでいない。","vi":"Từ khi bị bác sĩ cấm uống rượu, bố tôi không uống một giọt nào."},{"jp":"この美術館では、館内での撮影が**禁じられて**いる。","vi":"Bảo tàng mỹ thuật này cấm chụp ảnh bên trong."}],
  "149": [{"jp":"全国から集まった料理人たちが腕を**競った**。","vi":"Các đầu bếp từ khắp cả nước tụ hội để so tài."},{"jp":"二つの企業が新製品の開発で先を**競って**いる。","vi":"Hai doanh nghiệp đang tranh nhau đi trước trong việc phát triển sản phẩm mới."}],
  "150": [{"jp":"小学生の息子に将棋で**負かされて**しまった。","vi":"Tôi bị cậu con trai đang học tiểu học đánh bại trong ván cờ shogi."},{"jp":"彼は議論で相手を**負かす**ことばかり考えている。","vi":"Anh ta lúc nào cũng chỉ nghĩ đến chuyện đánh bại đối phương trong tranh luận."}],
  "151": [{"jp":"ヒーローが悪者を**やっつける**場面で、子供たちは歓声を上げた。","vi":"Đến cảnh siêu anh hùng hạ gục kẻ xấu, bọn trẻ reo hò."},{"jp":"残りの仕事は、今夜中に**やっつけて**しまおう。","vi":"Phần việc còn lại, hãy giải quyết cho xong ngay trong tối nay."}],
  "152": [{"jp":"彼は合格を目指して、毎日勉強に**励んで**いる。","vi":"Anh ấy đang chăm chỉ học tập mỗi ngày với mục tiêu thi đỗ."},{"jp":"退職後も、教授は研究に**励み**続けている。","vi":"Dù đã nghỉ hưu, giáo sư vẫn miệt mài nghiên cứu."}],
  "153": [{"jp":"この絵は、子供の表情の特徴をよく**捉えて**いる。","vi":"Bức tranh này nắm bắt rất tốt đặc điểm nét mặt của đứa trẻ."},{"jp":"彼の演説は聴衆の心をしっかりと**捉えた**。","vi":"Bài diễn thuyết của anh ấy đã chinh phục được lòng người nghe."}],
  "154": [{"jp":"警察は逃走中の犯人をついに**捕らえた**。","vi":"Cảnh sát cuối cùng đã bắt được tên tội phạm đang lẩn trốn."},{"jp":"畑を荒らしていたイノシシが罠で**捕らえられた**。","vi":"Con lợn rừng phá hoại ruộng đã bị bắt bằng bẫy."}],
  "155": [{"jp":"彼は怪我をした右足を**庇い**ながら歩いていた。","vi":"Anh ấy vừa đi vừa che chở cái chân phải bị thương."},{"jp":"母親は悪いことをした息子を**庇って**、嘘をついた。","vi":"Người mẹ bao che cho đứa con làm điều xấu và đã nói dối."}],
  "156": [{"jp":"子供の頃、背が低いことをよく**からかわれた**。","vi":"Hồi nhỏ, tôi hay bị trêu vì thấp."},{"jp":"冗談のつもりでも、人の失敗を**からかう**のはよくない。","vi":"Dù chỉ định đùa, trêu chọc thất bại của người khác là không hay."}],
  "157": [{"jp":"大型の台風が九州地方を**襲った**。","vi":"Một cơn bão lớn đã đổ bộ vào vùng Kyushu."},{"jp":"ライオンは群れの中の弱った獲物を**襲う**。","vi":"Sư tử tấn công con mồi yếu trong đàn."}],
  "158": [{"jp":"先生が質問すると、教室のあちこちで手が**挙がった**。","vi":"Khi thầy giáo đặt câu hỏi, khắp lớp có nhiều cánh tay giơ lên."},{"jp":"次期社長候補として、彼の名前が**挙がって**いる。","vi":"Tên anh ấy đang được nêu ra như một ứng viên giám đốc kế nhiệm."}],
  "159": [{"jp":"具体的な例を**挙げて**説明してください。","vi":"Hãy nêu ví dụ cụ thể để giải thích."},{"jp":"二人は来月、故郷の神社で結婚式を**挙げる**予定だ。","vi":"Tháng sau hai người dự định tổ chức lễ cưới tại đền thần ở quê."}],
  "160": [{"jp":"店が忙しくなったので、アルバイトを3人**雇った**。","vi":"Cửa hàng trở nên bận rộn nên tôi đã thuê 3 người làm thêm."},{"jp":"現地では通訳を**雇って**取材を進めた。","vi":"Ở địa phương, chúng tôi thuê phiên dịch để tiến hành lấy tin."}],
  "161": [{"jp":"彼は一人で働いて家族5人を**養って**いる。","vi":"Anh ấy một mình đi làm nuôi cả gia đình 5 người."},{"jp":"新聞の社説を毎日読むことで、読解力を**養う**ことができる。","vi":"Đọc xã luận báo mỗi ngày có thể bồi dưỡng năng lực đọc hiểu."}],
  "162": [{"jp":"国道と県道が**交わる**地点に、新しい道の駅ができた。","vi":"Tại điểm giao nhau giữa quốc lộ và tỉnh lộ, một trạm dừng chân mới đã được xây."},{"jp":"留学中、さまざまな国の人々と**交わり**、視野が広がった。","vi":"Trong thời gian du học, tôi giao lưu với người từ nhiều quốc gia và mở rộng tầm nhìn."}],
  "163": [{"jp":"彼はユーモアを**交えながら**、難しい話を分かりやすく説明した。","vi":"Anh ấy vừa pha chút hài hước vừa giải thích dễ hiểu một chủ đề khó."},{"jp":"仕事に私情を**交える**べきではない。","vi":"Không nên để tình cảm riêng xen vào công việc."}],
  "164": [{"jp":"息子は上京してから、めったに便りを**よこさない**。","vi":"Từ khi lên Tokyo, con trai tôi hiếm khi gửi tin về."},{"jp":"急用ができたので、会社が迎えの車を**よこして**くれた。","vi":"Vì có việc gấp nên công ty đã cho xe đến đón tôi."}],
  "165": [{"jp":"締め切りが迫っているのに全然進まず、**焦って**いる。","vi":"Hạn chót đã cận kề mà chẳng tiến triển gì, tôi đang sốt ruột."},{"jp":"勝利を**焦った**結果、思わぬミスを犯してしまった。","vi":"Vì nôn nóng giành chiến thắng mà tôi đã phạm phải sai lầm không ngờ."}],
  "166": [{"jp":"出発時間が迫り、母は支度の遅い妹を**急かした**。","vi":"Sắp đến giờ xuất phát, mẹ hối thúc đứa em gái chuẩn bị chậm chạp."},{"jp":"取引先から見積もりを早く出すよう**急かされて**いる。","vi":"Tôi đang bị đối tác hối thúc gửi báo giá sớm."}],
  "167": [{"jp":"彼は厳しい訓練に**耐えて**、一流の消防士になった。","vi":"Chịu đựng qua đợt huấn luyện khắc nghiệt, anh ấy đã trở thành lính cứu hỏa hạng nhất."},{"jp":"この橋は大型トラックの重さにも**耐えられる**よう設計されている。","vi":"Cây cầu này được thiết kế để chịu được cả trọng lượng của xe tải lớn."}],
  "168": [{"jp":"失礼なことを言われて、思わず**むっとした**。","vi":"Bị nói điều vô lễ, tôi bất giác thấy bực mình."},{"jp":"注意された彼女は、**むっとした**顔で黙り込んだ。","vi":"Bị nhắc nhở, cô ấy im lặng với vẻ mặt bực bội."}],
  "169": [{"jp":"あと一歩で崖から落ちるところだったと思うと、**ぞっとする**。","vi":"Nghĩ đến việc chỉ một bước nữa là rơi xuống vực, tôi lại rùng mình."},{"jp":"真夜中に誰もいないはずの部屋から物音がして、**ぞっとした**。","vi":"Nửa đêm nghe tiếng động từ căn phòng lẽ ra không có ai, tôi sởn gai ốc."}],
  "170": [{"jp":"暗闇から急に人が現れて、**ぎょっとした**。","vi":"Bỗng có người xuất hiện từ trong bóng tối, tôi giật nảy mình."},{"jp":"請求書の金額を見て、彼は**ぎょっとした**顔をした。","vi":"Nhìn số tiền trên hóa đơn, anh ấy lộ vẻ hoảng hốt."}],
  "171": [{"jp":"大雪で電車が止まり、旅行の予定がすっかり**狂って**しまった。","vi":"Tàu dừng vì tuyết lớn, lịch trình chuyến đi bị đảo lộn hoàn toàn."},{"jp":"彼はギャンブルに**狂い**、全財産を失った。","vi":"Anh ta mê muội cờ bạc và mất toàn bộ tài sản."}],
  "172": [{"jp":"みんなの前で褒められて、彼は**照れて**頭をかいた。","vi":"Được khen trước mọi người, anh ấy ngượng ngùng gãi đầu."},{"jp":"父は少し**照れ**ながら、結婚30周年の花束を母に渡した。","vi":"Bố hơi ngượng ngùng trao bó hoa kỷ niệm 30 năm ngày cưới cho mẹ."}],
  "173": [{"jp":"失敗したときこそ、自分の行動を**省みる**ことが大切だ。","vi":"Chính khi thất bại, việc tự xét lại hành động của bản thân là điều quan trọng."},{"jp":"一日の終わりに日記をつけて、自らを**省みて**いる。","vi":"Cuối mỗi ngày tôi viết nhật ký để tự kiểm điểm bản thân."}],
  "174": [{"jp":"卒業アルバムを開き、楽しかった青春時代を**顧みた**。","vi":"Mở cuốn album tốt nghiệp, tôi nhìn lại thời thanh xuân vui vẻ."},{"jp":"彼は家庭を**顧みず**、仕事ばかりしていた。","vi":"Anh ta chẳng đoái hoài gì đến gia đình, chỉ biết làm việc."}],
  "175": [{"jp":"健康のため、早寝早起きを**心掛けて**いる。","vi":"Vì sức khỏe, tôi luôn chú ý ngủ sớm dậy sớm."},{"jp":"家族を乗せるときは、いつも以上に安全運転を**心掛ける**。","vi":"Khi chở gia đình, tôi càng chú ý lái xe an toàn hơn bình thường."}],
  "176": [{"jp":"山で遭難した登山者は、何度も無線で連絡を**試みた**。","vi":"Người leo núi gặp nạn đã nhiều lần thử liên lạc bằng vô tuyến."},{"jp":"研究チームは、従来とは異なる新しい方法を**試みる**ことにした。","vi":"Nhóm nghiên cứu quyết định thử một phương pháp mới khác với trước đây."}],
  "177": [{"jp":"海外で暮らす娘の身を、母はいつも**案じて**いる。","vi":"Mẹ lúc nào cũng lo lắng cho con gái sống ở nước ngoài."},{"jp":"社長は会社の将来を**案じ**、改革を決断した。","vi":"Giám đốc lo cho tương lai công ty nên đã quyết định cải cách."}],
  "178": [{"jp":"居酒屋に行ったら、服にタバコの匂いが**染みて**しまった。","vi":"Đi quán nhậu về, quần áo bị ám mùi thuốc lá."},{"jp":"一晩置いたカレーは、具に味がよく**染みて**いておいしい。","vi":"Cà ri để qua một đêm thì gia vị ngấm vào nguyên liệu, rất ngon."}],
  "179": [{"jp":"雨に濡れて、封筒の宛名のインクが**にじんで**しまった。","vi":"Bị mưa ướt, mực ghi tên người nhận trên phong bì đã bị nhòe."},{"jp":"真夏の工事現場で、作業員たちの額に汗が**にじんで**いた。","vi":"Ở công trường giữa mùa hè, mồ hôi rịn ra trên trán các công nhân."}],
  "180": [{"jp":"眼鏡を外すと、目の前の景色が**ぼやけて**見える。","vi":"Tháo kính ra là cảnh vật trước mắt trông mờ nhòe."},{"jp":"何十年も前のことなので、当時の記憶はすっかり**ぼやけて**いる。","vi":"Vì là chuyện mấy chục năm trước nên ký ức thời đó đã phai nhạt hết."}],
  "181": [{"jp":"入院生活が長かったので、すっかり足腰が**弱って**しまった。","vi":"Vì nằm viện lâu nên chân và hông đã yếu hẳn đi."},{"jp":"終電に乗り遅れ、ホテルも満室で、本当に**弱った**。","vi":"Lỡ chuyến tàu cuối, khách sạn lại hết phòng, tôi thật sự khó xử."}],
  "182": [{"jp":"久しぶりに会った友人は、苦労したのか随分**老けて**見えた。","vi":"Người bạn lâu ngày gặp lại, chắc vì vất vả mà trông già đi nhiều."},{"jp":"彼女は40代だが、全然**老けない**ので驚かれる。","vi":"Cô ấy ngoài 40 nhưng chẳng già đi chút nào nên ai cũng ngạc nhiên."}],
  "183": [{"jp":"吹雪の中を歩き続け、手足が**凍えて**感覚がなくなった。","vi":"Đi bộ mãi trong bão tuyết, tay chân lạnh cóng đến mất cảm giác."},{"jp":"真冬の駅のホームで、**凍え**ながら始発電車を待った。","vi":"Trên sân ga giữa mùa đông, tôi vừa run rét vừa chờ chuyến tàu đầu tiên."}],
  "184": [{"jp":"長年の夢が**かなって**、自分の店を持つことができた。","vi":"Ước mơ bao năm thành hiện thực, tôi đã có được cửa hàng của riêng mình."},{"jp":"神社で祈った願いが**かなう**といいですね。","vi":"Mong rằng điều ước bạn cầu ở đền sẽ thành hiện thực nhé."}],
  "185": [{"jp":"病気の少年の願いを**かなえる**ため、有名な選手が病院を訪れた。","vi":"Để biến ước nguyện của cậu bé bị bệnh thành hiện thực, một cầu thủ nổi tiếng đã đến bệnh viện."},{"jp":"彼女は留学して、子供の頃からの夢を**かなえた**。","vi":"Cô ấy đã đi du học, thực hiện được ước mơ từ thuở nhỏ."}],
  "186": [{"jp":"彼はこのプロジェクトに会社の命運を**懸けて**いる。","vi":"Anh ấy đặt cược vận mệnh công ty vào dự án này."},{"jp":"救助隊員たちは命を**懸けて**被災者を救い出した。","vi":"Các nhân viên cứu hộ đã liều mạng cứu những người gặp nạn."}],
  "187": [{"jp":"危ないから、夜の山に一人で登るのは**よした**ほうがいい。","vi":"Nguy hiểm lắm, tốt hơn hết là thôi đừng leo núi một mình ban đêm."},{"jp":"兄弟げんかを始めた二人に、母は「**よし**なさい！」と叱った。","vi":"Mẹ quát hai anh em đang cãi nhau: \"Thôi ngay đi!\""}],
  "188": [{"jp":"両社は共同開発に関する契約を**交わした**。","vi":"Hai công ty đã ký kết hợp đồng về phát triển chung."},{"jp":"試合終了後、両監督はがっちりと握手を**交わした**。","vi":"Sau trận đấu, hai huấn luyện viên đã bắt tay nhau thật chặt."}],
  "189": [{"jp":"週末の商店街は多くの買い物客で**賑わって**いる。","vi":"Khu phố mua sắm cuối tuần nhộn nhịp đông khách."},{"jp":"夏祭りの夜、神社の境内は浴衣姿の人々で**賑わった**。","vi":"Đêm lễ hội mùa hè, khuôn viên đền náo nhiệt với những người mặc yukata."}],
  "190": [{"jp":"この国は毎年多くの難民を**受け入れて**いる。","vi":"Đất nước này mỗi năm tiếp nhận nhiều người tị nạn."},{"jp":"組合の要求を**受け入れ**、会社は賃上げを決めた。","vi":"Chấp nhận yêu cầu của công đoàn, công ty đã quyết định tăng lương."}],
  "191": [{"jp":"この金庫は非常に**頑丈な**作りで、火事にも耐えられる。","vi":"Chiếc két sắt này được làm rất chắc chắn, chịu được cả hỏa hoạn."},{"jp":"祖父は農作業で鍛えた**頑丈な**体をしている。","vi":"Ông tôi có thân hình vạm vỡ được rèn luyện từ việc đồng áng."}],
  "192": [{"jp":"ヨガを続けているので、彼女は体がとても**柔軟だ**。","vi":"Vì tập yoga đều đặn nên cơ thể cô ấy rất dẻo."},{"jp":"予想外のトラブルにも**柔軟に**対応できる人材が求められている。","vi":"Người ta đang cần nhân lực có thể ứng phó linh hoạt với cả những sự cố ngoài dự kiến."}],
  "193": [{"jp":"テントは、できるだけ**平らな**場所に張ったほうがいい。","vi":"Nên dựng lều ở chỗ càng bằng phẳng càng tốt."},{"jp":"川原で表面が**平らな**石を探して、水切りをして遊んだ。","vi":"Ở bãi sông, tôi tìm những hòn đá có bề mặt phẳng để chơi ném thia lia."}],
  "194": [{"jp":"この2本の線路は、駅まで**平行に**走っている。","vi":"Hai tuyến đường ray này chạy song song đến tận ga."},{"jp":"話し合いは双方が譲らず、最後まで**平行線**を辿った。","vi":"Cuộc thảo luận hai bên không ai nhường ai, đến cuối vẫn song song không đi đến kết quả."}],
  "195": [{"jp":"地震が起きたら、**手近な**机の下に身を隠してください。","vi":"Khi có động đất, hãy nấp dưới chiếc bàn ở gần nhất."},{"jp":"冷蔵庫にある**手近な**材料で、簡単な夕食を作った。","vi":"Tôi làm bữa tối đơn giản bằng những nguyên liệu sẵn có trong tủ lạnh."}],
  "196": [{"jp":"この柿はまだ熟していないので、食べると**渋い**。","vi":"Quả hồng này chưa chín nên ăn thấy chát."},{"jp":"部長は企画書を読みながら、**渋い**顔をしていた。","vi":"Trưởng phòng vừa đọc bản kế hoạch vừa cau mặt."}],
  "197": [{"jp":"パン屋の前を通ると、**香ばしい**匂いが漂ってきた。","vi":"Đi qua tiệm bánh mì, mùi thơm bánh nướng lan tỏa."},{"jp":"焙じたばかりのお茶は、とても**香ばしい**。","vi":"Trà vừa mới rang rất thơm."}],
  "198": [{"jp":"結婚パーティーの会場は、**華やかな**雰囲気に包まれていた。","vi":"Hội trường tiệc cưới tràn ngập không khí rực rỡ."},{"jp":"女優として**華やかな**生涯を送った彼女も、晩年は孤独だった。","vi":"Cô ấy đã sống một đời hào nhoáng của một nữ diễn viên, nhưng tuổi già lại cô độc."}],
  "199": [{"jp":"創立100周年の式典が**盛大に**行われた。","vi":"Lễ kỷ niệm 100 năm thành lập đã được tổ chức long trọng."},{"jp":"演奏が終わると、会場から**盛大な**拍手が送られた。","vi":"Khi buổi biểu diễn kết thúc, cả hội trường vang lên tràng pháo tay lớn."}],
  "200": [{"jp":"秋になると、山は赤や黄色の**鮮やかな**紅葉に彩られる。","vi":"Đến mùa thu, núi được tô điểm bởi sắc lá đỏ vàng rực rỡ."},{"jp":"彼は**鮮やかな**手並みで、難しい手術を成功させた。","vi":"Với tay nghề điêu luyện, anh ấy đã thực hiện thành công ca phẫu thuật khó."}],
  "201": [{"jp":"この化粧水を使うと、肌が**滑らかに**なる。","vi":"Dùng loại nước dưỡng da này thì da sẽ mịn màng."},{"jp":"留学から戻った彼は、英語を**滑らかに**話すようになっていた。","vi":"Du học trở về, anh ấy đã nói tiếng Anh trôi chảy."}],
  "202": [{"jp":"特別なことはなくても、家族と過ごす**平凡な**毎日が幸せだ。","vi":"Dù không có gì đặc biệt, những ngày bình thường bên gia đình là hạnh phúc."},{"jp":"彼の学生時代の成績は**平凡だった**が、社会に出てから才能を発揮した。","vi":"Thời sinh viên thành tích của anh ấy bình thường, nhưng sau khi ra đời thì phát huy tài năng."}],
  "203": [{"jp":"村の人々の**素朴な**人柄に触れ、心が温かくなった。","vi":"Tiếp xúc với tính cách chất phác của người dân trong làng, lòng tôi ấm lại."},{"jp":"子供の**素朴な**質問に、大人が答えられないことはよくある。","vi":"Người lớn thường không trả lời được những câu hỏi đơn giản của trẻ con."}],
  "204": [{"jp":"時計は小さな部品を組み合わせた**精密な**機械だ。","vi":"Đồng hồ là cỗ máy chính xác được lắp ráp từ những linh kiện nhỏ."},{"jp":"医師に勧められて、病院で**精密**検査を受けた。","vi":"Theo lời khuyên của bác sĩ, tôi đã làm kiểm tra chi tiết ở bệnh viện."}],
  "205": [{"jp":"彼の意見は**極端**すぎて、誰も賛成しなかった。","vi":"Ý kiến của anh ấy quá cực đoan nên không ai tán thành."},{"jp":"食事を**極端に**減らすダイエットは、体に悪い。","vi":"Chế độ giảm cân cắt bớt ăn uống một cách cực đoan có hại cho cơ thể."}],
  "206": [{"jp":"**猛烈な**台風の接近に伴い、全便が欠航となった。","vi":"Do cơn bão dữ dội tiến gần, tất cả các chuyến bay đều bị hủy."},{"jp":"年度末になると、経理部は**猛烈に**忙しくなる。","vi":"Cuối năm tài chính, phòng kế toán trở nên bận khủng khiếp."}],
  "207": [{"jp":"首脳会議の会場周辺では、**厳重な**警備が行われている。","vi":"Xung quanh hội trường hội nghị thượng đỉnh, an ninh được canh gác nghiêm ngặt."},{"jp":"個人情報が記載された書類は、金庫で**厳重に**保管すること。","vi":"Tài liệu có ghi thông tin cá nhân phải được bảo quản nghiêm ngặt trong két sắt."}],
  "208": [{"jp":"試験の前日は、**十分な**睡眠をとるようにしている。","vi":"Hôm trước kỳ thi, tôi cố gắng ngủ đủ giấc."},{"jp":"時間は**十分に**あるから、慌てなくていい。","vi":"Còn đủ thời gian nên không cần vội."}],
  "209": [{"jp":"原材料価格の高騰により、来月から**大幅な**値上げが予定されている。","vi":"Do giá nguyên liệu tăng vọt, dự kiến từ tháng sau sẽ tăng giá mạnh."},{"jp":"台風の影響で、列車のダイヤが**大幅に**乱れた。","vi":"Do ảnh hưởng của bão, lịch chạy tàu bị xáo trộn nghiêm trọng."}],
  "210": [{"jp":"研究チームは十年かけて**膨大な**データを集めた。","vi":"Nhóm nghiên cứu đã mất mười năm thu thập lượng dữ liệu khổng lồ."},{"jp":"その地震は地域経済に**膨大な**損害をもたらした。","vi":"Trận động đất đó đã gây thiệt hại khổng lồ cho kinh tế khu vực."}],
  "211": [{"jp":"この国は地下資源に**乏しい**ため、輸入に頼っている。","vi":"Đất nước này nghèo tài nguyên dưới lòng đất nên phải dựa vào nhập khẩu."},{"jp":"彼はまだ経験が**乏しい**が、学ぶ意欲は誰よりも強い。","vi":"Anh ấy kinh nghiệm còn ít ỏi nhưng ý chí học hỏi mạnh hơn ai hết."}],
  "212": [{"jp":"財布には**僅かな**お金しか残っていなかった。","vi":"Trong ví chỉ còn lại chút ít tiền."},{"jp":"その天才少年は**僅か**5歳でピアノ協奏曲を作曲した。","vi":"Cậu bé thiên tài ấy đã sáng tác một bản concerto piano khi mới vỏn vẹn 5 tuổi."}],
  "213": [{"jp":"遠くから**微かな**波の音が聞こえてくる。","vi":"Từ xa vọng lại tiếng sóng khe khẽ."},{"jp":"幼い頃に住んでいた町のことは、**微かに**覚えている。","vi":"Tôi chỉ còn nhớ mang máng về thị trấn mình sống hồi nhỏ."}],
  "214": [{"jp":"日本語と中国語では、同じ漢字でも**微妙な**ニュアンスの違いがある。","vi":"Giữa tiếng Nhật và tiếng Trung, dù cùng chữ Hán vẫn có khác biệt tinh tế về sắc thái."},{"jp":"合格できるかどうかは、今の成績では**微妙な**ところだ。","vi":"Với thành tích hiện tại, đỗ hay không vẫn còn khó nói."}],
  "215": [{"jp":"**急激な**気温の変化で、体調を崩す人が増えている。","vi":"Do nhiệt độ thay đổi đột ngột, số người bị ốm đang tăng."},{"jp":"円安の影響で、輸入品の価格が**急激に**上昇した。","vi":"Do đồng yên mất giá, giá hàng nhập khẩu đã tăng vọt."}],
  "216": [{"jp":"この国は、過去20年で**急速な**経済発展を遂げた。","vi":"Đất nước này đã đạt được sự phát triển kinh tế nhanh chóng trong 20 năm qua."},{"jp":"魚は水揚げ後すぐに**急速**冷凍されるので、新鮮さが保たれる。","vi":"Cá được cấp đông nhanh ngay sau khi đưa lên bờ nên giữ được độ tươi."}],
  "217": [{"jp":"住民たちはダムの建設に**強硬に**反対している。","vi":"Người dân đang phản đối quyết liệt việc xây đập."},{"jp":"政府は相手国に対して**強硬な**態度を崩さなかった。","vi":"Chính phủ không từ bỏ thái độ cứng rắn đối với nước kia."}],
  "218": [{"jp":"彼女は親切のつもりだろうが、正直**余計な**お世話だ。","vi":"Có lẽ cô ấy định tốt bụng, nhưng thật lòng là bao đồng không cần thiết."},{"jp":"見るなと言われると、**余計に**見たくなる。","vi":"Bị bảo đừng xem lại càng muốn xem."}],
  "219": [{"jp":"深夜、家の周りをうろつく**不審な**男がいたので、警察に通報した。","vi":"Đêm khuya có người đàn ông khả nghi lảng vảng quanh nhà nên tôi đã báo cảnh sát."},{"jp":"駅で**不審な**荷物を見つけたら、触らずに駅員に知らせてください。","vi":"Nếu phát hiện hành lý đáng ngờ ở ga, đừng chạm vào mà hãy báo nhân viên nhà ga."}],
  "220": [{"jp":"政府はまだその件について**公式な**発表をしていない。","vi":"Chính phủ vẫn chưa có thông báo chính thức về vụ việc đó."},{"jp":"首相は来週、隣国を**公式に**訪問する予定だ。","vi":"Thủ tướng dự kiến sẽ thăm chính thức nước láng giềng vào tuần sau."}],
  "221": [{"jp":"労働者には、働きに見合った**正当な**報酬を受け取る権利がある。","vi":"Người lao động có quyền nhận thù lao chính đáng tương xứng với công sức."},{"jp":"彼の努力はようやく**正当に**評価された。","vi":"Nỗ lực của anh ấy cuối cùng đã được đánh giá xứng đáng."}],
  "222": [{"jp":"検査の結果、血圧も脈拍も**正常だった**。","vi":"Kết quả kiểm tra cho thấy huyết áp và nhịp mạch đều bình thường."},{"jp":"停電から数時間後、電車の運行は**正常に**戻った。","vi":"Vài giờ sau khi mất điện, tàu điện đã chạy trở lại bình thường."}],
  "223": [{"jp":"彼女は本番で**完璧な**演技を見せ、金メダルを獲得した。","vi":"Cô ấy có màn trình diễn hoàn hảo trong phần thi chính thức và giành huy chương vàng."},{"jp":"人間なのだから、誰でも**完璧**にはなれない。","vi":"Đã là con người thì không ai có thể hoàn hảo."}],
  "224": [{"jp":"報告書は、要点を**簡潔に**まとめてください。","vi":"Báo cáo hãy tóm tắt các ý chính một cách ngắn gọn."},{"jp":"彼のスピーチは**簡潔で**分かりやすく、聴衆の心に響いた。","vi":"Bài phát biểu của anh ấy ngắn gọn, dễ hiểu, chạm đến lòng người nghe."}],
  "225": [{"jp":"防犯カメラの映像という**明白な**証拠がある以上、言い逃れはできない。","vi":"Một khi đã có bằng chứng rõ ràng là đoạn phim camera an ninh thì không thể chối cãi."},{"jp":"彼が嘘をついていることは、誰の目にも**明白だった**。","vi":"Việc anh ta nói dối đã rõ như ban ngày trước mắt mọi người."}],
  "226": [{"jp":"自分の文章を**客観的に**読み直すのは難しい。","vi":"Đọc lại văn của chính mình một cách khách quan là điều khó."},{"jp":"記者は個人的な感情を入れず、**客観的な**事実だけを伝えるべきだ。","vi":"Phóng viên không nên đưa cảm xúc cá nhân vào mà chỉ nên truyền đạt sự thật khách quan."}],
  "227": [{"jp":"彼女は食事の誘いを**えん曲に**断った。","vi":"Cô ấy đã khéo léo từ chối lời mời đi ăn."},{"jp":"日本人は相手を傷つけないよう、**えん曲な**言い方をすることが多い。","vi":"Người Nhật thường dùng cách nói vòng vo để không làm tổn thương đối phương."}],
  "228": [{"jp":"水と空気は、すべての生物にとって**不可欠な**ものだ。","vi":"Nước và không khí là thứ không thể thiếu đối với mọi sinh vật."},{"jp":"リーダーには、周囲の意見に耳を傾ける姿勢が**不可欠だ**。","vi":"Đối với người lãnh đạo, thái độ lắng nghe ý kiến xung quanh là điều không thể thiếu."}],
  "229": [{"jp":"英語ができると、就職活動で**有利に**なる。","vi":"Biết tiếng Anh sẽ có lợi khi tìm việc."},{"jp":"相手チームは地元での試合なので、我々より**有利な**立場にある。","vi":"Đội đối phương thi đấu trên sân nhà nên ở vị thế có lợi hơn chúng ta."}],
  "230": [{"jp":"彼は将来**有望な**若手研究者として注目されている。","vi":"Anh ấy được chú ý như một nhà nghiên cứu trẻ có triển vọng."},{"jp":"再生可能エネルギーは、今後**有望な**市場だと言われている。","vi":"Năng lượng tái tạo được cho là thị trường có triển vọng trong tương lai."}],
  "231": [{"jp":"子供たちは夏休みが**待ち遠しくて**たまらない。","vi":"Bọn trẻ mong ngóng kỳ nghỉ hè đến không chịu nổi."},{"jp":"海外赴任中の夫が帰ってくる日が**待ち遠しい**。","vi":"Tôi mong ngóng ngày chồng đi công tác nước ngoài trở về."}],
  "232": [{"jp":"事故で一人も死者が出なかったのは、本当に**喜ばしい**ことだ。","vi":"Thật đáng mừng khi trong vụ tai nạn không có ai thiệt mạng."},{"jp":"卒業生が各界で活躍しているのは、学校にとって**喜ばしい**限りだ。","vi":"Việc các cựu học sinh hoạt động sôi nổi ở mọi lĩnh vực là niềm vui vô hạn đối với nhà trường."}],
  "233": [{"jp":"会議の資料は、前日までに配布するのが**望ましい**。","vi":"Tài liệu cuộc họp tốt nhất nên được phát trước một ngày."},{"jp":"応募者は、実務経験3年以上が**望ましい**。","vi":"Ứng viên nên có kinh nghiệm thực tế từ 3 năm trở lên."}],
  "234": [{"jp":"その健康食品の効果は、科学的に見て**疑わしい**。","vi":"Hiệu quả của thực phẩm chức năng đó, xét về mặt khoa học, là đáng ngờ."},{"jp":"このままのペースでは、期限内に完成するかどうか**疑わしい**。","vi":"Với tốc độ thế này, khó mà chắc có hoàn thành đúng hạn hay không."}],
  "235": [{"jp":"彼は**楽観的な**性格で、どんな困難にもくよくよしない。","vi":"Anh ấy tính lạc quan, gặp khó khăn gì cũng không ủ rũ."},{"jp":"専門家の中には、景気の回復を**楽観的に**見る人もいる。","vi":"Trong số các chuyên gia, có người nhìn nhận lạc quan về sự phục hồi kinh tế."}],
  "236": [{"jp":"子犬に足の裏をなめられて、**くすぐったかった**。","vi":"Bị cún con liếm lòng bàn chân, tôi thấy nhột."},{"jp":"みんなの前で褒められて、なんだか**くすぐったい**気持ちになった。","vi":"Được khen trước mọi người, tôi thấy ngượng ngùng sao đó."}],
  "237": [{"jp":"風邪をひいたのか、朝から体が**だるい**。","vi":"Chắc bị cảm hay sao mà từ sáng người cứ uể oải."},{"jp":"一日中立ち仕事だったので、足が**だるくて**たまらない。","vi":"Cả ngày làm việc đứng nên chân mỏi rã rời."}],
  "238": [{"jp":"月曜日の朝は、会社に行くのが**憂鬱だ**。","vi":"Sáng thứ Hai, việc đi làm thật chán nản."},{"jp":"梅雨の時期は雨が続き、**憂鬱な**気分になりがちだ。","vi":"Mùa mưa dầm mưa kéo dài, dễ khiến tâm trạng u sầu."}],
  "239": [{"jp":"彼は**勤勉な**性格で、一日も休まずに働いた。","vi":"Anh ấy tính cần cù, làm việc không nghỉ ngày nào."},{"jp":"日本人は**勤勉だ**と言われることが多い。","vi":"Người Nhật thường được cho là siêng năng."}],
  "240": [{"jp":"火事の時こそ、**冷静に**行動することが大切だ。","vi":"Chính lúc hỏa hoạn, hành động bình tĩnh là điều quan trọng."},{"jp":"相手に怒鳴られても、彼は**冷静な**態度を崩さなかった。","vi":"Dù bị đối phương quát tháo, anh ấy vẫn giữ thái độ điềm tĩnh."}],
  "241": [{"jp":"天候が悪化しているので、登山を中止したのは**賢明な**判断だった。","vi":"Thời tiết đang xấu đi nên việc hủy leo núi là quyết định sáng suốt."},{"jp":"感情に任せて言い返すより、黙っているほうが**賢明だ**。","vi":"Im lặng thì khôn ngoan hơn là để cảm xúc chi phối mà cãi lại."}],
  "242": [{"jp":"この地方は一年を通じて気候が**温和で**、暮らしやすい。","vi":"Vùng này khí hậu ôn hòa quanh năm, dễ sống."},{"jp":"祖父は**温和な**人柄で、怒ったところを見たことがない。","vi":"Ông tôi tính tình ôn hòa, tôi chưa từng thấy ông nổi giận."}],
  "243": [{"jp":"彼女は**大らかな**性格で、細かいことは気にしない。","vi":"Cô ấy tính thoải mái, không để ý chuyện vặt."},{"jp":"田舎で**大らかに**育った彼は、誰とでもすぐに打ち解ける。","vi":"Lớn lên thoải mái ở nông thôn, anh ấy dễ dàng thân thiết với bất cứ ai."}],
  "244": [{"jp":"試験は明日なのに、弟は**のんきに**ゲームをしている。","vi":"Mai thi rồi mà em trai vẫn vô tư chơi game."},{"jp":"定年後は田舎で**のんきな**生活を送りたい。","vi":"Sau khi nghỉ hưu, tôi muốn sống cuộc đời thong thả ở quê."}],
  "245": [{"jp":"彼は**おおざっぱな**性格で、書類のミスが多い。","vi":"Anh ấy tính đại khái nên hay sai sót trong giấy tờ."},{"jp":"時間がないので、資料には**おおざっぱに**目を通しただけだ。","vi":"Vì không có thời gian nên tôi chỉ xem qua loa tài liệu."}],
  "246": [{"jp":"彼はいつも**大げさに**話すので、半分くらいに聞いておいたほうがいい。","vi":"Anh ta lúc nào cũng nói phóng đại, nên nghe chỉ tin một nửa thôi."},{"jp":"ちょっと転んだだけで救急車を呼ぶなんて、**大げさだ**よ。","vi":"Chỉ ngã một chút mà gọi xe cấp cứu thì làm quá rồi."}],
  "247": [{"jp":"失敗しても**前向きに**考えれば、次につながる。","vi":"Dù thất bại, nếu suy nghĩ tích cực thì sẽ có bước tiến cho lần sau."},{"jp":"会社は在宅勤務の導入に**前向きな**姿勢を示している。","vi":"Công ty đang thể hiện thái độ tích cực đối với việc áp dụng làm việc tại nhà."}],
  "248": [{"jp":"彼は**陽気な**性格で、いつもみんなを笑わせている。","vi":"Anh ấy tính vui vẻ, lúc nào cũng làm mọi người cười."},{"jp":"今日はいい**陽気**ですね。散歩にでも行きましょうか。","vi":"Hôm nay thời tiết đẹp nhỉ. Hay ta đi dạo nhé."}],
  "249": [{"jp":"祖母は70歳を過ぎても、**若々しい**声で歌う。","vi":"Bà tôi ngoài 70 vẫn hát bằng giọng trẻ trung."},{"jp":"彼は還暦を迎えたとは思えないほど**若々しい**。","vi":"Ông ấy trẻ trung đến mức không ai nghĩ đã bước sang tuổi 60."}],
  "250": [{"jp":"彼女は卵に**敏感な**体質なので、ケーキが食べられない。","vi":"Cô ấy có cơ địa mẫn cảm với trứng nên không ăn được bánh kem."},{"jp":"若者は流行に**敏感だ**。","vi":"Giới trẻ nhạy bén với xu hướng."}],
  "251": [{"jp":"川に落ちた子供を助けた青年の**勇敢な**行動が表彰された。","vi":"Hành động dũng cảm của chàng thanh niên cứu đứa trẻ rơi xuống sông đã được tuyên dương."},{"jp":"兵士たちは最後まで**勇敢に**戦った。","vi":"Những người lính đã chiến đấu dũng cảm đến cùng."}],
  "252": [{"jp":"父は**無口な**人だが、家族のことをいつも考えてくれている。","vi":"Bố là người ít nói nhưng luôn nghĩ đến gia đình."},{"jp":"彼は緊張すると**無口に**なってしまう。","vi":"Anh ấy hễ căng thẳng là trở nên lầm lì."}],
  "253": [{"jp":"うちの犬はとても**利口で**、言葉をいくつも理解している。","vi":"Con chó nhà tôi rất thông minh, hiểu được nhiều từ."},{"jp":"規則の抜け穴を使うなんて、**利口な**やり方だが感心はできない。","vi":"Lợi dụng kẽ hở quy định là cách làm láu cá, nhưng không đáng khen."}],
  "254": [{"jp":"ギャンブルで給料を全部使ってしまうなんて、**愚かな**ことをしたものだ。","vi":"Nướng hết lương vào cờ bạc, thật là chuyện ngu ngốc."},{"jp":"戦争という**愚かな**行為を二度と繰り返してはならない。","vi":"Không được lặp lại hành vi ngu xuẩn mang tên chiến tranh."}],
  "255": [{"jp":"うちの猫は**臆病で**、来客があるとすぐに隠れてしまう。","vi":"Con mèo nhà tôi nhút nhát, hễ có khách là trốn ngay."},{"jp":"失敗を恐れて**臆病に**なっていては、何も始められない。","vi":"Nếu cứ sợ thất bại mà rụt rè thì chẳng bắt đầu được gì."}],
  "256": [{"jp":"いい大人が悪口を言い合うなんて、**幼稚だ**。","vi":"Người lớn cả rồi mà còn nói xấu nhau, thật ấu trĩ."},{"jp":"彼のレポートは内容も文章も**幼稚で**、大学生が書いたとは思えない。","vi":"Bài báo cáo của cậu ấy cả nội dung lẫn câu văn đều non nớt, không thể nghĩ là sinh viên đại học viết."}],
  "257": [{"jp":"私はまだ技術が**未熟な**ので、先輩にいろいろ教えてもらっている。","vi":"Kỹ thuật của tôi còn non nớt nên được các đàn anh chỉ bảo nhiều điều."},{"jp":"**未熟な**果物は酸っぱくて固い。","vi":"Trái cây chưa chín thì chua và cứng."}],
  "258": [{"jp":"子供の頃は体格が**貧弱で**、よく風邪をひいていた。","vi":"Hồi nhỏ tôi gầy gò ốm yếu, hay bị cảm."},{"jp":"見出しは立派だが、記事の内容は**貧弱だ**。","vi":"Tiêu đề thì hoành tráng nhưng nội dung bài báo nghèo nàn."}],
  "259": [{"jp":"雨に濡れて震えている子猫の**哀れな**姿に、胸が痛んだ。","vi":"Nhìn dáng vẻ tội nghiệp của chú mèo con ướt mưa run rẩy, tôi thấy đau lòng."},{"jp":"全財産を失った彼は、**哀れな**身なりで街をさまよっていた。","vi":"Mất hết tài sản, anh ta lang thang trên phố trong bộ dạng thảm thương."}],
  "260": [{"jp":"新人のくせに先輩に意見するなんて、**生意気だ**と思われるかもしれない。","vi":"Là người mới mà đã góp ý với đàn anh, có thể bị cho là tinh tướng."},{"jp":"最近、中学生の息子が**生意気な**口をきくようになった。","vi":"Gần đây cậu con trai học cấp hai bắt đầu ăn nói hỗn hào."}],
  "261": [{"jp":"自分のミスを他人のせいにするとは、なんて**厚かましい**人だろう。","vi":"Đổ lỗi của mình cho người khác, đúng là kẻ mặt dày."},{"jp":"**厚かましい**お願いで恐縮ですが、推薦状を書いていただけないでしょうか。","vi":"Thật ngại vì lời nhờ vả trơ trẽn này, nhưng ngài có thể viết giúp tôi thư giới thiệu được không?"}],
  "262": [{"jp":"彼は怒ると**乱暴な**言葉遣いになる。","vi":"Hễ nổi giận là anh ta ăn nói lỗ mãng."},{"jp":"そんな**乱暴な**論理では、誰も納得しないだろう。","vi":"Với lập luận thô thiển như thế thì chẳng ai chịu đâu."}],
  "263": [{"jp":"自分の利益しか考えない**利己的な**態度は、チームの和を乱す。","vi":"Thái độ ích kỷ chỉ nghĩ đến lợi ích của bản thân sẽ phá vỡ sự hòa thuận của đội."},{"jp":"人間は本来**利己的な**生き物だと主張する学者もいる。","vi":"Cũng có học giả cho rằng con người vốn là sinh vật ích kỷ."}],
  "264": [{"jp":"少し成功したからといって、**傲慢な**態度をとるべきではない。","vi":"Không nên tỏ thái độ ngạo mạn chỉ vì thành công một chút."},{"jp":"社長の**傲慢な**経営が社員の反発を招いた。","vi":"Cách điều hành ngạo mạn của giám đốc đã gây ra sự phản đối của nhân viên."}],
  "265": [{"jp":"相手の弱みにつけ込むなんて**卑怯だ**。","vi":"Lợi dụng điểm yếu của đối phương thì thật là hèn hạ."},{"jp":"陰で悪口を言うような**卑怯な**まねはしたくない。","vi":"Tôi không muốn làm trò hèn hạ như nói xấu sau lưng."}],
  "266": [{"jp":"一週間で5キロ痩せるような**無茶な**ダイエットは体に悪い。","vi":"Ăn kiêng liều lĩnh kiểu giảm 5 cân trong một tuần thì có hại cho cơ thể."},{"jp":"徹夜続きの**無茶な**生活をしていたら、ついに倒れてしまった。","vi":"Sống bất cần, thức trắng đêm liên tục, cuối cùng tôi đã gục ngã."}],
  "267": [{"jp":"地震で部屋の中が**めちゃくちゃに**なった。","vi":"Do động đất, trong phòng trở nên bừa bộn hỗn độn."},{"jp":"あの店のラーメンは**めちゃくちゃ**美味しい。","vi":"Mì ramen ở quán đó ngon cực kì."}],
  "268": [{"jp":"工事の音が**喧しくて**、仕事に集中できない。","vi":"Tiếng công trình ồn ào quá, không tập trung làm việc được."},{"jp":"父はラーメンの味に**喧しい**。","vi":"Bố tôi rất khó tính về vị mì ramen."}],
  "269": [{"jp":"新入社員が社長に真っ向から反論するとは、**大胆な**行動だ。","vi":"Nhân viên mới mà phản bác thẳng mặt giám đốc, thật là hành động táo bạo."},{"jp":"この建物は曲線を多用した**大胆な**デザインで注目を集めている。","vi":"Tòa nhà này thu hút sự chú ý nhờ thiết kế táo bạo dùng nhiều đường cong."}],
  "270": [{"jp":"彼女は**軽快な**足取りで坂道を上っていった。","vi":"Cô ấy bước đi nhẹ nhàng lên con dốc."},{"jp":"カフェには**軽快な**ジャズが流れていた。","vi":"Trong quán cà phê vang lên điệu jazz rộn ràng."}],
  "271": [{"jp":"太ったせいか、去年のスーツが**窮屈に**なった。","vi":"Có lẽ do béo lên nên bộ vest năm ngoái đã trở nên chật."},{"jp":"社長と二人きりの食事は**窮屈で**、料理の味もよく分からなかった。","vi":"Bữa ăn chỉ có hai người với giám đốc thật ngột ngạt, tôi chẳng cảm nhận được vị món ăn."}],
  "272": [{"jp":"彼は上司の指示に**忠実な**部下として信頼されている。","vi":"Anh ấy được tin tưởng như một cấp dưới trung thành với chỉ thị của cấp trên."},{"jp":"この映画は原作に**忠実に**作られている。","vi":"Bộ phim này được làm trung thành với nguyên tác."}],
  "273": [{"jp":"事故の目撃者の証言は**あやふや**で、決め手にならなかった。","vi":"Lời khai của nhân chứng vụ tai nạn mơ hồ nên không trở thành bằng chứng quyết định."},{"jp":"**あやふやな**知識で人に教えるのは危険だ。","vi":"Dạy người khác bằng kiến thức mơ hồ là nguy hiểm."}],
  "274": [{"jp":"この映画には**残酷な**場面があるため、子供には見せられない。","vi":"Phim này có cảnh tàn nhẫn nên không thể cho trẻ em xem."},{"jp":"愛し合う二人を引き裂くとは、**残酷な**運命だ。","vi":"Chia cắt hai người yêu nhau, thật là số phận tàn khốc."}],
  "275": [{"jp":"台風が去った後の町は**悲惨な**光景だった。","vi":"Thị trấn sau khi bão đi qua là một cảnh tượng bi thảm."},{"jp":"戦場で彼は**悲惨な**最期を遂げた。","vi":"Anh ấy đã có một kết cục bi thảm trên chiến trường."}],
  "276": [{"jp":"こんな簡単な問題も解けないなんて、我ながら**情けない**。","vi":"Đến bài dễ thế này cũng không giải được, tự thấy mình thật thảm hại."},{"jp":"後輩の前で泣いてしまい、**情けない**姿を見せてしまった。","vi":"Tôi lỡ khóc trước mặt đàn em, để lộ bộ dạng đáng xấu hổ."}],
  "277": [{"jp":"女性の社会進出が進んでも、古い偏見はまだ**根強く**残っている。","vi":"Dù phụ nữ ngày càng tham gia xã hội, những định kiến cũ vẫn còn ăn sâu."},{"jp":"この商品は発売から30年経った今も**根強い**人気がある。","vi":"Sản phẩm này đến nay, 30 năm sau khi ra mắt, vẫn được ưa chuộng bền bỉ."}],
  "278": [{"jp":"睡眠と健康には**密接な**関係がある。","vi":"Giấc ngủ và sức khỏe có quan hệ mật thiết."},{"jp":"両国は経済面で**密接に**結びついている。","vi":"Hai nước gắn kết mật thiết về mặt kinh tế."}],
  "279": [{"jp":"部長は部下の失敗に**寛大な**人だ。","vi":"Trưởng phòng là người khoan dung với thất bại của cấp dưới."},{"jp":"初犯ということで、**寛大な**処置がとられた。","vi":"Vì là phạm tội lần đầu nên đã được xử lý nhẹ tay."}],
  "280": [{"jp":"彼女こそ、リーダーに**相応しい**人物だ。","vi":"Chính cô ấy là người xứng đáng làm lãnh đạo."},{"jp":"結婚式には、その場に**相応しい**服装で出席してください。","vi":"Hãy dự đám cưới với trang phục phù hợp với dịp đó."}],
  "281": [{"jp":"平気な顔をしていたが、**内心**はとても不安だった。","vi":"Tôi tỏ vẻ bình thản nhưng trong lòng rất bất an."},{"jp":"彼は上司の提案に賛成したものの、**内心**では反対していた。","vi":"Anh ấy tán thành đề xuất của cấp trên nhưng trong thâm tâm lại phản đối."}],
  "282": [{"jp":"新しいプロジェクトを任されて、**やる気**が出てきた。","vi":"Được giao dự án mới, tôi thấy có động lực hơn."},{"jp":"給料が下がり、社員の**やる気**が失われている。","vi":"Lương giảm, nhân viên đang mất dần động lực."}],
  "283": [{"jp":"彼は有名大学出身であることに**優越感**を持っている。","vi":"Anh ta có cảm giác hơn người vì tốt nghiệp trường đại học danh tiếng."},{"jp":"他人を見下して**優越感**に浸るのはみっともない。","vi":"Coi thường người khác để đắm chìm trong cảm giác ưu việt thật đáng xấu hổ."}],
  "284": [{"jp":"父は職人としての**誇り**を持って働いている。","vi":"Bố tôi làm việc với niềm tự hào của một người thợ thủ công."},{"jp":"地元のチームの優勝は、町の**誇り**だ。","vi":"Chức vô địch của đội nhà là niềm tự hào của thị trấn."}],
  "285": [{"jp":"長年勤めた会社を辞めることを**決断した**。","vi":"Tôi đã quyết định dứt khoát nghỉ công ty mình làm nhiều năm."},{"jp":"社長は赤字部門からの撤退を**決断した**。","vi":"Giám đốc đã quyết định rút khỏi bộ phận thua lỗ."}],
  "286": [{"jp":"彼は新商品の名前を決めるのに**苦心した**。","vi":"Anh ấy đã rất khổ tâm để đặt tên cho sản phẩm mới."},{"jp":"作者が**苦心して**書き上げた小説が、ついに出版された。","vi":"Cuốn tiểu thuyết tác giả dày công viết xong cuối cùng đã được xuất bản."}],
  "287": [{"jp":"兄は弟の才能に**嫉妬して**いた。","vi":"Người anh ghen tị với tài năng của em trai."},{"jp":"恋人が他の男性と話しているのを見て、思わず**嫉妬した**。","vi":"Thấy người yêu nói chuyện với người đàn ông khác, tôi bất giác ghen."}],
  "288": [{"jp":"事業に失敗し、彼は人生に**絶望した**。","vi":"Thất bại trong kinh doanh, anh ấy tuyệt vọng với cuộc đời."},{"jp":"どんなに苦しくても、未来に**絶望して**はいけない。","vi":"Dù khổ đến đâu cũng không được tuyệt vọng về tương lai."}],
  "289": [{"jp":"試合に負けて、自分の力不足を**痛感した**。","vi":"Thua trận, tôi thấm thía sự non kém của bản thân."},{"jp":"災害を経験し、日頃の備えの大切さを**痛感して**いる。","vi":"Trải qua thiên tai, tôi cảm nhận sâu sắc tầm quan trọng của việc chuẩn bị hằng ngày."}],
  "290": [{"jp":"**先入観**を捨てて、相手の話を聞くべきだ。","vi":"Nên gạt bỏ định kiến để lắng nghe đối phương."},{"jp":"外見だけで人を判断するのは、**先入観**にとらわれている証拠だ。","vi":"Đánh giá người khác chỉ qua vẻ ngoài là bằng chứng của việc bị định kiến chi phối."}],
  "291": [{"jp":"若い頃の**過ち**を、彼は一生後悔し続けた。","vi":"Anh ấy hối hận cả đời vì lỗi lầm thời trẻ."},{"jp":"二度と同じ**過ち**を繰り返さないと誓った。","vi":"Tôi thề sẽ không bao giờ lặp lại sai lầm tương tự."}],
  "292": [{"jp":"人間の**欲**には限りがない。","vi":"Lòng tham của con người là vô hạn."},{"jp":"**欲**を出して株を買い増したら、大損してしまった。","vi":"Vì tham mà mua thêm cổ phiếu, thế là tôi lỗ nặng."}],
  "293": [{"jp":"人前で転んで、**恥**をかいた。","vi":"Tôi bị ngã trước mặt mọi người, thật xấu hổ."},{"jp":"知らないことを聞くのは**恥**ではない。","vi":"Hỏi điều mình không biết không phải là điều đáng xấu hổ."}],
  "294": [{"jp":"法律に違反した者は厳しく**罰せられる**。","vi":"Người vi phạm pháp luật sẽ bị xử phạt nghiêm khắc."},{"jp":"先生は嘘をついた生徒を**罰した**。","vi":"Thầy giáo đã phạt học sinh nói dối."}],
  "295": [{"jp":"恩師に対して感謝の**念**を込めて手紙を書いた。","vi":"Tôi viết thư cho thầy cũ với tất cả lòng biết ơn."},{"jp":"彼の勇気ある行動に、尊敬の**念**を抱いた。","vi":"Tôi nảy sinh lòng kính trọng trước hành động dũng cảm của anh ấy."}],
  "296": [{"jp":"酒が入ると、彼はつい**本音**をもらす。","vi":"Hễ có chút rượu vào là anh ta lại buột miệng nói ra lòng thật."},{"jp":"建前ではなく、**本音**で話し合おう。","vi":"Hãy nói chuyện thật lòng với nhau, đừng khách sáo xã giao."}],
  "297": [{"jp":"彼は遅刻したことを**弁解した**が、誰も信じなかった。","vi":"Anh ta biện hộ cho việc đến muộn nhưng chẳng ai tin."},{"jp":"今更**弁解して**も、失った信用は戻らない。","vi":"Giờ có bào chữa thì lòng tin đã mất cũng không quay lại."}],
  "298": [{"jp":"記者の質問に、大臣は**沈黙した**ままだった。","vi":"Trước câu hỏi của phóng viên, bộ trưởng vẫn im lặng."},{"jp":"会議室は重い**沈黙**に包まれた。","vi":"Phòng họp chìm trong sự im lặng nặng nề."}],
  "299": [{"jp":"彼は研究に**没頭して**、食事をとるのも忘れていた。","vi":"Anh ấy say mê nghiên cứu đến quên cả ăn."},{"jp":"趣味の模型作りに**没頭する**時間が何より楽しい。","vi":"Khoảng thời gian đắm chìm vào sở thích làm mô hình là vui nhất."}],
  "300": [{"jp":"怪我が治るまで、今は治療に**専念して**ください。","vi":"Cho đến khi khỏi chấn thương, giờ hãy chuyên tâm điều trị."},{"jp":"彼女は会社を辞めて、子育てに**専念する**ことにした。","vi":"Cô ấy quyết định nghỉ việc để dồn sức nuôi con."}],
  "301": [{"jp":"この図書館は専門書が**充実して**いる。","vi":"Thư viện này có sách chuyên ngành rất phong phú."},{"jp":"仕事も趣味も楽しく、**充実した**毎日を送っている。","vi":"Cả công việc lẫn sở thích đều vui, tôi đang sống những ngày trọn vẹn."}],
  "302": [{"jp":"大学を卒業したら、親から経済的に**自立したい**。","vi":"Tốt nghiệp đại học xong, tôi muốn tự lập về kinh tế, không dựa vào bố mẹ."},{"jp":"障害のある人が**自立して**暮らせる社会を目指す。","vi":"Hướng tới một xã hội mà người khuyết tật có thể sống tự lập."}],
  "303": [{"jp":"彼とは初対面から気が合い、**相性**がいいと感じた。","vi":"Tôi hợp với anh ấy ngay từ lần đầu gặp và thấy hai người rất ăn ý."},{"jp":"この白ワインは魚料理との**相性**が抜群だ。","vi":"Loại vang trắng này cực kỳ hợp với món cá."}],
  "304": [{"jp":"彼女のスピーチに、多くの聴衆が**共感した**。","vi":"Nhiều khán giả đã đồng cảm với bài phát biểu của cô ấy."},{"jp":"患者の気持ちに**共感する**ことは、看護師にとって大切だ。","vi":"Đồng cảm với cảm xúc của bệnh nhân là điều quan trọng đối với y tá."}],
  "305": [{"jp":"各国が**協調して**環境問題の解決に取り組むべきだ。","vi":"Các nước nên phối hợp cùng nhau giải quyết vấn đề môi trường."},{"jp":"彼は能力は高いが、周囲と**協調する**のが苦手だ。","vi":"Anh ấy có năng lực cao nhưng kém trong việc hợp tác với mọi người xung quanh."}],
  "306": [{"jp":"二つの大学が**共同して**新薬の開発を進めている。","vi":"Hai trường đại học đang cùng nhau phát triển thuốc mới."},{"jp":"住民が**共同で**公園の清掃を行っている。","vi":"Cư dân cùng nhau dọn dẹp công viên."}],
  "307": [{"jp":"社長は試合を控えた選手たちを**激励した**。","vi":"Giám đốc đã động viên các vận động viên sắp thi đấu."},{"jp":"友人たちからの**激励**の言葉に勇気づけられた。","vi":"Tôi được tiếp thêm dũng khí nhờ những lời khích lệ của bạn bè."}],
  "308": [{"jp":"政府は地震の被災者を**支援する**ための予算を組んだ。","vi":"Chính phủ đã lập ngân sách để hỗ trợ nạn nhân động đất."},{"jp":"この NPO は途上国の子供たちの教育を**支援して**いる。","vi":"Tổ chức phi lợi nhuận này đang hỗ trợ giáo dục cho trẻ em ở các nước đang phát triển."}],
  "309": [{"jp":"先輩に報告書の誤りを**指摘された**。","vi":"Tôi bị đàn anh chỉ ra lỗi sai trong bản báo cáo."},{"jp":"専門家は、この計画にはいくつかの問題点があると**指摘して**いる。","vi":"Các chuyên gia chỉ ra rằng kế hoạch này có một số vấn đề."}],
  "310": [{"jp":"「明日は9時集合です。」「**了解しました**。」","vi":"“Ngày mai tập trung lúc 9 giờ.” “Rõ rồi ạ.”"},{"jp":"相手の事情を**了解した**うえで、契約の条件を見直した。","vi":"Sau khi hiểu rõ hoàn cảnh của đối phương, chúng tôi đã xem xét lại điều kiện hợp đồng."}],
  "311": [{"jp":"両親は私たちの結婚を**承諾して**くれた。","vi":"Bố mẹ đã chấp thuận cho chúng tôi kết hôn."},{"jp":"本人の**承諾**を得ずに、写真を公開してはいけない。","vi":"Không được công khai ảnh khi chưa có sự đồng ý của chính người đó."}],
  "312": [{"jp":"彼女は元交際相手から**嫌がらせ**を受けていた。","vi":"Cô ấy đã bị người yêu cũ quấy rối."},{"jp":"職場での**嫌がらせ**について、会社に相談した。","vi":"Tôi đã trao đổi với công ty về việc bị gây khó dễ ở nơi làm việc."}],
  "313": [{"jp":"工事の騒音が住民の睡眠を**妨害して**いる。","vi":"Tiếng ồn công trình đang cản trở giấc ngủ của cư dân."},{"jp":"選挙演説を**妨害した**男が逮捕された。","vi":"Người đàn ông phá rối buổi diễn thuyết tranh cử đã bị bắt."}],
  "314": [{"jp":"留学に反対する両親を、時間をかけて**説得した**。","vi":"Tôi đã dành thời gian thuyết phục bố mẹ, những người phản đối việc du học."},{"jp":"警察は立てこもった犯人を**説得し**、人質を解放させた。","vi":"Cảnh sát đã thuyết phục kẻ cố thủ và khiến hắn thả con tin."}],
  "315": [{"jp":"彼は何かと**理屈**をこねて、仕事をさぼろうとする。","vi":"Anh ta hay lý sự đủ điều để trốn việc."},{"jp":"**理屈**では分かっていても、気持ちがついていかない。","vi":"Dù hiểu về mặt lý lẽ nhưng cảm xúc không theo kịp."}],
  "316": [{"jp":"彼の主張は**論理**が一貫していて説得力がある。","vi":"Lập luận của anh ấy nhất quán về lô-gic nên có sức thuyết phục."},{"jp":"**論理**を重視する数学は、考える力を養うのに役立つ。","vi":"Toán học, môn coi trọng lô-gic, giúp rèn luyện khả năng tư duy."}],
  "317": [{"jp":"探偵は現場の状況から犯人を**推理した**。","vi":"Thám tử đã suy luận ra hung thủ từ tình trạng hiện trường."},{"jp":"限られた手がかりから真相を**推理する**のが、ミステリーの醍醐味だ。","vi":"Suy luận ra sự thật từ những manh mối ít ỏi chính là cái thú của truyện trinh thám."}],
  "318": [{"jp":"その噂には何の**根拠**もない。","vi":"Tin đồn đó không có căn cứ gì cả."},{"jp":"予測の**根拠**となるデータを示してください。","vi":"Hãy đưa ra dữ liệu làm căn cứ cho dự đoán."}],
  "319": [{"jp":"週刊誌は事実を**誇張して**報道しがちだ。","vi":"Tuần san hay đưa tin phóng đại sự thật."},{"jp":"彼の話はいつも**誇張されて**いるので、半分くらいに聞いておいたほうがいい。","vi":"Chuyện anh ta kể lúc nào cũng phóng đại, nên nghe chừng một nửa thôi."}],
  "320": [{"jp":"その小説の冒頭は、主人公の悲劇的な最期を**暗示して**いる。","vi":"Phần mở đầu của cuốn tiểu thuyết ám chỉ kết cục bi thảm của nhân vật chính."},{"jp":"催眠術師は被験者に**暗示**をかけた。","vi":"Nhà thôi miên đã ám thị người được thử nghiệm."}],
  "321": [{"jp":"駅で止まっている電車に乗っていると、自分が動いているように**錯覚する**ことがある。","vi":"Ngồi trên tàu đang dừng ở ga, đôi khi ta có ảo giác như mình đang chuyển động."},{"jp":"彼女は一瞬、夢を現実と**錯覚した**。","vi":"Trong khoảnh khắc, cô ấy đã nhầm tưởng giấc mơ là hiện thực."}],
  "322": [{"jp":"留学を通じて、世界への**視野**が広がった。","vi":"Qua du học, tầm nhìn của tôi về thế giới đã được mở rộng."},{"jp":"長時間運転して疲れると、**視野**が狭くなる。","vi":"Lái xe lâu mệt mỏi thì tầm nhìn bị thu hẹp."}],
  "323": [{"jp":"答案用紙の**空白**を埋めるだけで精一杯だった。","vi":"Tôi chỉ cố lấp được chỗ trống trên giấy thi là hết sức rồi."},{"jp":"事故の前後の記憶には**空白**がある。","vi":"Ký ức trước và sau tai nạn có một khoảng trống."}],
  "324": [{"jp":"交差点で車とバイクが**接触する**事故があった。","vi":"Đã xảy ra vụ va chạm giữa ô tô và xe máy ở ngã tư."},{"jp":"記者は事件の関係者と**接触しよう**と試みた。","vi":"Phóng viên đã cố tiếp xúc với những người liên quan đến vụ án."}],
  "325": [{"jp":"労働組合は会社と賃上げについて**交渉した**。","vi":"Công đoàn đã đàm phán với công ty về việc tăng lương."},{"jp":"家賃の値下げを大家さんと**交渉して**みた。","vi":"Tôi thử thương lượng với chủ nhà về việc giảm tiền thuê."}],
  "326": [{"jp":"予算の都合で、家の条件は少し**妥協せ**ざるを得なかった。","vi":"Vì ngân sách, tôi đành phải thỏa hiệp đôi chút về điều kiện nhà."},{"jp":"彼は作品の質に関しては一切**妥協しない**。","vi":"Về chất lượng tác phẩm thì anh ấy tuyệt đối không thỏa hiệp."}],
  "327": [{"jp":"来月、運転免許を**更新し**なければならない。","vi":"Tháng sau tôi phải gia hạn bằng lái xe."},{"jp":"彼は100メートル走で日本記録を**更新した**。","vi":"Anh ấy đã phá kỷ lục Nhật Bản ở nội dung chạy 100 mét."}],
  "328": [{"jp":"出張の交通費を会社で**精算した**。","vi":"Tôi đã thanh toán lại chi phí đi lại công tác với công ty."},{"jp":"乗り越した分の運賃は、降りる駅で**精算して**ください。","vi":"Tiền vé phần đi quá ga, xin hãy thanh toán bù tại ga xuống."}],
  "329": [{"jp":"台風で農作物に大きな**損害**が出た。","vi":"Bão gây thiệt hại lớn cho nông sản."},{"jp":"取引先に**損害**賠償を求める訴訟を起こした。","vi":"Chúng tôi đã khởi kiện đòi đối tác bồi thường thiệt hại."}],
  "330": [{"jp":"両国の**利害**が一致し、協定が結ばれた。","vi":"Lợi ích của hai nước trùng khớp nên hiệp định đã được ký kết."},{"jp":"この問題には多くの企業の**利害**が絡んでいる。","vi":"Vấn đề này dính líu đến lợi hại của nhiều doanh nghiệp."}],
  "331": [{"jp":"山頂から見た日の出の**光景**は一生忘れられない。","vi":"Cảnh mặt trời mọc nhìn từ đỉnh núi tôi sẽ không bao giờ quên."},{"jp":"子供たちが楽しそうに遊ぶ**光景**を見て、心が和んだ。","vi":"Nhìn cảnh bọn trẻ vui đùa, lòng tôi dịu lại."}],
  "332": [{"jp":"その事件は新聞各紙で大きく**報道された**。","vi":"Vụ việc đó đã được các tờ báo đưa tin rầm rộ."},{"jp":"マスコミは事実を正確に**報道する**責任がある。","vi":"Truyền thông có trách nhiệm đưa tin chính xác sự thật."}],
  "333": [{"jp":"無計画な開発が生態系を**破壊して**いる。","vi":"Việc khai thác thiếu kế hoạch đang phá hủy hệ sinh thái."},{"jp":"ウイルスがコンピューターのシステムを**破壊した**。","vi":"Virus đã phá hỏng hệ thống máy tính."}],
  "334": [{"jp":"個人情報が書かれた書類は、シュレッダーで**破棄して**ください。","vi":"Giấy tờ có ghi thông tin cá nhân, xin hãy hủy bằng máy hủy tài liệu."},{"jp":"相手が約束を守らなかったため、契約を**破棄した**。","vi":"Vì đối phương không giữ lời hứa nên chúng tôi đã hủy hợp đồng."}],
  "335": [{"jp":"この店では、外国人客にも英語で**対応して**いる。","vi":"Cửa hàng này tiếp đón cả khách nước ngoài bằng tiếng Anh."},{"jp":"日本語の「米」と「ご飯」に**対応する**英語は、どちらも rice だ。","vi":"Từ tiếng Anh tương ứng với cả “kome” và “gohan” trong tiếng Nhật đều là “rice”."}],
  "336": [{"jp":"予想外のトラブルにも冷静に**対処する**ことが大切だ。","vi":"Điều quan trọng là xử lý bình tĩnh cả những rắc rối ngoài dự kiến."},{"jp":"客の苦情への**対処**が遅れ、店の評判が落ちた。","vi":"Việc xử lý khiếu nại của khách chậm trễ khiến danh tiếng cửa hàng đi xuống."}],
  "337": [{"jp":"当社は海外の企業とも**取引して**いる。","vi":"Công ty chúng tôi giao dịch cả với doanh nghiệp nước ngoài."},{"jp":"彼は違法な**取引**に関わった疑いで逮捕された。","vi":"Anh ta bị bắt vì nghi liên quan đến giao dịch phi pháp."}],
  "338": [{"jp":"日本人選手が上位を**独占した**。","vi":"Các vận động viên Nhật Bản đã độc chiếm các vị trí dẫn đầu."},{"jp":"一部の企業が市場を**独占する**と、価格が高くなりやすい。","vi":"Khi một vài doanh nghiệp độc chiếm thị trường thì giá cả dễ tăng."}],
  "339": [{"jp":"その会社は来年、東南アジア市場に**進出する**予定だ。","vi":"Công ty đó dự định thâm nhập thị trường Đông Nam Á vào năm sau."},{"jp":"我がチームは準決勝で勝利し、決勝戦に**進出した**。","vi":"Đội chúng tôi thắng bán kết và tiến vào trận chung kết."}],
  "340": [{"jp":"人類はサルから**進化した**と言われている。","vi":"Người ta nói loài người tiến hóa từ loài khỉ."},{"jp":"スマートフォンは年々**進化して**いる。","vi":"Điện thoại thông minh được cải tiến qua từng năm."}],
  "341": [{"jp":"私はその事件とは**一切**関係ありません。","vi":"Tôi hoàn toàn không liên quan gì đến vụ việc đó."},{"jp":"彼は家の財産の**一切**を弟に譲った。","vi":"Anh ấy đã nhường toàn bộ tài sản gia đình cho em trai."}],
  "342": [{"jp":"煮物は火の強さを**加減し**ながら、じっくり煮込むのがコツだ。","vi":"Bí quyết của món ninh là vừa điều chỉnh lửa vừa hầm thật kỹ."},{"jp":"彼女は**うつむき加減**で歩いていた。","vi":"Cô ấy bước đi hơi cúi đầu."}],
  "343": [{"jp":"会社は経費を2割**削減する**方針を打ち出した。","vi":"Công ty đưa ra phương châm cắt giảm 20% chi phí."},{"jp":"二酸化炭素の排出量を**削減する**ための取り組みが進んでいる。","vi":"Các nỗ lực nhằm giảm lượng khí thải CO2 đang được đẩy mạnh."}],
  "344": [{"jp":"急な来客に備えて、料理を**余分に**作っておいた。","vi":"Để phòng khách đến bất ngờ, tôi đã nấu dư thức ăn."},{"jp":"文章から**余分な**言葉を削ると、読みやすくなる。","vi":"Lược bỏ những từ thừa khỏi bài viết thì sẽ dễ đọc hơn."}],
  "345": [{"jp":"駐車場はもう車が入る**余地**がない。","vi":"Bãi đỗ xe không còn chỗ cho xe vào nữa."},{"jp":"この計画にはまだ改善の**余地**がある。","vi":"Kế hoạch này vẫn còn chỗ để cải thiện."}],
  "346": [{"jp":"会議で積極的に**発言する**よう心がけている。","vi":"Tôi luôn cố gắng phát biểu tích cực trong các cuộc họp."},{"jp":"大臣の**発言**が問題となり、辞任に追い込まれた。","vi":"Phát ngôn của bộ trưởng trở thành vấn đề, khiến ông buộc phải từ chức."}],
  "347": [{"jp":"大学の事務室で成績証明書を**発行して**もらった。","vi":"Tôi được văn phòng trường cấp bảng điểm."},{"jp":"この雑誌は毎月10万部**発行されて**いる。","vi":"Tạp chí này được phát hành 100 nghìn bản mỗi tháng."}],
  "348": [{"jp":"SNSを通じて、誰でも世界に情報を**発信できる**。","vi":"Qua mạng xã hội, ai cũng có thể phát thông tin ra thế giới."},{"jp":"遭難した船は救助を求める信号を**発信した**。","vi":"Con tàu gặp nạn đã phát tín hiệu cầu cứu."}],
  "349": [{"jp":"ご注文の商品は明日**発送いたします**。","vi":"Hàng quý khách đặt sẽ được gửi đi vào ngày mai."},{"jp":"年末は荷物を**発送する**人が多く、配達が遅れがちだ。","vi":"Cuối năm nhiều người gửi hàng nên việc giao hàng hay bị chậm."}],
  "350": [{"jp":"パン生地が**発酵して**、二倍の大きさに膨らんだ。","vi":"Bột bánh mì lên men và nở to gấp đôi."},{"jp":"納豆や味噌は、大豆を**発酵させて**作る食品だ。","vi":"Natto và miso là thực phẩm làm từ đậu nành lên men."}],
  "351": [{"jp":"赤ちゃんは順調に**発育して**いる。","vi":"Em bé đang phát triển thuận lợi."},{"jp":"栄養が不足すると、子供の**発育**に悪影響が出る。","vi":"Nếu thiếu dinh dưỡng, sự phát triển của trẻ sẽ bị ảnh hưởng xấu."}],
  "352": [{"jp":"新しい内閣が**発足した**。","vi":"Nội các mới đã ra đời."},{"jp":"地域の高齢者を支える会が今年**発足した**。","vi":"Năm nay, một hội hỗ trợ người cao tuổi trong khu vực đã được thành lập."}],
  "353": [{"jp":"彼は自分の勝利を**確信して**いた。","vi":"Anh ấy tin chắc vào chiến thắng của mình."},{"jp":"証拠を見て、彼が犯人だと**確信した**。","vi":"Nhìn chứng cứ, tôi tin chắc anh ta là hung thủ."}],
  "354": [{"jp":"最高裁の判決で、被告の刑が**確定した**。","vi":"Với phán quyết của Tòa án Tối cao, hình phạt của bị cáo đã được xác định."},{"jp":"開票の結果、新市長が**確定した**。","vi":"Kết quả kiểm phiếu đã xác định thị trưởng mới."}],
  "355": [{"jp":"花見のために、朝早くから場所を**確保した**。","vi":"Để ngắm hoa, tôi đã giữ chỗ từ sáng sớm."},{"jp":"政府は災害に備えて食料を**確保して**いる。","vi":"Chính phủ đảm bảo nguồn lương thực để phòng thiên tai."}],
  "356": [{"jp":"彼は長年の努力によって、画家としての地位を**確立した**。","vi":"Nhờ nỗ lực nhiều năm, ông ấy đã xác lập vị thế của mình với tư cách họa sĩ."},{"jp":"顧客との信頼関係を**確立する**には時間がかかる。","vi":"Thiết lập quan hệ tin cậy với khách hàng cần thời gian."}],
  "357": [{"jp":"名前を呼ばれても、彼は何も**反応しなかった**。","vi":"Dù được gọi tên, anh ấy cũng không phản ứng gì."},{"jp":"このライトは人の動きに**反応して**自動で点灯する。","vi":"Chiếc đèn này phản ứng với chuyển động của người và tự động bật sáng."}],
  "358": [{"jp":"雪に**反射した**日光がまぶしい。","vi":"Ánh nắng phản chiếu trên tuyết thật chói mắt."},{"jp":"ボールが飛んできて、思わず**反射的に**目を閉じた。","vi":"Quả bóng bay tới, tôi nhắm mắt lại theo phản xạ."}],
  "359": [{"jp":"思春期の子供は、親に**反発する**ことが多い。","vi":"Trẻ ở tuổi dậy thì thường chống đối bố mẹ."},{"jp":"磁石の同じ極同士は**反発し**合う。","vi":"Các cực cùng loại của nam châm đẩy nhau."}],
  "360": [{"jp":"選挙の結果には、国民の声が**反映されて**いる。","vi":"Kết quả bầu cử phản ánh tiếng nói của người dân."},{"jp":"子供の言葉遣いは親の言動を**反映する**ものだ。","vi":"Cách ăn nói của trẻ phản ánh lời nói và hành động của bố mẹ."}],
  "361": [{"jp":"相手を押し倒したその選手は、**反則**で退場になった。","vi":"Cầu thủ xô ngã đối phương đã bị đuổi khỏi sân vì phạm luật."},{"jp":"何度も**反則した**ため、彼は次の試合に出場できなくなった。","vi":"Vì phạm lỗi nhiều lần nên anh ta không được thi đấu trận tiếp theo."}],
  "362": [{"jp":"彼は新しい技術を発明し、**特許**を取得した。","vi":"Anh ấy phát minh ra công nghệ mới và đã được cấp bằng sáng chế."},{"jp":"その会社は**特許**を侵害したとして訴えられた。","vi":"Công ty đó bị kiện vì xâm phạm bằng sáng chế."}],
  "363": [{"jp":"このチーズには**特有**の匂いがある。","vi":"Loại phô mai này có mùi đặc trưng."},{"jp":"満員電車は都会**特有**の光景だ。","vi":"Tàu điện chật cứng là cảnh tượng đặc trưng của thành phố."}],
  "364": [{"jp":"警察は防犯カメラの映像から犯人を**特定した**。","vi":"Cảnh sát đã xác định được hung thủ từ hình ảnh camera an ninh."},{"jp":"この割引は**特定**の条件を満たした人だけが受けられる。","vi":"Chỉ những người thỏa mãn điều kiện nhất định mới được giảm giá này."}],
  "365": [{"jp":"怪我をしていた選手が、半年ぶりにチームに**復帰した**。","vi":"Cầu thủ bị chấn thương đã trở lại đội sau nửa năm."},{"jp":"出産後、彼女は職場に**復帰する**つもりだ。","vi":"Sau khi sinh con, cô ấy định quay lại làm việc."}],
  "366": [{"jp":"地震で止まっていた電車が、ようやく**復旧した**。","vi":"Tàu điện ngừng chạy vì động đất cuối cùng đã được khôi phục."},{"jp":"作業員が徹夜で停電の**復旧**作業にあたった。","vi":"Công nhân thức trắng đêm làm công tác khắc phục mất điện."}],
  "367": [{"jp":"戦後、日本は驚くべき速さで**復興した**。","vi":"Sau chiến tranh, Nhật Bản đã tái thiết với tốc độ đáng kinh ngạc."},{"jp":"震災から10年、町の**復興**は着実に進んでいる。","vi":"10 năm sau động đất, công cuộc tái thiết thị trấn đang tiến triển vững chắc."}],
  "368": [{"jp":"野党は大臣の責任を厳しく**追及した**。","vi":"Phe đối lập đã truy cứu gay gắt trách nhiệm của bộ trưởng."},{"jp":"記者たちは会見で社長の不正を**追及した**。","vi":"Các phóng viên đã truy vấn sai phạm của giám đốc trong buổi họp báo."}],
  "369": [{"jp":"企業が利益を**追求する**のは当然だが、社会的責任も忘れてはならない。","vi":"Doanh nghiệp theo đuổi lợi nhuận là đương nhiên, nhưng cũng không được quên trách nhiệm xã hội."},{"jp":"人は誰でも幸福を**追求する**権利がある。","vi":"Ai cũng có quyền mưu cầu hạnh phúc."}],
  "370": [{"jp":"哲学者は生涯をかけて真理を**追究した**。","vi":"Nhà triết học đã dành cả đời để nghiên cứu làm sáng tỏ chân lý."},{"jp":"この研究は、言語の本質を**追究する**ことを目的としている。","vi":"Nghiên cứu này nhằm làm sáng tỏ bản chất của ngôn ngữ."}],
  "371": [{"jp":"パトカーが逃走する車を**追跡した**。","vi":"Xe cảnh sát đã truy đuổi chiếc xe đang tẩu thoát."},{"jp":"研究者は渡り鳥にGPSを付けて、その移動を**追跡して**いる。","vi":"Các nhà nghiên cứu gắn GPS cho chim di cư để theo dấu đường di chuyển."}],
  "372": [{"jp":"先生が書いた**お手本**を見ながら、習字の練習をした。","vi":"Tôi luyện viết thư pháp theo chữ mẫu thầy viết."},{"jp":"兄として、弟たちの**手本**になるよう努力している。","vi":"Là anh cả, tôi cố gắng trở thành tấm gương cho các em."}],
  "373": [{"jp":"警察は事件の**手がかり**をつかめずにいる。","vi":"Cảnh sát vẫn chưa nắm được manh mối của vụ án."},{"jp":"岩に**手がかり**を探しながら、慎重に登った。","vi":"Tôi vừa tìm chỗ bám tay trên đá vừa leo lên thận trọng."}],
  "374": [{"jp":"家族みんなで**手分けして**大掃除をした。","vi":"Cả nhà chia nhau tổng vệ sinh."},{"jp":"何人かで**手分けして**探したが、迷子の犬は見つからなかった。","vi":"Mấy người chia nhau đi tìm nhưng vẫn không thấy con chó bị lạc."}],
  "375": [{"jp":"会議の会場と弁当を**手配して**おいてください。","vi":"Hãy thu xếp sẵn hội trường và cơm hộp cho cuộc họp."},{"jp":"旅行会社にコンサートのチケットを**手配して**もらった。","vi":"Tôi nhờ công ty du lịch lo liệu vé xem hòa nhạc."}],
  "376": [{"jp":"停電で真っ暗になり、**手探り**で懐中電灯を探した。","vi":"Mất điện tối om, tôi phải mò mẫm tìm đèn pin."},{"jp":"前例のない事業なので、すべて**手探り**の状態で進めている。","vi":"Vì là dự án chưa có tiền lệ nên mọi thứ đều đang được tiến hành trong tình trạng mày mò."}],
  "377": [{"jp":"彼女は**手際**よく料理を作る。","vi":"Cô ấy nấu ăn rất khéo léo, nhanh gọn."},{"jp":"準備の**手際**が悪く、開始時間が遅れてしまった。","vi":"Khâu chuẩn bị vụng về nên giờ bắt đầu bị trễ."}],
  "378": [{"jp":"年末は忙しく、**人手**が足りない。","vi":"Cuối năm bận rộn, thiếu người làm."},{"jp":"この森は**人手**が加わっていない、自然のままの姿を残している。","vi":"Khu rừng này vẫn giữ nguyên vẻ tự nhiên, chưa có bàn tay con người tác động."}],
  "379": [{"jp":"彼は**人目**を気にせず、駅で大声で歌い出した。","vi":"Anh ta chẳng để ý ánh mắt người khác, cất giọng hát to ở nhà ga."},{"jp":"二人は**人目**を避けて会っていた。","vi":"Hai người lén gặp nhau tránh ánh mắt thiên hạ."}],
  "380": [{"jp":"夜、**人気**のない道を一人で歩くのは危ない。","vi":"Đi một mình trên con đường vắng người vào ban đêm thì nguy hiểm."},{"jp":"閉店後のデパートは**人気**がなく、しんと静まり返っていた。","vi":"Trung tâm thương mại sau giờ đóng cửa vắng bóng người, im phăng phắc."}],
  "381": [{"jp":"彼は壁に**寄りかかって**携帯を見ていた。","vi":"Anh ấy dựa vào tường xem điện thoại."},{"jp":"いつまでも親に**寄りかかって**いないで、自分で生活しなさい。","vi":"Đừng mãi ỷ lại vào bố mẹ, hãy tự lo cuộc sống của mình."}],
  "382": [{"jp":"電車の中で、隣の人が私の肩に**凭れかかって**眠っていた。","vi":"Trên tàu điện, người ngồi bên cạnh tựa vào vai tôi mà ngủ."},{"jp":"彼女は椅子の背に**凭れかかり**、大きく息をついた。","vi":"Cô ấy tựa lưng vào ghế và thở một hơi dài."}],
  "383": [{"jp":"口論の末、男は相手に**つかみかかった**。","vi":"Sau khi cãi vã, người đàn ông xông vào túm lấy đối phương."},{"jp":"酔っ払いが店員に**つかみかかろう**としたので、慌てて止めた。","vi":"Gã say rượu định xông vào túm nhân viên nên tôi vội ngăn lại."}],
  "384": [{"jp":"彼は機嫌が悪いと、誰にでも**突っかかる**。","vi":"Hễ tâm trạng không tốt là anh ta gây sự với bất kỳ ai."},{"jp":"興奮した牛が闘牛士に**突っかかって**いった。","vi":"Con bò bị kích động lao vào đấu sĩ."}],
  "385": [{"jp":"猫がネズミに**飛びかかった**。","vi":"Con mèo vồ lấy con chuột."},{"jp":"警官は逃げようとした犯人に**跳びかかり**、取り押さえた。","vi":"Viên cảnh sát nhảy bổ vào tên tội phạm đang định chạy trốn và khống chế hắn."}],
  "386": [{"jp":"夏休みに入ったら、すぐ卒業論文に**取りかかる**つもりだ。","vi":"Vào kỳ nghỉ hè là tôi định bắt tay ngay vào luận văn tốt nghiệp."},{"jp":"会議が終わると、彼はさっそく次の仕事に**取りかかった**。","vi":"Họp xong, anh ấy lập tức bắt tay vào công việc tiếp theo."}],
  "387": [{"jp":"日が**暮れかかった**頃、ようやく山小屋に着いた。","vi":"Khi trời sắp tối, cuối cùng chúng tôi cũng tới được lều trên núi."},{"jp":"**暮れかかる**空を、カラスが鳴きながら飛んでいった。","vi":"Trên bầu trời chạng vạng, đàn quạ vừa kêu vừa bay qua."}],
  "388": [{"jp":"棚の上の花瓶が**落ちかかって**いたので、慌てて押さえた。","vi":"Bình hoa trên kệ sắp rơi nên tôi vội giữ lại."},{"jp":"崖から**落ちかかった**子供を、父親が間一髪で助けた。","vi":"Người cha cứu được đứa con suýt rơi xuống vách đá trong gang tấc."}],
  "389": [{"jp":"自転車を壁に**立てかけて**おいたら、風で倒れてしまった。","vi":"Tôi dựng xe đạp tựa vào tường thì bị gió thổi đổ."},{"jp":"傘はドアの横に**立てかけて**ください。","vi":"Ô xin hãy dựng tựa bên cạnh cửa."}],
  "390": [{"jp":"電車で隣に座った外国人に英語で**話しかけられた**。","vi":"Trên tàu, tôi được người nước ngoài ngồi bên cạnh bắt chuyện bằng tiếng Anh."},{"jp":"母はお腹の赤ちゃんに毎日**話しかけて**いる。","vi":"Mẹ tôi ngày nào cũng nói chuyện với em bé trong bụng."}],
  "391": [{"jp":"市民団体は市に公園の保存を**働きかけて**いる。","vi":"Nhóm công dân đang vận động thành phố bảo tồn công viên."},{"jp":"住民の意識を変えるには、地道に**働きかける**しかない。","vi":"Để thay đổi nhận thức của cư dân, chỉ còn cách tác động một cách bền bỉ."}],
  "392": [{"jp":"有名人の自宅に記者たちが**押しかけた**。","vi":"Các phóng viên đã kéo đến nhà riêng của người nổi tiếng."},{"jp":"夜中に友人の家へ**押しかける**のは迷惑だ。","vi":"Kéo đến nhà bạn vào lúc nửa đêm là gây phiền hà."}],
  "393": [{"jp":"開店前から大勢の客が店の前に**詰めかけた**。","vi":"Từ trước giờ mở cửa, rất đông khách đã kéo đến chật kín trước cửa hàng."},{"jp":"判決を聞こうと、裁判所には多くの傍聴人が**詰めかけて**いた。","vi":"Rất nhiều người dự thính đã kéo đến tòa án để nghe phán quyết."}],
  "394": [{"jp":"犯人は殺人を事故に**見せかけよう**とした。","vi":"Hung thủ đã định ngụy tạo vụ giết người thành tai nạn."},{"jp":"在宅だと**見せかける**ために、外出中も電気をつけておく。","vi":"Để làm ra vẻ có người ở nhà, tôi để đèn sáng cả khi đi ra ngoài."}],
  "395": [{"jp":"彼女は何か**言いかけた**が、途中で黙ってしまった。","vi":"Cô ấy định nói gì đó nhưng giữa chừng lại im lặng."},{"jp":"先ほど**言いかけた**話の続きを聞かせてください。","vi":"Hãy cho tôi nghe tiếp câu chuyện anh định nói lúc nãy."}],
  "396": [{"jp":"子どもの頃、川で**溺れかけた**ことがある。","vi":"Hồi nhỏ tôi từng suýt chết đuối ở sông."},{"jp":"**溺れかけて**いた少年を、通りかかった男性が救い出した。","vi":"Một người đàn ông đi ngang qua đã cứu cậu bé đang suýt chết đuối."}],
  "397": [{"jp":"母は私に部屋の掃除を**言いつけて**出かけた。","vi":"Mẹ sai tôi dọn phòng rồi đi ra ngoài."},{"jp":"弟は私がお菓子を食べたことを母に**言いつけた**。","vi":"Em trai đã mách mẹ chuyện tôi ăn bánh kẹo."}],
  "398": [{"jp":"事故の知らせを受け、家族が病院に**駆けつけた**。","vi":"Nhận được tin tai nạn, gia đình đã vội chạy đến bệnh viện."},{"jp":"通報から5分で警察が現場に**駆けつけた**。","vi":"Chỉ 5 phút sau khi được báo, cảnh sát đã có mặt tại hiện trường."}],
  "399": [{"jp":"証拠もないのに、彼を犯人だと**決めつける**のはよくない。","vi":"Không có bằng chứng mà khăng khăng cho rằng anh ta là thủ phạm thì không hay."},{"jp":"最初から「自分には無理だ」と**決めつけないで**、やってみなさい。","vi":"Đừng ngay từ đầu đã quả quyết \"mình không làm được\", hãy thử làm xem."}],
  "400": [{"jp":"注文していない商品を一方的に**送り付ける**詐欺が増えている。","vi":"Kiểu lừa đảo đơn phương gửi đến những món hàng không hề đặt mua đang gia tăng."},{"jp":"彼は別れた恋人に何通もの手紙を**送り付けた**。","vi":"Anh ta đã gửi tới tấp không biết bao nhiêu lá thư cho người yêu cũ."}],
  "401": [{"jp":"壁に耳を**押し付けて**、隣の部屋の会話を聞いた。","vi":"Tôi áp tai vào tường để nghe cuộc nói chuyện ở phòng bên."},{"jp":"面倒な仕事を後輩に**押し付ける**先輩は信頼されない。","vi":"Đàn anh hay đùn đẩy việc phiền phức cho đàn em thì không được tin tưởng."}],
  "402": [{"jp":"彼女は何も言わず、私を**にらみつけた**。","vi":"Cô ấy không nói gì mà trừng mắt nhìn tôi."},{"jp":"足を踏まれた男は、相手を**にらみつけて**舌打ちした。","vi":"Người đàn ông bị giẫm chân trừng mắt nhìn đối phương rồi tặc lưỡi."}],
  "403": [{"jp":"彼は怒りのあまり、受話器を机に**叩きつけた**。","vi":"Quá tức giận, anh ta đập mạnh ống nghe xuống bàn."},{"jp":"激しい雨が窓ガラスに**叩きつける**ように降っている。","vi":"Mưa lớn đang trút xuống như quất mạnh vào cửa kính."}],
  "404": [{"jp":"コーチはミスをした選手を**怒鳴りつけた**。","vi":"Huấn luyện viên đã quát mắng cầu thủ mắc lỗi."},{"jp":"子どもを頭ごなしに**怒鳴りつけて**も、反発されるだけだ。","vi":"Có quát tháo trẻ con xối xả không cần nghe lý do thì cũng chỉ khiến chúng chống đối."}],
  "405": [{"jp":"全ての客室に空気清浄機が**備え付けられて**いる。","vi":"Tất cả các phòng khách đều được trang bị máy lọc không khí."},{"jp":"学校は各階にAEDを**備え付けた**。","vi":"Nhà trường đã lắp đặt máy AED ở mỗi tầng."}],
  "406": [{"jp":"子どもたちとクリスマスツリーに豆電球を**飾り付けた**。","vi":"Tôi cùng bọn trẻ trang trí bóng đèn nhỏ lên cây thông Noel."},{"jp":"会場を花と風船で**飾り付ける**のに半日かかった。","vi":"Mất nửa ngày để trang trí hội trường bằng hoa và bóng bay."}],
  "407": [{"jp":"**やりつけない**仕事を任されて、すっかり疲れてしまった。","vi":"Được giao việc chưa quen làm nên tôi mệt rã rời."},{"jp":"**やりつけた**作業なので、目をつぶってもできる。","vi":"Đây là việc đã quen tay nên nhắm mắt cũng làm được."}],
  "408": [{"jp":"会社の近くに**行きつけ**の居酒屋がある。","vi":"Gần công ty có một quán nhậu quen tôi hay lui tới."},{"jp":"父は毎月、**行きつけ**の床屋で髪を切ってもらう。","vi":"Hằng tháng bố tôi cắt tóc ở tiệm cắt tóc quen."}],
  "409": [{"jp":"労働者たちは長い交渉の末、賃上げを**勝ち取った**。","vi":"Sau thời gian dài đàm phán, người lao động đã giành được việc tăng lương."},{"jp":"彼女は厳しい選考を経て、主役の座を**勝ち取った**。","vi":"Trải qua vòng tuyển chọn khắt khe, cô ấy đã giành được vai chính."}],
  "410": [{"jp":"彼は一度きりのチャンスを**つかみ取った**。","vi":"Anh ấy đã nắm lấy cơ hội chỉ có một lần."},{"jp":"最後まであきらめなかったチームが勝利を**つかみ取った**。","vi":"Đội không bỏ cuộc đến phút cuối đã giành lấy chiến thắng."}],
  "411": [{"jp":"電話の声が小さくて、相手の名前が**聞き取れなかった**。","vi":"Giọng trong điện thoại nhỏ quá nên tôi không nghe được tên người kia."},{"jp":"警察は目撃者から事件の状況を**聞き取った**。","vi":"Cảnh sát đã nghe nhân chứng kể lại tình hình vụ án."}],
  "412": [{"jp":"講演者の話を一言も漏らさず**書き取った**。","vi":"Tôi đã ghi lại lời diễn giả không sót một chữ."},{"jp":"電話で聞いた住所を、メモ用紙に**書き取った**。","vi":"Tôi chép lại địa chỉ nghe qua điện thoại vào giấy ghi chú."}],
  "413": [{"jp":"彼の表情から不安な気持ちを**読み取る**ことができた。","vi":"Tôi có thể đọc được nỗi bất an từ nét mặt anh ấy."},{"jp":"この機械はICカードの情報を一瞬で**読み取る**。","vi":"Máy này đọc thông tin thẻ IC trong tích tắc."}],
  "414": [{"jp":"武装したグループが旅客機を**乗っ取った**。","vi":"Một nhóm vũ trang đã cướp quyền điều khiển máy bay chở khách."},{"jp":"何者かにSNSのアカウントを**乗っ取られて**しまった。","vi":"Tài khoản mạng xã hội của tôi đã bị ai đó chiếm quyền."}],
  "415": [{"jp":"満員電車で財布から紙幣を**抜き取られた**。","vi":"Trên tàu đông người, tôi bị móc mất tiền giấy trong ví."},{"jp":"検査のため、製品をいくつか**抜き取って**品質を確かめる。","vi":"Để kiểm tra, người ta rút ra vài sản phẩm để xác nhận chất lượng."}],
  "416": [{"jp":"母に叱られても、弟は何も**言い返さなかった**。","vi":"Dù bị mẹ mắng, em trai cũng không cãi lại câu nào."},{"jp":"理不尽なことを言われたら、はっきり**言い返した**ほうがいい。","vi":"Nếu bị nói những điều vô lý thì nên đáp trả rõ ràng."}],
  "417": [{"jp":"母からの手紙を何度も**読み返した**。","vi":"Tôi đã đọc đi đọc lại lá thư của mẹ nhiều lần."},{"jp":"提出する前に、報告書をもう一度**読み返して**ください。","vi":"Trước khi nộp, hãy đọc lại bản báo cáo thêm một lần nữa."}],
  "418": [{"jp":"相手の言葉がよく分からなかったので、**聞き返した**。","vi":"Vì không hiểu rõ lời đối phương nên tôi đã hỏi lại."},{"jp":"何度も**聞き返す**のは失礼だと思い、分かったふりをしてしまった。","vi":"Nghĩ rằng hỏi lại nhiều lần là bất lịch sự, tôi đã giả vờ hiểu."}],
  "419": [{"jp":"今になって**思い返す**と、あの時の判断は間違っていなかった。","vi":"Bây giờ nhớ lại thì quyết định lúc đó không hề sai."},{"jp":"一度は断ろうとしたが、**思い返して**引き受けることにした。","vi":"Lúc đầu tôi định từ chối, nhưng nghĩ lại thì quyết định nhận lời."}],
  "420": [{"jp":"提出する前に、レポートを何度も**見返した**。","vi":"Trước khi nộp, tôi đã xem lại bài báo cáo nhiều lần."},{"jp":"彼がじっと見つめてきたので、私も**見返した**。","vi":"Anh ta nhìn chằm chằm vào tôi nên tôi cũng nhìn lại."}],
  "421": [{"jp":"冷蔵庫の残り物で料理し、食材を無駄なく**使い切った**。","vi":"Tôi nấu bằng đồ thừa trong tủ lạnh, dùng hết nguyên liệu không lãng phí."},{"jp":"彼は親から受け継いだ財産を数年で**使い切って**しまった。","vi":"Anh ta đã tiêu sạch tài sản thừa kế của cha mẹ chỉ trong vài năm."}],
  "422": [{"jp":"結果は負けだったが、全力を**出し切った**ので悔いはない。","vi":"Kết quả là thua, nhưng tôi đã dốc hết sức nên không hối tiếc."},{"jp":"本番で実力を**出し切る**ためには、日頃の準備が大切だ。","vi":"Để phát huy hết thực lực khi thi thật, sự chuẩn bị hằng ngày rất quan trọng."}],
  "423": [{"jp":"そんな**分かり切った**ことを、いちいち説明しなくてもいい。","vi":"Không cần phải giải thích từng chút những điều hiển nhiên như vậy."},{"jp":"練習しなければ上達しないのは**分かり切って**いる。","vi":"Không luyện tập thì không tiến bộ, điều đó quá rõ ràng."}],
  "424": [{"jp":"道に迷って**困り切って**いたところ、地元の人が助けてくれた。","vi":"Đang lạc đường và vô cùng khốn đốn thì một người dân địa phương đã giúp tôi."},{"jp":"息子の反抗に、両親は**困り切った**様子だった。","vi":"Trước sự chống đối của cậu con trai, bố mẹ tỏ ra hết sức khổ sở."}],
  "425": [{"jp":"山頂には**澄み切った**青空が広がっていた。","vi":"Trên đỉnh núi, bầu trời xanh trong vắt trải rộng."},{"jp":"この湖の水は**澄み切って**いて、底まで見える。","vi":"Nước hồ này trong vắt, nhìn thấy cả đáy."}],
  "426": [{"jp":"社長は役員の反対を**押し切って**、新事業を始めた。","vi":"Giám đốc bất chấp sự phản đối của ban lãnh đạo, bắt đầu mảng kinh doanh mới."},{"jp":"与党は野党の抵抗を**押し切り**、法案を成立させた。","vi":"Đảng cầm quyền bất chấp sự chống đối của phe đối lập, thông qua dự luật."}],
  "427": [{"jp":"彼はその絵が本物だと**言い切った**。","vi":"Anh ta khẳng định bức tranh đó là thật."},{"jp":"この方法が絶対に正しいとは**言い切れない**。","vi":"Không thể khẳng định chắc chắn phương pháp này đúng tuyệt đối."}],
  "428": [{"jp":"政府はついに増税に**踏み切った**。","vi":"Chính phủ cuối cùng đã quyết định tăng thuế."},{"jp":"長年迷っていたが、転職に**踏み切る**ことにした。","vi":"Đã phân vân nhiều năm, nhưng tôi quyết định hạ quyết tâm chuyển việc."}],
  "429": [{"jp":"盗まれたバッグを警察が**取り返して**くれた。","vi":"Cảnh sát đã lấy lại chiếc túi bị trộm cho tôi."},{"jp":"一度失った信頼を**取り返す**のは簡単ではない。","vi":"Lấy lại niềm tin đã mất một lần chẳng dễ dàng gì."}],
  "430": [{"jp":"大家は滞納された家賃を**取り立てた**。","vi":"Chủ nhà đã đòi số tiền thuê nhà bị nợ."},{"jp":"今回の件は、**取り立てて**問題にするほどのことではない。","vi":"Chuyện lần này không đến mức phải đặc biệt đem ra làm vấn đề."}],
  "431": [{"jp":"警察は年末に飲酒運転を厳しく**取り締まる**。","vi":"Cảnh sát kiểm soát gắt gao việc lái xe khi say rượu vào dịp cuối năm."},{"jp":"国は偽ブランド品の販売を**取り締まる**法律を作った。","vi":"Nhà nước đã ban hành luật trấn áp việc buôn bán hàng hiệu giả."}],
  "432": [{"jp":"彼は今、環境問題の研究に**取り組んで**いる。","vi":"Hiện anh ấy đang chuyên tâm nghiên cứu các vấn đề môi trường."},{"jp":"会社全体で残業の削減に**取り組む**ことになった。","vi":"Toàn công ty đã quyết định cùng nỗ lực cắt giảm làm thêm giờ."}],
  "433": [{"jp":"雨が降りそうなので、洗濯物を**取り込んで**おいた。","vi":"Trời có vẻ sắp mưa nên tôi đã mang quần áo phơi vào."},{"jp":"新商品で若者の客層を**取り込む**作戦だ。","vi":"Đây là chiến lược thu hút tầng lớp khách hàng trẻ bằng sản phẩm mới."}],
  "434": [{"jp":"双方が和解したため、原告は訴えを**取り下げた**。","vi":"Vì hai bên đã hòa giải nên nguyên đơn rút đơn kiện."},{"jp":"上司に説得され、彼は辞表を**取り下げた**。","vi":"Được cấp trên thuyết phục, anh ấy đã rút lại đơn từ chức."}],
  "435": [{"jp":"受付で用件を伝えると、担当者に**取り次いで**くれた。","vi":"Khi tôi nói việc cần ở quầy lễ tân, họ đã chuyển lời đến người phụ trách."},{"jp":"社長は会議中のため、お電話を**取り次ぐ**ことができません。","vi":"Giám đốc đang họp nên tôi không thể chuyển máy được ạ."}],
  "436": [{"jp":"人気アイドルを大勢のファンが**取り巻いて**いた。","vi":"Rất đông người hâm mộ vây quanh thần tượng nổi tiếng."},{"jp":"若者を**取り巻く**雇用環境は年々厳しくなっている。","vi":"Môi trường việc làm bao quanh giới trẻ ngày càng khắc nghiệt."}],
  "437": [{"jp":"水の中の不純物をフィルターで**取り除く**。","vi":"Loại bỏ tạp chất trong nước bằng bộ lọc."},{"jp":"患者の不安を**取り除く**のも医師の大切な役目だ。","vi":"Xua tan nỗi lo của bệnh nhân cũng là vai trò quan trọng của bác sĩ."}],
  "438": [{"jp":"切れた電球を新しいものに**取り替えた**。","vi":"Tôi đã thay bóng đèn bị cháy bằng cái mới."},{"jp":"姉とセーターを**取り替えて**着てみた。","vi":"Tôi đổi áo len với chị gái để mặc thử."}],
  "439": [{"jp":"台所の天井に火災報知器を**取り付けた**。","vi":"Tôi đã lắp thiết bị báo cháy trên trần bếp."},{"jp":"粘り強い交渉の末、大手企業との契約を**取り付けた**。","vi":"Sau cuộc đàm phán bền bỉ, chúng tôi đã đạt được hợp đồng với một doanh nghiệp lớn."}],
  "440": [{"jp":"壊れやすい品物なので、丁寧に**取り扱って**ください。","vi":"Đây là hàng dễ vỡ nên xin hãy xử lý cẩn thận."},{"jp":"当店では海外のワインも**取り扱って**おります。","vi":"Cửa hàng chúng tôi cũng có bán rượu vang nước ngoài."}],
  "441": [{"jp":"両社は契約の条件を文書で**取り決めた**。","vi":"Hai công ty đã thỏa thuận các điều kiện hợp đồng bằng văn bản."},{"jp":"会議で**取り決めた**ルールは、全員が守らなければならない。","vi":"Mọi người đều phải tuân thủ quy tắc đã thống nhất trong cuộc họp."}],
  "442": [{"jp":"参加者の意見を**取りまとめて**、報告書を作成した。","vi":"Tôi tổng hợp ý kiến của người tham gia và lập báo cáo."},{"jp":"部長の尽力で、難航していた商談を**取りまとめる**ことができた。","vi":"Nhờ nỗ lực của trưởng phòng, cuộc đàm phán thương mại đang bế tắc đã được dàn xếp xong."}],
  "443": [{"jp":"台風が近づいているため、旅行を**取りやめた**。","vi":"Vì bão đang đến gần nên tôi đã hủy chuyến du lịch."},{"jp":"感染症の拡大を受けて、今年の花火大会は**取りやめ**となった。","vi":"Do dịch bệnh lan rộng, lễ hội pháo hoa năm nay đã bị hủy."}],
  "444": [{"jp":"全国からおいしいものを**取り寄せて**食べるのが趣味だ。","vi":"Sở thích của tôi là đặt mua đồ ngon từ khắp cả nước về ăn."},{"jp":"店頭にないサイズは、本社から**取り寄せる**ことができます。","vi":"Những cỡ không có tại cửa hàng có thể đặt gửi từ trụ sở chính."}],
  "445": [{"jp":"報告書を提出したが、上司に書き直せと**突き返された**。","vi":"Tôi đã nộp báo cáo nhưng bị sếp trả lại bắt viết lại."},{"jp":"彼は賄賂として渡された封筒を**突き返した**。","vi":"Anh ấy đã gạt trả lại phong bì được đưa làm tiền hối lộ."}],
  "446": [{"jp":"逃げようとした男は警官を**突き飛ばした**。","vi":"Người đàn ông định bỏ trốn đã xô ngã viên cảnh sát."},{"jp":"満員電車で後ろから**突き飛ばされ**、転びそうになった。","vi":"Trên tàu đông người, tôi bị xô mạnh từ phía sau suýt ngã."}],
  "447": [{"jp":"優勝が決まった瞬間、選手たちはこぶしを**突き上げた**。","vi":"Khoảnh khắc chức vô địch được định đoạt, các cầu thủ giơ cao nắm đấm."},{"jp":"現場の社員たちに**突き上げられて**、社長は方針を変えた。","vi":"Bị nhân viên ở hiện trường gây sức ép, giám đốc đã thay đổi phương châm."}],
  "448": [{"jp":"電車の窓から顔を**突き出す**と危ないですよ。","vi":"Thò mặt ra ngoài cửa sổ tàu là nguy hiểm đấy."},{"jp":"乗客たちはスリを捕まえて警察に**突き出した**。","vi":"Hành khách bắt được kẻ móc túi và giao nộp cho cảnh sát."}],
  "449": [{"jp":"甘えてくる子どもを**突き放す**のも、時には必要だ。","vi":"Đôi khi cũng cần phải đẩy ra những đứa trẻ hay nhõng nhẽo."},{"jp":"困って相談したのに、「自分で考えろ」と**突き放された**。","vi":"Khó khăn nên tôi đi hỏi ý kiến, vậy mà bị bỏ mặc với câu \"Tự mà nghĩ đi\"."}],
  "450": [{"jp":"強盗は店員にナイフを**突きつけて**、金を出せと脅した。","vi":"Tên cướp chĩa dao vào nhân viên, đe dọa bắt đưa tiền."},{"jp":"動かぬ証拠を**突きつけられ**、容疑者はついに罪を認めた。","vi":"Bị đưa ra bằng chứng không thể chối cãi, nghi phạm cuối cùng đã nhận tội."}],
  "451": [{"jp":"原本と写本を**突き合わせて**、違いを調べた。","vi":"Tôi đối chiếu bản gốc với bản chép để tìm điểm khác biệt."},{"jp":"両国の代表が膝を**突き合わせて**話し合った。","vi":"Đại diện hai nước đã ngồi sát gối bàn bạc với nhau."}],
  "452": [{"jp":"警察はついに犯人の隠れ家を**突き止めた**。","vi":"Cảnh sát cuối cùng đã tìm ra nơi ẩn náu của thủ phạm."},{"jp":"専門家たちが事故の原因を**突き止める**まで、運行は停止される。","vi":"Hoạt động vận hành sẽ bị dừng cho đến khi các chuyên gia xác định được nguyên nhân tai nạn."}],
  "453": [{"jp":"問題を**突き詰めて**考えると、原因は組織の体質にある。","vi":"Truy xét vấn đề đến tận cùng thì nguyên nhân nằm ở bản chất của tổ chức."},{"jp":"不明な点は最後まで**突き詰める**のが彼のやり方だ。","vi":"Cách làm của anh ấy là tìm hiểu thấu đáo đến cùng những điểm chưa rõ."}],
  "454": [{"jp":"猫が塀の上から**飛び降りた**。","vi":"Con mèo nhảy xuống từ trên bờ tường."},{"jp":"走っている電車から**飛び降りる**のは大変危険です。","vi":"Nhảy ra khỏi tàu đang chạy là cực kỳ nguy hiểm."}],
  "455": [{"jp":"営業の仕事で、毎日取引先を**飛び歩いて**いる。","vi":"Vì làm kinh doanh nên ngày nào tôi cũng chạy đôn chạy đáo giữa các đối tác."},{"jp":"彼女は記者として世界中を**飛び歩いて**きた。","vi":"Cô ấy đã đi khắp thế giới với tư cách phóng viên."}],
  "456": [{"jp":"目覚まし時計が鳴らず、遅刻だと気づいて**飛び起きた**。","vi":"Đồng hồ báo thức không kêu, nhận ra mình bị muộn là tôi bật dậy."},{"jp":"夜中に大きな地震があり、家族全員が**飛び起きた**。","vi":"Nửa đêm có trận động đất lớn, cả nhà đều bật dậy."}],
  "457": [{"jp":"馬は高い柵を軽々と**飛び越えた**。","vi":"Con ngựa nhảy qua hàng rào cao một cách nhẹ nhàng."},{"jp":"彼は先輩たちを**飛び越えて**、課長に昇進した。","vi":"Anh ấy vượt mặt các đàn anh để được thăng chức trưởng nhóm."}],
  "458": [{"jp":"久しぶりに帰ってきた父親に、娘が**飛びついた**。","vi":"Cô con gái nhào tới ôm người bố lâu ngày mới về."},{"jp":"安さだけに**飛びつく**と、後で後悔することになる。","vi":"Chỉ vồ lấy vì rẻ thì sau này sẽ phải hối hận."}],
  "459": [{"jp":"料理中に油が**飛び散って**、手をやけどした。","vi":"Trong lúc nấu ăn, dầu bắn tung tóe làm tôi bị bỏng tay."},{"jp":"夜空に花火の火花が**飛び散る**様子は美しい。","vi":"Cảnh tia pháo hoa bắn tứ tung trên bầu trời đêm thật đẹp."}],
  "460": [{"jp":"合格の知らせを聞いて、妹は**飛び跳ねて**喜んだ。","vi":"Nghe tin thi đỗ, em gái tôi nhảy cẫng lên vui mừng."},{"jp":"池の中で魚が**飛び跳ねる**音がした。","vi":"Có tiếng cá nhảy lên trong ao."}],
  "461": [{"jp":"彼は笑顔で握手の手を**差し出した**。","vi":"Anh ấy mỉm cười chìa tay ra bắt."},{"jp":"受付で招待状を**差し出す**と、会場に案内された。","vi":"Đưa thiệp mời ở quầy lễ tân xong, tôi được dẫn vào hội trường."}],
  "462": [{"jp":"困っている人に手を**差し伸べる**のは当然のことだ。","vi":"Chìa tay giúp đỡ người đang gặp khó khăn là điều đương nhiên."},{"jp":"被災地には世界中から支援の手が**差し伸べられた**。","vi":"Vùng bị thiên tai đã nhận được bàn tay hỗ trợ từ khắp thế giới."}],
  "463": [{"jp":"読みかけの本にしおりを**差し挟んだ**。","vi":"Tôi kẹp thẻ đánh dấu vào cuốn sách đang đọc dở."},{"jp":"人が話しているときに口を**差し挟む**のは失礼だ。","vi":"Chen ngang khi người khác đang nói là bất lịch sự."}],
  "464": [{"jp":"給料から税金や保険料が**差し引かれる**。","vi":"Thuế và phí bảo hiểm bị khấu trừ từ lương."},{"jp":"売上から経費を**差し引く**と、利益はほとんど残らない。","vi":"Trừ chi phí khỏi doanh thu thì lợi nhuận gần như chẳng còn lại bao nhiêu."}],
  "465": [{"jp":"体調が悪いときは、飲酒を**差し控えて**ください。","vi":"Khi sức khỏe không tốt, xin hãy hạn chế uống rượu."},{"jp":"捜査中の事件なので、コメントは**差し控えさせて**いただきます。","vi":"Vì vụ án đang được điều tra nên xin phép không bình luận."}],
  "466": [{"jp":"資料に間違いがあったので、3枚目を**差し替えた**。","vi":"Tài liệu có lỗi nên tôi đã thay trang thứ 3."},{"jp":"放送直前に、古い映像を新しいものに**差し替えた**。","vi":"Ngay trước khi phát sóng, chúng tôi đã thay đoạn phim cũ bằng đoạn mới."}],
  "467": [{"jp":"締め切りが**差し迫って**いるので、今週は休めない。","vi":"Hạn chót đang cận kề nên tuần này không thể nghỉ."},{"jp":"住民たちは**差し迫った**危険に気づいていなかった。","vi":"Người dân đã không nhận ra mối nguy hiểm đang cận kề."}],
  "468": [{"jp":"沈んだ船をクレーンで海から**引き上げた**。","vi":"Người ta dùng cần cẩu trục con tàu đắm lên khỏi biển."},{"jp":"政府は来年、消費税を**引き上げる**方針だ。","vi":"Chính phủ có kế hoạch tăng thuế tiêu dùng vào năm sau."}],
  "469": [{"jp":"戦争が終わり、多くの人が戦地から**引き揚げて**きた。","vi":"Chiến tranh kết thúc, nhiều người đã rút về từ chiến trường."},{"jp":"政府は治安の悪化を受けて、現地から軍隊を**引き揚げた**。","vi":"Trước tình hình an ninh xấu đi, chính phủ đã rút quân khỏi nơi đó."}],
  "470": [{"jp":"自分の出番ではないと分かり、彼は黙って会議室から**引き下がった**。","vi":"Biết không phải phần của mình, anh ấy lặng lẽ lui ra khỏi phòng họp."},{"jp":"一度断られたくらいで**引き下がる**わけにはいかない。","vi":"Không thể chỉ vì bị từ chối một lần mà rút lui được."}],
  "471": [{"jp":"帰ろうとする客を「もう少しいかがですか」と**引き止めた**。","vi":"Tôi giữ vị khách định về lại: \"Ở thêm chút nữa nhé?\""},{"jp":"会社は退職を希望する優秀な社員を必死に**引き止めた**。","vi":"Công ty ra sức níu giữ nhân viên giỏi muốn nghỉ việc."}],
  "472": [{"jp":"家電量販店では古い冷蔵庫を**引き取って**くれる。","vi":"Cửa hàng điện máy sẽ thu lại tủ lạnh cũ cho mình."},{"jp":"一人暮らしが難しくなった母を、我が家に**引き取る**ことにした。","vi":"Tôi quyết định đón mẹ, người không thể sống một mình nữa, về nhà chăm sóc."}],
  "473": [{"jp":"足を**引きずって**歩く彼を見て、けがをしていると気づいた。","vi":"Thấy anh ấy đi lết chân, tôi nhận ra anh ấy bị thương."},{"jp":"彼はいつまでも過去の失敗を**引きずって**いる。","vi":"Anh ấy cứ dằn vặt mãi về thất bại trong quá khứ."}],
  "474": [{"jp":"試合の前に、監督は「気を**引き締めて**いけ」と言った。","vi":"Trước trận đấu, huấn luyện viên nói: \"Hãy tập trung tinh thần mà ra sân.\""},{"jp":"収入が減ったので、家計を**引き締める**ことにした。","vi":"Thu nhập giảm nên tôi quyết định thắt chặt chi tiêu gia đình."}],
  "475": [{"jp":"失恋した弟は、一週間も部屋に**引きこもって**いる。","vi":"Em trai thất tình, đã giam mình trong phòng suốt một tuần."},{"jp":"退職後、家に**引きこもり**がちになる高齢者も少なくない。","vi":"Không ít người cao tuổi sau khi nghỉ hưu có xu hướng thu mình ở nhà."}],
  "476": [{"jp":"旅行の写真を**引き伸ばして**、部屋に飾った。","vi":"Tôi phóng to bức ảnh du lịch rồi treo trong phòng."},{"jp":"曲がった針金をペンチでまっすぐに**引き伸ばした**。","vi":"Tôi dùng kìm kéo thẳng sợi dây thép bị cong."}],
  "477": [{"jp":"彼はいろいろな理由をつけて、返事を**引き延ばして**いる。","vi":"Anh ta viện đủ lý do để trì hoãn câu trả lời."},{"jp":"野党は審議を**引き延ばす**作戦に出た。","vi":"Phe đối lập đã dùng chiến thuật kéo dài thời gian thẩm nghị."}],
  "478": [{"jp":"名前を呼ばれて**振り返る**と、昔の同級生が立っていた。","vi":"Bị gọi tên, tôi quay lại thì thấy bạn học cũ đang đứng đó."},{"jp":"年末になると、この一年を**振り返って**反省する。","vi":"Đến cuối năm, tôi nhìn lại một năm qua và tự kiểm điểm."}],
  "479": [{"jp":"祝日が日曜日と重なったため、休みが翌日の月曜日に**振り替えられた**。","vi":"Vì ngày lễ trùng Chủ nhật nên ngày nghỉ được chuyển sang thứ Hai hôm sau."},{"jp":"鉄道会社は運休区間をバス輸送に**振り替えた**。","vi":"Công ty đường sắt đã chuyển đoạn tạm ngừng chạy tàu sang vận chuyển bằng xe buýt."}],
  "480": [{"jp":"男は棒を**振り回して**暴れた。","vi":"Người đàn ông vung gậy quậy phá."},{"jp":"彼女のわがままに、いつも**振り回されて**いる。","vi":"Tôi lúc nào cũng bị sự ích kỷ của cô ấy làm cho xoay như chong chóng."}],
  "481": [{"jp":"屋根にソーラー**パネル**を取り付けた。","vi":"Tôi đã lắp tấm pin mặt trời lên mái nhà."},{"jp":"会場の入り口に、写真の**パネル**が展示されている。","vi":"Ở lối vào hội trường có trưng bày các tấm ảnh."}],
  "482": [{"jp":"人が近づくと、**センサー**が反応して明かりがつく。","vi":"Khi có người đến gần, cảm biến phản ứng và đèn bật sáng."},{"jp":"この車には衝突を防ぐ**センサー**が付いている。","vi":"Chiếc xe này được gắn cảm biến chống va chạm."}],
  "483": [{"jp":"長時間パソコンの**ディスプレイ**を見ていると、目が疲れる。","vi":"Nhìn màn hình máy tính lâu thì mắt bị mỏi."},{"jp":"店のショーウインドーの**ディスプレイ**は季節ごとに変わる。","vi":"Cách trưng bày ở tủ kính cửa hàng thay đổi theo từng mùa."}],
  "484": [{"jp":"コンサート会場で、好きなバンドの**グッズ**を買った。","vi":"Tôi đã mua đồ lưu niệm của ban nhạc yêu thích tại địa điểm hòa nhạc."},{"jp":"最近は防災**グッズ**を用意する家庭が増えている。","vi":"Gần đây số gia đình chuẩn bị đồ dùng phòng chống thiên tai đang tăng lên."}],
  "485": [{"jp":"スーパーで卵を1**パック**買ってきた。","vi":"Tôi đã mua 1 hộp trứng ở siêu thị."},{"jp":"**パック**旅行なら、航空券もホテルもまとめて予約できる。","vi":"Nếu đi tour trọn gói thì có thể đặt cả vé máy bay lẫn khách sạn một lần."}],
  "486": [{"jp":"ホテルの**シングル**ルームを2泊予約した。","vi":"Tôi đã đặt phòng đơn khách sạn 2 đêm."},{"jp":"彼女の新しい**シングル**が来月発売される。","vi":"Đĩa đơn mới của cô ấy sẽ được phát hành vào tháng sau."}],
  "487": [{"jp":"夫婦で泊まるので、**ダブル**の部屋を予約した。","vi":"Vì hai vợ chồng cùng ở nên tôi đặt phòng đôi."},{"jp":"今日はポイントが**ダブル**でたまる日だ。","vi":"Hôm nay là ngày tích điểm gấp đôi."}],
  "488": [{"jp":"**カタログ**を見ながら、新しいソファを選んだ。","vi":"Tôi vừa xem catalog vừa chọn chiếc ghế sofa mới."},{"jp":"展示会で、各社の製品**カタログ**を集めた。","vi":"Tại triển lãm, tôi đã thu thập catalog sản phẩm của các công ty."}],
  "489": [{"jp":"彼女は高級**ブランド**のバッグを持っている。","vi":"Cô ấy có chiếc túi của thương hiệu cao cấp."},{"jp":"地元の野菜を地域**ブランド**として売り出した。","vi":"Rau củ địa phương đã được tung ra thị trường như một thương hiệu vùng."}],
  "490": [{"jp":"週末の**フリーマーケット**で、古着を安く買った。","vi":"Tôi mua được quần áo cũ giá rẻ ở chợ đồ cũ cuối tuần."},{"jp":"使わなくなったおもちゃを**フリーマーケット**に出した。","vi":"Tôi đem những món đồ chơi không dùng nữa ra chợ đồ cũ bán."}],
  "491": [{"jp":"この番組の**スポンサー**は大手自動車メーカーだ。","vi":"Nhà tài trợ của chương trình này là một hãng ô tô lớn."},{"jp":"大会を開くために、**スポンサー**を探している。","vi":"Chúng tôi đang tìm nhà tài trợ để tổ chức giải đấu."}],
  "492": [{"jp":"新発売のビールの**キャンペーン**で、試飲会が開かれた。","vi":"Trong chiến dịch quảng bá loại bia mới, một buổi uống thử đã được tổ chức."},{"jp":"市は交通事故を減らすための**キャンペーン**を始めた。","vi":"Thành phố đã khởi động chiến dịch giảm tai nạn giao thông."}],
  "493": [{"jp":"駅前の広場で、子ども向けの**イベント**が開かれる。","vi":"Một sự kiện dành cho trẻ em sẽ được tổ chức ở quảng trường trước ga."},{"jp":"会社の年末の**イベント**で司会を任された。","vi":"Tôi được giao làm MC cho sự kiện cuối năm của công ty."}],
  "494": [{"jp":"夏に開かれる音楽**フェスティバル**には、毎年数万人が訪れる。","vi":"Lễ hội âm nhạc tổ chức vào mùa hè mỗi năm thu hút hàng chục nghìn người."},{"jp":"花が見頃を迎え、フラワー**フェスティバル**が始まった。","vi":"Hoa đã vào độ đẹp nhất, lễ hội hoa đã bắt đầu."}],
  "495": [{"jp":"優勝したチームの選手たちが大通りを**パレードした**。","vi":"Các cầu thủ của đội vô địch đã diễu hành trên đại lộ."},{"jp":"祭りの日には、華やかな衣装の人々が町を**パレードする**。","vi":"Vào ngày lễ hội, những người mặc trang phục rực rỡ diễu hành khắp phố."}],
  "496": [{"jp":"週末に好きなバンドの**ライブ**を見に行く。","vi":"Cuối tuần tôi đi xem buổi diễn trực tiếp của ban nhạc yêu thích."},{"jp":"試合の様子はインターネットで**ライブ**配信される。","vi":"Trận đấu sẽ được phát trực tiếp trên internet."}],
  "497": [{"jp":"夫は**アウトドア**が好きで、休日はよくキャンプに行く。","vi":"Chồng tôi thích hoạt động ngoài trời, ngày nghỉ hay đi cắm trại."},{"jp":"**アウトドア**ブランドの服を普段着として着る人も増えた。","vi":"Số người mặc quần áo của các thương hiệu đồ dã ngoại như đồ thường ngày cũng tăng lên."}],
  "498": [{"jp":"夏休みは南の島の**リゾート**でのんびり過ごした。","vi":"Kỳ nghỉ hè tôi đã thong thả nghỉ ngơi ở khu nghỉ dưỡng trên hòn đảo phía nam."},{"jp":"この辺りは冬になると、スキー**リゾート**として賑わう。","vi":"Vùng này vào mùa đông trở nên nhộn nhịp như một khu nghỉ dưỡng trượt tuyết."}],
  "499": [{"jp":"ジェットコースターの**スリル**がたまらない。","vi":"Cảm giác hồi hộp của tàu lượn siêu tốc thật không gì sánh bằng."},{"jp":"この小説は最後まで**スリル**があって、一気に読んでしまった。","vi":"Cuốn tiểu thuyết này gay cấn đến tận cuối nên tôi đọc một mạch hết luôn."}],
  "500": [{"jp":"ピラミッドの建設方法は、古代の**ミステリー**の一つだ。","vi":"Cách xây kim tự tháp là một trong những bí ẩn của thời cổ đại."},{"jp":"寝る前に**ミステリー**小説を読むのが楽しみだ。","vi":"Đọc tiểu thuyết trinh thám trước khi ngủ là niềm vui của tôi."}],
  "501": [{"jp":"この映画は**フィクション**であり、実在の人物とは関係ありません。","vi":"Bộ phim này là hư cấu, không liên quan đến nhân vật có thật."},{"jp":"彼の話はどこまでが事実で、どこからが**フィクション**なのか分からない。","vi":"Không biết chuyện anh ta kể đến đâu là thật, từ đâu là hư cấu."}],
  "502": [{"jp":"金メダルを取った彼は、一躍国民の**ヒーロー**になった。","vi":"Giành huy chương vàng, anh ấy bỗng chốc trở thành người hùng của cả nước."},{"jp":"この映画の**ヒーロー**を演じたのは新人俳優だ。","vi":"Người đóng vai nam chính của bộ phim này là một diễn viên mới."}],
  "503": [{"jp":"私は子どもの頃からこのチームの**ファン**だ。","vi":"Tôi là người hâm mộ đội này từ hồi nhỏ."},{"jp":"パソコンの**ファン**から変な音がする。","vi":"Quạt của máy tính phát ra tiếng lạ."}],
  "504": [{"jp":"彼女は16歳で歌手として**デビューした**。","vi":"Cô ấy ra mắt với tư cách ca sĩ năm 16 tuổi."},{"jp":"期待の新人が、今日の試合でプロ**デビューする**。","vi":"Tân binh được kỳ vọng sẽ ra mắt chuyên nghiệp trong trận đấu hôm nay."}],
  "505": [{"jp":"講演会の資料に、講師の**プロフィール**が載っている。","vi":"Tài liệu buổi diễn thuyết có đăng tiểu sử sơ lược của diễn giả."},{"jp":"SNSの**プロフィール**写真を変えた。","vi":"Tôi đã đổi ảnh hồ sơ trên mạng xã hội."}],
  "506": [{"jp":"贈り物のハンカチに彼の**イニシャル**を刺繍した。","vi":"Tôi thêu chữ cái đầu tên anh ấy lên chiếc khăn tay làm quà."},{"jp":"記事では、容疑者の名前は**イニシャル**で書かれていた。","vi":"Trong bài báo, tên nghi phạm được viết tắt bằng chữ cái đầu."}],
  "507": [{"jp":"寿司は今や海外でも**ポピュラーな**料理になった。","vi":"Sushi giờ đây đã trở thành món ăn phổ biến cả ở nước ngoài."},{"jp":"この曲は日本では**ポピュラー**だが、海外ではあまり知られていない。","vi":"Bài hát này phổ biến ở Nhật nhưng ở nước ngoài thì ít người biết."}],
  "508": [{"jp":"和食は低カロリーで**ヘルシーな**料理として人気がある。","vi":"Món ăn Nhật được ưa chuộng vì ít calo và tốt cho sức khỏe."},{"jp":"最近は野菜中心の**ヘルシーな**メニューを選ぶ人が多い。","vi":"Gần đây nhiều người chọn thực đơn tốt cho sức khỏe với rau là chủ đạo."}],
  "509": [{"jp":"インターネットで見つけた**レシピ**を見ながら、カレーを作った。","vi":"Tôi vừa xem công thức tìm được trên mạng vừa nấu cà ri."},{"jp":"祖母の秘伝の**レシピ**をノートに書き写した。","vi":"Tôi chép công thức gia truyền của bà vào sổ."}],
  "510": [{"jp":"カレーには何種類もの**スパイス**が使われている。","vi":"Trong cà ri có dùng rất nhiều loại gia vị."},{"jp":"彼の皮肉は、会話にちょうどいい**スパイス**になっている。","vi":"Những câu châm biếm của anh ấy trở thành gia vị vừa vặn cho cuộc trò chuyện."}],
  "511": [{"jp":"テレビの**ボリューム**を少し下げてくれない？","vi":"Vặn nhỏ âm lượng ti vi một chút được không?"},{"jp":"この店のランチは**ボリューム**があって、しかも安い。","vi":"Bữa trưa ở quán này nhiều mà lại rẻ."}],
  "512": [{"jp":"今年は毎週、新しい料理に**トライして**いる。","vi":"Năm nay tuần nào tôi cũng thử nấu món mới."},{"jp":"やったことのない方法に**トライする**のは勇気がいる。","vi":"Thử một cách làm chưa từng làm bao giờ thì cần can đảm."}],
  "513": [{"jp":"彼は60歳でフルマラソンに**チャレンジした**。","vi":"Ông ấy đã thử thách bản thân với cuộc chạy marathon toàn phần ở tuổi 60."},{"jp":"失敗を恐れずに、新しいことに**チャレンジする**姿勢が大切だ。","vi":"Thái độ không sợ thất bại, dám thử thách điều mới là rất quan trọng."}],
  "514": [{"jp":"彼は周りに流されず、いつも**マイペース**で仕事を進める。","vi":"Anh ấy không bị người xung quanh cuốn theo, luôn làm việc theo nhịp độ riêng."},{"jp":"無理をせず、**マイペース**で勉強を続けることが大切だ。","vi":"Điều quan trọng là không gắng quá sức mà học đều đặn theo nhịp của mình."}],
  "515": [{"jp":"この仕事は**チームワーク**が何より大切だ。","vi":"Công việc này cần tinh thần làm việc nhóm hơn hết."},{"jp":"個人の能力は高くないが、**チームワーク**の良さで優勝した。","vi":"Năng lực cá nhân không cao nhưng đội đã vô địch nhờ phối hợp nhóm tốt."}],
  "516": [{"jp":"新しい**プロジェクト**のリーダーに選ばれた。","vi":"Tôi được chọn làm trưởng nhóm của dự án mới."},{"jp":"国の一大**プロジェクト**として、新空港の建設が進められている。","vi":"Việc xây dựng sân bay mới đang được tiến hành như một dự án lớn của quốc gia."}],
  "517": [{"jp":"彼は私にとって最高のビジネス**パートナー**だ。","vi":"Anh ấy là đối tác kinh doanh tuyệt vời nhất đối với tôi."},{"jp":"人生の**パートナー**を見つけて、来年結婚する予定だ。","vi":"Tôi đã tìm được người bạn đời và dự định kết hôn vào năm sau."}],
  "518": [{"jp":"週末に資産運用の**セミナー**に参加した。","vi":"Cuối tuần tôi đã tham gia buổi hội thảo về quản lý tài sản."},{"jp":"会社は新入社員向けにビジネスマナーの**セミナー**を開いた。","vi":"Công ty đã mở lớp chuyên đề về phép lịch sự trong kinh doanh cho nhân viên mới."}],
  "519": [{"jp":"大学で環境問題をテーマにした**シンポジウム**が開催された。","vi":"Một hội thảo chuyên đề về vấn đề môi trường đã được tổ chức tại trường đại học."},{"jp":"**シンポジウム**では、三人の専門家がそれぞれの立場から意見を述べた。","vi":"Tại hội thảo chuyên đề, ba chuyên gia đã trình bày ý kiến từ lập trường của mỗi người."}],
  "520": [{"jp":"大学3年生になったら、経済学の**ゼミ**に入るつもりだ。","vi":"Lên năm ba đại học, tôi định vào nhóm nghiên cứu kinh tế học."},{"jp":"**ゼミ**の仲間と卒業論文について議論した。","vi":"Tôi đã thảo luận về luận văn tốt nghiệp với các bạn trong lớp chuyên đề."}],
  "521": [{"jp":"発表の内容をA4用紙1枚の**レジュメ**にまとめた。","vi":"Tôi đã tóm tắt nội dung bài thuyết trình vào một bản tóm tắt trên một tờ giấy A4."},{"jp":"ゼミの前に、参加者全員に**レジュメ**を配っておいてください。","vi":"Trước buổi seminar, hãy phát bản tóm tắt cho tất cả người tham gia."}],
  "522": [{"jp":"新しく入った会員の**リスト**を作ってください。","vi":"Hãy lập danh sách các hội viên mới gia nhập."},{"jp":"旅行の前に持っていく物を**リスト**にしておくと、忘れ物が減る。","vi":"Trước chuyến đi, nếu liệt kê đồ cần mang thành danh sách thì sẽ ít quên đồ."}],
  "523": [{"jp":"その大学は国内の評価で常に上位に**ランクされて**いる。","vi":"Trường đại học đó luôn được xếp hạng trong nhóm đầu trong các bảng đánh giá trong nước."},{"jp":"評論家は今年の映画を独自の基準で**ランクして**いる。","vi":"Nhà phê bình xếp hạng các bộ phim năm nay theo tiêu chuẩn riêng."}],
  "524": [{"jp":"大学3年の夏に、IT企業の**インターンシップ**に参加した。","vi":"Mùa hè năm 3 đại học, tôi đã tham gia chương trình thực tập tại một công ty IT."},{"jp":"**インターンシップ**を通じて、実際の仕事の厳しさを知った。","vi":"Thông qua kỳ thực tập, tôi đã biết được sự khắc nghiệt của công việc thực tế."}],
  "525": [{"jp":"業績悪化のため、会社は大規模な**リストラ**に踏み切った。","vi":"Do kết quả kinh doanh xấu đi, công ty đã quyết định tái cơ cấu quy mô lớn."},{"jp":"父は50歳で**リストラ**され、再就職に苦労した。","vi":"Bố tôi bị cho nghỉ việc ở tuổi 50 và đã vất vả tìm việc mới."}],
  "526": [{"jp":"大学を卒業した後も就職せず、**フリーター**として生活している。","vi":"Sau khi tốt nghiệp đại học, tôi vẫn không đi làm chính thức mà sống bằng nghề làm thêm tự do."},{"jp":"**フリーター**の増加は、社会問題の一つになっている。","vi":"Sự gia tăng người làm thêm tự do đã trở thành một vấn đề xã hội."}],
  "527": [{"jp":"上司の発言は**セクハラ**にあたるとして問題になった。","vi":"Phát ngôn của cấp trên đã trở thành vấn đề vì bị coi là quấy rối tình dục."},{"jp":"社内に**セクハラ**の相談窓口が設けられた。","vi":"Công ty đã lập bộ phận tiếp nhận tư vấn về quấy rối tình dục."}],
  "528": [{"jp":"試合では、相手に対しても**フェアな**態度を忘れてはいけない。","vi":"Trong trận đấu, không được quên thái độ công bằng ngay cả với đối thủ."},{"jp":"デパートで北海道の物産**フェア**が開かれている。","vi":"Ở trung tâm thương mại đang diễn ra hội chợ sản vật Hokkaido."}],
  "529": [{"jp":"学生たちは学費値上げに抗議して授業を**ボイコットした**。","vi":"Sinh viên đã tẩy chay giờ học để phản đối việc tăng học phí."},{"jp":"環境団体がその会社の製品の**ボイコット**を呼びかけた。","vi":"Tổ chức môi trường đã kêu gọi tẩy chay sản phẩm của công ty đó."}],
  "530": [{"jp":"息子は卵に**アレルギー**があるので、外食のときは注意が必要だ。","vi":"Con trai tôi bị dị ứng trứng nên khi ăn ngoài cần chú ý."},{"jp":"彼女は「努力」という言葉に**アレルギー**を感じるらしい。","vi":"Cô ấy dường như có ác cảm với từ “nỗ lực”."}],
  "531": [{"jp":"**近年**、日本を訪れる外国人観光客が急増している。","vi":"Những năm gần đây, khách du lịch nước ngoài đến Nhật tăng mạnh."},{"jp":"**近年**まれに見る大雪で、交通が麻痺した。","vi":"Do trận tuyết lớn hiếm thấy trong những năm gần đây, giao thông bị tê liệt."}],
  "532": [{"jp":"この辺りには、**かつて**大きな工場があった。","vi":"Khu vực này trước đây từng có một nhà máy lớn."},{"jp":"再開発で、**かつて**の街並みはすっかり姿を消した。","vi":"Do tái phát triển đô thị, dãy phố ngày xưa đã hoàn toàn biến mất."}],
  "533": [{"jp":"**かねてから**の夢だった世界一周旅行が、ついに実現した。","vi":"Chuyến du lịch vòng quanh thế giới, ước mơ từ lâu, cuối cùng đã thành hiện thực."},{"jp":"**かねてより**検討しておりました新制度を、来月から導入いたします。","vi":"Chế độ mới mà chúng tôi đã xem xét từ lâu sẽ được áp dụng từ tháng sau."}],
  "534": [{"jp":"事故の原因については、**目下**調査中です。","vi":"Về nguyên nhân tai nạn, hiện đang được điều tra."},{"jp":"**目下**の課題は、人手不足をどう解消するかだ。","vi":"Vấn đề trước mắt là giải quyết tình trạng thiếu nhân lực như thế nào."}],
  "535": [{"jp":"台風の影響で、今日の便は**終日**欠航となった。","vi":"Do ảnh hưởng của bão, các chuyến bay hôm nay bị hủy cả ngày."},{"jp":"この道路は工事のため、明日は**終日**通行止めです。","vi":"Con đường này do thi công nên ngày mai bị cấm lưu thông suốt cả ngày."}],
  "536": [{"jp":"システムの不具合については、**早急に**対処いたします。","vi":"Về sự cố hệ thống, chúng tôi sẽ xử lý khẩn cấp."},{"jp":"検査の結果、医師から**早急に**入院するよう言われた。","vi":"Theo kết quả kiểm tra, bác sĩ bảo tôi phải nhập viện gấp."}],
  "537": [{"jp":"彼は転勤の打診に、**即座に**「はい」と答えた。","vi":"Anh ấy đã ngay lập tức trả lời “vâng” khi được hỏi ý về việc chuyển công tác."},{"jp":"限定商品は、発売されると**即座に**売り切れた。","vi":"Sản phẩm giới hạn vừa mở bán đã bán hết ngay lập tức."}],
  "538": [{"jp":"相手が言い終わると、彼は**すかさず**反論した。","vi":"Đối phương vừa nói xong, anh ấy liền phản bác ngay."},{"jp":"先生が質問すると、彼女は**すかさず**手を挙げた。","vi":"Thầy vừa đặt câu hỏi, cô ấy đã giơ tay ngay không chút chậm trễ."}],
  "539": [{"jp":"晴れていた空が、**不意に**暗くなった。","vi":"Bầu trời đang nắng bỗng nhiên tối sầm lại."},{"jp":"後ろから**不意に**名前を呼ばれて、驚いて振り返った。","vi":"Bất ngờ bị gọi tên từ phía sau, tôi giật mình quay lại."}],
  "540": [{"jp":"会議の最中に、**突如**地面が大きく揺れた。","vi":"Giữa cuộc họp, đột nhiên mặt đất rung chuyển mạnh."},{"jp":"人気歌手が**突如**引退を発表し、ファンに衝撃を与えた。","vi":"Ca sĩ nổi tiếng đột ngột tuyên bố giải nghệ, gây chấn động cho người hâm mộ."}],
  "541": [{"jp":"**近々**引っ越す予定なので、荷物を整理している。","vi":"Vì sắp chuyển nhà nên tôi đang sắp xếp đồ đạc."},{"jp":"新製品の詳細は、**近々**発表される見込みだ。","vi":"Chi tiết sản phẩm mới dự kiến sẽ được công bố trong thời gian tới."}],
  "542": [{"jp":"薬を飲んだから、**直に**熱も下がるでしょう。","vi":"Đã uống thuốc rồi nên chẳng mấy chốc sẽ hạ sốt thôi."},{"jp":"父は**直に**戻りますので、こちらでお待ちください。","vi":"Bố tôi sắp về rồi, xin hãy đợi ở đây."}],
  "543": [{"jp":"もう6時か。**ぼつぼつ**帰る支度をしよう。","vi":"Đã 6 giờ rồi à. Sắp sửa chuẩn bị về thôi."},{"jp":"開店して1時間ほどすると、お客が**ぼつぼつ**来始めた。","vi":"Mở cửa được khoảng một tiếng thì khách bắt đầu lác đác đến."}],
  "544": [{"jp":"**今どき**手書きの書類しか受け付けないなんて、信じられない。","vi":"Thời nay mà chỉ nhận hồ sơ viết tay thì thật không thể tin nổi."},{"jp":"**今どき**の若者は新聞を読まないと言われる。","vi":"Người ta nói giới trẻ thời nay không đọc báo."}],
  "545": [{"jp":"締め切りは昨日だったのに、**今ごろ**提出しても遅いよ。","vi":"Hạn chót là hôm qua, giờ này mới nộp thì muộn rồi."},{"jp":"去年の**今ごろ**は、まだ学生だった。","vi":"Giờ này năm ngoái tôi vẫn còn là sinh viên."}],
  "546": [{"jp":"**今さら**慌てても、もう間に合わない。","vi":"Đến giờ có cuống lên thì cũng không kịp nữa rồi."},{"jp":"何年も前のことを**今さら**謝られても困る。","vi":"Chuyện từ nhiều năm trước, đến giờ mới xin lỗi thì tôi cũng khó xử."}],
  "547": [{"jp":"小さな町工場だった会社が、**今や**世界的な企業に成長した。","vi":"Công ty vốn là một xưởng nhỏ nay đã trở thành doanh nghiệp tầm cỡ thế giới."},{"jp":"**今や**国民全員が力を合わせるべき時だ。","vi":"Chính lúc này là lúc toàn dân phải đồng lòng."}],
  "548": [{"jp":"そんなに怠けていると、**今に**後悔するよ。","vi":"Cứ lười biếng thế thì sớm muộn gì cũng hối hận đấy."},{"jp":"彼の才能なら、**今に**世界で活躍するようになるだろう。","vi":"Với tài năng của anh ấy, chẳng bao lâu nữa sẽ tỏa sáng trên thế giới."}],
  "549": [{"jp":"この交差点では**頻繁に**事故が起こっている。","vi":"Tại ngã tư này tai nạn xảy ra thường xuyên."},{"jp":"海外の取引先と**頻繁に**メールをやり取りしている。","vi":"Tôi thường xuyên trao đổi email với đối tác nước ngoài."}],
  "550": [{"jp":"彼は**始終**風邪をひいている。","vi":"Anh ấy lúc nào cũng bị cảm."},{"jp":"隣の家の犬が**始終**吠えていてうるさい。","vi":"Con chó nhà bên cứ sủa suốt, ồn quá."}],
  "551": [{"jp":"駅前のカフェには、仕事帰りに**ちょくちょく**寄っている。","vi":"Tôi hay ghé quán cà phê trước ga trên đường đi làm về."},{"jp":"彼は最近、**ちょくちょく**会社を休むようになった。","vi":"Gần đây anh ấy hay nghỉ làm."}],
  "552": [{"jp":"駅から会場まで、歩いて**およそ**15分です。","vi":"Từ ga đến hội trường đi bộ khoảng 15 phút."},{"jp":"彼の話は**およそ**現実的ではない。","vi":"Câu chuyện của anh ấy hoàn toàn không thực tế."}],
  "553": [{"jp":"この問題は国の将来にとって**極めて**重要だ。","vi":"Vấn đề này cực kỳ quan trọng đối với tương lai đất nước."},{"jp":"手術は**極めて**順調に進んだ。","vi":"Ca phẫu thuật đã diễn ra vô cùng suôn sẻ."}],
  "554": [{"jp":"このような症状が出るのは、**ごく**まれなケースです。","vi":"Xuất hiện triệu chứng như thế này là trường hợp cực hiếm."},{"jp":"反対しているのは、**ごく**一部の人たちだけだ。","vi":"Chỉ có một bộ phận rất nhỏ người phản đối."}],
  "555": [{"jp":"祖父は90歳を過ぎたが、**至って**元気だ。","vi":"Ông tôi đã ngoài 90 nhưng vẫn rất khỏe mạnh."},{"jp":"見た目は派手だが、彼の性格は**至って**真面目だ。","vi":"Vẻ ngoài thì hào nhoáng nhưng tính cách anh ấy hết sức nghiêm túc."}],
  "556": [{"jp":"彼は才能がないと言われながらも、**人一倍**努力して成功した。","vi":"Dù bị nói là không có tài, anh ấy đã nỗ lực gấp bội người khác và thành công."},{"jp":"彼女は**人一倍**責任感が強い。","vi":"Cô ấy có tinh thần trách nhiệm mạnh hơn người."}],
  "557": [{"jp":"会議の前に、資料に**一通り**目を通しておいてください。","vi":"Trước cuộc họp, hãy xem sơ qua tài liệu."},{"jp":"あの人の日本文化に関する知識は、**一通り**ではない。","vi":"Kiến thức về văn hóa Nhật của người đó không phải tầm thường."}],
  "558": [{"jp":"彼は兄より**やや**背が高い。","vi":"Anh ấy cao hơn anh trai một chút."},{"jp":"今日の東京は晴れ、気温は平年より**やや**高めでしょう。","vi":"Hôm nay Tokyo trời nắng, nhiệt độ có lẽ hơi cao hơn mọi năm."}],
  "559": [{"jp":"薬を飲んだら、痛みは**幾分**治まった。","vi":"Uống thuốc xong, cơn đau đã đỡ phần nào."},{"jp":"朝晩は**幾分**涼しくなってきた。","vi":"Sáng và tối đã trở nên mát mẻ phần nào."}],
  "560": [{"jp":"新しく始めた店は、**そこそこ**客が入っている。","vi":"Cửa hàng mới mở có lượng khách tàm tạm."},{"jp":"寝坊した彼は、朝食も**そこそこ**に家を飛び出した。","vi":"Ngủ dậy muộn, anh ấy ăn sáng vội vàng rồi lao ra khỏi nhà."}],
  "561": [{"jp":"電車の遅延により、開始時刻が**若干**遅れる見込みです。","vi":"Do tàu điện bị trễ, giờ bắt đầu dự kiến sẽ chậm một chút."},{"jp":"席にはまだ**若干**余裕がありますので、お申し込みください。","vi":"Chỗ ngồi vẫn còn trống một ít, xin mời đăng ký."}],
  "562": [{"jp":"このスープ、悪くはないけど、味が**今一つ**だね。","vi":"Món súp này không tệ nhưng vị còn thiếu chút gì đó."},{"jp":"彼の説明は、**今一つ**よく分からなかった。","vi":"Lời giải thích của anh ấy tôi chưa hiểu rõ lắm."}],
  "563": [{"jp":"子供のころは、夏休みに近所を**散々**遊び回った。","vi":"Hồi nhỏ, nghỉ hè tôi rong chơi khắp xóm thỏa thích."},{"jp":"旅行中ずっと雨で、**散々**な目に遭った。","vi":"Suốt chuyến đi trời mưa, thật là một phen khốn khổ."}],
  "564": [{"jp":"重い扉を、**ぐっと**力を入れて押し開けた。","vi":"Tôi dồn sức đẩy mở cánh cửa nặng."},{"jp":"照明を変えただけで、部屋の雰囲気が**ぐっと**よくなった。","vi":"Chỉ thay đèn thôi mà không khí căn phòng đã tốt hơn hẳn."}],
  "565": [{"jp":"実物は、写真で見るより**遥かに**大きかった。","vi":"Đồ thật lớn hơn nhiều so với nhìn trên ảnh."},{"jp":"原作の小説のほうが、映画より**遥かに**面白い。","vi":"Tiểu thuyết gốc thú vị hơn nhiều so với phim."}],
  "566": [{"jp":"彼はラグビーをやっているだけあって、**がっちりした**体格をしている。","vi":"Đúng là chơi bóng bầu dục có khác, anh ấy có thân hình rắn chắc."},{"jp":"両国の首脳は**がっちり**と握手を交わした。","vi":"Lãnh đạo hai nước đã bắt tay nhau thật chặt."}],
  "567": [{"jp":"父は背が高く、**がっしりした**体つきをしている。","vi":"Bố tôi cao và có vóc dáng vạm vỡ."},{"jp":"古い家だが、柱は**がっしり**していて地震にも強い。","vi":"Nhà cũ nhưng cột rất vững chắc, chịu được cả động đất."}],
  "568": [{"jp":"今日は空気が澄んでいて、富士山が**くっきり**見える。","vi":"Hôm nay không khí trong lành, núi Phú Sĩ hiện lên rõ nét."},{"jp":"雪の上に、動物の足跡が**くっきり**と残っていた。","vi":"Trên tuyết vẫn còn in rõ dấu chân động vật."}],
  "569": [{"jp":"彼女は**すんなり**と伸びた長い指をしている。","vi":"Cô ấy có những ngón tay dài thon thả."},{"jp":"反対されると思っていたが、企画は**すんなり**通った。","vi":"Tôi tưởng sẽ bị phản đối nhưng đề án đã được thông qua suôn sẻ."}],
  "570": [{"jp":"新しい駅の工事は、**着々と**進んでいる。","vi":"Công trình nhà ga mới đang tiến triển đều đặn."},{"jp":"彼は夢の実現に向けて、**着々と**準備を整えている。","vi":"Anh ấy đang từng bước chuẩn bị chu đáo để thực hiện ước mơ."}],
  "571": [{"jp":"夏になって、庭のトマトが**ぐんぐん**伸びている。","vi":"Sang hè, cây cà chua trong vườn lớn vùn vụt."},{"jp":"新人選手は**ぐんぐん**実力をつけ、今ではチームの中心だ。","vi":"Tuyển thủ mới tiến bộ vùn vụt, giờ đã là trụ cột của đội."}],
  "572": [{"jp":"炎天下での作業で、全員**ぐったりして**しまった。","vi":"Làm việc dưới trời nắng gắt, mọi người đều mệt lả."},{"jp":"水をやり忘れて、鉢植えの花が**ぐったりして**いる。","vi":"Quên tưới nước nên hoa trong chậu héo rũ."}],
  "573": [{"jp":"長い入院生活で、彼は**げっそり**痩せてしまった。","vi":"Sau thời gian dài nằm viện, anh ấy gầy rộc đi."},{"jp":"山積みの仕事を見て、**げっそりした**。","vi":"Nhìn đống công việc chất như núi, tôi chán ngán hẳn."}],
  "574": [{"jp":"祭りが終わると、町は**ひっそり**と静まり返った。","vi":"Lễ hội kết thúc, thị trấn trở nên vắng lặng."},{"jp":"引退後、彼は田舎で**ひっそり**と暮らしている。","vi":"Sau khi giải nghệ, ông ấy sống lặng lẽ ở quê."}],
  "575": [{"jp":"部屋の隅に、古い雑誌が**ごたごた**と積まれている。","vi":"Tạp chí cũ chất bừa bộn ở góc phòng."},{"jp":"社長の交代をめぐって、会社が**ごたごた**している。","vi":"Công ty đang rối ren xoay quanh việc thay giám đốc."}],
  "576": [{"jp":"机の上が**ごちゃごちゃ**していて、必要な書類が見つからない。","vi":"Trên bàn lộn xộn quá nên không tìm thấy giấy tờ cần thiết."},{"jp":"終わったことを、**ごちゃごちゃ**言わないでくれ。","vi":"Chuyện đã qua thì đừng nói lằng nhằng nữa."}],
  "577": [{"jp":"汗でシャツが**べたべた**して気持ち悪い。","vi":"Áo sơ mi dính nhớp mồ hôi, khó chịu quá."},{"jp":"人前で**べたべた**するカップルを見ると、目のやり場に困る。","vi":"Nhìn các cặp đôi quấn quýt nhau nơi đông người, tôi chẳng biết nhìn đi đâu."}],
  "578": [{"jp":"猫が日なたで、**さも**気持ちよさそうに眠っている。","vi":"Con mèo đang ngủ dưới nắng trông thật dễ chịu."},{"jp":"彼は何も知らないくせに、**さも**知っているかのように話す。","vi":"Anh ta chẳng biết gì mà nói như thể biết rõ lắm."}],
  "579": [{"jp":"遠いところからお越しいただき、**さぞ**お疲れでしょう。","vi":"Quý vị từ xa đến, chắc hẳn là mệt lắm."},{"jp":"一人で3人の子供を育てるのは、**さぞ**大変だろう。","vi":"Một mình nuôi 3 đứa con chắc hẳn vất vả lắm."}],
  "580": [{"jp":"**何とぞ**よろしくお願い申し上げます。","vi":"Rất mong được quý vị giúp đỡ."},{"jp":"ご迷惑をおかけしましたことを、**何とぞ**お許しください。","vi":"Xin vui lòng thứ lỗi cho việc chúng tôi đã gây phiền hà."}],
  "581": [{"jp":"ご不明な点がございましたら、**何なりと**お尋ねください。","vi":"Nếu có điểm gì chưa rõ, xin cứ hỏi bất cứ điều gì."},{"jp":"私にできることでしたら、**何なりと**お申し付けください。","vi":"Nếu là việc tôi làm được, xin cứ sai bảo bất cứ điều gì."}],
  "582": [{"jp":"徹夜して、**どうやら**締め切りに間に合わせることができた。","vi":"Thức trắng đêm, cuối cùng bằng cách nào đó tôi cũng kịp hạn."},{"jp":"空が暗くなってきた。**どうやら**雨になりそうだ。","vi":"Trời tối dần. Có vẻ sắp mưa."}],
  "583": [{"jp":"彼は帰るなりベッドに倒れ込んだ。**よほど**疲れていたのだろう。","vi":"Anh ấy vừa về đã đổ vật xuống giường. Hẳn là mệt lắm."},{"jp":"部長は**よほど**機嫌が悪かったらしく、一言も話さなかった。","vi":"Trưởng phòng hẳn là tâm trạng rất tệ nên không nói một lời."}],
  "584": [{"jp":"試験は**さほど**難しくなかった。","vi":"Bài thi không khó lắm."},{"jp":"有名な店だと聞いて行ったが、味は**さほど**でもなかった。","vi":"Nghe nói là quán nổi tiếng nên đến, nhưng vị cũng không đến mức như vậy."}],
  "585": [{"jp":"この量の仕事を一人で終わらせるのは、**到底**無理だ。","vi":"Hoàn thành khối lượng công việc này một mình là hoàn toàn không thể."},{"jp":"今から出発しても、**到底**間に合わない。","vi":"Giờ có xuất phát thì cũng không thể nào kịp."}],
  "586": [{"jp":"彼女は**一見**おとなしそうだが、実は気が強い。","vi":"Cô ấy thoạt nhìn có vẻ hiền lành nhưng thực ra rất cứng cỏi."},{"jp":"この寺の庭園は、**一見**の価値がある。","vi":"Khu vườn của ngôi chùa này đáng để xem một lần."}],
  "587": [{"jp":"何度注意しても、息子は**一向に**勉強しようとしない。","vi":"Nhắc bao nhiêu lần, con trai tôi vẫn hoàn toàn không chịu học."},{"jp":"薬を飲んでいるのに、症状が**一向に**良くならない。","vi":"Dù đang uống thuốc mà triệu chứng mãi chẳng đỡ."}],
  "588": [{"jp":"若者がみんな本を読まないとは、**一概に**は言えない。","vi":"Không thể vơ đũa cả nắm rằng giới trẻ ai cũng không đọc sách."},{"jp":"値段が高いからといって、**一概に**品質が良いとは限らない。","vi":"Không phải cứ giá cao là nhất loạt chất lượng tốt."}],
  "589": [{"jp":"試験前で、ここ数日**ろくに**寝ていない。","vi":"Trước kỳ thi, mấy ngày nay tôi chẳng ngủ được mấy."},{"jp":"警察は**ろくに**調査もしてくれなかった。","vi":"Cảnh sát chẳng chịu điều tra tử tế."}],
  "590": [{"jp":"**何でも**、田中さんは来月会社を辞めるらしい。","vi":"Nghe nói anh Tanaka tháng sau sẽ nghỉ việc."},{"jp":"**何でも**、あの店は明治時代から続いているそうだ。","vi":"Nghe đâu cửa hàng đó có từ thời Minh Trị."}],
  "591": [{"jp":"会場内での飲食**及び**喫煙は禁止されています。","vi":"Ăn uống và hút thuốc trong hội trường bị cấm."},{"jp":"申込書**及び**身分証明書のコピーを提出してください。","vi":"Hãy nộp đơn đăng ký và bản sao giấy tờ tùy thân."}],
  "592": [{"jp":"卒業生**並びに**保護者の皆様、ご卒業おめでとうございます。","vi":"Các em tốt nghiệp cùng quý phụ huynh, xin chúc mừng lễ tốt nghiệp."},{"jp":"氏名**並びに**住所をご記入の上、ご返送ください。","vi":"Vui lòng ghi họ tên và địa chỉ rồi gửi lại."}],
  "593": [{"jp":"ご連絡は、電話**もしくは**メールでお願いします。","vi":"Xin liên lạc bằng điện thoại hoặc email."},{"jp":"本人**もしくは**代理人が、窓口で手続きを行ってください。","vi":"Bản thân hoặc người đại diện hãy làm thủ tục tại quầy."}],
  "594": [{"jp":"不合格の場合は再試験を受けられる。**但し**、受験料が必要だ。","vi":"Trường hợp không đỗ có thể thi lại. Tuy nhiên phải đóng lệ phí."},{"jp":"当院は日曜休診です。**但し**、急患は受け付けます。","vi":"Bệnh viện nghỉ khám chủ nhật. Tuy nhiên vẫn nhận ca cấp cứu."}],
  "595": [{"jp":"会議は3時から始めます。**なお**、資料は当日配布します。","vi":"Cuộc họp bắt đầu từ 3 giờ. Ngoài ra, tài liệu sẽ được phát vào hôm đó."},{"jp":"戦後80年が経った今**なお**、戦争の傷跡は残っている。","vi":"80 năm sau chiến tranh, đến nay vẫn còn vết thương chiến tranh."}],
  "596": [{"jp":"帽子を買ってきてほしい。**ちなみに**、黒い帽子がいい。","vi":"Tôi muốn bạn mua mũ về. Nhân tiện, mũ màu đen thì tốt."},{"jp":"今日の会場は市民ホールです。**ちなみに**、駐車場はありません。","vi":"Địa điểm hôm nay là hội trường thành phố. Nhân tiện, không có bãi đỗ xe."}],
  "597": [{"jp":"A選手は実力がある。**もっとも**、プロになれるかどうかは分からないが。","vi":"Tuyển thủ A có thực lực. Tuy nhiên, có thành chuyên nghiệp được hay không thì chưa biết."},{"jp":"あんなことを言われたら、彼女が怒るのも**もっとも**だ。","vi":"Bị nói như thế thì cô ấy giận cũng là đương nhiên."}],
  "598": [{"jp":"我思う、**故に**我あり。","vi":"Tôi tư duy, nên tôi tồn tại."},{"jp":"三角形ABCは二等辺三角形である。**故に**、二つの底角は等しい。","vi":"Tam giác ABC là tam giác cân. Do đó, hai góc đáy bằng nhau."}],
  "599": [{"jp":"右の者は成績優秀である。**よって**、ここに奨学金を授与する。","vi":"Người có tên trên có thành tích học tập xuất sắc. Do đó, xin trao học bổng."},{"jp":"賛成多数。**よって**、本案は可決されました。","vi":"Đa số tán thành. Do đó, dự án này đã được thông qua."}],
  "600": [{"jp":"旅行には行けないよ。お金もないし、**第一**時間がない。","vi":"Không đi du lịch được đâu. Không có tiền, mà trước hết là không có thời gian."},{"jp":"そんな計画は無理だ。**第一**、誰が費用を出すんだ。","vi":"Kế hoạch đó không khả thi. Trước hết, ai sẽ bỏ tiền ra chứ."}],
  "601": [{"jp":"夕食の後は、家族が**団らんする**大切な時間だ。","vi":"Sau bữa tối là khoảng thời gian quý giá để gia đình quây quần."},{"jp":"正月には親戚が集まって、楽しい**団らん**のひとときを過ごした。","vi":"Dịp Tết, họ hàng tụ họp và có những giây phút sum vầy vui vẻ."}],
  "602": [{"jp":"秋の**行楽**シーズンを迎え、観光地はにぎわっている。","vi":"Bước vào mùa du ngoạn mùa thu, các điểm du lịch nhộn nhịp."},{"jp":"連休は**行楽**客の車で、高速道路が渋滞した。","vi":"Kỳ nghỉ dài, đường cao tốc bị kẹt vì xe của khách đi chơi."}],
  "603": [{"jp":"大阪で**本場**のたこ焼きを食べた。","vi":"Tôi đã ăn takoyaki chính gốc ở Osaka."},{"jp":"彼はフランス料理を学ぶため、**本場**パリに留学した。","vi":"Anh ấy du học tại Paris, nơi khởi nguồn, để học ẩm thực Pháp."}],
  "604": [{"jp":"店が混んでいたので、知らない人と**相席**になった。","vi":"Quán đông nên tôi phải ngồi chung bàn với người lạ."},{"jp":"「ただいま満席のため、**相席**でもよろしいでしょうか。」","vi":"“Hiện đã hết chỗ, quý khách có đồng ý ngồi chung bàn không ạ?”"}],
  "605": [{"jp":"テストで100点を取ったご**褒美**に、新しいゲームを買ってもらった。","vi":"Phần thưởng cho việc được 100 điểm, tôi được mua cho trò chơi mới."},{"jp":"仕事を頑張った自分への**褒美**に、高級レストランで食事をした。","vi":"Để tự thưởng cho bản thân đã làm việc chăm chỉ, tôi đi ăn ở nhà hàng sang trọng."}],
  "606": [{"jp":"祖父が残した**遺産**をめぐって、兄弟が争っている。","vi":"Anh em tranh chấp nhau quanh khối tài sản ông để lại."},{"jp":"富士山は世界**遺産**に登録されている。","vi":"Núi Phú Sĩ được công nhận là di sản thế giới."}],
  "607": [{"jp":"雨のせいで、楽しみにしていた運動会が**台無し**になった。","vi":"Vì mưa mà hội thao mong đợi đã hỏng bét."},{"jp":"一言の失言で、これまでの努力が**台無し**だ。","vi":"Chỉ một lời lỡ miệng mà bao nỗ lực đến giờ thành công cốc."}],
  "608": [{"jp":"社会人としての**心構え**を、新入社員に伝えた。","vi":"Tôi đã truyền đạt cho nhân viên mới tinh thần cần có của một người đi làm."},{"jp":"災害はいつ起こるか分からないので、日頃からの**心構え**が大切だ。","vi":"Thiên tai không biết xảy ra lúc nào nên sự chuẩn bị tinh thần hằng ngày rất quan trọng."}],
  "609": [{"jp":"このソファは座り**心地**がいい。","vi":"Chiếc sofa này ngồi rất thoải mái."},{"jp":"合格の知らせを聞いて、天にも昇る**心地**がした。","vi":"Nghe tin đỗ, tôi cảm thấy như bay lên trời."}],
  "610": [{"jp":"パズルを完成させるには、**根気**が要る。","vi":"Để hoàn thành trò ghép hình cần sự kiên nhẫn."},{"jp":"先生は勉強の苦手な生徒に、**根気**よく教え続けた。","vi":"Thầy kiên nhẫn tiếp tục dạy học sinh học kém."}],
  "611": [{"jp":"彼は**意地**を張って、最後まで謝ろうとしなかった。","vi":"Anh ấy cố chấp, đến cuối cùng vẫn không chịu xin lỗi."},{"jp":"わざと難しい質問をするなんて、彼は**意地**が悪い。","vi":"Cố tình hỏi câu khó, anh ta thật là xấu tính."}],
  "612": [{"jp":"彼はリーダーとしての責任を**自覚して**いる。","vi":"Anh ấy ý thức được trách nhiệm của một người lãnh đạo."},{"jp":"初期の段階では、病気の**自覚**症状がほとんどない。","vi":"Ở giai đoạn đầu hầu như không có triệu chứng mà người bệnh tự nhận biết được."}],
  "613": [{"jp":"外見だけで人を判断するのは**偏見**だ。","vi":"Đánh giá người chỉ qua bề ngoài là định kiến."},{"jp":"病気に対する社会の**偏見**をなくしたい。","vi":"Tôi muốn xóa bỏ định kiến của xã hội đối với căn bệnh."}],
  "614": [{"jp":"ダイエット中なのに、ケーキの**誘惑**に負けてしまった。","vi":"Đang ăn kiêng mà tôi lại thua cám dỗ của chiếc bánh."},{"jp":"彼女は言葉巧みに男を**誘惑した**。","vi":"Cô ta đã khéo dùng lời lẽ để quyến rũ đàn ông."}],
  "615": [{"jp":"恋人を**束縛し**すぎると、嫌われてしまう。","vi":"Ràng buộc người yêu quá mức sẽ bị ghét."},{"jp":"規則に**束縛される**生活から抜け出したい。","vi":"Tôi muốn thoát khỏi cuộc sống bị quy tắc trói buộc."}],
  "616": [{"jp":"**油断した**隙に、財布を盗まれた。","vi":"Trong lúc lơ là, tôi bị trộm mất ví."},{"jp":"相手が弱いからといって、**油断して**はいけない。","vi":"Không được chủ quan chỉ vì đối thủ yếu."}],
  "617": [{"jp":"彼は、いつか業界のトップになるという**野心**を抱いている。","vi":"Anh ấy ôm tham vọng một ngày trở thành người đứng đầu ngành."},{"jp":"その国は領土拡大の**野心**を隠そうとしなかった。","vi":"Quốc gia đó không hề che giấu dã tâm mở rộng lãnh thổ."}],
  "618": [{"jp":"店で見かけたコートを、つい**衝動**買いしてしまった。","vi":"Tôi đã lỡ mua bốc đồng chiếc áo khoác nhìn thấy ở cửa hàng."},{"jp":"全部投げ出したいという**衝動**に駆られた。","vi":"Tôi bị thôi thúc muốn buông bỏ tất cả."}],
  "619": [{"jp":"彼は自分の**信念**を曲げない人だ。","vi":"Anh ấy là người không bao giờ bẻ cong niềm tin của mình."},{"jp":"「努力は必ず報われる」というのが私の**信念**だ。","vi":"“Nỗ lực nhất định được đền đáp” là niềm tin của tôi."}],
  "620": [{"jp":"高齢者に**配慮して**、駅にエレベーターが設置された。","vi":"Để quan tâm đến người cao tuổi, ga đã lắp thang máy."},{"jp":"彼の細やかな**配慮**のおかげで、会議は和やかに進んだ。","vi":"Nhờ sự chu đáo tỉ mỉ của anh ấy, cuộc họp diễn ra hòa nhã."}],
  "621": [{"jp":"引退して、ようやく生活に**ゆとり**ができた。","vi":"Nghỉ hưu rồi cuối cùng cuộc sống mới thong thả."},{"jp":"時間に**ゆとり**を持って家を出ましょう。","vi":"Hãy ra khỏi nhà sớm để dư dả thời gian."}],
  "622": [{"jp":"彼は**包容力**があって、誰の意見にも耳を傾ける。","vi":"Anh ấy bao dung, lắng nghe ý kiến của bất kỳ ai."},{"jp":"結婚相手に**包容力**のある人を求める女性は多い。","vi":"Nhiều phụ nữ tìm bạn đời là người có lòng bao dung."}],
  "623": [{"jp":"もう40歳なのだから、年**相応**の服装をしなさい。","vi":"Đã 40 tuổi rồi, hãy ăn mặc phù hợp với tuổi."},{"jp":"高い給料をもらっているのだから、それ**相応**の働きが求められる。","vi":"Đã nhận lương cao thì được yêu cầu làm việc tương xứng."}],
  "624": [{"jp":"彼の料理の腕はプロ**並み**だ。","vi":"Tay nghề nấu ăn của anh ấy ngang tầm dân chuyên nghiệp."},{"jp":"京都には、古い町**並み**が今も残っている。","vi":"Ở Kyoto, những dãy phố cổ vẫn còn đến ngày nay."}],
  "625": [{"jp":"来客の前で子供を叱るのは、**体裁**が悪い。","vi":"Mắng con trước mặt khách thì thật mất thể diện."},{"jp":"彼は**体裁**ばかり気にして、本当のことを言わない。","vi":"Anh ta chỉ lo giữ thể diện mà không nói thật."}],
  "626": [{"jp":"棚の上の箱を取ろうと、**背伸びした**。","vi":"Tôi nhón chân để lấy chiếc hộp trên kệ."},{"jp":"中学生の娘は**背伸び**して、大人っぽい服を着たがる。","vi":"Con gái học cấp 2 ra vẻ người lớn, thích mặc đồ trưởng thành."}],
  "627": [{"jp":"彼は酒を飲むと、いつも会社の**愚痴**をこぼす。","vi":"Cứ uống rượu là anh ấy lại than vãn về công ty."},{"jp":"**愚痴**ばかり言っていないで、行動しなさい。","vi":"Đừng chỉ toàn than vãn, hãy hành động đi."}],
  "628": [{"jp":"首相の演説中、議員たちから**野次**が飛んだ。","vi":"Trong lúc thủ tướng phát biểu, các nghị sĩ đã la ó."},{"jp":"観客の**野次**にも負けず、選手は最後まで戦った。","vi":"Bất chấp tiếng la ó của khán giả, tuyển thủ đã thi đấu đến cùng."}],
  "629": [{"jp":"残業している同僚たちに、おにぎりを**差し入れした**。","vi":"Tôi mang cơm nắm đến tiếp tế cho các đồng nghiệp đang làm thêm giờ."},{"jp":"ドアのすき間から、チラシが**差し入れられて**いた。","vi":"Tờ rơi đã được nhét vào qua khe cửa."}],
  "630": [{"jp":"沿道の人々が、マラソンランナーに**声援**を送った。","vi":"Người dân hai bên đường đã cổ vũ các vận động viên marathon."},{"jp":"地元のチームを全力で**声援した**。","vi":"Tôi đã cổ vũ hết sức cho đội nhà."}],
  "631": [{"jp":"来月、日米**首脳**会談が行われる。","vi":"Tháng sau sẽ diễn ra hội đàm thượng đỉnh Nhật – Mỹ."},{"jp":"会社の**首脳**陣が、記者会見で謝罪した。","vi":"Ban lãnh đạo công ty đã xin lỗi trong buổi họp báo."}],
  "632": [{"jp":"政府は円高を止めるため、為替市場に**介入した**。","vi":"Chính phủ đã can thiệp vào thị trường ngoại hối để ngăn đồng yên tăng giá."},{"jp":"警察は原則として、民事の争いには**介入し**ない。","vi":"Về nguyên tắc, cảnh sát không can thiệp vào tranh chấp dân sự."}],
  "633": [{"jp":"国境には多くの**兵**が配置されている。","vi":"Nhiều binh lính được bố trí ở biên giới."},{"jp":"戦争が終わり、**兵**たちは故郷へ帰っていった。","vi":"Chiến tranh kết thúc, binh lính đã trở về quê hương."}],
  "634": [{"jp":"他国の政治に**干渉する**べきではない。","vi":"Không nên can thiệp vào chính trị nước khác."},{"jp":"もう大人なんだから、私のすることに**干渉し**ないで。","vi":"Tôi đã lớn rồi, đừng can thiệp vào việc tôi làm."}],
  "635": [{"jp":"本人の許可なく写真を公開するのは、プライバシーを**侵害する**行為だ。","vi":"Đăng ảnh khi chưa được người đó cho phép là hành vi xâm phạm quyền riêng tư."},{"jp":"その会社は特許を**侵害した**として訴えられた。","vi":"Công ty đó bị kiện vì xâm phạm bằng sáng chế."}],
  "636": [{"jp":"地震の後は、津波を**警戒して**高台に避難してください。","vi":"Sau động đất, hãy đề phòng sóng thần và sơ tán lên chỗ cao."},{"jp":"野良猫は人を**警戒して**、なかなか近づいてこない。","vi":"Mèo hoang cảnh giác với người nên mãi không lại gần."}],
  "637": [{"jp":"その会社は経営**危機**に陥っている。","vi":"Công ty đó đang lâm vào khủng hoảng kinh doanh."},{"jp":"多くの野生動物が絶滅の**危機**にさらされている。","vi":"Nhiều động vật hoang dã đang đứng trước nguy cơ tuyệt chủng."}],
  "638": [{"jp":"彼の突然の死は、世間に**衝撃**を与えた。","vi":"Cái chết đột ngột của anh ấy đã gây chấn động dư luận."},{"jp":"このケースは、落としたときの**衝撃**からスマホを守ってくれる。","vi":"Chiếc ốp này bảo vệ điện thoại khỏi va đập khi bị rơi."}],
  "639": [{"jp":"労使双方が**譲歩し**、ようやく合意に達した。","vi":"Cả chủ và người lao động đã nhượng bộ, cuối cùng đạt được thỏa thuận."},{"jp":"価格については、これ以上**譲歩**できません。","vi":"Về giá cả, chúng tôi không thể nhượng bộ thêm nữa."}],
  "640": [{"jp":"彼は新薬の開発によって、医学の進歩に**貢献した**。","vi":"Ông ấy đã đóng góp cho sự tiến bộ y học bằng việc phát triển thuốc mới."},{"jp":"彼女の活躍は、チームの優勝に大きく**貢献した**。","vi":"Màn thể hiện của cô ấy đã đóng góp lớn vào chức vô địch của đội."}],
  "641": [{"jp":"政府は再生可能エネルギーの普及を**推進して**いる。","vi":"Chính phủ đang thúc đẩy phổ cập năng lượng tái tạo."},{"jp":"この船はスクリューの力で**推進される**。","vi":"Con tàu này được đẩy đi bằng lực của chân vịt."}],
  "642": [{"jp":"飛行機は出発前に入念に**整備される**。","vi":"Máy bay được bảo dưỡng kỹ lưỡng trước khi cất cánh."},{"jp":"市は子育てしやすい環境を**整備する**ことに力を入れている。","vi":"Thành phố đang chú trọng hoàn thiện môi trường thuận lợi cho việc nuôi con."}],
  "643": [{"jp":"少子化に**歯止め**をかけるための対策が求められている。","vi":"Cần có biện pháp để kìm hãm tình trạng tỉ lệ sinh giảm."},{"jp":"円安に**歯止め**がかからず、輸入品の値段が上がり続けている。","vi":"Đồng yên mất giá không kìm lại được, giá hàng nhập khẩu tiếp tục tăng."}],
  "644": [{"jp":"毎日の練習の**成果**が、試合で表れた。","vi":"Thành quả luyện tập hằng ngày đã thể hiện trong trận đấu."},{"jp":"研究チームは、長年の**成果**を学会で発表した。","vi":"Nhóm nghiên cứu đã công bố thành quả nhiều năm tại hội nghị khoa học."}],
  "645": [{"jp":"彼は**正義**のために戦う弁護士だ。","vi":"Anh ấy là luật sư đấu tranh vì chính nghĩa."},{"jp":"何が**正義**かは、立場によって異なる。","vi":"Thế nào là chính nghĩa thì tùy vào lập trường mà khác nhau."}],
  "646": [{"jp":"軍隊では、**規律**が何よりも重視される。","vi":"Trong quân đội, kỷ luật được coi trọng hơn hết."},{"jp":"寮生活を通じて、**規律**ある生活が身についた。","vi":"Qua cuộc sống ký túc xá, tôi đã quen với nếp sống kỷ luật."}],
  "647": [{"jp":"災害時にも**秩序**を守って行動する日本人の姿が称賛された。","vi":"Hình ảnh người Nhật giữ trật tự ngay cả khi thiên tai đã được ca ngợi."},{"jp":"内戦によって、社会の**秩序**が崩壊した。","vi":"Do nội chiến, trật tự xã hội đã sụp đổ."}],
  "648": [{"jp":"都市と地方の経済**格差**が広がっている。","vi":"Chênh lệch kinh tế giữa thành thị và địa phương đang ngày càng lớn."},{"jp":"男女の賃金**格差**は、まだ解消されていない。","vi":"Chênh lệch lương giữa nam và nữ vẫn chưa được xóa bỏ."}],
  "649": [{"jp":"彼は仕事のために家族を**犠牲**にしてきた。","vi":"Anh ấy đã hy sinh gia đình vì công việc."},{"jp":"その事故で多くの人が**犠牲**になった。","vi":"Nhiều người đã trở thành nạn nhân trong vụ tai nạn đó."}],
  "650": [{"jp":"大雨で川が**氾濫し**、多くの家が浸水した。","vi":"Do mưa lớn, sông tràn bờ, nhiều nhà bị ngập."},{"jp":"インターネット上には、真偽の分からない情報が**氾濫して**いる。","vi":"Trên internet tràn lan thông tin không rõ thật giả."}],
  "651": [{"jp":"台風の影響で、電車の復旧の**見込み**は立っていない。","vi":"Do ảnh hưởng của bão, vẫn chưa có triển vọng khôi phục tàu điện."},{"jp":"今年の売上は前年を上回る**見込み**だ。","vi":"Doanh thu năm nay dự kiến sẽ vượt năm trước."}],
  "652": [{"jp":"景気の**見通し**は依然として不透明だ。","vi":"Triển vọng kinh tế vẫn còn mờ mịt."},{"jp":"霧が濃くて、山道の**見通し**が悪い。","vi":"Sương mù dày đặc nên tầm nhìn trên đường núi rất kém."}],
  "653": [{"jp":"引っ越しの前に、三社から**見積もり**を取った。","vi":"Trước khi chuyển nhà, tôi đã lấy báo giá từ ba công ty."},{"jp":"工事の**見積もり**が予算を大幅に超えてしまった。","vi":"Bản ước tính chi phí thi công đã vượt quá ngân sách rất nhiều."}],
  "654": [{"jp":"この国では今も古い紙幣が**流通して**いる。","vi":"Ở nước này tiền giấy cũ vẫn còn đang lưu hành."},{"jp":"震災で道路が寸断され、物資の**流通**が止まった。","vi":"Vì động đất, đường sá bị chia cắt và việc lưu thông hàng hóa bị ngừng lại."}],
  "655": [{"jp":"大雪のため、物流が**停滞して**いる。","vi":"Do tuyết rơi dày, việc vận chuyển hàng hóa đang bị đình trệ."},{"jp":"長引く景気の**停滞**が若者の雇用に影響している。","vi":"Sự đình trệ kéo dài của nền kinh tế đang ảnh hưởng đến việc làm của giới trẻ."}],
  "656": [{"jp":"新製品の売れ行きが**不振**で、会社は赤字になった。","vi":"Sản phẩm mới bán ế ẩm nên công ty bị lỗ."},{"jp":"打撃**不振**に苦しむ選手が、ようやくホームランを打った。","vi":"Cầu thủ đang khổ sở vì phong độ đánh bóng sa sút cuối cùng cũng đánh được cú home run."}],
  "657": [{"jp":"市は利用者の少ないバス路線を**廃止する**ことにした。","vi":"Thành phố quyết định bãi bỏ tuyến xe buýt ít người đi."},{"jp":"死刑制度を**廃止した**国は年々増えている。","vi":"Số quốc gia đã bãi bỏ án tử hình đang tăng lên qua từng năm."}],
  "658": [{"jp":"この町はかつて宿場町として**繁栄した**。","vi":"Thị trấn này từng phồn vinh như một trạm nghỉ chân trên đường cái."},{"jp":"国家の**繁栄**は教育にかかっていると言われる。","vi":"Người ta nói sự thịnh vượng của quốc gia phụ thuộc vào giáo dục."}],
  "659": [{"jp":"日本の自動車市場はすでに**成熟して**おり、大きな成長は望めない。","vi":"Thị trường ô tô Nhật Bản đã bão hòa nên khó mong đợi tăng trưởng lớn."},{"jp":"彼は年齢の割に考え方が**成熟して**いる。","vi":"So với tuổi, cách suy nghĩ của anh ấy rất chín chắn."}],
  "660": [{"jp":"新技術の開発によって、会社は大きく**飛躍した**。","vi":"Nhờ phát triển công nghệ mới, công ty đã có bước phát triển nhảy vọt."},{"jp":"君の意見は論理が**飛躍して**いて、説得力に欠ける。","vi":"Ý kiến của cậu lập luận nhảy cóc nên thiếu sức thuyết phục."}],
  "661": [{"jp":"育児と仕事を**両立させる**のは簡単ではない。","vi":"Cân bằng giữa việc nuôi con và công việc không hề đơn giản."},{"jp":"経済成長と環境保護は**両立できる**のだろうか。","vi":"Liệu tăng trưởng kinh tế và bảo vệ môi trường có thể song hành được không?"}],
  "662": [{"jp":"政府の**統計**によると、出生率は過去最低を記録した。","vi":"Theo thống kê của chính phủ, tỷ lệ sinh đã ghi nhận mức thấp nhất từ trước đến nay."},{"jp":"大学で**統計**学を学び、データ分析の仕事に就いた。","vi":"Tôi học ngành thống kê ở đại học và đã làm công việc phân tích dữ liệu."}],
  "663": [{"jp":"投資では、リスクを**分散する**ことが大切だ。","vi":"Trong đầu tư, việc phân tán rủi ro rất quan trọng."},{"jp":"プリズムを通すと、光が七色に**分散する**。","vi":"Khi đi qua lăng kính, ánh sáng bị tán sắc thành bảy màu."}],
  "664": [{"jp":"輸出と輸入の**均衡**を保つのは難しい。","vi":"Duy trì cân bằng giữa xuất khẩu và nhập khẩu là việc khó."},{"jp":"後半30分、ついに0対0の**均衡**が破られた。","vi":"Phút 30 hiệp hai, thế cân bằng 0-0 cuối cùng đã bị phá vỡ."}],
  "665": [{"jp":"長年の研究で**蓄積された**データは会社の財産だ。","vi":"Dữ liệu được tích lũy qua nhiều năm nghiên cứu là tài sản của công ty."},{"jp":"睡眠不足が続き、疲労が**蓄積して**いる。","vi":"Thiếu ngủ kéo dài nên mệt mỏi cứ tích tụ lại."}],
  "666": [{"jp":"今年の花火大会には**延べ**50万人が訪れた。","vi":"Lễ hội pháo hoa năm nay có tổng cộng 50 vạn lượt người đến xem."},{"jp":"この家の**延べ**床面積は120平方メートルだ。","vi":"Tổng diện tích sàn của ngôi nhà này là 120 mét vuông."}],
  "667": [{"jp":"少子化で、どの業界も優秀な**人材**の確保に苦労している。","vi":"Do tỷ lệ sinh giảm, ngành nào cũng vất vả trong việc tìm nhân tài giỏi."},{"jp":"会社の将来のために、若手**人材**の育成に力を入れている。","vi":"Vì tương lai công ty, chúng tôi đang chú trọng đào tạo nhân lực trẻ."}],
  "668": [{"jp":"**公衆**の面前で部下を叱るのはよくない。","vi":"Mắng cấp dưới trước mặt công chúng là không nên."},{"jp":"最近は**公衆**電話を見かけることが少なくなった。","vi":"Gần đây hiếm khi thấy điện thoại công cộng nữa."}],
  "669": [{"jp":"彼は幅広い**教養**を身につけた紳士だ。","vi":"Ông ấy là một quý ông có học thức sâu rộng."},{"jp":"大学の一年目は、主に**教養**科目を履修する。","vi":"Năm nhất đại học chủ yếu học các môn đại cương."}],
  "670": [{"jp":"子供の**視点**に立って考えると、新しい発見がある。","vi":"Khi suy nghĩ từ góc nhìn của trẻ con, ta sẽ có những phát hiện mới."},{"jp":"熱のせいか、**視点**が定まらず頭がぼんやりする。","vi":"Có lẽ do sốt nên ánh mắt không tập trung được, đầu óc mơ màng."}],
  "671": [{"jp":"安全の**観点**から、この計画には反対だ。","vi":"Từ góc độ an toàn, tôi phản đối kế hoạch này."},{"jp":"経済的な**観点**だけで政策を判断するべきではない。","vi":"Không nên đánh giá chính sách chỉ từ góc độ kinh tế."}],
  "672": [{"jp":"農業は天候に**左右されやすい**仕事だ。","vi":"Nông nghiệp là công việc dễ bị thời tiết chi phối."},{"jp":"道路を渡る前に、**左右**をよく確認しなさい。","vi":"Trước khi qua đường, hãy nhìn kỹ hai bên trái phải."}],
  "673": [{"jp":"多くの企業が深刻な人手不足に**直面して**いる。","vi":"Nhiều doanh nghiệp đang đối mặt với tình trạng thiếu nhân lực nghiêm trọng."},{"jp":"困難に**直面した**ときこそ、人の真価が問われる。","vi":"Chính khi đối mặt với khó khăn, giá trị thật của con người mới được thử thách."}],
  "674": [{"jp":"新任の部長は、まず現場の状況を**把握する**ことから始めた。","vi":"Trưởng phòng mới bắt đầu bằng việc nắm rõ tình hình thực tế."},{"jp":"被害の全容はまだ**把握されて**いない。","vi":"Toàn bộ thiệt hại vẫn chưa được nắm rõ."}],
  "675": [{"jp":"この小説は主人公の心理を細かく**描写して**いる。","vi":"Cuốn tiểu thuyết này miêu tả tỉ mỉ tâm lý của nhân vật chính."},{"jp":"彼の作品は自然の**描写**が美しいことで知られる。","vi":"Tác phẩm của ông nổi tiếng với những đoạn miêu tả thiên nhiên tuyệt đẹp."}],
  "676": [{"jp":"この箱には、開けると人形が飛び出す**仕掛け**がある。","vi":"Chiếc hộp này có cơ chế khi mở ra thì búp bê bật ra."},{"jp":"夏祭りの最後に、**仕掛け**花火が打ち上げられた。","vi":"Cuối lễ hội mùa hè, pháo hoa tạo hình đã được bắn lên."}],
  "677": [{"jp":"年金制度の**仕組み**を理解している若者は少ない。","vi":"Ít người trẻ hiểu được cơ chế của chế độ lương hưu."},{"jp":"この時計は分解して、内部の**仕組み**を調べてみた。","vi":"Tôi đã tháo chiếc đồng hồ này ra để tìm hiểu cấu tạo bên trong."}],
  "678": [{"jp":"慣れれば、魚をさばくのにも**こつ**がわかってくる。","vi":"Quen tay rồi thì sẽ nắm được bí quyết làm cá."},{"jp":"ちょっとした**こつ**で、ご飯がぐんとおいしく炊ける。","vi":"Chỉ với một chút mẹo nhỏ, cơm sẽ nấu ngon hơn hẳn."}],
  "679": [{"jp":"職人の見事な**技**に、観客は息をのんだ。","vi":"Khán giả nín thở trước kỹ thuật tuyệt vời của người thợ."},{"jp":"柔道の試合で、彼は得意の**技**で一本を取った。","vi":"Trong trận judo, anh ấy giành ippon bằng đòn sở trường của mình."}],
  "680": [{"jp":"行列の**先**が見えないほど、店の前に人が並んでいる。","vi":"Người xếp hàng trước cửa tiệm đông đến mức không nhìn thấy đầu hàng."},{"jp":"結婚なんて、まだずっと**先**のことだと思っている。","vi":"Tôi nghĩ chuyện kết hôn vẫn còn xa lắm trong tương lai."}],
  "681": [{"jp":"鉛筆の**先端**が折れてしまった。","vi":"Đầu bút chì bị gãy mất rồi."},{"jp":"この研究所は医療技術の**最先端**を走っている。","vi":"Viện nghiên cứu này đang đi đầu về công nghệ y tế."}],
  "682": [{"jp":"実験の**過程**で、思いがけない発見があった。","vi":"Trong quá trình thí nghiệm, đã có một phát hiện bất ngờ."},{"jp":"結果だけでなく、そこに至るまでの**過程**も評価すべきだ。","vi":"Không chỉ kết quả mà cả quá trình đi đến đó cũng nên được đánh giá."}],
  "683": [{"jp":"人類の**起源**はアフリカにあると考えられている。","vi":"Người ta cho rằng nguồn gốc loài người là ở châu Phi."},{"jp":"この祭りの**起源**は平安時代にさかのぼる。","vi":"Nguồn gốc của lễ hội này có từ thời Heian."}],
  "684": [{"jp":"家族と過ごす時間が、私の**唯一**の楽しみだ。","vi":"Thời gian bên gia đình là niềm vui duy nhất của tôi."},{"jp":"この島へ行く**唯一**の手段は船だ。","vi":"Phương tiện duy nhất để đến hòn đảo này là tàu thuyền."}],
  "685": [{"jp":"年末**恒例**の歌番組を家族で見た。","vi":"Cả nhà cùng xem chương trình ca nhạc thường lệ cuối năm."},{"jp":"毎年**恒例**の社員旅行は、今年は沖縄だ。","vi":"Chuyến du lịch nhân viên thường niên năm nay là Okinawa."}],
  "686": [{"jp":"試験を**目前**に控え、学生たちは必死に勉強している。","vi":"Kỳ thi đã cận kề trước mắt, các sinh viên đang học hành cật lực."},{"jp":"**目前**に広がる雄大な景色に言葉を失った。","vi":"Tôi lặng người trước cảnh hùng vĩ trải ra trước mắt."}],
  "687": [{"jp":"出発**間際**になって、パスポートを忘れたことに気づいた。","vi":"Sát giờ khởi hành mới nhận ra là quên hộ chiếu."},{"jp":"試験開始の**間際**まで、彼は単語を覚えていた。","vi":"Anh ấy học từ vựng cho đến ngay trước giờ thi."}],
  "688": [{"jp":"夕暮れの空を、鳥の**群れ**が南へ飛んでいった。","vi":"Trên bầu trời hoàng hôn, đàn chim bay về phương nam."},{"jp":"イワシは大きな**群れ**をつくって泳ぐ。","vi":"Cá mòi bơi thành những đàn lớn."}],
  "689": [{"jp":"警察はついに犯人の**正体**を突き止めた。","vi":"Cảnh sát cuối cùng đã xác định được danh tính thật của hung thủ."},{"jp":"親切そうに見えた男の**正体**は、詐欺師だった。","vi":"Người đàn ông trông có vẻ tử tế, chân tướng lại là một kẻ lừa đảo."}],
  "690": [{"jp":"畑を荒らすイノシシを捕まえるため、**罠**を仕掛けた。","vi":"Tôi đã đặt bẫy để bắt con lợn rừng phá hoại ruộng."},{"jp":"うまい話には**罠**があるから気をつけなさい。","vi":"Chuyện quá hời thường có cạm bẫy, nên hãy cẩn thận."}],
  "691": [{"jp":"大事な部分は赤い**枠**で囲んでおいた。","vi":"Tôi đã khoanh phần quan trọng bằng khung màu đỏ."},{"jp":"予算の**枠**を超えない範囲で計画を立ててください。","vi":"Hãy lập kế hoạch trong phạm vi không vượt quá giới hạn ngân sách."}],
  "692": [{"jp":"毎日手入れをしているので、この革靴はいつも**艶**がある。","vi":"Vì được chăm chút hàng ngày nên đôi giày da này lúc nào cũng bóng."},{"jp":"祖母は90歳とは思えないほど、肌に**艶**がある。","vi":"Bà tôi có làn da mịn màng đến mức không thể nghĩ là đã 90 tuổi."}],
  "693": [{"jp":"木の**陰**で少し休んでから出発しよう。","vi":"Hãy nghỉ một chút dưới bóng cây rồi xuất phát."},{"jp":"人の悪口を**陰**で言うのはやめなさい。","vi":"Đừng nói xấu người khác sau lưng."}],
  "694": [{"jp":"夕方になると、自分の**影**が長く伸びる。","vi":"Đến chiều tối, cái bóng của mình kéo dài ra."},{"jp":"カーテンに怪しい人の**影**が映っていた。","vi":"Có bóng người đáng ngờ in trên rèm cửa."}],
  "695": [{"jp":"彼女は花**柄**のワンピースがよく似合う。","vi":"Cô ấy rất hợp với chiếc váy họa tiết hoa."},{"jp":"あの辺りは**柄**の悪い連中が多いから、夜は近づかないほうがいい。","vi":"Khu đó có nhiều kẻ thô lỗ, nên buổi tối đừng lại gần."}],
  "696": [{"jp":"彼の説明は、どうも**つじつま**が合わない。","vi":"Lời giải thích của anh ta có vẻ không khớp nhau."},{"jp":"嘘をつくと、あとで**つじつま**を合わせるのが大変だ。","vi":"Nói dối thì sau đó rất vất vả để làm cho câu chuyện khớp."}],
  "697": [{"jp":"お差し**支え**なければ、ご連絡先を教えていただけますか。","vi":"Nếu không phiền, anh có thể cho tôi biết thông tin liên lạc được không?"},{"jp":"明日の会議は午後からでも、特に**差し支え**はありません。","vi":"Cuộc họp ngày mai bắt đầu từ buổi chiều cũng không có trở ngại gì."}],
  "698": [{"jp":"人員削減の**しわ寄せ**が、現場の社員に来ている。","vi":"Hậu quả của việc cắt giảm nhân sự đang dồn lên nhân viên tuyến đầu."},{"jp":"景気悪化の**しわ寄せ**を受けるのは、いつも中小企業だ。","vi":"Những doanh nghiệp vừa và nhỏ luôn là nơi phải gánh hậu quả của suy thoái kinh tế."}],
  "699": [{"jp":"事故を防ぐために、**何らか**の対策を講じる必要がある。","vi":"Cần có biện pháp nào đó để ngăn ngừa tai nạn."},{"jp":"彼が突然辞めたのには、**何らか**の事情があるはずだ。","vi":"Việc anh ấy đột ngột nghỉ việc chắc hẳn phải có lý do gì đó."}],
  "700": [{"jp":"会費は**めいめい**で払ってください。","vi":"Hội phí xin mỗi người tự trả."},{"jp":"子供たちは**めいめい**好きな絵本を選んで読み始めた。","vi":"Bọn trẻ mỗi đứa chọn một cuốn truyện tranh mình thích và bắt đầu đọc."}],
  "701": [{"jp":"真犯人が捕まり、彼の疑いはようやく**晴れた**。","vi":"Hung thủ thật bị bắt, cuối cùng nỗi nghi ngờ đối với anh ấy cũng được giải tỏa."},{"jp":"朝から立ち込めていた霧が、昼には**晴れた**。","vi":"Sương mù bao phủ từ sáng đến trưa thì tan."}],
  "702": [{"jp":"親に内緒でアルバイトをしていたことが**ばれて**しまった。","vi":"Chuyện đi làm thêm giấu bố mẹ đã bị lộ mất rồi."},{"jp":"嘘はいつか**ばれる**ものだから、正直に話したほうがいい。","vi":"Lời nói dối rồi cũng sẽ bị lộ, nên tốt hơn hết là nói thật."}],
  "703": [{"jp":"誰にも言わないと約束したのに、彼は私の秘密を**ばらして**しまった。","vi":"Đã hứa không nói với ai, vậy mà anh ta lại tiết lộ bí mật của tôi."},{"jp":"古いパソコンを**ばらして**、使える部品を取り出した。","vi":"Tôi tháo rời chiếc máy tính cũ ra và lấy những linh kiện còn dùng được."}],
  "704": [{"jp":"美術館の名画が、いつの間にか偽物と**すり替えられて**いた。","vi":"Bức danh họa của bảo tàng đã bị đánh tráo bằng đồ giả từ lúc nào không hay."},{"jp":"大臣は質問に答えず、話を別の問題に**すり替えた**。","vi":"Bộ trưởng không trả lời câu hỏi mà lái câu chuyện sang vấn đề khác."}],
  "705": [{"jp":"選挙の前に現金を**ばらまいた**候補者が逮捕された。","vi":"Ứng cử viên vung tiền mặt trước bầu cử đã bị bắt."},{"jp":"子供がおもちゃを部屋中に**ばらまいて**いる。","vi":"Đứa trẻ vứt đồ chơi bừa bãi khắp phòng."}],
  "706": [{"jp":"息子は父親の肩に**またがって**、パレードを見物した。","vi":"Cậu con trai ngồi trên vai bố để xem diễu hành."},{"jp":"この山脈は三つの県に**またがって**いる。","vi":"Dãy núi này trải dài qua ba tỉnh."}],
  "707": [{"jp":"寝ている人を**またいで**はいけないと祖母に言われた。","vi":"Bà dặn tôi không được bước qua người đang ngủ."},{"jp":"国境を**またいで**通勤する人も少なくない。","vi":"Cũng không ít người đi làm vượt qua biên giới hằng ngày."}],
  "708": [{"jp":"銃弾が兵士の肩を**貫いた**。","vi":"Viên đạn xuyên qua vai người lính."},{"jp":"彼は周囲に反対されても、自分の信念を**貫いた**。","vi":"Dù bị xung quanh phản đối, anh ấy vẫn giữ vững niềm tin của mình đến cùng."}],
  "709": [{"jp":"ドアの隙間から部屋の中を**のぞいた**。","vi":"Tôi nhìn trộm vào trong phòng qua khe cửa."},{"jp":"帰りに本屋を**のぞいて**みたが、欲しい本はなかった。","vi":"Trên đường về tôi ghé qua hiệu sách nhưng không có cuốn mình muốn."}],
  "710": [{"jp":"社長の脇には、いつも秘書が**控えて**いる。","vi":"Bên cạnh giám đốc lúc nào cũng có thư ký chờ sẵn."},{"jp":"来月に選挙を**控えて**、候補者たちの動きが活発になってきた。","vi":"Với cuộc bầu cử sắp diễn ra vào tháng sau, các ứng cử viên bắt đầu hoạt động sôi nổi."}],
  "711": [{"jp":"確認を**怠った**ために、大きなミスにつながった。","vi":"Vì lơ là việc kiểm tra nên đã dẫn đến sai lầm lớn."},{"jp":"日々の努力を**怠らなければ**、きっと結果はついてくる。","vi":"Nếu không sao nhãng nỗ lực hằng ngày thì chắc chắn sẽ có kết quả."}],
  "712": [{"jp":"犯人は警察の目を**逃れて**海外へ逃亡した。","vi":"Hung thủ đã thoát khỏi tầm mắt cảnh sát và trốn ra nước ngoài."},{"jp":"彼はいつも言い訳をして責任を**逃れよう**とする。","vi":"Anh ta luôn viện cớ để trốn tránh trách nhiệm."}],
  "713": [{"jp":"決勝で敗れ、惜しくも金メダルを**逃した**。","vi":"Thua ở chung kết, tiếc thay đã để tuột mất huy chương vàng."},{"jp":"こんな好機を**逃す**手はない。","vi":"Không có lý do gì để bỏ lỡ cơ hội tốt thế này."}],
  "714": [{"jp":"父は単身で北海道の任地に**赴いた**。","vi":"Bố tôi một mình đến Hokkaido nhận nhiệm vụ."},{"jp":"大臣は自ら被災地に**赴き**、住民の声を聞いた。","vi":"Bộ trưởng đích thân đến vùng thiên tai để lắng nghe tiếng nói người dân."}],
  "715": [{"jp":"長男が実家の旅館を**継ぐ**ことになった。","vi":"Người con trai cả sẽ nối nghiệp nhà trọ của gia đình."},{"jp":"亡き父の意志を**継いで**、彼は研究を続けている。","vi":"Kế thừa ý chí của người cha quá cố, anh ấy tiếp tục nghiên cứu."}],
  "716": [{"jp":"視聴率が低く、その番組は三か月で**打ち切られた**。","vi":"Rating thấp nên chương trình đó bị dừng sau ba tháng."},{"jp":"手がかりが見つからず、警察は捜索を**打ち切った**。","vi":"Không tìm được manh mối, cảnh sát đã dừng việc tìm kiếm."}],
  "717": [{"jp":"古いシーツを細く**裂いて**、雑巾にした。","vi":"Tôi xé chiếc ga trải giường cũ thành dải nhỏ để làm giẻ lau."},{"jp":"父はスルメを**裂き**ながら、ビールを飲んでいた。","vi":"Bố vừa xé mực khô vừa uống bia."}],
  "718": [{"jp":"忙しい中、貴重なお時間を**割いて**いただき、ありがとうございます。","vi":"Cảm ơn anh đã dành thời gian quý báu trong lúc bận rộn."},{"jp":"包丁で魚の腹を**割いて**、内臓を取り除く。","vi":"Dùng dao mổ bụng cá và loại bỏ nội tạng."}],
  "719": [{"jp":"新入社員にそれぞれの担当業務を**割り当てた**。","vi":"Đã phân công công việc phụ trách cho từng nhân viên mới."},{"jp":"劇の役は先生がくじで**割り当てる**ことになった。","vi":"Vai trong vở kịch sẽ được giáo viên phân bằng cách bốc thăm."}],
  "720": [{"jp":"期限までに返事がない場合は、欠席と**見なします**。","vi":"Nếu không có phản hồi trước hạn, sẽ được coi là vắng mặt."},{"jp":"彼は周囲から次期社長の最有力候補と**見なされて**いる。","vi":"Anh ấy được mọi người xem là ứng viên sáng giá nhất cho chức giám đốc tiếp theo."}],
  "721": [{"jp":"母は私の嘘をすぐに**見抜いた**。","vi":"Mẹ nhìn thấu lời nói dối của tôi ngay lập tức."},{"jp":"面接官は応募者の本音を**見抜こう**としている。","vi":"Người phỏng vấn đang cố nhìn thấu suy nghĩ thật của ứng viên."}],
  "722": [{"jp":"投資する前に、その会社の将来性をしっかり**見極める**べきだ。","vi":"Trước khi đầu tư, nên xác định rõ tiềm năng tương lai của công ty đó."},{"jp":"問題の本質を**見極めて**から対策を考えよう。","vi":"Hãy xác định rõ bản chất vấn đề rồi mới nghĩ biện pháp."}],
  "723": [{"jp":"楽しみにしていたドラマの最終回を**見逃して**しまった。","vi":"Tôi đã lỡ mất tập cuối của bộ phim mà mình mong đợi."},{"jp":"審判は明らかな反則を**見逃した**。","vi":"Trọng tài đã bỏ qua một lỗi phạm quy rõ ràng."}],
  "724": [{"jp":"残業で、楽しみにしていたサッカーの試合を**見損なった**。","vi":"Vì tăng ca nên tôi đã không xem được trận bóng đá mà mình mong chờ."},{"jp":"君がそんなことをする人だとは思わなかった。**見損なった**よ。","vi":"Không ngờ cậu lại là người làm chuyện như vậy. Tôi đã nhìn lầm cậu."}],
  "725": [{"jp":"彼はボランティア活動に生きがいを**見いだした**。","vi":"Anh ấy đã tìm thấy lẽ sống trong hoạt động tình nguyện."},{"jp":"監督は無名の少年の才能を**見いだした**。","vi":"Huấn luyện viên đã phát hiện ra tài năng của cậu bé vô danh."}],
  "726": [{"jp":"部下を**おだてて**仕事をさせるのが上手な上司だ。","vi":"Ông ấy là sếp giỏi tâng bốc cấp dưới để họ làm việc."},{"jp":"**おだてられて**、つい幹事を引き受けてしまった。","vi":"Được tâng bốc, tôi lỡ nhận làm người tổ chức."}],
  "727": [{"jp":"一人娘なので、両親は彼女を**ちやほやして**育てた。","vi":"Vì là con gái một nên bố mẹ đã nuông chiều cô ấy hết mực."},{"jp":"若い頃に**ちやほやされた**俳優ほど、人気が落ちると苦労する。","vi":"Diễn viên càng được chiều chuộng khi còn trẻ thì càng vất vả khi hết nổi tiếng."}],
  "728": [{"jp":"彼は人の作品を**けなして**ばかりで、自分では何も作らない。","vi":"Anh ta chỉ toàn chê bai tác phẩm của người khác, còn bản thân chẳng làm ra gì."},{"jp":"批評家に**けなされた**映画が、意外にも大ヒットした。","vi":"Bộ phim bị các nhà phê bình chê lại bất ngờ thành công lớn."}],
  "729": [{"jp":"結婚が決まった同僚を、みんなで**冷やかした**。","vi":"Mọi người cùng trêu chọc anh đồng nghiệp sắp kết hôn."},{"jp":"買う気はないが、温泉街の土産物屋を**冷やかして**歩いた。","vi":"Tuy không định mua nhưng tôi vẫn đi dạo xem hàng ở các tiệm quà lưu niệm phố suối nước nóng."}],
  "730": [{"jp":"遠くから来たお客様を、地元の料理で**もてなした**。","vi":"Chúng tôi đã tiếp đãi vị khách từ xa đến bằng món ăn địa phương."},{"jp":"この旅館は心のこもった**もてなし**で知られている。","vi":"Nhà trọ này nổi tiếng với sự tiếp đãi chu đáo, tận tình."}],
  "731": [{"jp":"彼は三代の社長に**仕えて**きたベテラン秘書だ。","vi":"Ông ấy là thư ký kỳ cựu đã phục vụ ba đời giám đốc."},{"jp":"昔、武士は命をかけて主君に**仕えた**。","vi":"Ngày xưa, võ sĩ phục vụ chủ quân bằng cả tính mạng."}],
  "732": [{"jp":"新しい監督がチームを優勝に**導いた**。","vi":"Huấn luyện viên mới đã dẫn dắt đội đến chức vô địch."},{"jp":"進路に迷っていた私を、先輩の助言が正しい道へ**導いて**くれた。","vi":"Lời khuyên của đàn anh đã dẫn dắt tôi, khi đang phân vân về con đường tương lai, đến hướng đi đúng đắn."}],
  "733": [{"jp":"親の言いつけに**背いて**、彼は家を出た。","vi":"Làm trái lời dặn của bố mẹ, anh ấy đã bỏ nhà ra đi."},{"jp":"期待に**背かない**よう、全力を尽くします。","vi":"Tôi sẽ dốc hết sức để không phụ lòng mong đợi."}],
  "734": [{"jp":"田中先生は多くの教え子に**慕われて**いる。","vi":"Thầy Tanaka được nhiều học trò yêu mến."},{"jp":"幼い弟は兄を**慕って**、どこへでもついて行く。","vi":"Cậu em nhỏ quyến luyến anh trai, đi đâu cũng theo."}],
  "735": [{"jp":"部屋に入った瞬間、彼は危険な気配を**察した**。","vi":"Ngay khi bước vào phòng, anh ấy đã cảm nhận được bầu không khí nguy hiểm."},{"jp":"ご家族を亡くされたお気持ち、お**察し**いたします。","vi":"Tôi xin chia sẻ nỗi đau mất người thân của anh chị."}],
  "736": [{"jp":"彼は家族に別れを**告げて**、戦地へ向かった。","vi":"Anh ấy từ biệt gia đình rồi lên đường ra chiến trường."},{"jp":"鶏の鳴き声が朝を**告げた**。","vi":"Tiếng gà gáy báo hiệu buổi sáng."}],
  "737": [{"jp":"家賃を滞納している住人に支払いを**促した**。","vi":"Đã thúc giục người thuê nhà nợ tiền nhà thanh toán."},{"jp":"適度な運動は血行を**促す**。","vi":"Vận động vừa phải giúp thúc đẩy tuần hoàn máu."}],
  "738": [{"jp":"最終的な判断は社長に**委ねられた**。","vi":"Quyết định cuối cùng được giao phó cho giám đốc."},{"jp":"彼は温泉に身を**委ねて**、旅の疲れを癒した。","vi":"Anh ấy thả mình trong suối nước nóng để xua tan mệt mỏi của chuyến đi."}],
  "739": [{"jp":"会社の不当な解雇を裁判所に**訴えた**。","vi":"Tôi đã kiện việc sa thải bất công của công ty ra tòa."},{"jp":"この映画は、戦争の悲惨さを見る人の心に**訴える**。","vi":"Bộ phim này tác động vào lòng người xem về sự bi thảm của chiến tranh."}],
  "740": [{"jp":"週末は子供たちと山へ行き、自然に**親しんで**いる。","vi":"Cuối tuần tôi cùng bọn trẻ lên núi, gần gũi với thiên nhiên."},{"jp":"秋は読書に**親しむ**のにちょうどいい季節だ。","vi":"Mùa thu là mùa thích hợp để đọc sách."}],
  "741": [{"jp":"彼は三度目の世界記録に**挑んだ**。","vi":"Anh ấy lần thứ ba thử thách kỷ lục thế giới."},{"jp":"登山隊は冬のエベレストに**挑む**計画を立てた。","vi":"Đoàn leo núi đã lập kế hoạch chinh phục Everest vào mùa đông."}],
  "742": [{"jp":"満天の星空を**仰いで**、宇宙の広さを感じた。","vi":"Ngước nhìn bầu trời đầy sao, tôi cảm nhận được sự bao la của vũ trụ."},{"jp":"判断に迷ったら、上司の指示を**仰いで**ください。","vi":"Nếu phân vân khi phán đoán, hãy xin chỉ thị của cấp trên."}],
  "743": [{"jp":"お寺で仏様を**拝んで**、家族の健康を祈った。","vi":"Tôi vái Phật ở chùa và cầu sức khỏe cho gia đình."},{"jp":"元日の朝、富士山の頂上で初日の出を**拝んだ**。","vi":"Sáng mùng một Tết, tôi ngắm bình minh đầu năm trên đỉnh núi Phú Sĩ."}],
  "744": [{"jp":"戦死した兵士たちは、この丘に**葬られた**。","vi":"Những người lính tử trận được chôn cất trên ngọn đồi này."},{"jp":"その汚職事件は、真相が明らかにされないまま闇に**葬られた**。","vi":"Vụ tham nhũng đó đã bị chôn vùi vào bóng tối mà sự thật chưa được làm sáng tỏ."}],
  "745": [{"jp":"悩んだ末、彼は歌手になる夢を**思い切った**。","vi":"Sau nhiều trăn trở, anh ấy đã từ bỏ ước mơ trở thành ca sĩ."},{"jp":"**思い切って**告白したら、彼女もOKしてくれた。","vi":"Tôi đã lấy hết can đảm tỏ tình, và cô ấy cũng đồng ý."}],
  "746": [{"jp":"彼は獄中で自らの罪を**悔いて**いる。","vi":"Hắn đang ăn năn tội lỗi của mình trong tù."},{"jp":"**悔い**のない人生を送りたい。","vi":"Tôi muốn sống một cuộc đời không hối tiếc."}],
  "747": [{"jp":"市民は政治家の腐敗に**憤って**いる。","vi":"Người dân phẫn nộ trước sự tha hóa của chính trị gia."},{"jp":"社会の不公平を**憤る**若者たちがデモを行った。","vi":"Những người trẻ căm phẫn sự bất công trong xã hội đã tổ chức biểu tình."}],
  "748": [{"jp":"彼は自分の不運を**嘆いて**ばかりいる。","vi":"Anh ta chỉ toàn than thở về sự xui xẻo của mình."},{"jp":"教授たちは学生の学力低下を**嘆いて**いる。","vi":"Các giáo sư than phiền về sự sa sút học lực của sinh viên."}],
  "749": [{"jp":"少し褒められたくらいで**うぬぼれて**はいけない。","vi":"Không được tự mãn chỉ vì được khen một chút."},{"jp":"彼は自分が一番だと**うぬぼれて**いるが、実力はまだまだだ。","vi":"Anh ta tự phụ cho mình là nhất, nhưng thực lực vẫn còn kém lắm."}],
  "750": [{"jp":"網にかかった魚が**もがいて**いる。","vi":"Con cá mắc lưới đang giãy giụa."},{"jp":"借金地獄から抜け出そうと、彼は必死に**もがいた**。","vi":"Anh ấy vật lộn tuyệt vọng để thoát khỏi địa ngục nợ nần."}],
  "751": [{"jp":"今月に入って、各地で大雨による被害が**相次いで**いる。","vi":"Từ đầu tháng này, thiệt hại do mưa lớn liên tiếp xảy ra ở nhiều nơi."},{"jp":"不祥事が**相次ぎ**、社長は辞任に追い込まれた。","vi":"Bê bối xảy ra liên tiếp khiến giám đốc buộc phải từ chức."}],
  "752": [{"jp":"最近、有名ブランドの偽物がネットで**出回って**いる。","vi":"Gần đây hàng nhái thương hiệu nổi tiếng đang tràn lan trên mạng."},{"jp":"秋になると、店頭に新米が**出回り**始める。","vi":"Vào mùa thu, gạo mới bắt đầu xuất hiện ở các cửa hàng."}],
  "753": [{"jp":"この地域は地下資源に**富んで**いる。","vi":"Khu vực này giàu tài nguyên dưới lòng đất."},{"jp":"彼のスピーチはユーモアに**富んで**いて、会場は笑いに包まれた。","vi":"Bài phát biểu của anh ấy đầy hài hước, cả hội trường ngập trong tiếng cười."}],
  "754": [{"jp":"落ちたお菓子にアリが**群がって**いる。","vi":"Kiến bu đầy quanh mẩu bánh kẹo rơi."},{"jp":"人気歌手の周りに、ファンが**群がった**。","vi":"Người hâm mộ vây kín quanh ca sĩ nổi tiếng."}],
  "755": [{"jp":"転校生はすぐにクラスに**溶け込んだ**。","vi":"Học sinh chuyển trường đã nhanh chóng hòa nhập với lớp."},{"jp":"工場から出た有害物質が川の水に**溶け込んで**いた。","vi":"Chất độc hại từ nhà máy đã hòa tan vào nước sông."}],
  "756": [{"jp":"シャツのすそがズボンから**はみ出て**いるよ。","vi":"Vạt áo sơ mi của cậu lòi ra khỏi quần kìa."},{"jp":"行列が店の外の通路にまで**はみ出して**いた。","vi":"Hàng người xếp tràn ra tận lối đi bên ngoài cửa hàng."}],
  "757": [{"jp":"このボールはよく**弾む**ので、子供たちに人気がある。","vi":"Quả bóng này nảy rất tốt nên được bọn trẻ ưa thích."},{"jp":"久しぶりに会った友人と、昔話に話が**弾んだ**。","vi":"Gặp lại người bạn lâu ngày, chúng tôi trò chuyện rôm rả về chuyện xưa."}],
  "758": [{"jp":"つきたての餅はよく**粘る**。","vi":"Bánh mochi vừa giã xong rất dẻo dính."},{"jp":"彼は最後まで**粘って**、ついに契約を取ってきた。","vi":"Anh ấy kiên trì đến cùng và cuối cùng đã giành được hợp đồng."}],
  "759": [{"jp":"昔話では、キツネが美しい女性に**化けて**人をだます。","vi":"Trong truyện cổ, cáo hóa thành người phụ nữ xinh đẹp để lừa người."},{"jp":"投資した資金が、数年で大きな利益に**化けた**。","vi":"Số vốn đầu tư đã biến thành khoản lợi nhuận lớn chỉ sau vài năm."}],
  "760": [{"jp":"水をやり忘れて、花が**しぼんで**しまった。","vi":"Quên tưới nước nên hoa héo mất rồi."},{"jp":"パーティーの翌朝には、風船がすっかり**しぼんで**いた。","vi":"Sáng hôm sau bữa tiệc, những quả bóng bay đã xẹp hết."}],
  "761": [{"jp":"洗濯物を干すロープが**たるんで**いる。","vi":"Sợi dây phơi đồ bị chùng xuống."},{"jp":"最近、遅刻が多いぞ。気持ちが**たるんで**いるんじゃないか。","vi":"Dạo này đi muộn nhiều đấy. Có phải tinh thần đang lơi lỏng không?"}],
  "762": [{"jp":"母は茶碗にご飯を山のように**盛った**。","vi":"Mẹ xới cơm vào bát đầy như núi."},{"jp":"大皿に料理をきれいに**盛り**付けた。","vi":"Tôi bày món ăn thật đẹp lên đĩa lớn."}],
  "763": [{"jp":"市役所は外国人向けの相談窓口を**設けた**。","vi":"Tòa thị chính đã lập quầy tư vấn dành cho người nước ngoài."},{"jp":"両国の首脳が話し合う機会が**設けられた**。","vi":"Cơ hội để lãnh đạo hai nước hội đàm đã được tạo ra."}],
  "764": [{"jp":"創立50周年を記念して、盛大なパーティーが**催された**。","vi":"Một bữa tiệc hoành tráng đã được tổ chức để kỷ niệm 50 năm thành lập."},{"jp":"退屈な講義を聞いているうちに、眠気を**催して**きた。","vi":"Trong lúc nghe bài giảng nhàm chán, tôi bắt đầu buồn ngủ."}],
  "765": [{"jp":"事件の後、少年は心を**閉ざして**しまった。","vi":"Sau vụ việc, cậu bé đã khép kín lòng mình."},{"jp":"冬の間、この村は雪に**閉ざされる**。","vi":"Suốt mùa đông, ngôi làng này bị tuyết phủ kín, cô lập."}],
  "766": [{"jp":"羽田空港は海を**埋め立てて**造られた。","vi":"Sân bay Haneda được xây dựng bằng cách lấn biển."},{"jp":"干潟を**埋め立てる**計画に、住民が反対している。","vi":"Người dân đang phản đối kế hoạch san lấp bãi bồi."}],
  "767": [{"jp":"この仕事は高度な専門知識を**要する**。","vi":"Công việc này đòi hỏi kiến thức chuyên môn cao."},{"jp":"新しい橋の建設に**要する**費用は、約100億円だ。","vi":"Chi phí cần cho việc xây cây cầu mới là khoảng 10 tỷ yên."}],
  "768": [{"jp":"彼はいつも家庭より仕事を**優先して**きた。","vi":"Anh ấy lúc nào cũng ưu tiên công việc hơn gia đình."},{"jp":"安全はすべてに**優先する**。","vi":"An toàn được ưu tiên hơn hết thảy."}],
  "769": [{"jp":"船の汽笛がだんだん**遠ざかって**いった。","vi":"Tiếng còi tàu xa dần."},{"jp":"引退してから、彼は政界からすっかり**遠ざかって**いる。","vi":"Từ khi nghỉ hưu, ông ấy đã hoàn toàn xa rời chính trường."}],
  "770": [{"jp":"ハウリングが起きたので、マイクをスピーカーから**遠ざけた**。","vi":"Vì bị hú tiếng nên tôi đưa micro ra xa loa."},{"jp":"健康のため、医者に言われて酒を**遠ざけて**いる。","vi":"Vì sức khỏe, theo lời bác sĩ tôi đang tránh xa rượu."}],
  "771": [{"jp":"露天風呂にゆっくりと**浸って**、旅の疲れを癒した。","vi":"Tôi ngâm mình thong thả trong bồn tắm lộ thiên để xua tan mệt mỏi chuyến đi."},{"jp":"卒業アルバムを見ながら、昔の思い出に**浸った**。","vi":"Vừa xem album tốt nghiệp, tôi vừa đắm chìm trong kỷ niệm xưa."}],
  "772": [{"jp":"乾燥わかめを水に**浸して**戻す。","vi":"Ngâm rong biển khô vào nước cho nở ra."},{"jp":"疲れた足をお湯に**浸す**と、気持ちがいい。","vi":"Ngâm đôi chân mỏi vào nước nóng thật dễ chịu."}],
  "773": [{"jp":"恐竜は約6600万年前に**滅びた**と言われている。","vi":"Người ta nói khủng long đã diệt vong khoảng 66 triệu năm trước."},{"jp":"どんなに栄えた国も、いつかは**滅びる**。","vi":"Đất nước dù thịnh vượng đến đâu thì rồi cũng có ngày diệt vong."}],
  "774": [{"jp":"核戦争は人類を**滅ぼす**かもしれない。","vi":"Chiến tranh hạt nhân có thể hủy diệt loài người."},{"jp":"彼はギャンブルにのめり込み、身を**滅ぼした**。","vi":"Anh ta nghiện cờ bạc và đã tự hủy hoại bản thân."}],
  "775": [{"jp":"この町はかつて絹織物の産地として**栄えた**。","vi":"Thị trấn này từng thịnh vượng như một vùng sản xuất lụa."},{"jp":"平安時代には貴族の文化が**栄えた**。","vi":"Thời Heian, văn hóa quý tộc đã phát triển rực rỡ."}],
  "776": [{"jp":"長い議論の末、ようやく今後の方針が**定まった**。","vi":"Sau thời gian dài tranh luận, cuối cùng phương châm sắp tới cũng đã được quyết định."},{"jp":"春先は天候が**定まらない**ので、上着を持って行こう。","vi":"Đầu xuân thời tiết thất thường nên hãy mang theo áo khoác."}],
  "777": [{"jp":"日本国憲法には基本的人権が**定められて**いる。","vi":"Hiến pháp Nhật Bản quy định các quyền cơ bản của con người."},{"jp":"国会は新しい法律を**定めた**。","vi":"Quốc hội đã ban hành luật mới."}],
  "778": [{"jp":"夕暮れの空を、渡り鳥が列を**なして**飛んでいく。","vi":"Trên bầu trời hoàng hôn, đàn chim di trú bay thành hàng."},{"jp":"この文章は主語がなく、意味を**なさない**。","vi":"Câu văn này không có chủ ngữ nên vô nghĩa."}],
  "779": [{"jp":"若い世代が次の時代を**担って**いく。","vi":"Thế hệ trẻ sẽ gánh vác thời đại tiếp theo."},{"jp":"彼女は会社の再建という重要な役割を**担って**いる。","vi":"Cô ấy đang đảm nhận vai trò quan trọng là tái thiết công ty."}],
  "780": [{"jp":"災害の後も、彼は故郷の島に**とどまる**ことを選んだ。","vi":"Sau thảm họa, anh ấy vẫn chọn ở lại hòn đảo quê hương."},{"jp":"今年の経済成長率は1%に**とどまった**。","vi":"Tốc độ tăng trưởng kinh tế năm nay chỉ dừng ở mức 1%."}],
  "781": [{"jp":"事故の被害を最小限に**とどめる**ため、迅速な対応が求められた。","vi":"Để giữ thiệt hại của vụ tai nạn ở mức tối thiểu, cần phải ứng phó thật nhanh chóng."},{"jp":"恩師の言葉を、今も心に**とどめて**いる。","vi":"Đến giờ tôi vẫn ghi nhớ trong lòng lời dạy của người thầy cũ."}],
  "782": [{"jp":"何度も交渉を重ねたが、ついに打つ手が**尽きて**しまった。","vi":"Đã đàm phán nhiều lần nhưng cuối cùng đã hết cách."},{"jp":"子育ては楽しいが、悩みが**尽きる**ことはない。","vi":"Nuôi dạy con cái tuy vui nhưng nỗi lo không bao giờ hết."}],
  "783": [{"jp":"医師たちは手を**尽くした**が、患者を救うことはできなかった。","vi":"Các bác sĩ đã thử mọi cách nhưng vẫn không cứu được bệnh nhân."},{"jp":"祖父は生涯を通じて地域社会のために**尽くした**。","vi":"Ông tôi suốt đời đã cống hiến cho cộng đồng địa phương."}],
  "784": [{"jp":"万全の準備をして面接に**臨んだ**。","vi":"Tôi bước vào buổi phỏng vấn với sự chuẩn bị chu đáo."},{"jp":"このホテルは海に**臨む**高台に建っている。","vi":"Khách sạn này nằm trên một khu đất cao nhìn ra biển."}],
  "785": [{"jp":"睡眠不足が続くと、健康を**損なう**おそれがある。","vi":"Nếu tình trạng thiếu ngủ kéo dài thì có nguy cơ làm tổn hại sức khỏe."},{"jp":"派手な看板が古い町並みの景観を**損なって**いる。","vi":"Những biển hiệu lòe loẹt đang làm hỏng cảnh quan của dãy phố cổ."}],
  "786": [{"jp":"台所からカレーのいい香りが**漂って**きた。","vi":"Mùi cà ri thơm phức lan tỏa từ trong bếp ra."},{"jp":"会議室には険悪な空気が**漂って**いた。","vi":"Bầu không khí căng thẳng bao trùm phòng họp."}],
  "787": [{"jp":"新入社員たちは希望に**満ちた**表情をしていた。","vi":"Các nhân viên mới mang vẻ mặt tràn đầy hy vọng."},{"jp":"潮が**満ちて**くると、この岩場は海に沈む。","vi":"Khi thủy triều lên, bãi đá này chìm xuống biển."}],
  "788": [{"jp":"応募するには、すべての条件を**満たす**必要がある。","vi":"Để ứng tuyển, cần phải đáp ứng tất cả các điều kiện."},{"jp":"バケツに水を**満たして**、庭の花に水をやった。","vi":"Tôi đổ đầy nước vào xô rồi tưới hoa ngoài vườn."}],
  "789": [{"jp":"彼はアルバイトをして学費を**まかなって**いる。","vi":"Anh ấy đi làm thêm để tự trang trải học phí."},{"jp":"会の経費は、すべて会員の会費で**まかなわれて**いる。","vi":"Chi phí của hội đều được trang trải bằng hội phí của các hội viên."}],
  "790": [{"jp":"彼はまだ高校生だが、プロに**匹敵する**実力を持っている。","vi":"Cậu ấy mới là học sinh cấp 3 nhưng đã có thực lực sánh ngang dân chuyên nghiệp."},{"jp":"この地震の被害は、関東大震災に**匹敵する**規模だった。","vi":"Thiệt hại của trận động đất này có quy mô tương đương với Đại động đất Kanto."}],
  "791": [{"jp":"手入れを怠ったら、庭に雑草が**はびこって**しまった。","vi":"Lơ là chăm sóc một thời gian, thế là cỏ dại mọc tràn lan khắp vườn."},{"jp":"その国では役人の間に汚職が**はびこって**いる。","vi":"Ở nước đó, tham nhũng đang hoành hành trong giới công chức."}],
  "792": [{"jp":"業績の悪化が続き、その会社は経営不振に**陥った**。","vi":"Kết quả kinh doanh liên tục xấu đi, công ty đó đã rơi vào tình trạng làm ăn sa sút."},{"jp":"地震の直後、客たちはパニックに**陥った**。","vi":"Ngay sau trận động đất, khách hàng đã rơi vào hoảng loạn."}],
  "793": [{"jp":"早めに避難したおかげで、一家は被害を**免れた**。","vi":"Nhờ sơ tán sớm mà cả nhà đã thoát khỏi thiệt hại."},{"jp":"社長である以上、事故の責任を**免れる**ことはできない。","vi":"Một khi đã là giám đốc thì không thể trốn tránh trách nhiệm về sự cố."}],
  "794": [{"jp":"経験では、相手チームのほうが**勝って**いる。","vi":"Về kinh nghiệm thì đội đối thủ vượt trội hơn."},{"jp":"健康に**勝る**財産はない。","vi":"Không có tài sản nào hơn được sức khỏe."}],
  "795": [{"jp":"彼女の声は、少し悲しみを**帯びて**いた。","vi":"Giọng cô ấy phảng phất chút buồn."},{"jp":"大使は首相の特命を**帯びて**現地に向かった。","vi":"Vị đại sứ mang sứ mệnh đặc biệt của thủ tướng lên đường đến nơi."}],
  "796": [{"jp":"しばらく練習を休んだら、すっかり腕が**鈍って**しまった。","vi":"Nghỉ tập một thời gian, tay nghề tôi đã kém đi hẳn."},{"jp":"家族に反対されて、留学の決心が**鈍った**。","vi":"Bị gia đình phản đối, quyết tâm đi du học của tôi bị lung lay."}],
  "797": [{"jp":"彼の小説は筋が**ありふれて**いて、面白みに欠ける。","vi":"Tiểu thuyết của anh ta có cốt truyện tầm thường, thiếu sức hấp dẫn."},{"jp":"どこにでもある**ありふれた**名前なので、すぐに忘れられてしまう。","vi":"Vì là cái tên bình thường thấy ở đâu cũng có nên rất dễ bị quên."}],
  "798": [{"jp":"朝のコーヒーを飲むと、頭が**冴えて**くる。","vi":"Uống cà phê buổi sáng vào là đầu óc trở nên minh mẫn."},{"jp":"どうしたの？今日は**冴えない**顔をしているね。","vi":"Sao thế? Hôm nay trông cậu ủ rũ quá."}],
  "799": [{"jp":"彼女の演技は、出演者の中でも**際立って**いた。","vi":"Diễn xuất của cô ấy nổi bật nhất trong số các diễn viên."},{"jp":"この地域の料理には**際立った**特色がある。","vi":"Ẩm thực vùng này có những nét đặc sắc nổi bật."}],
  "800": [{"jp":"彼は**ずば抜けた**記憶力の持ち主だ。","vi":"Anh ấy là người có trí nhớ xuất chúng."},{"jp":"その少女は幼い頃から、**ずば抜けた**音楽の才能を見せていた。","vi":"Cô bé ấy từ nhỏ đã thể hiện tài năng âm nhạc vượt trội."}],
  "801": [{"jp":"彼は**ソフトな**口調で話すので、誰からも好かれている。","vi":"Anh ấy nói chuyện bằng giọng điệu nhẹ nhàng nên được mọi người yêu mến."},{"jp":"このタオルは手触りがとても**ソフト**だ。","vi":"Chiếc khăn này sờ vào rất mềm mại."}],
  "802": [{"jp":"今週は会議と出張が続く**ハードな**スケジュールだ。","vi":"Tuần này là lịch trình dày đặc với các cuộc họp và chuyến công tác liên tiếp."},{"jp":"大会を前に、選手たちは**ハードな**トレーニングを重ねている。","vi":"Trước giải đấu, các tuyển thủ đang miệt mài tập luyện nặng."}],
  "803": [{"jp":"結婚式には**フォーマルな**服装で出席してください。","vi":"Vui lòng mặc trang phục trang trọng khi dự lễ cưới."},{"jp":"取引先との**フォーマルな**場では、言葉遣いに気をつけなければならない。","vi":"Ở những dịp trang trọng với đối tác, phải chú ý cách dùng từ."}],
  "804": [{"jp":"週末は**カジュアルな**格好で出かけることが多い。","vi":"Cuối tuần tôi thường ra ngoài với trang phục thoải mái."},{"jp":"今日の集まりは**カジュアルな**会なので、気軽に参加してください。","vi":"Buổi gặp mặt hôm nay là buổi thân mật, không trang trọng nên mọi người cứ thoải mái tham gia."}],
  "805": [{"jp":"私は飾りの少ない**シンプルな**デザインの服が好きだ。","vi":"Tôi thích quần áo có thiết kế đơn giản, ít họa tiết."},{"jp":"物を減らして、**シンプルに**暮らしたいと思っている。","vi":"Tôi muốn bớt đồ đạc để sống đơn giản."}],
  "806": [{"jp":"彼女は恋愛に関しては、意外と**ドライな**性格だ。","vi":"Về chuyện yêu đương, cô ấy lại có tính cách lý trí, rạch ròi đến bất ngờ."},{"jp":"仕事のことは感情を交えず、**ドライに**考えるようにしている。","vi":"Chuyện công việc, tôi cố gắng suy nghĩ thực tế, không xen lẫn cảm xúc."}],
  "807": [{"jp":"新製品は消費者から**シビアな**評価を受けた。","vi":"Sản phẩm mới đã nhận được đánh giá khắt khe từ người tiêu dùng."},{"jp":"業界は今、生き残りをかけた**シビアな**状況にある。","vi":"Ngành này hiện đang trong tình thế khắc nghiệt, sống còn."}],
  "808": [{"jp":"今月は出費が多くて、お金が**ピンチ**だ。","vi":"Tháng này chi tiêu nhiều quá nên tôi đang kẹt tiền."},{"jp":"9回裏、チームは最大の**ピンチ**を迎えた。","vi":"Ở lượt cuối hiệp 9, đội bóng đối mặt với tình thế nguy cấp nhất."}],
  "809": [{"jp":"電車に乗り遅れそうだったが、ぎりぎり**セーフ**だった。","vi":"Tưởng là lỡ tàu rồi, nhưng may mà vừa kịp."},{"jp":"締め切りの5分前に提出できたので、なんとか**セーフ**だった。","vi":"Tôi nộp được 5 phút trước hạn chót nên vừa kịp."}],
  "810": [{"jp":"毎週同じような企画ばかりで、この番組は**マンネリ**化している。","vi":"Tuần nào cũng toàn nội dung na ná nhau, chương trình này đã đi vào lối mòn nhàm chán."},{"jp":"付き合って5年になり、デートも**マンネリ**気味だ。","vi":"Hẹn hò đã 5 năm nên các buổi gặp cũng có vẻ nhàm chán, lặp lại."}],
  "811": [{"jp":"この店のランチは**バラエティー**に富んでいて、毎日来ても飽きない。","vi":"Bữa trưa ở quán này rất phong phú nên ngày nào đến cũng không thấy chán."},{"jp":"アンケートには**バラエティー**のある回答が集まった。","vi":"Bảng khảo sát thu được những câu trả lời rất đa dạng."}],
  "812": [{"jp":"この車は小型だが、エンジンの**パワー**が違う。","vi":"Chiếc xe này tuy nhỏ nhưng sức mạnh động cơ thì khác hẳn."},{"jp":"子どもたちの笑顔を見ると、元気と**パワー**をもらえる。","vi":"Nhìn nụ cười của bọn trẻ, tôi như được tiếp thêm sinh lực và sức mạnh."}],
  "813": [{"jp":"祖母は80歳を過ぎても、**バイタリティー**にあふれている。","vi":"Bà tôi đã ngoài 80 mà vẫn tràn đầy sức sống."},{"jp":"彼の**バイタリティー**には、若い社員も驚かされる。","vi":"Đến các nhân viên trẻ cũng phải kinh ngạc trước sức sống mãnh liệt của ông ấy."}],
  "814": [{"jp":"彼の絵は筆致が**ダイナミック**で、見る者を圧倒する。","vi":"Tranh của ông ấy có nét bút mạnh mẽ, choáng ngợp người xem."},{"jp":"サーカスの**ダイナミックな**技に、観客は息をのんだ。","vi":"Khán giả nín thở trước những màn biểu diễn mạnh mẽ của đoàn xiếc."}],
  "815": [{"jp":"マラソンを完走するには、**スタミナ**が欠かせない。","vi":"Để chạy hết một cuộc marathon thì không thể thiếu thể lực."},{"jp":"夏バテしないように、**スタミナ**のつく料理を食べよう。","vi":"Hãy ăn những món bồi bổ thể lực để không bị mệt mỏi vì nóng mùa hè."}],
  "816": [{"jp":"8時頃、通勤ラッシュは**ピーク**を迎えた。","vi":"Khoảng 8 giờ, giờ cao điểm đi làm lên đến đỉnh điểm."},{"jp":"花粉の飛散は、今週が**ピーク**だそうだ。","vi":"Nghe nói phấn hoa phát tán mạnh nhất vào tuần này."}],
  "817": [{"jp":"映画は**クライマックス**に近づき、会場は静まり返った。","vi":"Bộ phim tiến đến cao trào, cả rạp lặng như tờ."},{"jp":"結婚式の**クライマックス**は、花嫁による手紙の朗読だった。","vi":"Cao trào của lễ cưới là lúc cô dâu đọc lá thư."}],
  "818": [{"jp":"そのポスターは色使いが大胆で、**インパクト**がある。","vi":"Tấm áp phích đó phối màu táo bạo, gây ấn tượng mạnh."},{"jp":"彼のデビュー作は、映画界に大きな**インパクト**を与えた。","vi":"Tác phẩm đầu tay của anh ấy đã tạo ra tác động lớn đến giới điện ảnh."}],
  "819": [{"jp":"青い空と白い雪山の**コントラスト**が美しい。","vi":"Sự tương phản giữa bầu trời xanh và núi tuyết trắng thật đẹp."},{"jp":"画面の**コントラスト**を上げると、文字が見やすくなる。","vi":"Tăng độ tương phản của màn hình thì chữ sẽ dễ đọc hơn."}],
  "820": [{"jp":"このテレビは画像が**クリア**で見やすい。","vi":"Chiếc tivi này có hình ảnh rõ nét, dễ xem."},{"jp":"十分に寝たので、頭が**クリア**になった。","vi":"Ngủ đủ giấc nên đầu óc tôi đã minh mẫn trở lại."}],
  "821": [{"jp":"彼は急に声の**トーン**を落として話し始めた。","vi":"Anh ấy đột nhiên hạ giọng xuống rồi bắt đầu nói."},{"jp":"明るい**トーン**の絵を飾ると、部屋の雰囲気が変わる。","vi":"Treo một bức tranh tông màu sáng là bầu không khí căn phòng thay đổi hẳn."}],
  "822": [{"jp":"外国語で微妙な**ニュアンス**を伝えるのは難しい。","vi":"Truyền đạt những sắc thái tinh tế bằng ngoại ngữ thật khó."},{"jp":"「結構です」は、場面によって**ニュアンス**が変わる。","vi":"Câu \"Kekkou desu\" thay đổi sắc thái tùy theo tình huống."}],
  "823": [{"jp":"彼とは、初めて会ったときから**フィーリング**が合った。","vi":"Tôi và anh ấy hợp cảm giác nhau ngay từ lần đầu gặp."},{"jp":"色々比較したが、最後は**フィーリング**で部屋を決めた。","vi":"So sánh đủ kiểu nhưng cuối cùng tôi chọn phòng theo cảm nhận."}],
  "824": [{"jp":"理想と現実の**ギャップ**に悩む新入社員は多い。","vi":"Nhiều nhân viên mới trăn trở vì khoảng cách giữa lý tưởng và thực tế."},{"jp":"親と子の間には、考え方に**ギャップ**がある。","vi":"Giữa cha mẹ và con cái có khoảng cách trong cách suy nghĩ."}],
  "825": [{"jp":"「女性は理系が苦手だ」というのは、**ステレオタイプな**考え方だ。","vi":"Cho rằng \"phụ nữ kém các môn tự nhiên\" là một lối suy nghĩ rập khuôn."},{"jp":"彼の小説に登場する外国人は**ステレオタイプ**で、現実味がない。","vi":"Những nhân vật người nước ngoài trong tiểu thuyết của anh ta rập khuôn, thiếu tính chân thực."}],
  "826": [{"jp":"一度遅刻しただけで、怠け者の**レッテル**を貼られてしまった。","vi":"Chỉ đi muộn một lần mà tôi đã bị gán mác lười biếng."},{"jp":"瓶の**レッテル**に製造年が書いてある。","vi":"Năm sản xuất được ghi trên nhãn chai."}],
  "827": [{"jp":"エアコンの**フィルター**は、定期的に掃除したほうがいい。","vi":"Nên vệ sinh bộ lọc điều hòa định kỳ."},{"jp":"写真に**フィルター**をかけて、柔らかい雰囲気にした。","vi":"Tôi dùng bộ lọc cho bức ảnh để tạo bầu không khí dịu nhẹ."}],
  "828": [{"jp":"この小説は、作者の実体験が**ベース**になっている。","vi":"Cuốn tiểu thuyết này lấy trải nghiệm thực tế của tác giả làm nền tảng."},{"jp":"スープは鶏がらを**ベース**にして作った。","vi":"Món súp được nấu với nước dùng xương gà làm nền."}],
  "829": [{"jp":"地震で、電気や水道などの**インフラ**が大きな被害を受けた。","vi":"Do động đất, cơ sở hạ tầng như điện, nước đã bị thiệt hại nặng nề."},{"jp":"経済成長のためには、交通**インフラ**の整備が欠かせない。","vi":"Để tăng trưởng kinh tế, không thể thiếu việc hoàn thiện hạ tầng giao thông."}],
  "830": [{"jp":"彼は業界に幅広い人脈の**ネットワーク**を持っている。","vi":"Anh ấy có mạng lưới quan hệ rộng khắp trong ngành."},{"jp":"この番組は全国の**ネットワーク**で放送されている。","vi":"Chương trình này được phát sóng trên mạng lưới toàn quốc."}],
  "831": [{"jp":"**テクノロジー**の進歩によって、私たちの生活は大きく変わった。","vi":"Nhờ sự tiến bộ của công nghệ, cuộc sống của chúng ta đã thay đổi rất nhiều."},{"jp":"最新のバイオ**テクノロジー**を使って、新薬が開発された。","vi":"Thuốc mới đã được phát triển nhờ ứng dụng công nghệ sinh học tiên tiến nhất."}],
  "832": [{"jp":"彼はドリブルの**テクニック**がずば抜けている。","vi":"Kỹ thuật rê bóng của anh ấy vượt trội hẳn."},{"jp":"話し方の**テクニック**を学べば、面接で自分をうまく伝えられる。","vi":"Nếu học kỹ thuật nói chuyện, bạn sẽ thể hiện bản thân tốt trong buổi phỏng vấn."}],
  "833": [{"jp":"地震が起こる**メカニズム**は、まだ完全には解明されていない。","vi":"Cơ chế phát sinh động đất vẫn chưa được làm sáng tỏ hoàn toàn."},{"jp":"機械式時計の内部の**メカニズム**は非常に精巧だ。","vi":"Cấu tạo bên trong của đồng hồ cơ cực kỳ tinh xảo."}],
  "834": [{"jp":"結果だけでなく、そこに至る**プロセス**も評価すべきだ。","vi":"Không chỉ kết quả mà cả quá trình đi đến đó cũng nên được đánh giá."},{"jp":"工場で、製品ができるまでの**プロセス**を見学した。","vi":"Ở nhà máy, tôi đã tham quan quá trình làm ra sản phẩm."}],
  "835": [{"jp":"顧客の意見は、すぐに開発部門へ**フィードバックする**ようにしている。","vi":"Chúng tôi luôn phản hồi ý kiến của khách hàng ngay cho bộ phận phát triển."},{"jp":"上司は私のプレゼンについて、丁寧に**フィードバックして**くれた。","vi":"Cấp trên đã phản hồi rất chi tiết về bài thuyết trình của tôi."}],
  "836": [{"jp":"この店は「森の中のカフェ」という**コンセプト**で作られた。","vi":"Quán này được xây dựng theo ý tưởng chủ đạo \"quán cà phê trong rừng\"."},{"jp":"新商品の**コンセプト**を、もっと明確にする必要がある。","vi":"Cần làm rõ hơn ý tưởng chủ đạo của sản phẩm mới."}],
  "837": [{"jp":"借金はしないというのが私の**ポリシー**だ。","vi":"Không vay nợ là phương châm của tôi."},{"jp":"当社は、個人情報の扱いについて明確な**ポリシー**を定めている。","vi":"Công ty chúng tôi có chính sách rõ ràng về việc xử lý thông tin cá nhân."}],
  "838": [{"jp":"面接では、自分の強みを積極的に**アピールした**ほうがいい。","vi":"Trong buổi phỏng vấn, nên chủ động thể hiện thế mạnh của bản thân."},{"jp":"市は観光客を増やすため、地元の魅力を**アピールして**いる。","vi":"Thành phố đang quảng bá nét hấp dẫn của địa phương để thu hút thêm du khách."}],
  "839": [{"jp":"本番の前に、面接の流れを何度も**シミュレーションして**おいた。","vi":"Trước buổi chính thức, tôi đã mô phỏng trình tự buổi phỏng vấn nhiều lần."},{"jp":"コンピューターで津波による被害を**シミュレーションする**。","vi":"Mô phỏng thiệt hại do sóng thần bằng máy tính."}],
  "840": [{"jp":"会場は駅から遠く、**アクセス**が悪い。","vi":"Hội trường ở xa ga nên đi lại bất tiện."},{"jp":"詳しくは、当社のホームページに**アクセス**してください。","vi":"Để biết chi tiết, vui lòng truy cập trang web của công ty chúng tôi."}],
  "841": [{"jp":"道を間違えたので、次の交差点で**Uターンした**。","vi":"Vì đi nhầm đường nên tôi đã quay đầu xe ở ngã tư tiếp theo."},{"jp":"彼は東京の会社を辞めて、故郷に**Uターンした**。","vi":"Anh ấy nghỉ việc ở công ty tại Tokyo và trở về quê làm việc."}],
  "842": [{"jp":"多くの企業が、生産拠点を国内から海外へ**シフトして**いる。","vi":"Nhiều doanh nghiệp đang dịch chuyển cơ sở sản xuất từ trong nước ra nước ngoài."},{"jp":"来週のアルバイトの**シフト**は、もう決まった？","vi":"Ca làm thêm tuần sau đã xếp xong chưa?"}],
  "843": [{"jp":"髪型を変えて、イメージを**チェンジした**。","vi":"Tôi đổi kiểu tóc để thay đổi hình ảnh."},{"jp":"次の試合では、メンバーを何人か**チェンジする**予定だ。","vi":"Ở trận tới, dự định sẽ thay đổi vài thành viên."}],
  "844": [{"jp":"コーチに、ピッチングの**フォーム**を直してもらった。","vi":"Tôi được huấn luyện viên chỉnh lại tư thế ném bóng."},{"jp":"申し込みは、ウェブサイトの入力**フォーム**から行ってください。","vi":"Vui lòng đăng ký qua mẫu điền thông tin trên trang web."}],
  "845": [{"jp":"カメラマンの指示に合わせて、モデルが**ポーズ**をとった。","vi":"Người mẫu tạo dáng theo chỉ dẫn của nhiếp ảnh gia."},{"jp":"動画を一時停止したいときは、この**ポーズ**ボタンを押してください。","vi":"Khi muốn tạm dừng video, hãy bấm nút tạm dừng này."}],
  "846": [{"jp":"話しかける**タイミング**がなかなかつかめなかった。","vi":"Tôi mãi không nắm được thời điểm để bắt chuyện."},{"jp":"ちょうどいい**タイミング**で電話がかかってきた。","vi":"Điện thoại gọi đến đúng lúc."}],
  "847": [{"jp":"映画の**ラスト**シーンで、思わず泣いてしまった。","vi":"Đến cảnh cuối của bộ phim, tôi bất giác bật khóc."},{"jp":"彼は**ラスト**の100メートルで、一気に前の選手を追い抜いた。","vi":"Ở 100 mét cuối cùng, anh ấy vượt lên các vận động viên phía trước một mạch."}],
  "848": [{"jp":"事前に準備しておいたので、手続きは**スムーズに**進んだ。","vi":"Nhờ chuẩn bị trước nên thủ tục diễn ra suôn sẻ."},{"jp":"新しい道路ができて、車の流れが**スムーズに**なった。","vi":"Con đường mới được xây xong, dòng xe cộ lưu thông trôi chảy hơn."}],
  "849": [{"jp":"四季の**サイクル**に合わせて、農作業を行う。","vi":"Công việc đồng áng được tiến hành theo chu kỳ bốn mùa."},{"jp":"スマートフォンは買い替えの**サイクル**が短い。","vi":"Điện thoại thông minh có chu kỳ thay mới ngắn."}],
  "850": [{"jp":"**ジェンダー**による差別をなくす取り組みが進んでいる。","vi":"Các nỗ lực nhằm xóa bỏ phân biệt đối xử dựa trên giới tính đang được đẩy mạnh."},{"jp":"大学で**ジェンダー**論の授業を受けている。","vi":"Tôi đang học môn nghiên cứu giới ở trường đại học."}],
  "851": [{"jp":"大臣の**軽率な**発言が、大きな批判を浴びた。","vi":"Phát ngôn khinh suất của bộ trưởng đã hứng chịu nhiều chỉ trích."},{"jp":"よく調べずに契約したのは**軽率**だった。","vi":"Ký hợp đồng mà không tìm hiểu kỹ là khinh suất."}],
  "852": [{"jp":"事故の原因は、管理者の**怠慢な**点検にあった。","vi":"Nguyên nhân vụ tai nạn nằm ở việc kiểm tra chểnh mảng của người quản lý."},{"jp":"市民の訴えを放置したのは、行政の**怠慢**だ。","vi":"Bỏ mặc lời khiếu nại của người dân là sự lơ là trách nhiệm của chính quyền."}],
  "853": [{"jp":"確かめもしないで、**いい加減な**ことを言うな。","vi":"Đừng có nói bừa khi chưa kiểm chứng."},{"jp":"毎日同じメニューで、**いい加減**飽きてしまった。","vi":"Ngày nào cũng thực đơn y hệt, tôi chán ngấy rồi."}],
  "854": [{"jp":"何度も失敗して、彼は**投げやりな**態度になってしまった。","vi":"Thất bại nhiều lần, anh ấy trở nên có thái độ bất cần."},{"jp":"仕事を**投げやり**にしていると、周りの信頼を失う。","vi":"Nếu làm việc cẩu thả, bạn sẽ mất lòng tin của những người xung quanh."}],
  "855": [{"jp":"彼女にメールを送ったが、**素っ気ない**返事しか来なかった。","vi":"Tôi gửi email cho cô ấy nhưng chỉ nhận được câu trả lời cộc lốc."},{"jp":"店員の**素っ気ない**態度に、少しがっかりした。","vi":"Tôi hơi thất vọng trước thái độ lạnh nhạt của nhân viên cửa hàng."}],
  "856": [{"jp":"彼の自慢話に、周りは**冷ややかな**視線を向けた。","vi":"Mọi người xung quanh nhìn anh ta một cách lạnh nhạt khi nghe anh ta khoe khoang."},{"jp":"政府の新しい政策を、国民は**冷ややかに**見ている。","vi":"Người dân nhìn chính sách mới của chính phủ một cách thờ ơ."}],
  "857": [{"jp":"初対面なのに**なれなれしい**話し方をされて、不快だった。","vi":"Mới gặp lần đầu mà bị nói chuyện suồng sã, tôi thấy khó chịu."},{"jp":"目上の人に、**なれなれしい**口を利くものではない。","vi":"Không nên ăn nói suồng sã với người bề trên."}],
  "858": [{"jp":"人前で大声を出して喧嘩するなんて、**みっともない**。","vi":"Cãi nhau to tiếng trước mặt mọi người thì thật đáng xấu hổ."},{"jp":"そんな**みっともない**格好で外に出ないで。","vi":"Đừng ra ngoài với bộ dạng khó coi như thế."}],
  "859": [{"jp":"彼は毎日体を鍛えているので、**たくましい**体つきをしている。","vi":"Anh ấy rèn luyện mỗi ngày nên có thân hình vạm vỡ."},{"jp":"戦後の混乱期を、祖母は**たくましく**生き抜いた。","vi":"Bà tôi đã kiên cường sống qua thời kỳ hỗn loạn sau chiến tranh."}],
  "860": [{"jp":"子どもたちが**健やかに**育つ環境を作りたい。","vi":"Tôi muốn tạo ra một môi trường để trẻ em lớn lên khỏe mạnh."},{"jp":"皆様の**健やかな**毎日をお祈りしております。","vi":"Kính chúc quý vị mỗi ngày đều mạnh khỏe."}],
  "861": [{"jp":"公園で**無邪気に**遊ぶ子どもたちを見ていると、心が和む。","vi":"Nhìn lũ trẻ hồn nhiên chơi đùa trong công viên, lòng tôi thấy nhẹ nhõm."},{"jp":"赤ちゃんの**無邪気な**笑顔に癒された。","vi":"Tôi được xoa dịu bởi nụ cười ngây thơ của em bé."}],
  "862": [{"jp":"失恋したばかりの友人に、彼は**無神経な**ことを言った。","vi":"Anh ta đã nói những lời thiếu tế nhị với người bạn vừa thất tình."},{"jp":"長年工場で働くうちに、騒音に**無神経に**なってしまった。","vi":"Làm việc lâu năm ở nhà máy, tôi đã trở nên không còn nhạy cảm với tiếng ồn."}],
  "863": [{"jp":"彼は大事な書類を、机の上に**無造作に**置いていた。","vi":"Anh ta để giấy tờ quan trọng tùy tiện trên bàn."},{"jp":"髪を**無造作に**束ねただけなのに、おしゃれに見える。","vi":"Chỉ buộc tóc hờ hững thôi mà trông vẫn sành điệu."}],
  "864": [{"jp":"白鳥が湖を**優雅に**泳いでいる。","vi":"Đàn thiên nga đang bơi thật thanh thoát trên hồ."},{"jp":"退職後、彼は海辺の別荘で**優雅な**生活を送っている。","vi":"Sau khi nghỉ hưu, ông ấy sống cuộc sống thanh nhàn tao nhã ở biệt thự ven biển."}],
  "865": [{"jp":"職人の**見事な**腕前に、見物客から拍手が起こった。","vi":"Trước tay nghề tuyệt vời của người thợ, khách tham quan vỗ tay tán thưởng."},{"jp":"自信があったのに、試験には**見事に**落ちてしまった。","vi":"Tự tin là thế mà tôi đã trượt kỳ thi hoàn toàn."}],
  "866": [{"jp":"経験も人柄も、彼なら市長候補として**申し分ない**。","vi":"Cả kinh nghiệm lẫn nhân cách, nếu là ông ấy thì làm ứng cử viên thị trưởng không chê vào đâu được."},{"jp":"料理もサービスも**申し分ない**レストランだった。","vi":"Đó là nhà hàng mà cả món ăn lẫn dịch vụ đều hoàn hảo."}],
  "867": [{"jp":"彼は遅刻も欠席もない**模範的な**学生だ。","vi":"Cậu ấy là sinh viên gương mẫu, không bao giờ đi muộn hay vắng mặt."},{"jp":"新人の手本となるよう、**模範的な**態度で仕事に取り組んでいる。","vi":"Tôi làm việc với thái độ mẫu mực để làm gương cho nhân viên mới."}],
  "868": [{"jp":"彼は**まめに**連絡をくれるので、安心できる。","vi":"Anh ấy chăm liên lạc nên tôi yên tâm."},{"jp":"健康のために、普段から**まめに**体を動かしている。","vi":"Vì sức khỏe, tôi thường xuyên chăm chỉ vận động."}],
  "869": [{"jp":"部署間の連携を強め、業務を**円滑に**進めたい。","vi":"Tôi muốn tăng cường phối hợp giữa các phòng ban để công việc tiến triển suôn sẻ."},{"jp":"職場では、**円滑な**人間関係を保つことが大切だ。","vi":"Ở nơi làm việc, việc duy trì các mối quan hệ êm thấm là rất quan trọng."}],
  "870": [{"jp":"災害時には、行政の**迅速な**対応が求められる。","vi":"Khi có thiên tai, chính quyền cần phải ứng phó nhanh chóng."},{"jp":"顧客からの苦情を**迅速に**解決した。","vi":"Chúng tôi đã giải quyết nhanh chóng khiếu nại của khách hàng."}],
  "871": [{"jp":"試験が終わったら、**速やかに**退室してください。","vi":"Khi bài thi kết thúc, xin hãy nhanh chóng rời khỏi phòng."},{"jp":"問題が発生した場合は、**速やかに**上司に報告すること。","vi":"Khi có vấn đề phát sinh, phải báo cáo ngay cho cấp trên."}],
  "872": [{"jp":"彼の**素早い**判断のおかげで、事故を防ぐことができた。","vi":"Nhờ phán đoán nhanh nhạy của anh ấy mà đã ngăn được tai nạn."},{"jp":"猫は**素早く**身をかわして逃げていった。","vi":"Con mèo nhanh nhẹn né người rồi chạy mất."}],
  "873": [{"jp":"リスは**敏捷な**動きで木に登っていった。","vi":"Con sóc leo lên cây với những động tác nhanh nhẹn."},{"jp":"彼は小柄だが**敏捷**で、守備がうまい。","vi":"Anh ấy tuy nhỏ con nhưng nhanh nhẹn, phòng thủ rất giỏi."}],
  "874": [{"jp":"事故の**詳細な**報告書を提出してください。","vi":"Hãy nộp bản báo cáo chi tiết về vụ tai nạn."},{"jp":"警察は目撃者から**詳細に**話を聞いた。","vi":"Cảnh sát đã hỏi chi tiết các nhân chứng."}],
  "875": [{"jp":"彼は**緻密な**計算に基づいて橋を設計した。","vi":"Anh ấy thiết kế cây cầu dựa trên những tính toán tỉ mỉ."},{"jp":"長年の**緻密な**研究が、ついに実を結んだ。","vi":"Những nghiên cứu chặt chẽ suốt nhiều năm cuối cùng đã đơm hoa kết trái."}],
  "876": [{"jp":"この地方で雪が降るのは**まれ**だ。","vi":"Ở vùng này hiếm khi có tuyết rơi."},{"jp":"彼ほどの才能を持つ人は、実に**まれな**存在だ。","vi":"Người có tài năng như anh ấy thật là hiếm có."}],
  "877": [{"jp":"週末に一人で映画を見るのが、私の**ひそかな**楽しみだ。","vi":"Cuối tuần một mình đi xem phim là niềm vui thầm kín của tôi."},{"jp":"その社員は会社の機密書類を**ひそかに**持ち出していた。","vi":"Nhân viên đó đã lén mang tài liệu mật của công ty ra ngoài."}],
  "878": [{"jp":"この旅館は**細やかな**サービスで評判だ。","vi":"Lữ quán này nổi tiếng với dịch vụ chu đáo."},{"jp":"母は家族一人一人への**細やかな**心遣いを忘れない。","vi":"Mẹ tôi không bao giờ quên sự quan tâm ân cần đến từng người trong gia đình."}],
  "879": [{"jp":"**ささやかな**贈り物ですが、どうぞお受け取りください。","vi":"Chỉ là món quà nhỏ mọn thôi, xin hãy nhận cho."},{"jp":"昇進を、家族だけで**細やかに**祝った。","vi":"Chúng tôi đã ăn mừng việc thăng chức một cách đơn sơ, chỉ trong gia đình."}],
  "880": [{"jp":"**ささいな**ことで、友人と喧嘩してしまった。","vi":"Tôi đã cãi nhau với bạn chỉ vì chuyện vặt vãnh."},{"jp":"大きな事故も、**ささいな**ミスから始まることがある。","vi":"Tai nạn lớn đôi khi cũng bắt đầu từ sai sót nhỏ nhặt."}],
  "881": [{"jp":"待機児童の問題は、働く親にとって**切実な**問題だ。","vi":"Vấn đề trẻ chờ vào nhà trẻ là vấn đề cấp thiết đối với các bậc cha mẹ đi làm."},{"jp":"病気になって、健康のありがたさを**切実に**感じた。","vi":"Bị bệnh rồi tôi mới cảm nhận sâu sắc giá trị của sức khỏe."}],
  "882": [{"jp":"海外で暮らしてみて、語学力の必要性を**痛切に**感じた。","vi":"Sống ở nước ngoài, tôi cảm nhận thấm thía sự cần thiết của năng lực ngoại ngữ."},{"jp":"事故の遺族の**痛切な**訴えが胸に響いた。","vi":"Lời khẩn cầu da diết của gia đình nạn nhân vụ tai nạn đã chạm đến trái tim tôi."}],
  "883": [{"jp":"結ばれない**切ない**恋を描いた映画に涙した。","vi":"Tôi đã rơi nước mắt vì bộ phim kể về mối tình đau khổ không thành."},{"jp":"卒業式で友達と別れるのは**切ない**。","vi":"Chia tay bạn bè trong lễ tốt nghiệp thật buồn da diết."}],
  "884": [{"jp":"梅雨の時期は毎日雨ばかりで**鬱陶しい**。","vi":"Mùa mưa ngày nào cũng mưa, thật ngột ngạt khó chịu."},{"jp":"前髪が伸びて目にかかり、**鬱陶しい**。","vi":"Tóc mái dài ra che cả mắt, thật phiền."}],
  "885": [{"jp":"ビザの申請には、**煩わしい**手続きがたくさんある。","vi":"Xin visa có rất nhiều thủ tục phiền phức."},{"jp":"近所付き合いを**煩わしい**と感じる人も増えている。","vi":"Ngày càng nhiều người cảm thấy việc giao tiếp với hàng xóm thật phiền toái."}],
  "886": [{"jp":"上司に、クレーム対応という**厄介な**仕事を押し付けられた。","vi":"Tôi bị cấp trên đẩy cho công việc rắc rối là xử lý khiếu nại."},{"jp":"大学時代は、4年間叔父の家に**厄介**になった。","vi":"Thời đại học, tôi đã ở nhờ nhà chú suốt 4 năm."}],
  "887": [{"jp":"この程度の問題なら、彼にとっては**容易い**ことだ。","vi":"Vấn đề cỡ này thì với anh ấy là chuyện dễ dàng."},{"jp":"人の心は、そう**容易く**変えられるものではない。","vi":"Lòng người không phải thứ có thể dễ dàng thay đổi."}],
  "888": [{"jp":"治療を続けているが、父の病状は**思わしく**ない。","vi":"Dù vẫn đang điều trị nhưng bệnh tình của bố tôi không khả quan."},{"jp":"売り上げが**思わしくない**ため、新商品の発売を延期した。","vi":"Vì doanh thu không được như ý nên đã hoãn ra mắt sản phẩm mới."}],
  "889": [{"jp":"仕事を取るか家庭を取るか、**悩ましい**問題だ。","vi":"Chọn công việc hay chọn gia đình, đó là vấn đề nan giải."},{"jp":"雑誌の表紙で、モデルが**悩ましい**ポーズをとっている。","vi":"Trên bìa tạp chí, người mẫu đang tạo dáng quyến rũ."}],
  "890": [{"jp":"友人を待つ間、**手持無沙汰な**ので本を読んでいた。","vi":"Trong lúc chờ bạn, vì không có gì làm nên tôi đọc sách."},{"jp":"仕事が早く終わってしまい、**手持無沙汰**で困った。","vi":"Công việc xong sớm quá, chẳng có gì làm nên tôi thấy lúng túng."}],
  "891": [{"jp":"部屋の壁は**淡い**ピンクで塗られている。","vi":"Tường phòng được sơn màu hồng nhạt."},{"jp":"合格できるかもしれないという**淡い**期待を抱いていた。","vi":"Tôi đã ôm một hy vọng mong manh rằng có thể sẽ đỗ."}],
  "892": [{"jp":"この魚は味が**淡泊**なので、濃いソースがよく合う。","vi":"Loại cá này vị thanh đạm nên rất hợp với nước sốt đậm đà."},{"jp":"彼はお金に**淡白な**性格で、細かいことにこだわらない。","vi":"Anh ấy có tính cách không câu nệ chuyện tiền bạc, không để ý những điều nhỏ nhặt."}],
  "893": [{"jp":"桜の花は、**はかない**からこそ美しい。","vi":"Hoa anh đào đẹp chính vì sự mong manh, ngắn ngủi của nó."},{"jp":"宝くじが当たるという**はかない**望みを抱いている。","vi":"Tôi đang ôm hy vọng mong manh là sẽ trúng xổ số."}],
  "894": [{"jp":"優勝候補のチームが、1回戦で**あっけなく**負けた。","vi":"Đội ứng cử viên vô địch đã thua chóng vánh ngay từ vòng 1."},{"jp":"楽しみにしていた旅行も、**あっけない**ほど早く終わってしまった。","vi":"Chuyến du lịch háo hức mong chờ cũng kết thúc nhanh đến hụt hẫng."}],
  "895": [{"jp":"どんなに努力しても報われず、**むなしい**気持ちになった。","vi":"Cố gắng bao nhiêu cũng không được đền đáp, tôi thấy thật vô nghĩa."},{"jp":"救助隊の懸命な捜索も**むなしく**、行方不明者は見つからなかった。","vi":"Bất chấp nỗ lực tìm kiếm của đội cứu hộ, người mất tích vẫn không được tìm thấy."}],
  "896": [{"jp":"村の周りには**なだらかな**丘が広がっている。","vi":"Xung quanh làng là những ngọn đồi thoai thoải trải dài."},{"jp":"この山道は**なだらか**なので、初心者でも登りやすい。","vi":"Con đường núi này thoai thoải nên người mới cũng dễ leo."}],
  "897": [{"jp":"川は下流に行くほど**緩やかに**流れる。","vi":"Sông càng về hạ lưu càng chảy chậm rãi."},{"jp":"景気は**緩やかな**回復が続いている。","vi":"Nền kinh tế đang tiếp tục phục hồi chậm rãi."}],
  "898": [{"jp":"週末は都会を離れて、**のどかな**田舎で過ごしたい。","vi":"Cuối tuần tôi muốn rời thành phố, về sống ở vùng quê thanh bình."},{"jp":"春の**のどかな**日差しの中、猫が昼寝をしている。","vi":"Dưới nắng xuân êm ả, chú mèo đang ngủ trưa."}],
  "899": [{"jp":"会議は**和やかな**雰囲気の中で行われた。","vi":"Cuộc họp diễn ra trong bầu không khí hòa nhã."},{"jp":"両家の家族は、食事をしながら**和やかに**話し合った。","vi":"Gia đình hai bên vừa dùng bữa vừa trò chuyện êm ấm."}],
  "900": [{"jp":"バレエダンサーの**しなやかな**動きに見とれた。","vi":"Tôi say mê ngắm những động tác uyển chuyển của vũ công ba lê."},{"jp":"変化の激しい時代には、**しなやかな**考え方が求められる。","vi":"Trong thời đại biến động mạnh mẽ, cần có lối suy nghĩ linh hoạt."}],
  "901": [{"jp":"家族は、私にとって**かけがえのない**存在だ。","vi":"Gia đình là điều không gì thay thế được đối với tôi."},{"jp":"**かけがえのない**地球を、次の世代に残そう。","vi":"Hãy giữ gìn Trái Đất vô giá cho thế hệ sau."}],
  "902": [{"jp":"山頂で飲むコーヒーの味は**格別**だ。","vi":"Cà phê uống trên đỉnh núi có hương vị tuyệt hảo."},{"jp":"今年の夏は**格別に**暑い。","vi":"Mùa hè năm nay nóng đặc biệt."}],
  "903": [{"jp":"インターネットは**画期的な**発明だった。","vi":"Internet là một phát minh mang tính bước ngoặt."},{"jp":"その研究チームは、がん治療の**画期的な**方法を開発した。","vi":"Nhóm nghiên cứu đó đã phát triển một phương pháp điều trị ung thư mang tính đột phá."}],
  "904": [{"jp":"この鍋は煮る、焼く、蒸すができる**重宝な**調理器具だ。","vi":"Chiếc nồi này là dụng cụ nấu ăn hữu ích, có thể nấu, nướng, hấp."},{"jp":"小型の懐中電灯は、災害時にとても**重宝**だ。","vi":"Chiếc đèn pin nhỏ rất hữu dụng khi có thiên tai."}],
  "905": [{"jp":"初めての取引先への手土産は、お菓子が**無難**だ。","vi":"Quà mang đến đối tác lần đầu thì bánh kẹo là lựa chọn an toàn."},{"jp":"彼のスピーチは**無難に**まとまっていたが、印象には残らなかった。","vi":"Bài phát biểu của anh ấy được gói gọn an toàn nhưng không để lại ấn tượng."}],
  "906": [{"jp":"**画一的な**教育では、子どもの個性が育たない。","vi":"Với nền giáo dục rập khuôn thì cá tính của trẻ không thể phát triển."},{"jp":"郊外には**画一的な**デザインの住宅が並んでいる。","vi":"Ở ngoại ô, những ngôi nhà có thiết kế giống hệt nhau nằm san sát."}],
  "907": [{"jp":"「れ」と「わ」は形が似ていて**紛らわしい**。","vi":"Chữ \"re\" và \"wa\" có hình dạng giống nhau nên dễ nhầm lẫn."},{"jp":"**紛らわしい**表現は誤解を招くので、避けるべきだ。","vi":"Nên tránh những cách diễn đạt dễ gây hiểu lầm."}],
  "908": [{"jp":"冷蔵庫に入れ忘れたビールが**生ぬるく**なっていた。","vi":"Chai bia quên cho vào tủ lạnh đã trở nên âm ấm."},{"jp":"そんな**生ぬるい**やり方では、不正はなくならない。","vi":"Với cách làm nửa vời như thế thì gian lận không thể chấm dứt."}],
  "909": [{"jp":"彼は人当たりはいいが、商売では**強かな**人物だ。","vi":"Ông ấy dễ gần nhưng trong làm ăn lại là người khôn ranh lì lợm."},{"jp":"戦後の混乱した時代を、彼女は**強かに**生き抜いた。","vi":"Bà ấy đã sống sót qua thời kỳ hỗn loạn sau chiến tranh một cách cứng cỏi."}],
  "910": [{"jp":"年をとると、骨が**脆く**なる。","vi":"Khi về già, xương trở nên giòn, dễ gãy."},{"jp":"彼は情に**脆い**ので、頼まれると断れない。","vi":"Anh ấy dễ mềm lòng nên hễ được nhờ là không từ chối được."}],
  "911": [{"jp":"今のままの支持率では、次の選挙での当選は**危うい**。","vi":"Với tỷ lệ ủng hộ như hiện nay thì khả năng trúng cử ở cuộc bầu cử tới rất bấp bênh."},{"jp":"寝坊したが、タクシーを使って**危うく**会議に間に合った。","vi":"Tôi ngủ quên nhưng nhờ đi taxi nên suýt soát kịp cuộc họp."}],
  "912": [{"jp":"この書類は手続きが**ややこしくて**、何度も窓口に問い合わせた。","vi":"Thủ tục giấy tờ này rắc rối nên tôi đã phải hỏi quầy tiếp nhận nhiều lần."},{"jp":"話が**ややこしく**なるから、今は余計なことを言わないでほしい。","vi":"Đừng nói thêm điều thừa thãi lúc này, kẻo câu chuyện thành rắc rối."}],
  "913": [{"jp":"同窓会では、参加者の服装が**まちまち**だった。","vi":"Ở buổi họp lớp, trang phục của người tham gia mỗi người một kiểu."},{"jp":"この問題については、専門家の意見も**まちまちな**ようだ。","vi":"Về vấn đề này, ý kiến của các chuyên gia dường như cũng không thống nhất."}],
  "914": [{"jp":"被災地には、まだ地震の爪痕が**生々しく**残っている。","vi":"Ở vùng bị thiên tai, dấu vết của trận động đất vẫn còn nguyên vẹn."},{"jp":"彼は戦争の体験を**生々しい**言葉で語った。","vi":"Ông ấy kể lại trải nghiệm chiến tranh bằng những lời lẽ chân thực, sống động."}],
  "915": [{"jp":"彼女は上司に対して**露骨な**嫌悪感を示した。","vi":"Cô ấy thể hiện sự ghét bỏ lộ liễu với cấp trên."},{"jp":"子ども向けの番組で**露骨な**暴力描写は避けるべきだ。","vi":"Nên tránh những cảnh bạo lực trắng trợn trong chương trình dành cho trẻ em."}],
  "916": [{"jp":"高齢者を狙った**巧妙な**詐欺の手口が増えている。","vi":"Các thủ đoạn lừa đảo tinh vi nhắm vào người cao tuổi đang gia tăng."},{"jp":"その推理小説は、伏線が**巧妙に**張られている。","vi":"Cuốn tiểu thuyết trinh thám đó cài cắm các tình tiết báo trước rất khéo léo."}],
  "917": [{"jp":"社長室には**重厚な**木製の家具が並んでいた。","vi":"Trong phòng giám đốc bày những món đồ gỗ bề thế."},{"jp":"この映画は**重厚な**人間ドラマとして高く評価された。","vi":"Bộ phim này được đánh giá cao như một tác phẩm chính kịch về con người có chiều sâu."}],
  "918": [{"jp":"神社で**厳かな**結婚式が執り行われた。","vi":"Một lễ cưới trang nghiêm được cử hành tại đền thờ."},{"jp":"式典は国歌斉唱とともに**厳かに**始まった。","vi":"Buổi lễ bắt đầu trang nghiêm cùng lúc hát quốc ca."}],
  "919": [{"jp":"標高が高くなるにつれて、酸素が**希薄に**なる。","vi":"Càng lên cao, oxy càng loãng."},{"jp":"都会では近所付き合いが**希薄に**なっていると言われる。","vi":"Người ta nói rằng ở thành phố, quan hệ hàng xóm ngày càng nhạt nhẽo."}],
  "920": [{"jp":"育ち盛りの息子は食欲が**旺盛で**、ご飯を3杯も食べる。","vi":"Cậu con trai đang tuổi lớn ăn rất khỏe, ăn tới 3 bát cơm."},{"jp":"彼女は好奇心が**旺盛な**人で、何にでも挑戦する。","vi":"Cô ấy là người tò mò dồi dào, việc gì cũng thử sức."}],
  "921": [{"jp":"そのチームは決勝戦で**圧倒的な**強さを見せた。","vi":"Đội đó đã thể hiện sức mạnh áp đảo trong trận chung kết."},{"jp":"新しい市長は**圧倒的な**支持を得て当選した。","vi":"Thị trưởng mới đắc cử với sự ủng hộ áp đảo."}],
  "922": [{"jp":"睡眠や食欲は、人間の**生理的な**欲求だ。","vi":"Ngủ và ăn là những nhu cầu sinh lý của con người."},{"jp":"理由はないが、あの人の声は**生理的に**受け付けない。","vi":"Không vì lý do gì cả, nhưng giọng người đó tôi không chịu nổi theo bản năng."}],
  "923": [{"jp":"一つの計算ミスが、会社に**致命的な**損失をもたらした。","vi":"Một lỗi tính toán đã gây ra tổn thất chí mạng cho công ty."},{"jp":"そのボクサーは**致命的な**一撃を受けて倒れた。","vi":"Võ sĩ quyền anh đó trúng một cú đánh chí mạng và gục ngã."}],
  "924": [{"jp":"この10年で、町の人口は**著しく**減少した。","vi":"Trong 10 năm qua, dân số của thị trấn đã giảm rõ rệt."},{"jp":"新薬の開発には**著しい**進歩が見られる。","vi":"Có thể thấy tiến bộ đáng kể trong việc phát triển thuốc mới."}],
  "925": [{"jp":"この薬は高齢者に特に**顕著な**効果を示した。","vi":"Thuốc này cho hiệu quả nổi bật đặc biệt ở người cao tuổi."},{"jp":"地球温暖化の影響は、北極で**顕著に**現れている。","vi":"Ảnh hưởng của sự nóng lên toàn cầu thể hiện rõ rệt ở Bắc Cực."}],
  "926": [{"jp":"彼は亡くなった祖父から**莫大な**遺産を相続した。","vi":"Anh ấy được thừa kế khối tài sản khổng lồ từ người ông đã mất."},{"jp":"新しい空港の建設には**莫大な**費用がかかる。","vi":"Việc xây dựng sân bay mới tốn chi phí khổng lồ."}],
  "927": [{"jp":"人気歌手の到着を待って、空港には**おびただしい**数のファンが集まった。","vi":"Một lượng fan đông vô số tụ tập ở sân bay chờ ca sĩ nổi tiếng đến."},{"jp":"台風の後、海岸には**おびただしい**量のごみが打ち上げられた。","vi":"Sau bão, vô số rác bị sóng đánh dạt lên bờ biển."}],
  "928": [{"jp":"自分が一番優秀だと思うなんて、**甚だしい**思い上がりだ。","vi":"Nghĩ mình giỏi nhất thì thật là ngạo mạn quá mức."},{"jp":"都市と地方の所得格差は**甚だしい**。","vi":"Chênh lệch thu nhập giữa thành thị và nông thôn là cực kỳ lớn."}],
  "929": [{"jp":"この事件は、現代社会の問題を**端的に**示している。","vi":"Vụ việc này cho thấy rõ ràng vấn đề của xã hội hiện đại."},{"jp":"**端的に**言えば、この計画には予算が足りない。","vi":"Nói ngắn gọn thì kế hoạch này thiếu ngân sách."}],
  "930": [{"jp":"彼女は英語と中国語に**堪能な**ので、通訳を頼まれた。","vi":"Cô ấy thông thạo tiếng Anh và tiếng Trung nên được nhờ làm phiên dịch."},{"jp":"旅行では地元の海鮮料理を**堪能した**。","vi":"Trong chuyến du lịch, tôi đã thưởng thức thỏa thích hải sản địa phương."}],
  "931": [{"jp":"この国際会議は国連が**主催して**いる。","vi":"Hội nghị quốc tế này do Liên Hợp Quốc đứng ra tổ chức."},{"jp":"市が**主催する**花火大会に、10万人が訪れた。","vi":"10 vạn người đã đến lễ hội pháo hoa do thành phố tổ chức."}],
  "932": [{"jp":"部長に言われて、社員旅行を**企画する**ことになった。","vi":"Theo lời trưởng phòng, tôi được giao lên kế hoạch cho chuyến du lịch công ty."},{"jp":"若手社員の**企画**が採用され、新商品として発売された。","vi":"Đề án của nhân viên trẻ được chấp thuận và ra mắt thành sản phẩm mới."}],
  "933": [{"jp":"まず、本日の会の**趣旨**をご説明いたします。","vi":"Trước tiên, tôi xin giải thích mục đích của buổi họp hôm nay."},{"jp":"彼の発言は会議の**趣旨**から外れていた。","vi":"Phát biểu của anh ấy đi lệch khỏi ý chính của cuộc họp."}],
  "934": [{"jp":"彼の説明は**要領**を得ていて、とても分かりやすい。","vi":"Lời giải thích của anh ấy đúng trọng tâm nên rất dễ hiểu."},{"jp":"新しい仕事の**要領**がつかめるまで、少し時間がかかった。","vi":"Phải mất một chút thời gian tôi mới nắm được cách làm công việc mới."}],
  "935": [{"jp":"開業資金が足りず、親戚に**融通して**もらった。","vi":"Thiếu vốn mở cửa hàng, tôi đã được họ hàng xoay tiền giúp."},{"jp":"うちの課長は規則にうるさくて、**融通**が利かない。","vi":"Trưởng ban của chúng tôi khắt khe quy tắc, chẳng linh hoạt chút nào."}],
  "936": [{"jp":"市は留学生のために住宅探しの**便宜**を図っている。","vi":"Thành phố tạo điều kiện thuận lợi cho du học sinh tìm nhà ở."},{"jp":"説明の**便宜**上、図を使って示します。","vi":"Để tiện giải thích, tôi sẽ minh họa bằng hình vẽ."}],
  "937": [{"jp":"彼女は5か国語を**駆使して**、国際会議の通訳を務めている。","vi":"Cô ấy sử dụng thành thạo 5 ngôn ngữ và làm phiên dịch cho các hội nghị quốc tế."},{"jp":"最新の技術を**駆使した**映像が観客を驚かせた。","vi":"Những hình ảnh sử dụng thành thạo công nghệ mới nhất đã khiến khán giả kinh ngạc."}],
  "938": [{"jp":"健康のために、毎朝のジョギングを**実践して**いる。","vi":"Vì sức khỏe, tôi đang thực hành chạy bộ mỗi sáng."},{"jp":"大学で学んだ理論を現場で**実践する**のは簡単ではない。","vi":"Thực hành lý thuyết học ở đại học tại hiện trường không hề đơn giản."}],
  "939": [{"jp":"市は駅前の再開発に**着手した**。","vi":"Thành phố đã bắt tay vào tái phát triển khu trước nhà ga."},{"jp":"予算が決まり次第、新しいプロジェクトに**着手する**予定だ。","vi":"Ngay khi ngân sách được quyết định, chúng tôi dự định bắt tay vào dự án mới."}],
  "940": [{"jp":"政府は感染拡大を防ぐため、緊急の**措置**を講じた。","vi":"Chính phủ đã đưa ra biện pháp khẩn cấp để ngăn dịch lây lan."},{"jp":"違反した選手には、出場停止の**措置**が取られた。","vi":"Biện pháp đình chỉ thi đấu đã được áp dụng với vận động viên vi phạm."}],
  "941": [{"jp":"男女の賃金格差を**是正する**必要がある。","vi":"Cần chấn chỉnh chênh lệch lương giữa nam và nữ."},{"jp":"監査で指摘された誤りは、すぐに**是正された**。","vi":"Những sai sót bị chỉ ra trong đợt kiểm toán đã được sửa chữa ngay."}],
  "942": [{"jp":"死刑制度の**是非**について、授業で議論した。","vi":"Chúng tôi đã tranh luận trong giờ học về đúng sai của án tử hình."},{"jp":"日本に来たら、**是非**うちに遊びに来てください。","vi":"Nếu đến Nhật, nhất định hãy đến nhà tôi chơi nhé."}],
  "943": [{"jp":"両国は紛争の平和的な解決策を**模索して**いる。","vi":"Hai nước đang tìm cách giải quyết xung đột một cách hòa bình."},{"jp":"会社を辞めた後、彼は新しい生き方を**模索した**。","vi":"Sau khi nghỉ việc, anh ấy mò mẫm tìm một lối sống mới."}],
  "944": [{"jp":"この旅館は和洋**折衷**の造りになっている。","vi":"Lữ quán này được xây theo lối kết hợp Nhật - Tây."},{"jp":"両者の案を**折衷して**、新しい計画を作った。","vi":"Chúng tôi dung hòa phương án của hai bên để lập kế hoạch mới."}],
  "945": [{"jp":"今回の改正で、誤差は1%まで**許容される**ことになった。","vi":"Với lần sửa đổi này, sai số được chấp nhận đến 1%."},{"jp":"多様な価値観を**許容する**社会を目指すべきだ。","vi":"Chúng ta nên hướng tới một xã hội chấp nhận các giá trị quan đa dạng."}],
  "946": [{"jp":"この薬は痛みを**緩和する**効果がある。","vi":"Thuốc này có tác dụng giảm nhẹ cơn đau."},{"jp":"外国人観光客の入国規制が**緩和された**。","vi":"Quy định nhập cảnh với khách du lịch nước ngoài đã được nới lỏng."}],
  "947": [{"jp":"地震から3時間後、津波警報が**解除された**。","vi":"3 giờ sau trận động đất, cảnh báo sóng thần đã được dỡ bỏ."},{"jp":"携帯の画面ロックを**解除する**方法を忘れてしまった。","vi":"Tôi quên mất cách mở khóa màn hình điện thoại."}],
  "948": [{"jp":"災害が起きたので、派手なパーティーは**自粛する**ことにした。","vi":"Vì xảy ra thiên tai nên chúng tôi quyết định tự hạn chế những bữa tiệc xa hoa."},{"jp":"感染拡大を受けて、多くの企業がイベントの開催を**自粛した**。","vi":"Trước tình hình dịch lan rộng, nhiều doanh nghiệp đã tự kiềm chế không tổ chức sự kiện."}],
  "949": [{"jp":"この辺りは**治安**がいいので、夜一人で歩いても安心だ。","vi":"Khu này an ninh tốt nên đi bộ một mình ban đêm cũng yên tâm."},{"jp":"内戦が続き、その国の**治安**は悪化する一方だ。","vi":"Nội chiến kéo dài khiến an ninh trật tự nước đó ngày càng xấu đi."}],
  "950": [{"jp":"この建物は防犯カメラで24時間**監視されて**いる。","vi":"Tòa nhà này bị giám sát 24/24 bằng camera an ninh."},{"jp":"国連は選挙が公正に行われるか**監視する**ために職員を派遣した。","vi":"Liên Hợp Quốc đã cử nhân viên để giám sát xem cuộc bầu cử có diễn ra công bằng không."}],
  "951": [{"jp":"病上がりなのだから、無理は**禁物**だよ。","vi":"Vừa mới khỏi bệnh nên tuyệt đối đừng làm quá sức nhé."},{"jp":"試験直前だからといって、油断は**禁物**だ。","vi":"Dù sắp thi rồi thì cũng không được chủ quan."}],
  "952": [{"jp":"その大臣には献金をめぐる**疑惑**が持ち上がっている。","vi":"Có nghi vấn về khoản tiền quyên góp chính trị xung quanh vị bộ trưởng đó."},{"jp":"彼は記者会見で自身の**疑惑**を強く否定した。","vi":"Ông ấy đã phủ nhận mạnh mẽ những nghi vấn về mình trong buổi họp báo."}],
  "953": [{"jp":"この問題について、専門家の**見解**を聞いてみたい。","vi":"Về vấn đề này, tôi muốn nghe quan điểm của chuyên gia."},{"jp":"両社の**見解**の相違は最後まで埋まらなかった。","vi":"Sự khác biệt quan điểm giữa hai công ty đến cuối cùng vẫn không được thu hẹp."}],
  "954": [{"jp":"社員一人ひとりが安全の重要性を**認識する**必要がある。","vi":"Mỗi nhân viên cần nhận thức rõ tầm quan trọng của an toàn."},{"jp":"彼は自分の置かれた立場をまだ正しく**認識して**いない。","vi":"Anh ta vẫn chưa nhận thức đúng vị trí của mình."}],
  "955": [{"jp":"幼い子どもには、まだ時間の**概念**がない。","vi":"Trẻ nhỏ vẫn chưa có khái niệm về thời gian."},{"jp":"この発明は、「家」という**概念**を大きく変えた。","vi":"Phát minh này đã thay đổi lớn khái niệm về \"ngôi nhà\"."}],
  "956": [{"jp":"この物語に登場する人物や団体はすべて**架空**のものです。","vi":"Các nhân vật và tổ chức xuất hiện trong câu chuyện này đều là hư cấu."},{"jp":"彼は**架空**の会社を作り、投資家から金をだまし取った。","vi":"Hắn lập ra một công ty ma để lừa tiền của các nhà đầu tư."}],
  "957": [{"jp":"満天の星を見ていると、宇宙の**神秘**を感じる。","vi":"Ngắm bầu trời đầy sao, tôi cảm nhận được sự huyền bí của vũ trụ."},{"jp":"霧に包まれた湖は、**神秘的**な雰囲気を漂わせていた。","vi":"Hồ nước chìm trong sương mù toát lên bầu không khí huyền bí."}],
  "958": [{"jp":"深海に住む生物の生態は、まさに自然界の**驚異**だ。","vi":"Hệ sinh thái của các sinh vật sống ở biển sâu đúng là điều kỳ diệu của thế giới tự nhiên."},{"jp":"その選手は100メートルで**驚異的**な記録を出した。","vi":"Vận động viên đó đã lập kỷ lục đáng kinh ngạc ở cự ly 100 mét."}],
  "959": [{"jp":"京都は日本でも**有数**の観光地だ。","vi":"Kyoto là một trong những điểm du lịch hàng đầu Nhật Bản."},{"jp":"彼は世界でも**有数**の生物学者として知られている。","vi":"Ông ấy được biết đến là một nhà sinh vật học hàng đầu thế giới."}],
  "960": [{"jp":"長く続いた不況にも、ようやく回復の**兆し**が見えてきた。","vi":"Cuộc suy thoái kéo dài cuối cùng cũng có dấu hiệu phục hồi."},{"jp":"梅の花がほころび始め、春の**兆し**が感じられる。","vi":"Hoa mơ bắt đầu hé nở, cảm nhận được dấu hiệu của mùa xuân."}],
  "961": [{"jp":"2000年は新しい世紀の**幕開け**として盛大に祝われた。","vi":"Năm 2000 được ăn mừng long trọng như sự mở màn của thế kỷ mới."},{"jp":"この新薬の登場は、がん治療の新時代の**幕開け**だ。","vi":"Sự xuất hiện của loại thuốc mới này là khởi đầu thời đại mới trong điều trị ung thư."}],
  "962": [{"jp":"警察は事件の詳しい**経緯**を調べている。","vi":"Cảnh sát đang điều tra đầu đuôi chi tiết của vụ án."},{"jp":"社長は合併に至った**経緯**を社員に説明した。","vi":"Giám đốc đã giải thích cho nhân viên ngọn ngành dẫn đến việc sáp nhập."}],
  "963": [{"jp":"国民は選挙結果の**成り行き**を注目して見守っている。","vi":"Người dân đang chăm chú theo dõi diễn biến của kết quả bầu cử."},{"jp":"計画を立てずに、何事も**成り行き**に任せるのは危険だ。","vi":"Không lập kế hoạch mà phó mặc mọi việc theo diễn biến tự nhiên là nguy hiểm."}],
  "964": [{"jp":"駅で待ち合わせたが、**行き違い**になって会えなかった。","vi":"Chúng tôi hẹn gặp ở ga nhưng lỡ nhau nên không gặp được."},{"jp":"ちょっとした**行き違い**から、二人は口をきかなくなった。","vi":"Từ một hiểu lầm nhỏ mà hai người không nói chuyện với nhau nữa."}],
  "965": [{"jp":"駅から会場までは、歩いて30分ほどの**道のり**だ。","vi":"Từ ga đến hội trường là quãng đường khoảng 30 phút đi bộ."},{"jp":"彼は社長になるまでの長い**道のり**を振り返った。","vi":"Ông ấy nhìn lại chặng đường dài cho đến khi trở thành giám đốc."}],
  "966": [{"jp":"倒れた木が道をふさぎ、私たちの**行く手**を阻んだ。","vi":"Cây đổ chắn đường, cản lối đi phía trước của chúng tôi."},{"jp":"新しい人生を歩み始めた彼女の**行く手**には困難も多いだろう。","vi":"Trên con đường phía trước của cô ấy, người vừa bắt đầu cuộc đời mới, hẳn sẽ có nhiều khó khăn."}],
  "967": [{"jp":"宇宙の**果て**には何があるのだろうか。","vi":"Ở tận cùng vũ trụ có gì nhỉ?"},{"jp":"激しい口論の**果て**に、二人は別れることになった。","vi":"Kết cục sau cuộc cãi vã dữ dội, hai người đã chia tay."}],
  "968": [{"jp":"意見が出尽くしたところで、議長が**決**を採った。","vi":"Khi các ý kiến đã được nêu hết, chủ tọa tiến hành biểu quyết."},{"jp":"賛成と反対が同数で、**決**は議長に委ねられた。","vi":"Số phiếu thuận và chống bằng nhau nên quyết định được giao cho chủ tọa."}],
  "969": [{"jp":"健康のため、毎日1万歩を**目安**に歩いている。","vi":"Vì sức khỏe, tôi đi bộ với mục tiêu khoảng 1 vạn bước mỗi ngày."},{"jp":"引っ越し費用の**目安**を業者に聞いてみた。","vi":"Tôi đã hỏi công ty dịch vụ mức chi phí chuyển nhà ước tính."}],
  "970": [{"jp":"資金が集まり、ようやく工事再開の**目処**が立った。","vi":"Vốn đã được huy động, cuối cùng cũng có triển vọng tái khởi công."},{"jp":"年内の完成を**目処**に、作業を進めている。","vi":"Chúng tôi đang tiến hành công việc với mục tiêu hoàn thành trong năm."}],
  "971": [{"jp":"父は医師から余命3か月と**宣告された**。","vi":"Bố tôi bị bác sĩ báo chỉ còn sống được 3 tháng."},{"jp":"裁判長は被告に懲役10年を**宣告した**。","vi":"Chánh án đã tuyên án bị cáo 10 năm tù."}],
  "972": [{"jp":"政府は事件について公式の**声明**を発表した。","vi":"Chính phủ đã công bố tuyên bố chính thức về vụ việc."},{"jp":"両国の首脳は会談後、共同**声明**を出した。","vi":"Sau hội đàm, lãnh đạo hai nước đã ra tuyên bố chung."}],
  "973": [{"jp":"彼はオリンピックで世界新記録を**樹立した**。","vi":"Anh ấy đã lập kỷ lục thế giới mới tại Olympic."},{"jp":"両国は1972年に国交を**樹立した**。","vi":"Hai nước đã thiết lập quan hệ ngoại giao vào năm 1972."}],
  "974": [{"jp":"キャプテンとしてチームを**統率する**のは簡単ではない。","vi":"Thống lĩnh đội với tư cách đội trưởng không hề đơn giản."},{"jp":"彼は1000人の兵士を**統率する**指揮官だった。","vi":"Ông ấy là chỉ huy thống lĩnh 1000 binh sĩ."}],
  "975": [{"jp":"戦国時代には、各地の大名が**勢力**を争った。","vi":"Thời Chiến Quốc, các lãnh chúa khắp nơi tranh giành quyền lực."},{"jp":"台風は**勢力**を保ったまま北上している。","vi":"Cơn bão đang tiến lên phía bắc mà vẫn giữ nguyên sức mạnh."}],
  "976": [{"jp":"近年、アジアの新興企業が急速に**台頭して**きた。","vi":"Những năm gần đây, các doanh nghiệp mới nổi ở châu Á trỗi dậy nhanh chóng."},{"jp":"経済不安を背景に、極端な思想が**台頭する**恐れがある。","vi":"Trong bối cảnh bất ổn kinh tế, có nguy cơ những tư tưởng cực đoan nổi lên."}],
  "977": [{"jp":"後半に入って、試合の**形勢**が逆転した。","vi":"Bước sang hiệp hai, cục diện trận đấu đã đảo ngược."},{"jp":"選挙戦は現職に不利な**形勢**になってきた。","vi":"Cuộc chạy đua bầu cử đang trở thành tình thế bất lợi cho người đương nhiệm."}],
  "978": [{"jp":"彼は倍率50倍の難関を**突破して**合格した。","vi":"Anh ấy đã vượt qua cửa ải khó với tỷ lệ chọi 1/50 để đỗ."},{"jp":"このアプリの利用者は、ついに1000万人を**突破した**。","vi":"Số người dùng ứng dụng này cuối cùng đã vượt mốc 10 triệu."}],
  "979": [{"jp":"試合は予想外の**展開**となり、観客は熱狂した。","vi":"Trận đấu diễn biến ngoài dự đoán khiến khán giả cuồng nhiệt."},{"jp":"その会社はアジア各国で事業を**展開して**いる。","vi":"Công ty đó đang triển khai kinh doanh tại các nước châu Á."}],
  "980": [{"jp":"明治時代、多くの人が北海道に渡って原野を**開拓した**。","vi":"Thời Minh Trị, nhiều người đã sang Hokkaido khai hoang vùng đồng hoang."},{"jp":"営業部は海外の新しい販路を**開拓して**いる。","vi":"Phòng kinh doanh đang khai thác kênh tiêu thụ mới ở nước ngoài."}],
  "981": [{"jp":"誤った情報がSNSで瞬く間に**拡散した**。","vi":"Thông tin sai lệch đã lan rộng trên mạng xã hội trong chớp mắt."},{"jp":"工場から漏れた有害物質が周辺に**拡散する**恐れがある。","vi":"Có nguy cơ chất độc hại rò rỉ từ nhà máy sẽ khuếch tán ra xung quanh."}],
  "982": [{"jp":"金属は熱を加えると**膨張する**。","vi":"Kim loại giãn nở khi bị nung nóng."},{"jp":"国の予算は年々**膨張し**続けている。","vi":"Ngân sách quốc gia tiếp tục phình to qua từng năm."}],
  "983": [{"jp":"空には**無数**の星が輝いていた。","vi":"Trên trời có vô số ngôi sao đang tỏa sáng."},{"jp":"インターネット上には**無数**の情報があふれている。","vi":"Trên Internet tràn ngập vô số thông tin."}],
  "984": [{"jp":"部長は自分の意見に**固執して**、誰の話も聞かない。","vi":"Trưởng phòng khăng khăng giữ ý kiến của mình, không nghe ai cả."},{"jp":"過去の成功に**固執する**と、変化に対応できなくなる。","vi":"Nếu cố chấp vào thành công trong quá khứ thì sẽ không thể thích ứng với thay đổi."}],
  "985": [{"jp":"親の過保護は、子どもの自立を**阻害する**。","vi":"Sự bao bọc quá mức của cha mẹ cản trở tính tự lập của con cái."},{"jp":"一部企業による独占が、公平な競争を**阻害して**いる。","vi":"Sự độc quyền của một số doanh nghiệp đang cản trở cạnh tranh công bằng."}],
  "986": [{"jp":"弁護士として、弱い立場の人々の人権を**擁護したい**。","vi":"Với tư cách luật sư, tôi muốn bảo vệ nhân quyền của những người yếu thế."},{"jp":"彼は批判を浴びる友人を最後まで**擁護した**。","vi":"Anh ấy bênh vực người bạn đang hứng chịu chỉ trích đến cùng."}],
  "987": [{"jp":"憲法は国民に健康で文化的な生活を**保障して**いる。","vi":"Hiến pháp bảo đảm cho người dân cuộc sống khỏe mạnh và có văn hóa."},{"jp":"表現の自由は、民主社会で**保障される**べき権利だ。","vi":"Tự do ngôn luận là quyền phải được bảo đảm trong xã hội dân chủ."}],
  "988": [{"jp":"会社は事故の被害者に損害を**補償する**ことになった。","vi":"Công ty sẽ bồi thường thiệt hại cho nạn nhân vụ tai nạn."},{"jp":"工事で営業できなかった店には、市から**補償**金が支払われた。","vi":"Thành phố đã chi trả tiền bồi thường cho các cửa hàng không thể kinh doanh do công trình."}],
  "989": [{"jp":"先ほどの説明に、少し**補足させて**ください。","vi":"Xin cho phép tôi bổ sung một chút vào phần giải thích lúc nãy."},{"jp":"部長の発表を、担当者が具体例を挙げて**補足した**。","vi":"Người phụ trách đã bổ sung cho phần trình bày của trưởng phòng bằng các ví dụ cụ thể."}],
  "990": [{"jp":"暑い日は、こまめに水分を**補給する**ようにしてください。","vi":"Những ngày nóng, hãy thường xuyên bổ sung nước."},{"jp":"車は途中のサービスエリアでガソリンを**補給した**。","vi":"Xe đã đổ thêm xăng ở trạm dừng chân giữa đường."}],
  "991": [{"jp":"塩分を過剰に**摂取する**と、高血圧の原因になる。","vi":"Hấp thụ quá nhiều muối sẽ là nguyên nhân gây cao huyết áp."},{"jp":"明治時代の日本は、西洋の文化を積極的に**摂取した**。","vi":"Nhật Bản thời Minh Trị đã tích cực tiếp thu văn hóa phương Tây."}],
  "992": [{"jp":"戦争中は、食糧や物資が**欠乏して**いた。","vi":"Trong thời chiến, lương thực và vật tư thiếu thốn."},{"jp":"鉄分が**欠乏する**と、貧血になりやすい。","vi":"Khi thiếu chất sắt sẽ dễ bị thiếu máu."}],
  "993": [{"jp":"この食品には保存料が**添加されて**いない。","vi":"Thực phẩm này không được thêm chất bảo quản."},{"jp":"セメントに特殊な素材を**添加する**ことで、強度が増す。","vi":"Bằng cách pha thêm vật liệu đặc biệt vào xi măng, độ bền tăng lên."}],
  "994": [{"jp":"この化粧品には天然の**成分**しか使われていない。","vi":"Mỹ phẩm này chỉ dùng thành phần tự nhiên."},{"jp":"薬を飲む前に、含まれている**成分**を確認したほうがいい。","vi":"Trước khi uống thuốc, nên kiểm tra các thành phần có trong đó."}],
  "995": [{"jp":"給与明細で、手当や税金の**内訳**を確認した。","vi":"Tôi kiểm tra chi tiết các khoản phụ cấp và thuế trong bảng lương."},{"jp":"旅行代金の**内訳**は、交通費が半分を占めている。","vi":"Trong các khoản của tiền tour du lịch, phí đi lại chiếm một nửa."}],
  "996": [{"jp":"今回の調査では、回答が不十分なデータは**除外した**。","vi":"Trong cuộc khảo sát lần này, chúng tôi đã loại bỏ những dữ liệu trả lời không đầy đủ."},{"jp":"今回の募集では、未経験者は対象から**除外されて**いる。","vi":"Đợt tuyển dụng lần này loại trừ những người chưa có kinh nghiệm."}],
  "997": [{"jp":"その企業は利益の一部を地域社会に**還元して**いる。","vi":"Doanh nghiệp đó trả lại một phần lợi nhuận cho cộng đồng địa phương."},{"jp":"買い物金額の5%がポイントとして**還元される**。","vi":"5% số tiền mua sắm được hoàn lại dưới dạng điểm."}],
  "998": [{"jp":"この島では、人間と野生の動物が平和に**共存して**いる。","vi":"Trên hòn đảo này, con người và động vật hoang dã chung sống hòa bình."},{"jp":"異なる文化が**共存する**社会を作るには、互いの理解が欠かせない。","vi":"Để tạo ra xã hội nơi các nền văn hóa khác nhau cùng tồn tại, sự thấu hiểu lẫn nhau là không thể thiếu."}],
  "999": [{"jp":"市は子どもたちの読書を**奨励する**ため、図書館を増やした。","vi":"Thành phố tăng thêm thư viện để khuyến khích trẻ em đọc sách."},{"jp":"政府は男性の育児休暇取得を**奨励して**いる。","vi":"Chính phủ đang khuyến khích nam giới nghỉ phép chăm con."}],
  "1000": [{"jp":"仕事に見合った**報酬**が支払われていない。","vi":"Thù lao tương xứng với công việc không được chi trả."},{"jp":"彼は**報酬**を得ずに、ボランティアで翻訳をしている。","vi":"Anh ấy làm dịch thuật tình nguyện mà không nhận thù lao."}],
  "1001": [{"jp":"結婚10年目にして、**待望**の子どもが生まれた。","vi":"Sau 10 năm kết hôn, đứa con mong đợi bấy lâu đã chào đời."},{"jp":"ファンが**待望して**いたシリーズの新作が、ついに発売された。","vi":"Phần mới của bộ truyện mà người hâm mộ mong chờ cuối cùng đã được phát hành."}],
  "1002": [{"jp":"お酒は**節度**を守って楽しみましょう。","vi":"Hãy thưởng thức rượu bia một cách chừng mực."},{"jp":"大人として、**節度**のある行動を心がけたい。","vi":"Là người lớn, tôi muốn chú ý hành xử có chừng mực."}],
  "1003": [{"jp":"行きたくはなかったが、**義理**で取引先のパーティーに出席した。","vi":"Tôi không muốn đi nhưng vì bổn phận nên đã dự tiệc của đối tác."},{"jp":"**義理**の母とは、本当の親子のように仲がいい。","vi":"Tôi với mẹ chồng thân thiết như mẹ con ruột."}],
  "1004": [{"jp":"この辺りには、昔ながらの下町の**情緒**が残っている。","vi":"Khu này vẫn còn lưu giữ không khí khu phố bình dân như xưa."},{"jp":"仕事のストレスで、最近彼女は**情緒**不安定になっている。","vi":"Do căng thẳng công việc, gần đây cô ấy bị bất ổn về cảm xúc."}],
  "1005": [{"jp":"突然の知らせに、彼は明らかに**動揺して**いた。","vi":"Trước tin báo đột ngột, anh ấy rõ ràng đã dao động."},{"jp":"社長の辞任で、社内に**動揺**が広がった。","vi":"Việc giám đốc từ chức khiến sự xáo động lan khắp công ty."}],
  "1006": [{"jp":"彼の成績は科目によって**むら**がある。","vi":"Thành tích của cậu ấy không đều giữa các môn."},{"jp":"壁のペンキを塗ったら、色に**むら**ができてしまった。","vi":"Sơn tường xong thì màu bị loang lổ không đều."}],
  "1007": [{"jp":"最近、結婚しない生き方を認める**風潮**が広がっている。","vi":"Gần đây, xu hướng chấp nhận lối sống không kết hôn đang lan rộng."},{"jp":"お金さえあれば何でもできるという**風潮**には疑問を感じる。","vi":"Tôi thấy hoài nghi với trào lưu cho rằng chỉ cần có tiền là làm được mọi thứ."}],
  "1008": [{"jp":"国は非正規労働者の雇用の**実態**を調査した。","vi":"Nhà nước đã điều tra thực trạng tuyển dụng lao động không chính thức."},{"jp":"取材によって、介護現場の厳しい**実態**が明らかになった。","vi":"Qua quá trình tác nghiệp, thực trạng khắc nghiệt tại các cơ sở chăm sóc đã được làm sáng tỏ."}],
  "1009": [{"jp":"週刊誌が大物政治家のスキャンダルを**暴露した**。","vi":"Tuần san đã phơi bày vụ bê bối của một chính trị gia tầm cỡ."},{"jp":"元社員が会社の不正を**暴露する**本を出版した。","vi":"Một cựu nhân viên đã xuất bản cuốn sách vạch trần sai phạm của công ty."}],
  "1010": [{"jp":"容疑者は事件の直後に海外へ**逃亡した**。","vi":"Nghi phạm đã bỏ trốn ra nước ngoài ngay sau vụ án."},{"jp":"5年の**逃亡**の末、犯人はついに逮捕された。","vi":"Sau 5 năm lẩn trốn, thủ phạm cuối cùng đã bị bắt."}],
  "1011": [{"jp":"彼はつらい現実から**逃避する**ように、ゲームに没頭した。","vi":"Như để trốn tránh thực tại khắc nghiệt, anh ấy vùi đầu vào game."},{"jp":"試験前なのに部屋の掃除を始めるのは、一種の現実**逃避**だ。","vi":"Sắp thi rồi mà lại bắt đầu dọn phòng là một kiểu trốn tránh thực tại."}],
  "1012": [{"jp":"当事者だけでなく、**第三者**の意見も聞くべきだ。","vi":"Không chỉ người trong cuộc, mà cũng nên nghe ý kiến của người thứ ba."},{"jp":"会社は**第三者**委員会を設置して、不正の調査を依頼した。","vi":"Công ty đã lập ủy ban độc lập (bên thứ ba) để nhờ điều tra sai phạm."}],
  "1013": [{"jp":"裁判官は被害者と加害者の**言い分**を聞いた。","vi":"Thẩm phán đã nghe lời phân trần của cả nạn nhân và người gây hại."},{"jp":"相手にも**言い分**があるだろうから、一方的に責めるのはよくない。","vi":"Hẳn phía bên kia cũng có lý lẽ của họ, nên trách móc một chiều là không tốt."}],
  "1014": [{"jp":"彼は何でも母親の**言いなり**になっている。","vi":"Anh ta việc gì cũng răm rắp nghe theo mẹ."},{"jp":"上司の**言いなり**に動くだけでは、成長できない。","vi":"Chỉ làm răm rắp theo lời cấp trên thì không thể trưởng thành được."}],
  "1015": [{"jp":"子どもは親の言葉づかいや行動を**模倣する**ものだ。","vi":"Trẻ con thường bắt chước cách nói năng và hành động của cha mẹ."},{"jp":"他社の製品を**模倣した**だけの商品では、客の心をつかめない。","vi":"Sản phẩm chỉ mô phỏng sản phẩm của công ty khác thì không thể chinh phục khách hàng."}],
  "1016": [{"jp":"売り上げだけに**着目する**と、本当の問題を見落とす。","vi":"Nếu chỉ chú ý đến doanh số thì sẽ bỏ sót vấn đề thực sự."},{"jp":"研究チームは植物の葉の形に**着目して**、新しい素材を開発した。","vi":"Nhóm nghiên cứu đã chú ý đến hình dạng lá cây và phát triển ra vật liệu mới."}],
  "1017": [{"jp":"江戸時代に造られたこの庭園は、実に**趣**がある。","vi":"Khu vườn được xây từ thời Edo này thật có nét phong nhã."},{"jp":"雨にぬれた石畳の道も、また違った**趣**がある。","vi":"Con đường lát đá ướt mưa cũng có một vẻ thú vị khác."}],
  "1018": [{"jp":"川の流れがぶつかり合って、大きな**渦**ができていた。","vi":"Dòng sông va vào nhau tạo thành một xoáy nước lớn."},{"jp":"優勝が決まった瞬間、会場は歓喜の**渦**に包まれた。","vi":"Khoảnh khắc chức vô địch được định đoạt, hội trường chìm trong vòng xoáy hân hoan."}],
  "1019": [{"jp":"大雨で、道路脇の**溝**から水があふれ出した。","vi":"Do mưa lớn, nước tràn ra từ rãnh bên đường."},{"jp":"些細なことで喧嘩して以来、二人の間に**溝**ができてしまった。","vi":"Từ khi cãi nhau vì chuyện vặt, giữa hai người đã nảy sinh khoảng cách."}],
  "1020": [{"jp":"寒さ厳しい**折**、くれぐれもお体を大切になさってください。","vi":"Trong lúc trời rét khắc nghiệt này, xin hãy hết sức giữ gìn sức khỏe."},{"jp":"故郷の母のことは、**折**に触れて思い出す。","vi":"Mỗi khi có dịp tôi lại nhớ đến mẹ ở quê nhà."}],
  "1021": [{"jp":"泳いでいる途中で、急に足が**つって**しまった。","vi":"Đang bơi thì chân tôi đột nhiên bị chuột rút."},{"jp":"台所の壁に棚を**つって**、食器を並べた。","vi":"Tôi treo kệ lên tường bếp rồi xếp bát đĩa lên."}],
  "1022": [{"jp":"夏になると、ベランダに風鈴を**つるす**。","vi":"Đến mùa hè, tôi treo chuông gió ở ban công."},{"jp":"洗濯物をハンガーに**つるして**、部屋の中で干した。","vi":"Tôi treo quần áo lên móc rồi phơi trong phòng."}],
  "1023": [{"jp":"切れ味が悪くなったので、包丁を**研いだ**。","vi":"Dao bị cùn nên tôi đã mài lại."},{"jp":"ご飯を炊く前に、お米を水で**研ぎます**。","vi":"Trước khi nấu cơm, vo gạo bằng nước."}],
  "1024": [{"jp":"仕事で疲れている父の肩を**揉んで**あげた。","vi":"Tôi đã bóp vai cho bố đang mệt vì công việc."},{"jp":"彼は若いころ社会に**揉まれて**、精神的に強くなった。","vi":"Hồi trẻ anh ấy đã va vấp nhiều ngoài đời nên trở nên vững vàng về tinh thần."}],
  "1025": [{"jp":"強風が庭の木を激しく**揺さぶって**いる。","vi":"Gió mạnh đang lay dữ dội cây trong vườn."},{"jp":"彼女の歌声に、観客は心を**揺さぶられた**。","vi":"Khán giả đã bị lay động trái tim bởi giọng hát của cô ấy."}],
  "1026": [{"jp":"疲れていたので、壁に**もたれて**電車を待った。","vi":"Vì mệt nên tôi tựa vào tường chờ tàu."},{"jp":"夕食に揚げ物を食べ過ぎて、胃が**もたれて**いる。","vi":"Bữa tối ăn quá nhiều đồ chiên nên bụng tôi bị đầy, khó tiêu."}],
  "1027": [{"jp":"地震で揺れた時、子どもは母親に**しがみついた**。","vi":"Khi động đất rung chuyển, đứa bé bám chặt lấy mẹ."},{"jp":"彼は昔の地位に**しがみついて**、なかなか引退しようとしない。","vi":"Ông ta bám lấy địa vị ngày xưa, mãi không chịu nghỉ hưu."}],
  "1028": [{"jp":"知らない男にずっと**付きまとわれて**、警察に相談した。","vi":"Bị một người đàn ông lạ đeo bám mãi, tôi đã trình báo cảnh sát."},{"jp":"高い場所での作業には、常に危険が**付きまとう**。","vi":"Công việc ở trên cao luôn đi kèm nguy hiểm."}],
  "1029": [{"jp":"新しく来た先生に、子どもたちはすぐ**懐いた**。","vi":"Lũ trẻ đã nhanh chóng quấn quýt với cô giáo mới đến."},{"jp":"拾ってきた猫は、なかなか私に**懐かない**。","vi":"Con mèo tôi nhặt về mãi vẫn không chịu thân với tôi."}],
  "1030": [{"jp":"彼は服装には全然**構わない**人だ。","vi":"Anh ấy là người hoàn toàn không để ý đến ăn mặc."},{"jp":"「ここでタバコを吸ってもいいですか。」「ええ、**構いません**よ。」","vi":"\"Tôi hút thuốc ở đây được không?\" \"Vâng, không sao đâu.\""}],
  "1031": [{"jp":"弟は新しいゲーム機を友達に**見せびらかして**いる。","vi":"Em trai tôi đang khoe máy chơi game mới với bạn bè."},{"jp":"ブランド品を**見せびらかす**ような人は、あまり好きではない。","vi":"Tôi không ưa lắm những người hay phô trương đồ hiệu."}],
  "1032": [{"jp":"子どもがおもちゃ売り場で、母親に新しいおもちゃを**ねだって**いる。","vi":"Đứa bé đang vòi mẹ mua đồ chơi mới ở quầy đồ chơi."},{"jp":"旅行に行く前に、娘にお土産を**ねだられた**。","vi":"Trước khi đi du lịch, tôi bị con gái nài nỉ mua quà."}],
  "1033": [{"jp":"泣いている妹を**なだめて**、寝かしつけた。","vi":"Tôi dỗ dành em gái đang khóc rồi cho em đi ngủ."},{"jp":"部長は怒っている客をうまく**なだめた**。","vi":"Trưởng phòng đã khéo léo xoa dịu vị khách đang nổi giận."}],
  "1034": [{"jp":"電車ではお年寄りを**いたわる**気持ちを忘れないようにしよう。","vi":"Trên tàu điện, hãy đừng quên tấm lòng ân cần với người già."},{"jp":"働きすぎなんだから、たまには体を**いたわって**ね。","vi":"Anh làm việc quá sức rồi, thỉnh thoảng hãy chăm sóc bản thân nhé."}],
  "1035": [{"jp":"満員電車で、知らない人と肩が**触れ合った**。","vi":"Trên chuyến tàu chật cứng, vai tôi chạm vào vai người lạ."},{"jp":"この牧場では、子どもたちが動物と**触れ合う**ことができる。","vi":"Ở trang trại này, trẻ em có thể giao lưu, tiếp xúc với động vật."}],
  "1036": [{"jp":"証拠を見せられても、彼は「知らない」と**とぼけた**。","vi":"Dù bị đưa ra bằng chứng, hắn vẫn giả ngơ nói \"không biết\"."},{"jp":"その俳優の**とぼけた**表情が、観客の笑いを誘った。","vi":"Biểu cảm ngây ngô của diễn viên đó khiến khán giả bật cười."}],
  "1037": [{"jp":"その店員はつり銭を**ごまかして**いたことがばれて、解雇された。","vi":"Nhân viên đó bị phát hiện ăn bớt tiền thối lại và bị sa thải."},{"jp":"彼は笑ってその場を**ごまかそう**とした。","vi":"Anh ta cười để lấp liếm cho qua chuyện."}],
  "1038": [{"jp":"長引く不況が庶民の生活を**脅かして**いる。","vi":"Suy thoái kéo dài đang đe dọa cuộc sống của người dân thường."},{"jp":"外来種の増加が、在来の生物の生存を**脅かす**。","vi":"Sự gia tăng các loài ngoại lai đe dọa sự sinh tồn của sinh vật bản địa."}],
  "1039": [{"jp":"犬は雷の音に**おびえて**、机の下に隠れた。","vi":"Con chó sợ tiếng sấm nên trốn dưới gầm bàn."},{"jp":"地震の後、住民たちは余震に**おびえる**日々を送った。","vi":"Sau trận động đất, người dân sống những ngày khiếp sợ dư chấn."}],
  "1040": [{"jp":"会議で突然指名されて、**戸惑って**しまった。","vi":"Bị gọi tên bất ngờ trong cuộc họp, tôi đã lúng túng."},{"jp":"日本に来たばかりのころは、習慣の違いに**戸惑う**ことが多かった。","vi":"Hồi mới đến Nhật, tôi thường bối rối trước sự khác biệt về phong tục."}],
  "1041": [{"jp":"目上の人の前では言葉を**慎む**べきだ。","vi":"Trước mặt người bề trên thì nên giữ gìn lời ăn tiếng nói."},{"jp":"医者に言われて、しばらくお酒と辛いものを**慎んで**いる。","vi":"Theo lời bác sĩ, tôi đang kiêng rượu và đồ cay một thời gian."}],
  "1042": [{"jp":"新人なのだから、もう少し自分の立場を**わきまえる**べきだ。","vi":"Là người mới thì nên hiểu rõ vị trí của mình hơn một chút."},{"jp":"彼は公私の別をきちんと**わきまえて**いる。","vi":"Anh ấy phân biệt rạch ròi việc công và việc tư."}],
  "1043": [{"jp":"卒業式の後、私たちはいつまでも別れを**惜しんだ**。","vi":"Sau lễ tốt nghiệp, chúng tôi mãi lưu luyến chia tay."},{"jp":"成功したいなら、努力を**惜しんで**はならない。","vi":"Nếu muốn thành công thì không được tiếc công sức."}],
  "1044": [{"jp":"二人は人目を**はばかって**、夜遅く会っていた。","vi":"Hai người e ngại ánh mắt người đời nên gặp nhau vào đêm khuya."},{"jp":"これは外聞を**はばかる**話なので、誰にも言わないでください。","vi":"Đây là chuyện ngại để người ngoài biết, nên đừng nói với ai nhé."}],
  "1045": [{"jp":"新しいシステムの導入に**手こずって**、作業が大幅に遅れた。","vi":"Vất vả với việc đưa hệ thống mới vào nên công việc bị chậm trễ nhiều."},{"jp":"わがままな子供に**手こずらされる**のは毎日のことだ。","vi":"Ngày nào cũng vất vả vì đứa trẻ bướng bỉnh."}],
  "1046": [{"jp":"一度株で大損して**懲りた**ので、もう投資はしない。","vi":"Đã một lần lỗ nặng vì cổ phiếu nên tôi chừa rồi, không đầu tư nữa."},{"jp":"何度失敗しても**懲りず**に挑戦する彼の姿勢には感心する。","vi":"Tôi khâm phục tinh thần không nản của anh ấy, thất bại bao lần vẫn thử thách."}],
  "1047": [{"jp":"嘘をついたことで、良心が**とがめた**。","vi":"Vì đã nói dối nên lương tâm tôi cắn rứt."},{"jp":"夜中に一人で歩いていたら、警官に**とがめられた**。","vi":"Đang đi bộ một mình lúc nửa đêm thì tôi bị cảnh sát chặn hỏi."}],
  "1048": [{"jp":"事故を起こした会社には、被害者の損害を**償う**責任がある。","vi":"Công ty gây ra tai nạn có trách nhiệm bồi thường thiệt hại cho nạn nhân."},{"jp":"彼は一生をかけて罪を**償う**つもりだ。","vi":"Anh ấy định dùng cả đời để chuộc tội."}],
  "1049": [{"jp":"最近、妻はお菓子作りに**凝って**いる。","vi":"Dạo này vợ tôi đang mê làm bánh kẹo."},{"jp":"長時間パソコンに向かっていたので、肩が**凝って**しまった。","vi":"Ngồi máy tính lâu nên tôi bị mỏi vai."}],
  "1050": [{"jp":"暗闇の中で目を**凝らす**と、人影が見えた。","vi":"Căng mắt nhìn trong bóng tối, tôi thấy bóng người."},{"jp":"各店がディスプレーに工夫を**凝らして**いる。","vi":"Các cửa hàng đều dồn công sức sáng tạo cho việc trưng bày."}],
  "1051": [{"jp":"いつまでも過去の失敗に**こだわって**いても仕方がない。","vi":"Cứ mãi để tâm đến thất bại trong quá khứ thì cũng chẳng ích gì."},{"jp":"この店の主人は材料の質に**こだわって**いる。","vi":"Chủ quán này rất chăm chút chất lượng nguyên liệu."}],
  "1052": [{"jp":"彼は裏方に**徹して**チームを支えた。","vi":"Anh ấy dốc lòng làm người đứng sau, hỗ trợ cả đội."},{"jp":"両国の代表は夜を**徹して**話し合った。","vi":"Đại diện hai nước đã bàn bạc suốt đêm."}],
  "1053": [{"jp":"彼らは苦労の末、ついにエベレストの山頂を**極めた**。","vi":"Sau bao gian khổ, cuối cùng họ đã chinh phục đỉnh Everest."},{"jp":"災害直後の現場は混乱を**極めて**いた。","vi":"Hiện trường ngay sau thảm họa hỗn loạn đến cực độ."}],
  "1054": [{"jp":"彼は長年の思いを**遂げ**、彼女と結婚した。","vi":"Anh ấy đã toại nguyện tình cảm bao năm và cưới được cô ấy."},{"jp":"この町はここ10年で急成長を**遂げた**。","vi":"Thị trấn này đã phát triển vượt bậc trong 10 năm qua."}],
  "1055": [{"jp":"祝日には国旗を**掲げる**家もある。","vi":"Vào ngày lễ cũng có nhà treo quốc kỳ."},{"jp":"新市長は「子育てしやすい町」という理想を**掲げて**いる。","vi":"Tân thị trưởng nêu cao lý tưởng \"thành phố dễ nuôi dạy con\"."}],
  "1056": [{"jp":"政府は問題の早期解決を**図る**方針だ。","vi":"Chính phủ có chủ trương tìm cách sớm giải quyết vấn đề."},{"jp":"取引先の便宜を**図って**、納期を調整した。","vi":"Để tạo thuận lợi cho đối tác, chúng tôi đã điều chỉnh thời hạn giao hàng."}],
  "1057": [{"jp":"彼女は5か国語を自由に**操る**。","vi":"Cô ấy sử dụng thành thạo 5 ngoại ngữ."},{"jp":"黒幕が裏で政治家を**操って**いたらしい。","vi":"Nghe nói kẻ giật dây đã thao túng chính trị gia từ phía sau."}],
  "1058": [{"jp":"広い部屋をカーテンで**仕切って**、二人で使っている。","vi":"Chúng tôi ngăn căn phòng rộng bằng rèm để hai người dùng."},{"jp":"今年の忘年会は田中さんが一人で**仕切った**。","vi":"Tiệc tất niên năm nay do một mình anh Tanaka quán xuyến."}],
  "1059": [{"jp":"医師たちはすぐに応急処置を**施した**。","vi":"Các bác sĩ lập tức tiến hành sơ cứu."},{"jp":"この城の天井には美しい装飾が**施されて**いる。","vi":"Trần của tòa lâu đài này được trang trí rất đẹp."}],
  "1060": [{"jp":"タクシーで急いだので、何とか終電に**間に合った**。","vi":"Nhờ đi taxi gấp nên tôi cũng kịp chuyến tàu cuối."},{"jp":"「新聞はいかがですか。」「うちは**間に合って**います。」","vi":"\"Anh có đặt báo không?\" \"Nhà tôi đủ rồi.\""}],
  "1061": [{"jp":"あの俳優はどんな役でもうまく**こなす**。","vi":"Diễn viên đó vai nào cũng đóng tốt."},{"jp":"彼女は大量の注文を一人で**こなして**いる。","vi":"Cô ấy một mình xử lý trơn tru lượng đơn hàng lớn."}],
  "1062": [{"jp":"静かな図書館だと勉強が**はかどる**。","vi":"Ở thư viện yên tĩnh thì việc học tiến triển tốt."},{"jp":"雨が続いたため、工事が思うように**はかどらない**。","vi":"Do mưa kéo dài nên công trình không tiến triển như mong muốn."}],
  "1063": [{"jp":"研究に**行き詰まった**ときは、散歩をして気分を変える。","vi":"Khi bế tắc trong nghiên cứu, tôi đi dạo để thay đổi tâm trạng."},{"jp":"資金不足で会社の経営が**行き詰まって**しまった。","vi":"Do thiếu vốn, việc kinh doanh của công ty đã rơi vào bế tắc."}],
  "1064": [{"jp":"大雪の影響で物流が**滞って**いる。","vi":"Do ảnh hưởng của tuyết lớn, việc lưu thông hàng hóa đang bị đình trệ."},{"jp":"家賃の支払いが3か月も**滞って**いる。","vi":"Tiền nhà bị chậm trả đến 3 tháng rồi."}],
  "1065": [{"jp":"広場の中央に創業者の銅像が**据え置かれて**いる。","vi":"Tượng đồng của người sáng lập được đặt cố định ở giữa quảng trường."},{"jp":"物価は上がっているのに、賃金は何年も**据え置かれた**ままだ。","vi":"Vật giá tăng mà lương thì mấy năm nay vẫn giữ nguyên."}],
  "1066": [{"jp":"父は30年間、新薬の開発に**携わって**きた。","vi":"Cha tôi đã làm công việc phát triển thuốc mới suốt 30 năm."},{"jp":"教育に**携わる**者として、子供たちの未来を真剣に考えたい。","vi":"Là người làm giáo dục, tôi muốn nghiêm túc nghĩ về tương lai của trẻ em."}],
  "1067": [{"jp":"彼は手土産を**携えて**、恩師の家を訪ねた。","vi":"Anh ấy mang theo quà đến thăm nhà thầy cũ."},{"jp":"地域の人々が手を**携えて**、町の復興に取り組んでいる。","vi":"Người dân địa phương đang chung tay khôi phục thị trấn."}],
  "1068": [{"jp":"地震の被災地のために、駅前で募金を**募って**いる。","vi":"Người ta đang quyên góp trước nhà ga cho vùng bị động đất."},{"jp":"連絡が取れないまま時間が過ぎ、不安が**募る**ばかりだ。","vi":"Thời gian trôi qua mà vẫn không liên lạc được, nỗi bất an cứ thế tăng lên."}],
  "1069": [{"jp":"地震の後、高波が海岸に**押し寄せた**。","vi":"Sau trận động đất, sóng cao ùa vào bờ biển."},{"jp":"連休には大勢の観光客が京都に**押し寄せる**。","vi":"Vào kỳ nghỉ dài, rất đông khách du lịch đổ về Kyoto."}],
  "1070": [{"jp":"地図を頼りに細い山道を**たどって**いった。","vi":"Tôi dựa vào bản đồ lần theo con đường núi nhỏ."},{"jp":"古い写真を見ながら、子供の頃の記憶を**たどった**。","vi":"Vừa xem ảnh cũ, tôi vừa lần lại ký ức thời thơ ấu."}],
  "1071": [{"jp":"彼はポケットを**探って**鍵を取り出した。","vi":"Anh ấy lục túi lấy chìa khóa ra."},{"jp":"専門家が事故の原因を**探って**いる。","vi":"Các chuyên gia đang tìm hiểu nguyên nhân vụ tai nạn."}],
  "1072": [{"jp":"彼の犯行を**裏付ける**証拠は見つかっていない。","vi":"Chưa tìm thấy bằng chứng xác thực hành vi phạm tội của hắn."},{"jp":"その仮説は最新の研究結果によって**裏付けられた**。","vi":"Giả thuyết đó đã được chứng minh bởi kết quả nghiên cứu mới nhất."}],
  "1073": [{"jp":"不審な男が家の中の様子を**うかがって**いる。","vi":"Một người đàn ông khả nghi đang dò xét tình hình trong nhà."},{"jp":"彼の言葉から、決意の固さが**うかがえる**。","vi":"Từ lời nói của anh ấy có thể nhận thấy quyết tâm vững chắc."}],
  "1074": [{"jp":"家臣たちは王の暗殺を**謀った**が、失敗に終わった。","vi":"Các gia thần âm mưu ám sát nhà vua nhưng thất bại."},{"jp":"元社員が顧客情報の流出を**謀って**いたことが発覚した。","vi":"Đã bị phát hiện cựu nhân viên âm mưu tuồn thông tin khách hàng ra ngoài."}],
  "1075": [{"jp":"敵を**欺く**には、まず味方から。","vi":"Muốn lừa kẻ địch thì trước hết phải lừa cả phe mình."},{"jp":"彼は巧妙な手口で多くの高齢者を**欺いた**。","vi":"Hắn đã lừa gạt nhiều người cao tuổi bằng thủ đoạn tinh vi."}],
  "1076": [{"jp":"倒れた大木が行く手を**阻んだ**。","vi":"Cây lớn bị đổ chặn mất lối đi."},{"jp":"円高が景気の回復を**阻んで**いる。","vi":"Đồng yên tăng giá đang cản trở sự phục hồi kinh tế."}],
  "1077": [{"jp":"ブラインドで直射日光を**遮る**。","vi":"Dùng rèm chắn ánh nắng trực tiếp."},{"jp":"彼は私の話を**遮って**、自分の意見を話し始めた。","vi":"Anh ta ngắt lời tôi và bắt đầu nói ý kiến của mình."}],
  "1078": [{"jp":"夜更かしは体に**障る**から、早く寝なさい。","vi":"Thức khuya có hại cho sức khỏe nên hãy ngủ sớm đi."},{"jp":"彼の偉そうな言い方が神経に**障る**。","vi":"Cách nói kẻ cả của anh ta làm tôi khó chịu."}],
  "1079": [{"jp":"長年の過労が彼の体を**蝕んで**いた。","vi":"Nhiều năm làm việc quá sức đã bào mòn cơ thể anh ấy."},{"jp":"森の木々は酸性雨に**蝕まれて**いる。","vi":"Cây cối trong rừng đang bị mưa axit ăn mòn."}],
  "1080": [{"jp":"休日は一日中部屋に**こもって**本を読んでいる。","vi":"Ngày nghỉ tôi ở lì trong phòng đọc sách cả ngày."},{"jp":"祖母から心の**こもった**手紙が届いた。","vi":"Tôi nhận được lá thư chan chứa tình cảm từ bà."}],
  "1081": [{"jp":"犯人は知人のアパートに**潜んで**いた。","vi":"Hung thủ đã ẩn nấp trong căn hộ của người quen."},{"jp":"何気ない頭痛に重い病気が**潜んで**いることもある。","vi":"Đằng sau cơn đau đầu tưởng bình thường đôi khi tiềm ẩn bệnh nặng."}],
  "1082": [{"jp":"容疑者は山奥の小屋に身を**潜めて**いた。","vi":"Nghi phạm đã ẩn mình trong túp lều sâu trong núi."},{"jp":"彼女は声を**潜めて**、秘密を打ち明けた。","vi":"Cô ấy hạ giọng thổ lộ bí mật."}],
  "1083": [{"jp":"度重なる不祥事で政権が**揺らいで**いる。","vi":"Vì liên tiếp bê bối, chính quyền đang lung lay."},{"jp":"柳の枝が風に**揺らいで**いる。","vi":"Cành liễu đang đung đưa trong gió."}],
  "1084": [{"jp":"賃上げをめぐって経営側と労働側が**もめて**いる。","vi":"Phía quản lý và phía người lao động đang tranh chấp về việc tăng lương."},{"jp":"娘の帰りが遅くて、気が**もめる**。","vi":"Con gái về muộn nên tôi sốt ruột."}],
  "1085": [{"jp":"校庭に国旗が風に**翻って**いる。","vi":"Quốc kỳ đang bay phấp phới trong gió ở sân trường."},{"jp":"一晩で彼の考えが**翻った**。","vi":"Chỉ sau một đêm, suy nghĩ của anh ấy đã thay đổi hẳn."}],
  "1086": [{"jp":"彼女はスカーフを風に**翻して**歩いていった。","vi":"Cô ấy bước đi, để chiếc khăn bay phấp phới trong gió."},{"jp":"一度賛成した議員が、突然態度を**翻した**。","vi":"Nghị sĩ từng tán thành bỗng nhiên đổi thái độ."}],
  "1087": [{"jp":"新しい発見によって、これまでの定説が**覆った**。","vi":"Nhờ phát hiện mới, học thuyết được công nhận bấy lâu đã bị đảo ngược."},{"jp":"強風でボートが**覆り**、乗っていた人が海に投げ出された。","vi":"Thuyền bị lật úp do gió mạnh, người trên thuyền bị hất xuống biển."}],
  "1088": [{"jp":"新人選手が大方の予想を**覆して**優勝した。","vi":"Vận động viên tân binh đã lật ngược mọi dự đoán để giành chức vô địch."},{"jp":"後半に入って、チームは5点差を**覆した**。","vi":"Sang hiệp hai, đội đã lật ngược cách biệt 5 điểm."}],
  "1089": [{"jp":"踏んでしまったせいで、メガネの枠が**ゆがんで**しまった。","vi":"Vì lỡ giẫm lên nên gọng kính bị méo."},{"jp":"幼い頃の辛い経験で、彼の心は**ゆがんで**しまったのかもしれない。","vi":"Có lẽ vì những trải nghiệm đau khổ thời thơ ấu mà tâm hồn anh ta đã trở nên lệch lạc."}],
  "1090": [{"jp":"一言謝らなかったせいで、二人の仲がすっかり**こじれて**しまった。","vi":"Chỉ vì không nói một lời xin lỗi mà quan hệ hai người trở nên rắc rối hẳn."},{"jp":"風邪が**こじれて**、肺炎になってしまった。","vi":"Cảm trở nặng thành viêm phổi."}],
  "1091": [{"jp":"目撃者の証言が互いに**食い違って**いる。","vi":"Lời khai của các nhân chứng mâu thuẫn với nhau."},{"jp":"方針をめぐって社長と副社長の意見が**食い違った**。","vi":"Ý kiến của giám đốc và phó giám đốc bất đồng về phương châm."}],
  "1092": [{"jp":"故郷から遠く**隔たった**土地で暮らしている。","vi":"Tôi đang sống ở một nơi cách xa quê hương."},{"jp":"両者の考えは大きく**隔たって**いて、合意は難しい。","vi":"Quan điểm của hai bên cách xa nhau nên khó đạt thỏa thuận."}],
  "1093": [{"jp":"二人はテーブルを**隔てて**向かい合った。","vi":"Hai người ngồi đối diện nhau cách một chiếc bàn."},{"jp":"20年の時を**隔てて**、二人は再会した。","vi":"Cách nhau 20 năm, hai người đã gặp lại."}],
  "1094": [{"jp":"今月はなんとか収入と支出が**釣り合った**。","vi":"Tháng này thu và chi cũng cân bằng được."},{"jp":"彼は自分がその大女優に**釣り合う**男だとは思えなかった。","vi":"Anh ấy không nghĩ mình là người xứng đôi với nữ diễn viên lớn ấy."}],
  "1095": [{"jp":"この汚職事件には大物政治家が**絡んで**いるらしい。","vi":"Nghe nói vụ tham nhũng này có dính líu đến chính trị gia tầm cỡ."},{"jp":"叔父は酔うと誰にでも**絡む**癖がある。","vi":"Chú tôi có tật hễ say là gây sự với bất kỳ ai."}],
  "1096": [{"jp":"古い木の幹にツタが**絡まって**いる。","vi":"Dây thường xuân quấn quanh thân cây cổ thụ."},{"jp":"箱の中で毛糸が**絡まって**、ほどくのに苦労した。","vi":"Len trong hộp bị rối nên gỡ ra rất vất vả."}],
  "1097": [{"jp":"焼いた肉に甘辛いたれを**絡める**。","vi":"Rưới đều nước sốt ngọt mặn lên thịt nướng."},{"jp":"高齢者の問題は少子化問題と**絡めて**考える必要がある。","vi":"Vấn đề người cao tuổi cần được xem xét gắn với vấn đề giảm sinh."}],
  "1098": [{"jp":"犯人は人込みに**紛れて**姿を消した。","vi":"Hung thủ lẫn vào đám đông rồi biến mất."},{"jp":"忙しさに**紛れて**、友人への返事を忘れていた。","vi":"Mải bận rộn nên tôi quên trả lời bạn."}],
  "1099": [{"jp":"彼は失恋の悲しみを仕事で**紛らそう**とした。","vi":"Anh ấy cố khuây khỏa nỗi buồn thất tình bằng công việc."},{"jp":"空腹を**紛らす**ために、水をたくさん飲んだ。","vi":"Để quên cơn đói, tôi đã uống thật nhiều nước."}],
  "1100": [{"jp":"冬の服は**かさばる**ので、旅行の荷物が多くなる。","vi":"Quần áo mùa đông cồng kềnh nên hành lý du lịch nhiều lên."},{"jp":"紙の本は**かさばる**から、最近は電子書籍で読んでいる。","vi":"Sách giấy cồng kềnh nên dạo này tôi đọc sách điện tử."}],
  "1101": [{"jp":"円安の影響で原材料の費用が**かさんで**いる。","vi":"Do đồng yên yếu, chi phí nguyên liệu đang đội lên."},{"jp":"入院が長引いて、治療費が**かさんだ**。","vi":"Nằm viện kéo dài nên chi phí điều trị tăng lên."}],
  "1102": [{"jp":"冷蔵庫に入れ忘れた野菜が**しなびて**しまった。","vi":"Rau quên cho vào tủ lạnh đã bị héo."},{"jp":"祖母の**しなびた**手を握ると、温かかった。","vi":"Nắm bàn tay nhăn nheo của bà, tôi thấy thật ấm áp."}],
  "1103": [{"jp":"若者の間で流行ったファッションも、すぐに**廃れて**しまった。","vi":"Thời trang từng thịnh hành trong giới trẻ cũng nhanh chóng lỗi thời."},{"jp":"安い輸入木材に押されて、この地域の林業は**廃れて**しまった。","vi":"Bị gỗ nhập khẩu giá rẻ lấn át, ngành lâm nghiệp vùng này đã suy tàn."}],
  "1104": [{"jp":"この曲を聴くと、学生時代の記憶が**よみがえる**。","vi":"Mỗi khi nghe bài hát này, ký ức thời học sinh lại ùa về."},{"jp":"雨が降って、枯れかけていた庭の草木が**よみがえった**。","vi":"Mưa xuống, cây cỏ trong vườn sắp héo khô đã hồi sinh."}],
  "1105": [{"jp":"インターネットは情報の革命を**もたらした**。","vi":"Internet đã mang lại một cuộc cách mạng thông tin."},{"jp":"今回の台風は農作物に大きな被害を**もたらした**。","vi":"Cơn bão lần này đã gây thiệt hại lớn cho nông sản."}],
  "1106": [{"jp":"久しぶりの雨で畑が**潤った**。","vi":"Nhờ cơn mưa sau bao ngày, ruộng vườn đã được thấm ướt."},{"jp":"観光客が増えて、町の財政が**潤って**いる。","vi":"Khách du lịch tăng nên tài chính của thị trấn dư dả."}],
  "1107": [{"jp":"冷たい水を飲んで、からからののどを**潤した**。","vi":"Tôi uống nước lạnh cho cổ họng khô khốc đỡ khát."},{"jp":"芸術は人の心を**潤して**くれる。","vi":"Nghệ thuật làm phong phú tâm hồn con người."}],
  "1108": [{"jp":"薬を飲んだら、頭の痛みが**和らいだ**。","vi":"Uống thuốc xong thì cơn đau đầu dịu đi."},{"jp":"彼の冗談で、会議の張り詰めた雰囲気が**和らいだ**。","vi":"Nhờ câu đùa của anh ấy, bầu không khí căng thẳng của cuộc họp dịu đi."}],
  "1109": [{"jp":"熱々のピザの上でチーズが**とろけて**いる。","vi":"Phô mai đang tan chảy trên chiếc pizza nóng hổi."},{"jp":"孫の笑顔を見ると、心が**とろける**ようだ。","vi":"Nhìn nụ cười của cháu, lòng tôi như tan chảy."}],
  "1110": [{"jp":"週末は家でゆっくり**くつろぐ**のが一番だ。","vi":"Cuối tuần thì thư thả nghỉ ngơi ở nhà là nhất."},{"jp":"どうぞ遠慮なく**くつろいで**ください。","vi":"Xin cứ tự nhiên thoải mái nhé."}],
  "1111": [{"jp":"彼は階段を**一気に**駆け上がった。","vi":"Anh ấy chạy một mạch lên cầu thang."},{"jp":"面白くて、分厚い小説を**一気に**読み終えた。","vi":"Hay quá nên tôi đọc một mạch hết cuốn tiểu thuyết dày."}],
  "1112": [{"jp":"無理な要求は**きっぱりと**断るべきだ。","vi":"Những yêu cầu vô lý thì nên từ chối dứt khoát."},{"jp":"医者に注意されて、父はたばこを**きっぱり**やめた。","vi":"Bị bác sĩ nhắc nhở, bố tôi bỏ thuốc lá dứt khoát."}],
  "1113": [{"jp":"彼女は家事を**てきぱきと**こなす。","vi":"Cô ấy làm việc nhà nhanh nhẹn, tháo vát."},{"jp":"新人なのに、彼は**てきぱき**と仕事を片付けていく。","vi":"Dù là người mới nhưng cậu ấy giải quyết công việc rất nhanh nhẹn."}],
  "1114": [{"jp":"会議は結論が出ないまま、**だらだらと**5時間も続いた。","vi":"Cuộc họp kéo dài lê thê suốt 5 tiếng mà không có kết luận."},{"jp":"坂道を上っていると、汗が**だらだら**流れてきた。","vi":"Leo dốc mà mồ hôi chảy ròng ròng."}],
  "1115": [{"jp":"**ぐずぐず**していると、電車に乗り遅れるよ。","vi":"Cứ lề mề là trễ tàu đấy."},{"jp":"花粉症で、朝から鼻が**ぐずぐず**する。","vi":"Vì dị ứng phấn hoa nên từ sáng mũi cứ sụt sịt."}],
  "1116": [{"jp":"大きな鷲が空を**ゆうゆうと**飛んでいる。","vi":"Con đại bàng lớn đang bay lượn thong dong trên bầu trời."},{"jp":"この成績なら、志望校に**ゆうゆう**合格できるだろう。","vi":"Với thành tích này thì dư sức đỗ trường nguyện vọng."}],
  "1117": [{"jp":"娘はデートらしく、**いそいそと**出かけて行った。","vi":"Con gái tôi hớn hở ra ngoài, có vẻ là đi hẹn hò."},{"jp":"父は孫が来ると聞いて、**いそいそと**部屋を片付け始めた。","vi":"Nghe tin cháu đến, bố tôi háo hức bắt đầu dọn phòng."}],
  "1118": [{"jp":"車が飛び出してきたので、**とっさに**身をかわした。","vi":"Một chiếc xe lao ra nên tôi theo phản xạ né người."},{"jp":"名前を聞かれて、**とっさに**嘘をついてしまった。","vi":"Bị hỏi tên, tôi buột miệng nói dối ngay."}],
  "1119": [{"jp":"大事なことなので、時間をかけて**じっくり**考えたい。","vi":"Vì là việc quan trọng nên tôi muốn dành thời gian suy nghĩ kỹ."},{"jp":"骨付き肉を弱火で**じっくりと**煮込む。","vi":"Hầm thịt có xương từ từ trên lửa nhỏ."}],
  "1120": [{"jp":"突然のことで、私は**おろおろ**するばかりで何もできなかった。","vi":"Chuyện quá đột ngột, tôi chỉ biết luống cuống chẳng làm được gì."},{"jp":"子供が帰ってこないので、母親は心配で**おろおろと**歩き回っていた。","vi":"Con chưa về nên người mẹ lo lắng, cuống cuồng đi tới đi lui."}],
  "1121": [{"jp":"券売機の操作が分からず、**まごまごして**しまった。","vi":"Không biết cách dùng máy bán vé nên tôi lúng túng."},{"jp":"**まごまごして**いると置いていくぞ。","vi":"Cứ lóng ngóng thế là tao bỏ lại đấy."}],
  "1122": [{"jp":"兄は何か独り言を**ぶつぶつ**つぶやいている。","vi":"Anh trai tôi đang lẩm bẩm gì đó một mình."},{"jp":"寝不足のせいか、顔に**ぶつぶつ**ができた。","vi":"Có lẽ do thiếu ngủ mà mặt nổi mụn lấm tấm."}],
  "1123": [{"jp":"観客は彼女の歌声に**うっとりと**聞き入っていた。","vi":"Khán giả ngây ngất lắng nghe giọng hát của cô ấy."},{"jp":"花嫁の美しい姿に、皆が**うっとりした**表情を浮かべた。","vi":"Trước dáng vẻ xinh đẹp của cô dâu, ai cũng lộ vẻ mê mẩn."}],
  "1124": [{"jp":"妊娠中は**ゆったりした**服を着るようにしている。","vi":"Khi mang thai tôi cố mặc quần áo rộng rãi."},{"jp":"休日は温泉で**ゆったりと**過ごしたい。","vi":"Ngày nghỉ tôi muốn thư thái ở suối nước nóng."}],
  "1125": [{"jp":"病気をして、健康のありがたさを**しみじみ**感じた。","vi":"Bị ốm rồi tôi mới thấm thía giá trị của sức khỏe."},{"jp":"久しぶりに会った旧友と、夜遅くまで**しみじみと**語り合った。","vi":"Tôi tâm tình với người bạn cũ lâu ngày gặp lại đến tận khuya."}],
  "1126": [{"jp":"彼女は鏡で自分の顔を**つくづくと**眺めた。","vi":"Cô ấy chăm chú ngắm khuôn mặt mình trong gương."},{"jp":"同じミスを繰り返す自分が**つくづく**嫌になる。","vi":"Tôi thật sự chán ghét bản thân vì cứ lặp lại cùng một lỗi."}],
  "1127": [{"jp":"第一志望の大学に落ちて、彼は**がっくりと**肩を落とした。","vi":"Trượt trường đại học nguyện vọng một, cậu ấy thất vọng buông thõng vai."},{"jp":"新商品の不評で、売り上げが**がっくり**落ちた。","vi":"Vì sản phẩm mới bị chê, doanh thu giảm đột ngột."}],
  "1128": [{"jp":"いくら好きな料理でも、毎日食べると**うんざりする**。","vi":"Món dù thích đến mấy mà ngày nào cũng ăn thì cũng ngán."},{"jp":"上司の長い自慢話には、もう**うんざりだ**。","vi":"Tôi đã chán ngấy những câu chuyện khoe khoang dài dòng của sếp."}],
  "1129": [{"jp":"**てっきり**場所を間違えたのだと思ったが、実際はみんなが遅刻したのだった。","vi":"Tôi cứ ngỡ mình nhầm địa điểm, nhưng thực ra là mọi người đều đến muộn."},{"jp":"彼は若く見えるので、**てっきり**学生だと思っていた。","vi":"Anh ấy trông trẻ nên tôi cứ đinh ninh là sinh viên."}],
  "1130": [{"jp":"こんなにつらい思いをするくらいなら、**いっそ**会社を辞めてしまいたい。","vi":"Nếu phải khổ sở thế này thì thà nghỉ việc luôn còn hơn."},{"jp":"修理に高いお金がかかるなら、**いっそ**新しいのを買ったほうがいい。","vi":"Nếu sửa tốn nhiều tiền thì thà mua cái mới còn hơn."}],
  "1131": [{"jp":"会議は9時**きっかり**に始まった。","vi":"Cuộc họp bắt đầu đúng 9 giờ."},{"jp":"代金は**きっかり**3000円だった。","vi":"Tiền hàng vừa chẵn 3000 yên."}],
  "1132": [{"jp":"お菓子作りでは材料を**きっちり**量ることが大切だ。","vi":"Khi làm bánh, cân đo nguyên liệu thật chính xác là điều quan trọng."},{"jp":"彼女は何事にも**きっちりと**計画を立てる。","vi":"Việc gì cô ấy cũng lập kế hoạch chỉn chu."}],
  "1133": [{"jp":"このたびはご迷惑をおかけして、**誠に**申し訳ございません。","vi":"Lần này đã gây phiền phức cho quý khách, chúng tôi thật sự xin lỗi."},{"jp":"本日はお忙しい中お越しいただき、**誠に**ありがとうございます。","vi":"Thành thật cảm ơn quý vị đã dành thời gian đến đây hôm nay."}],
  "1134": [{"jp":"今晩は**ことに**冷える。","vi":"Tối nay đặc biệt lạnh."},{"jp":"彼は音楽が好きで、**ことに**ジャズには詳しい。","vi":"Anh ấy thích âm nhạc, đặc biệt là rất am hiểu nhạc jazz."}],
  "1135": [{"jp":"この絵は**まさに**彼の最高傑作だ。","vi":"Bức tranh này đúng là kiệt tác xuất sắc nhất của ông ấy."},{"jp":"今**まさに**、新しい年が明けようとしている。","vi":"Ngay lúc này, năm mới sắp bắt đầu."}],
  "1136": [{"jp":"彼女は息子の帰りを**ひたすら**待ち続けた。","vi":"Bà ấy một mực chờ con trai trở về."},{"jp":"合格するまで、彼は**ひたすら**勉強に打ち込んだ。","vi":"Cho đến khi đỗ, anh ấy chỉ chuyên tâm vào học."}],
  "1137": [{"jp":"彼は自分の主張を**あくまでも**貫くつもりだ。","vi":"Anh ấy định giữ vững quan điểm của mình đến cùng."},{"jp":"これは**あくまで**私個人の意見です。","vi":"Đây suy cho cùng chỉ là ý kiến cá nhân của tôi."}],
  "1138": [{"jp":"9月も半ばを過ぎ、**めっきり**涼しくなった。","vi":"Đã quá giữa tháng 9, trời mát hẳn lên."},{"jp":"祖父は入院してから、**めっきり**体が弱くなった。","vi":"Từ khi nhập viện, ông tôi yếu đi trông thấy."}],
  "1139": [{"jp":"最後の試合で逆転し、**かろうじて**予選をパスした。","vi":"Lội ngược dòng ở trận cuối, chúng tôi khó khăn lắm mới qua được vòng loại."},{"jp":"車は大破したが、運転手は**かろうじて**難を逃れた。","vi":"Chiếc xe hư hỏng nặng nhưng tài xế suýt soát thoát nạn."}],
  "1140": [{"jp":"皆が賛成する中、彼は**あえて**反対意見を述べた。","vi":"Giữa lúc mọi người đều tán thành, anh ấy mạnh dạn nêu ý kiến phản đối."},{"jp":"分かりきったことなので、**あえて**説明するまでもないだろう。","vi":"Đó là điều hiển nhiên nên không nhất thiết phải giải thích."}],
  "1141": [{"jp":"**あわや**衝突かというところで、車は止まった。","vi":"Chiếc xe dừng lại đúng lúc suýt chút nữa thì va chạm."},{"jp":"後半に失点が続き、**あわや**予選敗退かと心配した。","vi":"Hiệp hai liên tục bị thủng lưới, tôi đã lo suýt nữa bị loại từ vòng loại."}],
  "1142": [{"jp":"打球が**もろに**顔に当たった。","vi":"Quả bóng đánh ra trúng thẳng vào mặt."},{"jp":"輸出企業は円高の影響を**もろに**受けた。","vi":"Các doanh nghiệp xuất khẩu hứng trọn ảnh hưởng của đồng yên tăng giá."}],
  "1143": [{"jp":"いつもうるさい弟が、今日は**いやに**おとなしい。","vi":"Đứa em vốn ồn ào mà hôm nay ngoan một cách khác thường."},{"jp":"梅雨に入ってから、**いやに**蒸し暑い日が続いている。","vi":"Từ khi vào mùa mưa, những ngày oi bức quá mức cứ kéo dài."}],
  "1144": [{"jp":"今日は**やけに**暑いね。","vi":"Hôm nay nóng quá chừng nhỉ."},{"jp":"彼女、今日は**やけに**優しいね。何かあったのかな。","vi":"Hôm nay cô ấy dịu dàng khác thường nhỉ. Có chuyện gì chăng?"}],
  "1145": [{"jp":"知らない人を**むやみに**信じてはいけない。","vi":"Không được tin người lạ một cách thiếu suy nghĩ."},{"jp":"抗生物質を**むやみに**使うと、薬が効かなくなることがある。","vi":"Dùng kháng sinh bừa bãi có thể khiến thuốc mất tác dụng."}],
  "1146": [{"jp":"昨夜塩辛いものを食べたせいか、**やたらに**のどが渇く。","vi":"Có lẽ vì tối qua ăn đồ mặn nên khát nước quá mức."},{"jp":"彼は**やたらに**人の話に口を出すので、嫌われている。","vi":"Anh ta hay chen ngang chuyện người khác một cách tùy tiện nên bị ghét."}],
  "1147": [{"jp":"暖房がないので、**何しろ**寒くて眠れない。","vi":"Vì không có máy sưởi, lạnh quá nên không ngủ được."},{"jp":"**何しろ**初めての経験なので、分からないことばかりだ。","vi":"Dù sao đây cũng là lần đầu nên toàn những điều không biết."}],
  "1148": [{"jp":"休みの日は**専ら**山歩きをしている。","vi":"Ngày nghỉ tôi chủ yếu đi leo núi."},{"jp":"二人が結婚するというのが**専ら**のうわさだ。","vi":"Lời đồn khắp nơi là hai người sẽ kết hôn."}],
  "1149": [{"jp":"無理だとは思うが、**一応**頼んでみた。","vi":"Tôi nghĩ là không được nhưng cũng thử nhờ xem sao."},{"jp":"研修で、**一応**の仕事の流れは分かった。","vi":"Qua đợt đào tạo, tôi đã nắm được đại khái quy trình công việc."}],
  "1150": [{"jp":"交差点では自転車から**一旦**降りて渡ってください。","vi":"Ở ngã tư, hãy tạm xuống xe đạp rồi dắt qua đường."},{"jp":"**一旦**引き受けておいて後で断るなんて、無責任だ。","vi":"Một khi đã nhận lời mà sau đó lại từ chối thì thật vô trách nhiệm."}],
  "1151": [{"jp":"父の手術が無事に終わり、**ひとまず**安心だ。","vi":"Ca phẫu thuật của bố đã thành công, trước mắt thì yên tâm rồi."},{"jp":"細かい点は後で決めるとして、**ひとまず**計画を進めよう。","vi":"Chi tiết thì quyết sau, tạm thời cứ triển khai kế hoạch đã."}],
  "1152": [{"jp":"詳しい日程は**追って**ご連絡いたします。","vi":"Lịch trình chi tiết chúng tôi sẽ liên lạc sau."},{"jp":"合否の結果は**追って**書面でお知らせします。","vi":"Kết quả đỗ trượt sẽ được thông báo bằng văn bản sau."}],
  "1153": [{"jp":"あの薬は効くと言われているし、**現に**私も治った。","vi":"Thuốc đó được cho là hiệu quả, và thực tế là tôi cũng đã khỏi."},{"jp":"彼は集中力が足りない。**現に**、今日もつまらないミスをしている。","vi":"Cậu ta thiếu tập trung. Thực tế là hôm nay cũng mắc lỗi vớ vẩn."}],
  "1154": [{"jp":"成田空港は**言わば**日本の玄関だ。","vi":"Sân bay Narita có thể nói là cửa ngõ của Nhật Bản."},{"jp":"彼は私にとって、**言わば**第二の父のような存在だ。","vi":"Với tôi, ông ấy có thể nói là như người cha thứ hai."}],
  "1155": [{"jp":"人生、**いかに**生きるべきか。","vi":"Đời người, nên sống như thế nào?"},{"jp":"彼が**いかに**努力したか、私はよく知っている。","vi":"Tôi biết rõ anh ấy đã nỗ lực biết bao."}],
  "1156": [{"jp":"ボーナスとして、全社員に**一律に**1万円が支給された。","vi":"Toàn bộ nhân viên được phát đồng loạt 10.000 yên tiền thưởng."},{"jp":"事情の違う人たちを**一律に**扱うのは不公平だ。","vi":"Đối xử đồng loạt như nhau với những người có hoàn cảnh khác nhau là bất công."}],
  "1157": [{"jp":"参加者は**各々**弁当を持参してください。","vi":"Mỗi người tham gia vui lòng tự mang cơm hộp."},{"jp":"家族の一人一人に、**各々**役割がある。","vi":"Mỗi thành viên trong gia đình đều có vai trò riêng."}],
  "1158": [{"jp":"病院に運ばれたときには、**もはや**手遅れだった。","vi":"Khi được đưa đến bệnh viện thì đã quá muộn rồi."},{"jp":"スマートフォンは**もはや**生活に欠かせないものになった。","vi":"Điện thoại thông minh giờ đã trở thành thứ không thể thiếu trong cuộc sống."}],
  "1159": [{"jp":"人は**ともすれば**楽な方へ流れがちだ。","vi":"Con người dễ có khuynh hướng sa vào lối dễ dàng."},{"jp":"一人暮らしをしていると、**ともすると**食生活が乱れやすい。","vi":"Khi sống một mình, chế độ ăn uống dễ trở nên thất thường."}],
  "1160": [{"jp":"台風は**依然**強い勢力を保ったまま北上している。","vi":"Cơn bão vẫn giữ cường độ mạnh và đang di chuyển lên phía bắc."},{"jp":"事件から1年たったが、犯人は**依然として**捕まっていない。","vi":"Đã một năm kể từ vụ án nhưng hung thủ vẫn chưa bị bắt."}],
  "1161": [{"jp":"将来に対して**漠然とした**不安を抱いている。","vi":"Tôi mang nỗi bất an mơ hồ về tương lai."},{"jp":"目標もなく、**漠然と**毎日を過ごしてはいけない。","vi":"Không nên sống mơ hồ qua ngày mà không có mục tiêu."}],
  "1162": [{"jp":"若い人でも大変なのだから、**まして**お年寄りには無理だろう。","vi":"Người trẻ còn vất vả, huống chi người già thì chắc không làm nổi."},{"jp":"日本人でも難しい漢字だ。**まして**外国人には読めないだろう。","vi":"Chữ Hán này người Nhật còn thấy khó, nói gì đến người nước ngoài thì chắc không đọc được."}],
  "1163": [{"jp":"ベッドから出るのはつらい。寒い冬の朝は**なおさら**だ。","vi":"Ra khỏi giường thật khổ sở. Sáng mùa đông lạnh giá thì càng khổ hơn."},{"jp":"止められると、**なおさら**やりたくなるものだ。","vi":"Bị ngăn cấm thì lại càng muốn làm."}],
  "1164": [{"jp":"アメリカの不況は日本に、**ひいては**我が家の家計にも影響を及ぼす。","vi":"Suy thoái ở Mỹ ảnh hưởng đến Nhật Bản, và kéo theo đó là cả chi tiêu nhà tôi."},{"jp":"一人一人の節電が、**ひいては**地球環境を守ることにつながる。","vi":"Việc tiết kiệm điện của mỗi người, rộng ra, góp phần bảo vệ môi trường trái đất."}],
  "1165": [{"jp":"よく読めば、答えは**おのずから**分かるだろう。","vi":"Đọc kỹ thì câu trả lời sẽ tự khắc hiểu ra."},{"jp":"努力を続ければ、結果は**おのずから**ついてくる。","vi":"Nếu tiếp tục nỗ lực, kết quả sẽ tự nhiên đến."}],
  "1166": [{"jp":"台風が過ぎた**明くる**日は、雲ひとつない晴天だった。","vi":"Ngày hôm sau khi bão qua, trời quang không một gợn mây."},{"jp":"二人は出会った**明くる**年に結婚した。","vi":"Hai người kết hôn vào năm sau khi gặp nhau."}],
  "1167": [{"jp":"**来る**15日、中央公園でフリーマーケットが開かれる。","vi":"Ngày 15 sắp tới, chợ trời sẽ được tổ chức ở công viên trung tâm."},{"jp":"新製品の発表会は**来る**3月5日に行われる予定です。","vi":"Buổi ra mắt sản phẩm mới dự kiến diễn ra vào ngày 5 tháng 3 sắp tới."}],
  "1168": [{"jp":"**去る**7月10日、創立50周年の式典が行われた。","vi":"Ngày 10 tháng 7 vừa qua, lễ kỷ niệm 50 năm thành lập đã được tổ chức."},{"jp":"**去る**3月、祖父が90歳で亡くなった。","vi":"Tháng 3 vừa qua, ông tôi qua đời ở tuổi 90."}],
  "1169": [{"jp":"「**例の**物を持ってきてくれ。」","vi":"\"Mang cái đó lại đây cho tôi.\""},{"jp":"**例の**件ですが、先方から返事がありました。","vi":"Về việc đó (anh biết rồi đấy), bên kia đã trả lời rồi."}],
  "1170": [{"jp":"**ありとあらゆる**方法を試してみたが、効果はなかった。","vi":"Tôi đã thử mọi cách nhưng không hiệu quả."},{"jp":"この店には**ありとあらゆる**種類の調味料がそろっている。","vi":"Cửa hàng này có đủ mọi loại gia vị."}]
});
